object Main {
  def main(args: Array[String]): Unit = {
    import scala.io.StdIn.readLine
    val _ = readLine
    val datA = readLine.split(" ").map(_.toLong)

    def judgement(acc: (Long, Long), cur: (Long, Long)): (Long, Long) = {
      val sum = acc._1
      val count = acc._2
      val a = cur._1
      if (sum > 0) {
        if (sum + a >= 0) (-1, count + math.abs(sum + a) + 1)
        else (sum + a, count)
      }
      else { // (sum < 0)
        if (sum + a <= 0) (1, count + math.abs(sum + a) + 1)
        else (sum + a, count)
      } // not care for sum == 0
    }

    val posA = datA.tail.map(a => (a, 0L)).foldLeft(
      if (datA.head == 0) (1L, 1L)
      else (datA.head, 0L)
    ){ judgement(_, _) }
    val negA = datA.tail.map(a => (a, 0L)).foldLeft(
      if (datA.head == 0) (-1L, 1L)
      else (if(datA.head > 0) -1L else 1L, math.abs(datA.head) + 1)
    ){ judgement(_, _) }

    val ans = math.min(posA._2, negA._2)
    println(ans)
  }
}

