  for (int i = 0; i < n; i++) {
    long long k; cin >> k;
    sum += k;
    if (i == 0) {
      if (k == 0) {
        op = 1;
        sum += 1;
        ans1 += 1;
      }
      else op = k / max(k, -k);
    }
    else {
      op *= -1;
      if (sum / op <= 0) {
        ans1 += max(sum, -sum) + 1;
        sum = op;
      }
    }
    v.push_back(k);
  }
  sum = 0;
  long long ans2 = 0;
  for (int i = 0; i < n; i++) {
    sum += v[i];
    if (i == 0) {
      if (v[i] == 0) {
        op = 1;
        sum += -1;
        ans2 += 1;
      }
      else op = v[i] / max(v[i], -v[i]);
    }
    op *= -1;
    if (sum / op <= 0) {
      ans2 += max(sum, -sum) + 1;
      sum = op;
    }
  }

  cout << min(ans1, ans2) << endl;
  return 0;
