LL n, cnt = 0;
LL A[MAXN];

LL solve(int i, bool target, LL prev) {
  LL a = A[i] + prev;
  LL diff = 0;
  if ((a > 0) != target) {
    if (target == 1) { // A < 0
      diff = 1 - a;
    }
    else {  // A > 0
      diff = -1 - a;
    }
    cnt += abs(diff);
  }
  else if (a == 0) {
    if (target == 1) { // A < 0
      diff = 1 - a;
    }
    else {  // A > 0
      diff = -1 - a;
    }
    cnt += abs(diff);
  }
  return diff;
}

