  FORN(i, n) {
    diff += solve(i, sign, diff);
    sign ^= 1;
  }


  LL ans1 = cnt; cnt = 0;
  diff = 0; sign = 0;
  FORN(i, n) {
    diff += solve(i, sign, diff);
    sign ^= 1;
  }
  LL ans2 = cnt;

  printf("%lld\n", min(ans1, ans2));
  return 0;
}

