int sol(vector<int> a, int n, int pos) {
  int ans = 0;
  for (int i = 0; i < n; i++) {
    if (i) a[i] += a[i - 1];
    if (pos == 1 && a[i] <= 0) ans += 1 - a[i], a[i] = 1;
    if (pos == 0 && a[i] >= 0) ans += a[i] + 1, a[i] = -1;
    pos = 1 - pos;
  }
  return ans;
}

