    vector<int> a(n, 0);
    vector<int> S(n, 0);
    for (size_t i=0; i<a.size(); ++i)
        cin >> a[i];

    int operation = 0;

    S[0] = a[0];
    if (S[0] == 0) {
        size_t j = 0;
        while (j<a.size()) {
            if (a[j] != 0) break;
            ++j;
        }
        if (j == a.size()) {
            S[0] = 1;
            ++operation;
        }
        else if (j%2 == 0) {
            S[0] = a[j] / abs(a[j]);
            ++operation;
        }
        else {
            S[0] = -a[j] / abs(a[j]);
            ++operation;
        }
    }

    for (size_t i=1; i<a.size(); ++i) {
        S[i] = S[i-1] + a[i];
        if (S[i] == 0) {
            S[i] = -(S[i-1] / abs(S[i-1]));
            ++operation;
        }
        else {
            if(S[i-1]*S[i] > 0) {
                operation = operation + abs(S[i]) + 1;
                // set to +1 or -1.
                S[i] = - (S[i] / abs(S[i]));
            }
        }
    }
    cout << operation << endl;
}

