int calc(int flag, const int a[], int n) {
  int cost = 0;
  long sum = 0;
  for (int i = 0; i < n; ++i) {
    sum += a[i];
    if ((sum * flag) <= 0) {
      cost += abs(flag - sum);
      sum += flag - sum;
    }
    flag = -flag;
  }
  return cost;
}

