ll check(vector<ll>& A, int start_sign, int N)
{
  ll diff = 0, ret = 0;
  for (int i = 1, sign = start_sign; i <= N; ++i, sign *= -1) {
    ll val = A[i] + diff;
    if (sign > 0) {
      if (val > 0) { continue; }
      diff += abs(val) + 1;
      ret += abs(val) + 1;
    }
    else if (sign < 0) {
      if (val < 0) { continue; }
      diff -= (val + 1);
      ret += val + 1;
    }
  }
  return ret;
}

