template<class T> void gc(T &x)
{
    char c;
    int s = 0;
    x = 0;

    c = getchar_unlocked();

    if (c == '-') s = 1;
    else if ('0' <= c && c <= '9')  x = c - '0';

    while (true)
    {
        c = getchar_unlocked();

        if (c < '0' || c > '9') break;
        x = x * 10 + (c - '0');
    }

    if (s) x = -x;
}

void ctsm(const int &tmp, long long int &sm, long long int &ct)
{
    // 正から負へ反転させる 正⇒負(-1)
    if ((0LL <= sm + tmp) && (0LL < sm))
    {
        ct += 1LL + sm + tmp;
        sm = -1LL;
    }
    // 負から正へ反転させる 負⇒正(1)
    else if ((sm + tmp <= 0LL) && (sm < 0LL))
    {
        ct += 1LL - sm - tmp;
        sm = 1LL;
    }
    // 反転させる必要がない
    else sm = sm + tmp;
}

int main()
{
    int n;
    gc(n);

    int tmp;

    gc(tmp);

    long long int sm = 0LL;
    long long int ct = 0LL;

    // 第1項目の符号の符号通りの場合
    sm = 0 == tmp ? 1LL : sm + tmp;
    ct = 0 == tmp ? 1LL : ct;

    // opposite 第1項目目の反対の符号
    tmp = (-1) * tmp;

    long long opsm = 0LL;
    long long opct = 0LL;

    // 第1項目の符号の正負逆の場合
    // 反転させたものが正なら元は負 負⇒正(1)
    // 反転させたものが負なら元は正 正⇒負(-1)
    opsm = 0 == tmp ? -1LL : 0 < tmp ? 1LL : -1LL;
    // 操作回数
    // 負⇒正(1)
    // 正⇒負(-1)
    opct += abs(tmp) + 1LL;

    for (int i = 1; i < n; i++)
    {
        gc(tmp);

        // count sum
        ctsm(tmp, sm, ct);
        // opposite count sum
        ctsm(tmp, opsm, opct);
    }

    printf("%lld\n", ct < opct ? ct : opct);
    return 0;
}

