    REP(i,n) cin >> v[i];
    auto sign = [](int x){
        if (x == 0) return 0;
        else if (x > 0) return 1;
        else return -1;};

    ll pos = 0, neg = 0;
    REP(i,2) {
        int now = 0;
        int prevsign = 0;
        ll count = 0;
        if (i == 0) {
            if (sign(v[0]) != 1) {
                now = 1;
                count = abs(v[0]) +1;
            } else now = v[0];
            prevsign = 1;
        } else {
            if (sign(v[0]) != -1) {
                now = -1;
                count = abs(v[0]) +1;
            } else now = v[0];
            prevsign = -1;
        }

        FOR(j,1,n) {
            now += v[j];
            int s = sign(now);
            //cerr << i << " " << j << " " << now << " " << s;
            if (prevsign == s || s == 0) {
                count += abs(now) + 1;
                if (prevsign == 1) {
                    now = -1;
                } else {
                    now = 1;
                }
            }
            prevsign = sign(now);
            //cerr << " " << count << endl;
        }
        if (i == 0) pos = count;
        else neg = count;
    }

    cout << min(pos,neg) << endl;


    return 0;
}

