        // 奇数番目で負の整数ではない場合
        if (i % 2 == 1 && sum > -1) {
            cnt_a += sum + 1; // ギリギリ負の整数(-1)にするために必要な数を加算
            sum = -1;
        }
    }

    // pattern -1 1 -1 1
    sum = 0;
    ll cnt_b = 0;
    rep(i, n) {
        sum += a[i];
        // 偶数番目で負の整数ではない場合
        if (i % 2 == 0 && sum > -1) {
            cnt_b += sum + 1; // ギリギリ負の整数(-1)にするために必要な数を加算
            sum = -1;
        }
        // 奇数番目で正の整数ではない場合
        if (i % 2 == 1 && sum < 1) {
            cnt_b += 1 - sum; // ギリギリ正の整数(1)にするために必要な数を加算
            sum = 1;
        }
    }

    cout << min(cnt_a, cnt_b) << endl;
    return 0;
}

