int ans(int n, int *a, int change){
  long long Ans = 0;
  long long sum = 0;
  for(int i = 0; i < n; i++){
    sum += a[i];
    switch (change) {
      case -1:
      if(sum > -1) Ans += 1 + sum, sum = -1;
      change *= -1;
      break;

      case 1:
      if(sum < 1) Ans += 1 - sum, sum = 1;
      change *= -1;
      break;
    }
  }

  return Ans;
}

