//BigMod (a^p)%mod

template<typename A, typename P>
int BigMod(A a, P p, const int MOD)
{
    int ret = 1;
    while(p)
    {
        if(p & 1)ret = (1LL * ret * a) % MOD;
        a = (1LL * a * a) % MOD;
        p >>= 1LL;
    }
    return ret;
}

//Base (value,base)
template<typename T>
T toBase(T n, T base)
{
    T ret = 0LL;
    while(n)
    {
        ret += n % base;
        ret *= 10LL;
        n /= base;
    }
    return ret;
}


// Divisor
template<typename T>
vector<T> Divisor(T value)
{
    vector<T> v;
    for(int i = 1LL; i * i <= value; ++i)
    {
        if(value % i == 0)

        {
            v.push_back(i);
            if(i * i != value) v.push_back(value / i);
        }
    }
    return v;
}

//Primes
template<typename T>
bool prime(T n)
{
    if (n % 2 == 0) return 0;
    for (T i = 3; i*i <= n; i += 2)
    {
        if (n % i == 0) return 0;
    }
    return 1;
}

//Sieve
template<typename T>
void SieveOfEratostheness(T n)
{
    bool prime[n+1];
    memset(prime, true, sizeof(prime));
    for (T p=2; p*p<=n; p++)
    {
        if (prime[p] == true)
        {
            for (int i=p*p; i<=n; i += p) prime[i] = false;
        }
    }
}

