using namespace std;

void ctsm(const long long &tmp, long long int &sm, long long int &ct)
{
    if ((0 <= sm + tmp) && (0 < sm))
    {
        ct += 1 + sm + tmp;
        sm = -1;
    }
    else if ((sm + tmp <= 0) && (sm < 0))
    {
        ct += 1 - sm - tmp;
        sm = 1;
    }
    else sm = sm + tmp;
}

int main()
{
    int n;
    if (scanf("%d", &n) < 1) return 0;

    long long int tmp;
    long long int sm = 0;
    long long int ct = 0;

    if (scanf("%lld", &tmp) < 1) return 0;
    sm = sm + tmp;

    // opposite
    long long int opsm = 0;
    long long int opct = 0;

    tmp = (-1) * tmp;
    opsm = opsm + tmp;
    opct += abs(tmp) + 1;

    for (int i = 1; i < n; i++)
    {
        if (scanf("%lld", &tmp) < 1) return 0;

        // count sum
        ctsm(tmp, sm, ct);
        // opposite count sum
        ctsm(tmp, opsm, opct);
    }

    printf("%lld\n", ct < opct ? ct : opct);
    return 0;
}

