int calc(bool firstPositive, int a[], int n) {
  bool positive = firstPositive;
  int cost = 0;
  long sum = 0;
  for (int i = 0; i < n; ++i) {
    bool sumpos = (sum + a[i]) >= 0;
    if (sumpos != positive) {
      while (((sum + a[i]) >= 0) == sumpos) {
        a[i] += sumpos ? -1 : 1;
        ++cost;
      }
    }
    if ((sum + a[i]) == 0) {
      a[i] += sumpos ? -1 : 1;
      ++cost;
    }
    sum += a[i];
    positive = !positive;
  }
  return cost;
}

