std::int_fast64_t solve(const tools::fenwick<std::int_fast64_t>& a_fenwick, const std::int_fast64_t first_target) {
  assert(first_target == 1 || first_target == -1);
  tools::fenwick<std::int_fast64_t> work = a_fenwick;
  std::int_fast64_t target = first_target;
  std::int_fast64_t result = 0;
  for (std::size_t i = 0; i < work.size(); ++i, target *= -1) {
    const std::int_fast64_t current_sum = work.sum(0, i + 1);
    const std::int_fast64_t diff = (target > 0 ? current_sum < target : target < current_sum) ? target - current_sum : 0;
    result += std::abs(diff);
    work.add(i, diff);
  }
  return result;
}

