int N;

int solve(int ans, vector<int> A, vector<int> cu) {
	rep(i, N) {
		//0なら
		if (cu[i] == 0) {
			ans++;
			if (i == 0) {
				if (cu[i + 1] < 0) {
					cu[i] = 1;
				}
				else {
					cu[i] = -1;
				}
			}
			else {
				if (cu[i - 1] < 0) {
					cu[i] = 1;
				}
				else {
					cu[i] = -1;
				}
			}
		}

		if (i == N - 1) {
			break;
		}

		//符号が同じなら
		if (cu[i] < 0 == cu[i + 1] < 0) {
			if (cu[i + 1] > 0) {
				ans += cu[i + 1] + 1;
				cu[i + 1] -= cu[i + 1] + 1;
			}
			else {
				ans += -cu[i + 1] + 1;
				cu[i + 1] += -cu[i + 1] + 1;
			}
		}
		cu[i + 2] = cu[i + 1] + A[i + 2];
	}
	return ans;
}

signed main() {

	cin >> N;
	vector<int> A(N + 2), A2;
	vector<int> cu(N + 2);
	int su = 0;
	rep(i, N) {
		cin >> A[i];
		su += A[i];
		cu[i] = su;
	}
	A2 = A;

	int ans1 = 0, ans2 = 0;
	ans1 = solve(ans1, A, cu);

	if (A2[0] < 0) {
		ans2 = -A2[0] + 1;
		A2[0] = 1;
	}
	else {
		ans2 = A2[0] + 1;
		A2[0] = -1;
	}


	su = 0;
	rep(i, N) {
		su += A2[i];
		cu[i] = su;
	}

	ans2 = solve(ans2, A2, cu);

	cout << min(ans1, ans2) << "\n";

	return 0;

}

