int calc(vector<int>& t, bool topPlus) {
  int parityA, parityB;
  if (topPlus) {
    parityA = 0;
    parityB = 1;
  }
  else {
    parityA = 1;
    parityB = 0;
  }

  int sum = 0;
  int cnt = 0;
  for (int i = 0; i < t.size(); ++i) {
    sum += t.at(i);
    if (i % 2 == parityA && sum <= 0) {
      cnt += (1 - sum);
      sum = 1;
    }
    else if (i % 2 == parityB && sum >= 0) {
      cnt += (1 + sum);
      sum = -1;
    }
//cout << "*" << t.at(i) << " " << cnt << " " << sum << endl;
  }
  return cnt;
}


