static std::uint64_t
solve(const std::vector<int>& va, bool isPositive)
{
  std::int64_t sum = 0;
  std::uint64_t cnt = 0;
  for (std::remove_reference<decltype(va)>::type::size_type i = 0; i < va.size(); i++) {
    auto nextSum = sum + va[i];
    if (nextSum >= 0 && isPositive) {
      cnt += nextSum + 1;
      sum = -1;
    } else if (nextSum <= 0 && !isPositive) {
      cnt += -nextSum + 1;
      sum = 1;
    } else {
      sum = nextSum;
    }
    isPositive = !isPositive;
  }
  return cnt;
}


