template <typename Set>
struct Monoid
{
    using Op = function<Set(Set, Set)>;
    const Op f;
    const Set e;
    Monoid(const Op F, const Set E) : f(F), e(E)
    {
    }
};
template <typename Set>
struct SegmentTree
{
    using Op = function<Set(Set, Set)>;
    Monoid<Set> M;
    Set e;
    int size; //一番下以外の区間たち全部の数
    vector<Set> seg;
    SegmentTree(int n, const Monoid<Set> &M) : M(M)
    {
        size = 1;
        while (size < n)
        {
            size <<= 1;
        }
        e = M.e;
        seg.assign(2 * size, e);
    }
    void set(int k, const Set &x)
    {
        seg[k + size] = x;
    }
    void build()
    {
        for (int k = size - 1; k > 0; k--)
        {
            seg[k] = M.f(seg[2 * k + 0], seg[2 * k + 1]);
        }
    }
    void update(int k, const Set &x)
    {
        k += size;
        seg[k] = x;
        while (k >>= 1)
        {
            seg[k] = M.f(seg[2 * k + 0], seg[2 * k + 1]);
        }
    }
    Set query(int a, int b) //区間[a,b)に対して演算したやつを返す
    {
        Set L = e, R = e;
        for (a += size, b += size; a < b; a >>= 1, b >>= 1) //ループ一回ごとにa,bは親に向かう
        {
            if (a & 1) //a%2==1なら
            {
                L = M.f(L, seg[a++]);
            }
            if (b & 1)
            {
                R = M.f(seg[--b], R);
            }
        }
        return M.f(L, R);
    }
};
int main()
{
    int n;
    cin >> n;
    vint a(n), s(n + 1);
    Monoid<int> M([](int a, int b) { return a + b; }, 0);
    SegmentTree<int> sg(n, M), sg2(n, M);
    rep(i, n)
    {
        cin >> a[i];
        s[i + 1] = s[i] + a[i];
        sg.update(i, a[i]);
        sg2.update(i, a[i]);
    }
    int prev = 1, ans = 0;
    rep(i, n)
    {
        int sum = sg.query(0, i + 1);
        if (sum == 0)
        {
            if (prev < 0)
            {
                sg.update(i, sg.query(i, i + 1) + 1);
            }
            else
            {
                sg.update(i, sg.query(i, i + 1) - 1);
            }
            if (prev != 0)
                prev *= -1;
            else
                prev = 1;
            ans++;
            continue;
        }
        else
        {
            int sgn = sum / abs(sum);
            if (prev == sgn)
            {
                int cnt = -sgn - sum;
                ans += abs(cnt);
                sg.update(i, sg.query(i, i + 1) + cnt);
            }
            prev *= -1;
        }
    }
    prev = -1;
    int ans2 = 0;
    rep(i, n)
    {
        int sum = sg2.query(0, i + 1);
        if (sum == 0)
        {
            if (prev < 0)
            {
                sg2.update(i, sg2.query(i, i + 1) + 1);
            }
            else
            {
                sg2.update(i, sg2.query(i, i + 1) - 1);
            }
            if (prev != 0)
                prev *= -1;
            else
                prev = 1;
            ans2++;
            continue;
        }
        else
        {
            int sgn = sum / abs(sum);
            if (prev == sgn)
            {
                int cnt = -sgn - sum;
                ans2 += abs(cnt);
                sg2.update(i, sg2.query(i, i + 1) + cnt);
            }
            prev *= -1;
        }
    }
    cout << min(ans, ans2);
    return 0;
}

