    amin(ans, f(1) + 1);
    amin(ans, f(-1) + 1);
  } else {
    amin(ans, f(a[0]));
    amin(ans, f(a[0] > 0 ? -1 : 1) + abs(a[0]) + 1);
  }
  cout << ans << endl;
}

