ll add(ll idx, ll minus_max, ll plus_min, ll flag){//flagは小さくするか大きくするかを決めている
    if(idx == 0){
        if(minus_max >= 0) return minus_max+1LL;
        else if(plus_min <= 0) return  -plus_min+1LL;
        return 0;
    }
    else if(flag==0){
        /*小さくする場合*/
        ll change=max(0LL,  sum[idx-1]-(plus_min-2));//どんだけ上にあげるか
        if(idx==n-1){
            return change+add(idx-1, sum[idx-1], plus_min+change, 1LL);
        }
        //cout<<idx<<" "<<change<<endl;
        return change+add(idx-1, max(sum[idx-1], minus_max+change), plus_min+change, 1LL);
    }
    else{
        /*大きくする場合*/
        ll change= max(0LL, (minus_max+2)-sum[idx-1]);
        if(idx==n-1){
            return change+add(idx-1, minus_max-change, sum[idx-1], 0LL);
        }
        //cout<<idx<<" "<<change<<endl;
        return change+add(idx-1, minus_max-change, min(sum[idx-1], plus_min-change), 0LL);
    }
}
