  int flag = 0;
  int count =0;
  int buf;
  for(int i=0; i<N;){
    show();
    if(adder.at(i+1) >0){
      if(flag != 1){
        flag = 1;
        i++;
      }else{
        buf = abs(adder.at(i+1))+1;
        adds(i+1, -buf);
        count += buf;
      }

    }else if(adder.at(i+1) <0){
      if(flag != -1){
        flag = -1;
        i++;
      }else{
        buf = abs(adder.at(i+1))+1;
        adds(i+1, buf);
        count += buf;
      }

    }else{
      if(flag == -1){
        adds(i+1, 1);
        count++;
        flag == 1;
        i++;
      }else if(flag == 1){
        adds(i+1, -1);
        count++;
        flag == -1;
        i++;
      }else{
        if(i == 0){
          adds(i+1,1);
        }

      }
    }

  }

  cout << count <<endl;
  return 0;
}

