using namespace std;


long long f1 (int n, int arr[])
{
    long long ans = 0, sum = 0;
    for(int i=0; i<n; i++){
        sum += arr[i];
        if(i % 2) {
            if(sum <= 0){
                ans += -sum + 1;
                sum = 1;
            }
        }
        else {
            if(sum >= 0){
                ans += sum + 1;
                sum = -1;
            }
        }
    }

    return ans;
}

long long f2 (int n, int arr[])
{
    long long ans = 0, sum = 0;
    for(int i=0; i<n; i++){
        sum += arr[i];
        if(i % 2) {
            if(sum >= 0){
                ans += sum + 1;
                sum = -1;
            }
        }
        else {
            if(sum <= 0){
                ans += -sum + 1;
                sum = 1;
            }
        }
    }

    return ans;
}

