long long INF = (1LL<<62);

long long N;
vector<long long> A, W;
long long S[100002] = {INF*(-1)};
long long dp[100002] = {0};

void calcDP(int n){
	if(n == 1){
		if(W[1] != 0){
			dp[1] = 0;
		}
		else{
			dp[1] = 1;
			if(W[2] <= 0){
				W[1] = 1;
			}
			else{
				W[1] = -1;
			}
			S[1] = W[1];
		}
		return;
	}
	else if(n == 2){
		calcDP(1);
		if(W[1] > 0 && W[1] + W[2] < 0){
			dp[2] = dp[1];
		}
		else if(W[1] > 0 && W[1] + W[2] >= 0){
			dp[2] = dp[1] + abs(W[2] - ( -1 - W[1]));
			W[2] = -1 - W[1];
			S[2] = S[1] + W[2];
		}
		else if(W[1] < 0 && W[1] + W[2] > 0){
			dp[2] = dp[1];
		}
		else if(W[1] < 0 && W[1] + W[2] <= 0){
			dp[2] = dp[1] + abs(W[2] - (1 - W[1]));
			W[2] = 1 - W[1];
			S[2] = S[1] + W[2];
		}
	}
	else{
		S[n] = S[n-1] + W[n];
		if( ( S[n-1] < 0 && S[n] > 0 ) || ( S[n-1] > 0 && S[n] < 0 ) ){
			dp[n] = dp[n-1];
		}
		else{
			long long dpa = -1, dpb = -1, dpc = -1;
			//1つ前も操作する場合
			long long d, w, s;
			if(S[n-2] > 0){
				w = -1 - S[n-2];
				s = S[n-2] + w;
				dpb = dp[n-1] + abs(w - W[n-1]) + abs(1 - s - W[n]);
			}
			else{
				w = 1 - S[n-2];
				s = S[n-2] + w;
				dpb = dp[n-1] + abs(w - W[n-1]) + abs(-1 - s - W[n]);
			}
			//1つ前を操作しない場合
			if(S[n-1] > 0){
				dpc = dp[n-1] + abs(-1 - S[n-1]  - W[n]);
			}
			else{
				dpc = dp[n-1] + abs(1 - S[n-1] - W[n]);
			}
			if(dpc <= dpb){
				dp[n] = dpc;
				if(S[n-1] > 0){
					W[n] = -1 - S[n-1];
				}
				else{
					W[n] = 1 - S[n-1];
				}
			}
			else{
				dp[n] = dpb;
				W[n-1] = w;
				S[n-1] = S[n-2] + W[n-1];
				W[n] = 0 - S[n-1] - ( abs(S[n-1]) / S[n-1] );
			}
			S[n] = S[n-1] + W[n];
		}
		return;
	}
}

int main(int argc, char* argv[]){
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N;
	W.push_back(0);
	S[0] = 0;
	for(int i=1; i<=N; i++){
		long long a;
		cin >> a;
		A.push_back(a);
		W.push_back(a);
		if(i == 1){
			S[1] = a;
		}
		else{
			S[i] = S[i-1] + a;
		}
	}
	for(int i=1; i<=N; i++){
		calcDP(i);
	}
	printf("%lld\n", dp[N]);
	return 0;
}

