int n;


ll rp(ll *a, ll sum, ll cnt){

    for(int j=1; j<n; j++){
        //2つ目からスタート

        if(sum > 0 && sum + a[j] < 0)
        { sum += a[j];
            continue;}//条件を満たしているとき
        if(sum < 0 && sum + a[j] > 0)
        { sum += a[j];
            continue;}
        if(sum < 0 && sum + a[j] <= 0){
            //新しく足した合計が負なので, 正になるまでまわす
            ll dt = 1 - (sum+a[j]);
            cnt += dt;
            a[j] += dt;
            sum += a[j];
            continue;
        }
        if(sum > 0 && sum + a[j] >= 0){
            //新しく足した合計が正なので, 負になるまでまわす
            ll dt = (sum+a[j]) - (-1); //きょり
            cnt += dt;
            a[j] -= dt; //距離分ひく
            sum += a[j];
            continue;
        }
    }

    return cnt;

}

