        a[i] += sumpos ? -1 : 1;
        ++cost;
      }
    }
    if ((sum + a[i]) == 0) {
      a[i] += sumpos ? -1 : 1;
      ++cost;
    }
    sum += a[i];
    positive = !positive;
  }
  return cost;
}

