int zerocount(vector<int>& a ,int i, int n){
	if(a.at(i) != 0){
		return 0;
	}
	if(i == n-1){
		a.at(i) = 1;
		return 1;
	}
	int count = 0;
	count += zerocount(a ,i+1, n);
	if(a.at(i+1)>0){
		a.at(i) = -1;
	}else{
		a.at(i) = 1;
	}
	count++;
	return count;
}

