using ll = long long;

ll solve(vector<ll>& v, int first) {
    ll cost = abs(first - v[0]);
    ll sum =  first;

    for (int i = 1; i < v.size(); ++i) {
        ll after = sum + v[i];
        if (after * sum < 0) {
            sum = after;
        } else {
            cost += abs(after) + 1;
            sum = sum > 0 ? -1 : 1;
        }
    }

    return cost;
}

