        ret = min(ret, solve(v, 1));
        ret = min(ret, solve(v, -1));
    } else {
        ret = min(ret, solve(v, v[0]));
        ret = min(ret, solve(v, v[0] > 0 ? -1 : 1));
    }

    cout << ret << endl;
    return 0;
}

