long long calc_cost(bool ps) {
	long long res,dis;
	res = dis = 0;
	for (int i = 0; i < sum.size(); ++i) {
		long long temp = sum[i] + dis;
		if (i%2 == 0) {
			if (temp == 0) {
				++res;
				if (ps) {
					++dis;
				}
				else {
					--dis;
				}
			}
			else if (ps && temp < 0) {
				res += -temp+1;
				dis += -temp+1;
			}
			else if (!ps && temp > 0) {
				res += temp+1;
				dis -= temp+1;
			}
		}
		else {
			if (temp == 0) {
				++res;
				if (ps) {
					--dis;
				}
				else {
					++dis;
				}
			}
			else if (ps && temp > 0) {
				res += temp+1;
				dis -= temp+1;
			}
			else if (!ps && temp < 0)  {
				res += -temp+1;
				dis += -temp+1;
			}
		}
	}
	return res;
}

