int fplus (int n, int arr[])
{
    int ans = 0, sum = 0;
    for(int i=0; i<n; i++){
        sum += arr[i];
        if(i % 2) {
            if(sum <= 0){
                ans += -sum + 1;
                sum = 1;
            }
        }
        else {
            if(sum >= 0){
                ans += sum + 1;
                sum = -1;
            }
        }
    }

    return ans;
}

int fminus (int n, int arr[])
{
    int ans = 0, sum = 0;
    for(int i=0; i<n; i++){
        sum += arr[i];
        if(i % 2) {
            if(sum >= 0){
                ans += sum + 1;
                sum = -1;
            }
        }
        else {
            if(sum <= 0){
                ans += -sum + 1;
                sum = 1;
            }
        }
    }

    return ans;
}

int main()
{
    int n, a[100000];
    cin >> n;
    for(int i=0; i<n; i++) cin >> a[i];

    int ans = min(fplus(n, a), fminus(n, a));

    cout << ans << endl;

    return 0;
}

