long check(vector<long> a){
	long time = 0;
	long pre_sum = a.at(0);
	int n = a.size();
	if(a.at(0)<0){
		for(int i = 1; i<n; i++){
			long sum = pre_sum + a.at(i);
			if(i%2==1 && sum <= 0){
				time += abs(sum-1);
				sum = 1;
			}else if (i%2==0 && sum >=0){
				time += abs(sum+1);
				sum = -1;
			}
			pre_sum = sum;
		}
	}else if(a.at(0)>0){
		for(int i = 1; i<n; i++){
			long sum = pre_sum + a.at(i);
			if(i%2==0 && sum <= 0){
				time += abs(sum-1);
				sum = 1;
			}else if(i%2==1 && sum >=0){
				time += abs(sum+1);
				sum = -1;
			}
			pre_sum = sum;
		}
	}
	return time;
}

long zerocheck(vector<long> a){
	a.at(0) = 1;
	long time1 = check(a)+1;
	a.at(0) = -1;
	long time2 = check(a)+1;
	long time = min(time1, time2);
	return time;
}

