        if (sumA > 0 && next_sumA >= 0) {
            ll diff = 1 + next_sumA;
            countA += diff;
            a.at(i + 1) -= diff;
            next_sumA -= diff;
        }
        else if (sumA < 0 && next_sumA <= 0) {
            ll diff = 1 - next_sumA;
            countA += diff;
            a.at(i + 1) += diff;
            next_sumA += diff;
        }
        if (sumB > 0 && next_sumB >= 0) {
            ll diff = 1 + next_sumB;
            countB += diff;
            b.at(i + 1) -= diff;
            next_sumB -= diff;
        }
        else if (sumB < 0 && next_sumB <= 0) {
            ll diff = 1 - next_sumB;
            countB += diff;
            b.at(i + 1) += diff;
            next_sumB += diff;
        }
        sumA = next_sumA;
        sumB = next_sumB;
    }

    cout << min(countA, countB) << endl;

