int main(void) {
	// in
	int n;
	std::cin >> n;
	std::vector<long long> a(n);
	for(int i = 0; i < n; ++i) std::cin >> a[i];

	// sum
	long long cost_all = -1;
	std::vector<long long> s(n, 0);

	for(int k = 0; k < 2; ++k) {
		long long cost = 0;
		if(k == 0) {
			s[0] = (a[0] > 0 ? a[0] : 1);
			cost += std::abs(a[0] - s[0]);
		}
		else {
			s[0] = (a[0] < 0 ? a[0] : -1);
			cost += std::abs(a[0] - s[0]);
		}
		for(int i = 1; i < n; ++i) {
			// current sum
			s[i] = s[i-1] + a[i];
			if(s[i] * s[i-1] < 0) continue;
			else {
				if(s[i-1] < 0) {
					cost += std::abs(1 - s[i-1] - a[i]);
					s[i] = s[i-1] + 1 - s[i-1];
				}
				else {
					cost += std::abs(- 1 - s[i-1] - a[i]);
					s[i] = s[i-1] - 1 - s[i-1];
				}
			}
		}
		if(cost_all < 0) cost_all = cost;
		else cost_all = (cost < cost_all ? cost : cost_all);
	}

	std::cout << cost_all << std::endl;

	return 0;
}

