void answer2() {
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int n;
  cin >> n;
  vector<int> a(n);
  for(int& a_i: a) {
    cin >> a_i;
  }

  int count = 0;
  int sum = a.at(0);
  bool is_positive = a.at(0) > 0;
  for (int i = 1; i < a.size(); i++) {
    sum += a.at(i);
    is_positive = ! is_positive;

    if (is_positive) {
      if (sum > 0) {
        continue;
      } else {
        // 次は1になるまでインクリメント
        int diff = 1 - sum;
        count += diff;
        sum += diff;
      }
    } else {
      if (sum < 0) {
        continue;
      } else {
        // 次は2になるまでデクリメント
        int diff = 1 + sum;
        count += diff;
        sum -= diff;
      }
    }
  }
  cout << count << endl;

}

