int zerocount(vector<int>& a ,int i, int n){
	cout << "strart" << endl;
	if(a.at(i) != 0){
		return 0;
	}
	if(i == n-1){
		a.at(i) = 1;
		return 1;
	}
	int count = 0;
	count += zerocount(a ,i+1, n);
	if(a.at(i+1)>0){
		a.at(i) = -1;
	}else{
		a.at(i) = 1;
	}
	count++;
	return count;
}

int main(){
	int n;
	cin >> n;
	vector<int> a(n);
	for(auto& x:a){
		cin >> x;
	}
	bool hugou;
	int sum = 0;
	int count = 0;
	if(a.at(0)<0) {
		hugou = false;
		sum += a.at(0);
	}
	if(a.at(0)>0){
		hugou = true;
		sum += a.at(0);
	}
	if(a.at(0)==0){
		count += zerocount(a, 0, n);
	}
	for(int i = 0; i<n-1; i++){
		int i_sum;
		i_sum = sum + a.at(i+1);
		if(i_sum>=0){
			if(hugou){
				sum = -1;
				count += (i_sum +1);
				hugou = false;
			}else{
				hugou = true;
				sum = i_sum;
			}
		}
		if(i_sum<=0){
			if(!hugou){
				sum = 1;
				count += (-1)*(i_sum-1);
				hugou = true;
			}else{
				hugou = false;
				sum = i_sum;
			}
		}
		}
		if(sum == 0) count++;
		cout << count << endl;
}

