int solve(int sign, vi &a, int n) {
  int cs = 0;
  int ans = 0;
  rep(i,n) {
    cs += a[i];
    if (cs*sign < 1) {
      int diff = 1 - cs*sign;
      ans += diff;
      cs += sign*diff;
    }
    sign *= -1;
  }
  return ans;
}

