#include <bits/stdc++.h>
using namespace std;

const int DIM = 1e5 + 5;

long long arr[DIM];

inline long long solve( int n ) {
    long long sum( arr[1] ), ans( 0 );

    for( int i = 2; i <= n; i ++ ) {
        if( sum < 0 && sum + arr[i] <= 0 )
            ans += 1 - sum - arr[i], sum = 1;
        else
        if( sum > 0 && sum + arr[i] >= 0 )
            ans += 1 + sum + arr[i], sum = -1;
        else
            sum += arr[i];
    }

    return ans;
}

int main( void ) {

    int n;
    cin >> n;

    long long ans( 1e18 );
    for( int i = 1; i <= n; i ++ )
        cin >> arr[i];

    if( arr[1] != 0 )
        ans = solve( n );
    else {
        arr[1] = -1;
        ans = min( ans, solve( n ) + 1 );

        arr[1] = +1;
        ans = min( ans, solve( n ) + 1 );
    }

    cout << ans << endl;
    return 0;
}

