                    sum = 1;
                } else if (tmp == 0) {
                    sum = 1;
                    step++;
                } else {
                    sum = tmp;
                }
            } else { // even is negative
                if (tmp < 0) {
                    sum = tmp;
                } else if (tmp == 0) {
                    sum = -1;
                    step++;
                } else {
                    step += tmp + 1;
                    sum = -1;
                }
            }
        } else { // Odd
            if (evenIsPositive) { // Odd is negative
                if (tmp < 0) {
                    sum = tmp;
                } else if (tmp == 0) {
                    sum = -1;
                    step++;
                } else {
                    step += sum + 1;
                    sum = -1;
                }
            } else { // Odd is positive
                if (tmp < 0) {
                    step += abs(tmp) + 1;
                    sum = 1;
