#include <bits/stdc++.h> 
using namespace std;
using ll = long long;

const int sz = 1e5+5;
int n;
ll a1[sz], a2[sz];

int pos(ll a[sz], ll& sum, int i, ll prev){
    if(sum > 0) return 0;

    ll needtoadd = -sum+1; 
    ll ret = needtoadd;
    if(i >= 1){
        assert(prev < 0);
        ll addtoprev = min(needtoadd, -prev-1);
        a[i-1] += addtoprev; 
        needtoadd -= addtoprev;
    }
    a[i] += needtoadd;
    sum += ret;
    return ret;
}

int neg(ll a[sz], ll& sum, int i, ll prev){
    if(sum < 0) return 0;

    ll needtosub = sum+1;
    ll ret = needtosub;  
    if(i >= 1){
        assert(prev > 0);
        ll subfromprev = min(needtosub, prev-1);
        a[i-1] -= subfromprev; 
        needtosub -= subfromprev;
    }
    a[i] -= needtosub;
    sum -= ret;
    return ret;
}

void solve(){
    cin >> n;
    for(int i = 0; i < n; ++i){
        cin >> a1[i];
        a2[i] = a1[i];
    }

    ll sum1 = 0, sum2 = 0, op1 = 0, op2 = 0;
    for(int i = 0; i < n; ++i){
        sum1 += a1[i];
        sum2 += a2[i];
        if(i%2==0){
            op1 += pos(a1, sum1, i, sum1-a1[i]);
            op2 += neg(a2, sum2, i, sum2-a2[i]);
        }
        else{
            op1 += neg(a1, sum1, i, sum1-a1[i]);
            op2 += pos(a2, sum2, i, sum2-a2[i]);
        }
    }

    cout << min(op1, op2) << '\n';
}

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    solve();
    return 0;
}

