ll calc(vector<ll>& a, int n, int flag) {
  ll ans = 0;
  ll sum = 0;
  rep(i, n) {
    if (i % 2 == flag) {
      if (sum + a[i] < 1) {
        // 足した結果を +1 以上にしたい
        ans += 1 - (sum + a[i]);
        sum = 1;
