typedef long long ll;
const int maxx = 1e5 + 7;
const ll Inf = 1ll << 60;
ll n;
ll a[maxx];
ll ans = Inf;

int main() {
	cin >> n;
	for(int i = 1; i <= n; i++) cin >> a[i];
	bool flg = 0;
	ll sum = 0, res = 0;
	for(int i = 1; i <= n; i++) { // + - + - + - ...
		sum += a[i];
		if(!flg) { // sum为正, flg = 0
			if(sum <= 0) { //若当前sum <= 0, 将sum变为1
				res += 1 - sum; //sum变为1所需要的花费是 1 - sum (sum <= 0)
				sum = 1;
			}
		}
		else { // sum为负, flg = 1
			if(sum >= 0) { //若当前sum >= 0, 将sum变为-1
				res += sum + 1; //sum变为-1所需花费是 sum + 1 (sum >= 0)
				sum = -1;
			}
		}
		flg ^= 1; //flg变号, 按位异或
	}
	ans = min(ans, res);
	sum = res = 0;
	flg = 0;
	for(int i = 1; i <= n; i++) { // - + - + - + ...
		sum += a[i];
		if(!flg) { //sum为负, flg = 0
			if(sum >= 0) { //与上一次进行的O(n)操作同理
				res += sum + 1;
				sum = -1;
			}
		}
		else { //sum为正, flg = 1
			if(sum <= 0) { //与上一次进行的O(n)操作同理
				res += 1 - sum;
				sum = 1;
			}
		}
		flg ^= 1;
	}
	ans = min(ans, res);
	cout << ans << endl;
}

