signed main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  int n;
  cin >> n;
  vector<int> a(n);
  rep(i,n) cin >> a[i];

  // + => - => + => ...
  int sum1 = 0, cost1 = 0;
  rep(i,n) {
    sum1 += a[i];
    //cout << i << " : " << sum1;
    int diff = abs(sum1) + 1;//+1か-1まで動かすための操作回数

    if(i % 2 == 0 && sum1 < 0) {sum1 += diff; cost1 += diff;}
    if(i % 2 == 1 && sum1 > 0) {sum1 -= diff; cost1 += diff;}

    if(sum1 == 0) {
      if(i % 2 == 0) {sum1++; cost1++;}
      if(i % 2 == 1) {sum1--; cost1++;}
    }
    //cout << " => " << sum1 << " コストは" << cost1 << endl;
  }

  // - => + => - => ...
  int sum2 = 0, cost2 = 0;
  rep(i,n) {
    sum2 += a[i];
    //cout << i << " : " << sum2;
    int diff = abs(sum2) + 1;//+1か-1まで動かすための操作回数

    if(i % 2 == 0 && sum2 > 0) {sum2 -= diff; cost2 += diff;}
    if(i % 2 == 1 && sum2 < 0) {sum2 += diff; cost2 += diff;}

    if(sum2 == 0) {
      if(i % 2 == 0) {sum2--; cost2++;}
      if(i % 2 == 1) {sum2++; cost2++;}
    }
    //cout << " => " << sum2 << " コストは" << cost2 << endl;
  }

  cout << min(cost1, cost2) << endl;
  return 0;
}
