int main()
{
  int N;
  cin >> N;
  vector<ll> a(N);
  for (int i = 0; i < N; i++) {
    cin >> a[i];
  }

  ll ans = 0;
  while (ans < N && a[ans] == 0) ans++;

  ll sum;
  if (ans == 0) sum = a[0];
  else if (ans < N && a[ans + 1] > 0) sum = -1;
  else sum = 1;

  for (int i = ans + 1; i < N; i++) {
    //cout << sum << ' ' << (sum + a[i]) << endl;
    if (sum * (sum + a[i]) >= 0) {
      if (sum + a[i] >= 0) {
        // sum > 0, sum + a[i] >= 0
        // sum + a[i] = -1になるように変える
        // sum + (-sum - 1) = -1
        // a[i] -> -sum - 1
        ans += abs(sum + a[i] + 1);
        //cout << "cost : " << abs(sum + a[i] + 1) << endl;
        a[i] = -sum - 1;
      } else {
        // sum < 0, sum + a[i] < 0
        // sum + a[i] = 1 になるように変える
        // sum + (-sum + 1) = 1
        // a[i] -> -sum + 1
        ans += abs(sum + a[i] - 1);
        //cout << "cost : " << abs(sum + a[i] - 1) << endl;

        a[i] = -sum + 1;
      }
    }
    sum += a[i];
  }
  cout << ans << endl;

  return 0;
}

