int sign(LL n) { return n == 0 ? 0 : n / abs(n); }
int main() {
  int n;
  cin >> n;
  VEC<LL> a(n);
  REP(i, 0, n) { cin >> a[i]; }
  auto make = [&](LL tgt) -> LL {
    VEC<LL> cur(n, 0);
    cur[0] = a[0];
    LL cnt = 0;

    if (sign(cur[0]) != sign(tgt)) {
      cnt += abs(a[0] - tgt);
      cur[0] = tgt;
    }
    // DUMP(tgt, a);
    // DUMP(0, cnt, cur);
    REP(i, 1, n) {
      tgt = -tgt;
      cur[i] = cur[i - 1] + a[i];

      if (sign(cur[i]) != sign(tgt)) {
        cnt += abs(cur[i] - tgt);
        cur[i] = tgt;
      }
      // DUMP(i, cnt, cur);
    }
    return cnt;
  };
  cout << min(make(1), make(-1)) << endl;

  return 0;
}

