using ll = long long;

int N;
int A[100005];

// 結果の数列は+始まりか-始まりのいずれか
void solve()
{
    ll cost1 = 0;
    ll cost2 = 0;
    ll s;

    // +始まり
    s = 0;
    REP(i, N) {
        // S[i] が偶数番目で0なら A[i] を1増やせば S[i] = 1 となる
        if(s+A[i] == 0 && i%2 == 0) {
            cost1 += 1;
            s = 1;
        }
        // S[i] が奇数番目で0なら A[i] を1減らせば S[i] = -1 となる
        else if(s+A[i] == 0 && i%2 == 1) {
            cost1 += 1;
            s = -1;
        }
        // S[i] が偶数番目で正なら操作は不要。S[i] = S[i-1] + A[i]
        else if(s+A[i] > 0 && i%2 == 0) {
            s += A[i];
        }
        // S[i] が奇数番目で正なら A[i] を |S[i]|+1 減らせば S[i] = -1 となる
        else if(s+A[i] > 0 && i%2 == 1) {
            cost1 += abs(s+A[i]) + 1;
            s = -1;
        }
        // S[i] が偶数番目で負なら A[i] を |S[i]|+1 増やせば S[i] = 1 となる
        else if(s+A[i] < 0 && i%2 == 0) {
            cost1 += abs(s+A[i]) + 1;
            s = 1;
        }
        // S[i] が奇数番目で負なら操作は不要。S[i] = S[i-1] + A[i]
        else if(s+A[i] < 0 && i%2 == 1){
            s += A[i];
        }

#ifdef DEBUG
        cout << "s:     " << s << "\n";
        cout << "cost1: " << cost1 << "\n";
#endif
    }

    // -始まり
    s = 0;
    REP(i, N) {
        // S[i] が偶数番目で0なら A[i] を1減らせば S[i] = -1 となる
        if(s+A[i] == 0 && i%2 == 0) {
            cost2 += 1;
            s = -1;
        }
        // S[i] が奇数番目で0なら A[i] を1増やせば S[i] = 1 となる
        else if(s+A[i] == 0 && i%2 == 1) {
            cost2 += 1;
            s = 1;
        }
        // S[i] が偶数番目で正なら A[i] を |S[i]|+1 減らせば S[i] = -1 となる
        else if(s+A[i] > 0 && i%2 == 0) {
            cost2 += abs(s+A[i]) + 1;
            s = -1;
        }
        // S[i] が奇数番目で正なら操作は不要。S[i] = S[i-1] + A[i]
        else if(s+A[i] > 0 && i%2 == 1) {
            s += A[i];
        }
        // S[i] が偶数番目で負なら操作は不要。S[i] = S[i-1] + A[i]
        else if(s+A[i] < 0 && i%2 == 0){
            s += A[i];
        }
        // S[i] が奇数番目で負なら A[i] を |S[i]|+1 増やせば S[i] = 1 となる
        else if(s+A[i] < 0 && i%2 == 1) {
            cost2 += abs(s+A[i]) + 1;
            s = 1;
        }

#ifdef DEBUG
        cout << "s:     " << s << "\n";
        cout << "cost2: " << cost2 << "\n";
#endif
    }

    cout << min(cost1, cost2) << "\n";
}

