static int
solve(int N, vector<int> &a)
{
  int count_a = 0;
  int count_b = 0;
  int sum_a = 0;
  int sum_b = 0;
  int sign_a = 1;
  int sign_b = -1;
  for (int n = 0; n < N; n++)
  {
    int val = a[n];
    sum_a += val;
    sum_b += val;
    if (sum_a * sign_a <= 0)
    {
      count_a += 1 - (sum_a * sign_a);
      sum_a = sign_a;
    }
    if (sum_b * sign_b <= 0)
    {
      count_b += 1 - (sum_b * sign_b);
      sum_b = sign_b;
    }
    sign_a = -sign_a;
    sign_b = -sign_b;
  }
  return min(count_a, count_b);
}

