  bool pos = (a[0] > 0);
  int sum = a[0];
  FOR(i, 1, a.size()) {
    sum += a[i];
    if ((pos && i % 2 && sum >= 0) || (pos && !(i % 2) && sum <= 0) ||
        (!pos && i % 2 && sum <= 0) || (!pos && !(i % 2) && sum >= 0)) {
      ret = false;
      break;
    }
  }
  return ret;
}

int solve(vi a, int res) {
  int sum = a[0];
  bool pos = (a[0] > 0);
  FOR(i, 1, a.size()) {
    if ((pos && i % 2 && sum + a[i] >= 0) ||
        (!pos && !(i % 2) && sum + a[i] >= 0)) {
      while (true) {
        a[i]--;
        res++;
        if (sum + a[i] == -1) break;
      }
    } else if ((pos && !(i % 2) && sum + a[i] <= 0) ||
               (!pos && i % 2 && sum + a[i] <= 0)) {
      while (true) {
        a[i]++;
        res++;
        if (sum + a[i] == 1) break;
      }
    }
    sum += a[i];
  }
  return res;
}

