template<typename T = ll> class BIT {
public:
	BIT( T n ) {
		v.resize( n + 1, 0 );
		size = n;
	}

	ll sum( T i ) {
		T ans = 0;
		while ( i > 0 ) {
			ans += v[i];
			i -= i & -i;
		}

		return ( ans );
	}

	void add( T i, T val ) {
		while ( i <= size ) {
			v[i] += val;
			i += i & -i;
		}
	}

private:
	vector<T> v;
	T size;
};

int main()
{
	ll N; cin >> N;
	vector<ll> v( N );
	rep( i, N ) cin >> v[i];

	auto solve = []( const vector<ll> &v, bool flg ) {
		ll N = v.size();
		BIT<ll> bit( N );
		rep( i, N ) bit.add( i + 1, v[i] );

		ll ans = 0;
		rep( i, N )
		{
			ll s = bit.sum( i + 1 );
			if ( ( s >= 0 ) && flg )
			{
				bit.add( i + 1, - ( s + 1 ) );
				ans += s + 1;
			}
			else if ( ( s <= 0 ) && !flg )
			{
				bit.add( i + 1, 1 - s );
				ans += 1 - s;
			}
			flg ^= 1;
		}

		return ( ans );
	};

	ll ans1 = solve( v, true );
	ll ans2 = solve( v, false );

	cout << min( ans1, ans2 ) << endl;

	return ( 0 );
}

