long long int func(int start_polarity, std::vector<long long int>& a, int n) {
  long long int count = 0;
  signed long long sum = 0;
  for (int i = 0; i < n; i++) {
    sum += a[i];
    if ((start_polarity == +1 && (i % 2 == 1)) ||
        (start_polarity == -1 && (i % 2 == 0))) {
      //std::cout << "-" << sum << std::endl;
      if(sum >= 0) {
        count += sum + 1;
        sum = -1;
      }
    } else if ((start_polarity == +1 && (i % 2 == 0)) ||
               (start_polarity == -1 && (i % 2 == 1))) {
      //std::cout << ":" << sum << std::endl;
      if(sum <= 0) {
        count += -sum + 1;
        sum = 1;
      }
    }
  }
  return count;
}

