// ジグザグにするために必要なコスト
// B[0]は適切に設定されているとする
ll f(VI B){
  ll N = SZ(B);
  ll cost=0;
  ll sum = B[0];
  FOR(i,1,N){
    if(sum>0){
      // 今回は負にする必要
      sum += B[i];
      if(sum<0){
        continue;
      }else{
        // sum>=0である
        cost += sum+1;
        sum = -1;
      }
    }
    else{
      // 今回は正にする必要
      sum += B[i];
      if(sum>0){
        continue;
      }
      else{
        // sum<=0
        cost += abs(sum)+1;
        sum=1;
      }
    }
  }
  return cost;
}

