int check(vector<int> a){
	int time = 0;
	int pre_sum = a.at(0);
	int n = a.size();
	if(a.at(0)<0){
		for(int i = 1; i<n; i++){
			int sum = pre_sum + a.at(i);
			if(i%2==1 && sum <= 0){
				time += abs(sum-1);
				sum = 1;
			}else if (i%2==0 && sum >=0){
				time += abs(sum+1);
				sum = -1;
			}
			pre_sum = sum;
		}
	}else if(a.at(0)>0){
		for(int i = 1; i<n; i++){
			int sum = pre_sum + a.at(i);
			if(i%2==0 && sum <= 0){
				time += abs(sum-1);
				sum = 1;
			}else if(i%2==1 && sum >=0){
				time += abs(sum+1);
				sum = -1;
			}
			pre_sum = sum;
		}
	}
	return time;
}

int zerocheck(vector<int> a){
	a.at(0) = 1;
	int time1 = check(a)+1;
	a.at(0) = -1;
	int time2 = check(a)+1;
	int time = min(time1, time2);
	return time;
}

