    ios::sync_with_stdio(false);
    int n;
    in >> n;
    vector<long long int> a(n), p(n);
    for (int i = 0; i < n; ++i) {
      in >> a[i];
    }
//    int res = 0;
    long long int steps = 0;
    long long int steps2 = 0;

    if (a[0] == 0) {
      a[0] = 1;
      ++steps;
    }
    p[0] = a[0];
    for (int i = 0; i < n - 1; ++i) {
      p[i + 1] = p[i] + a[i + 1];
      if (sgn(p[i]) != -sgn(p[i + 1])) {
        steps += abs(p[i + 1]) + 1;
        p[i + 1] = -sgn(p[i]);
      }
    }
    steps2 = abs(a[0]) + 1;
    p[0] = -sgn(p[0]);
    for (int i = 0; i < n - 1; ++i) {
      p[i + 1] = p[i] + a[i + 1];
      if (sgn(p[i]) != -sgn(p[i + 1])) {
        steps2 += abs(p[i + 1]) + 1;
        p[i + 1] = -sgn(p[i]);
      }
    }

    steps = min(steps, steps2);
    out << steps << endl;
  }

};


