    FOR(n) {
        sum += a[i];

        if (i % 2 == 0 && sum <= 0) {
            ans += (1 - sum);
            sum = 1;
        }
        else if (i & 1 && sum >= 0) {
            ans += (1 + sum);
            sum = -1;
        }
    }

    return ans;
}

int odd(vt<int> a) {
    int ans = 0;
    int n = a.size();
    int sum = 0;

    FOR(n) {
        sum += a[i];

        if (i % 2 == 0 && sum >=0) {
            ans += (1 + sum);
            sum = -1;
        }
        else if (i & 1 && sum <= 0) {

            ans += (1 - sum);
            sum = 1;
        }
    }

    return ans;
}

