long long solve(const vector<int> data, int sign) {

    int n = data.size();
    vector<int> a = data;

    long long sum = 0;
    long long result = 0;
    for(int i=0; i<n; i++) {
        if(i%2==0) {
            long long delta = (sum + a[i]) * sign;
            if(delta <= 0) {
                result += -delta + 1;
                a[i] += (-delta + 1) * sign;
            }
        }
        else {
            long long delta = (sum + a[i]) * sign;
            if(delta >= 0) {
                result += delta + 1;
                a[i] -= (delta + 1) * sign;
            }
        }
        sum += a[i];
    }
    return result;
}


