int N;

int sign(ll v){
    if(v > 0){
        return 1;
    }else if(v == 0){
        return 0;
    }else{
        return -1;
    }
}

ll calc(ll count, ll sum){
    FOR(i, 1, N){
        ll nextSum = sum + a[i];
        if(nextSum == 0){
            if(sign(sum) > 0){
                nextSum = -1;
            }else{
                nextSum = 1;
            }
            count += 1;
        }
        else if(sum * nextSum < 0){
            // do nothing
        }else{
            ll diff;
            if(sign(sum) > 0){
                diff = -1 - nextSum;
                nextSum += diff;
            }else{
                diff = 1 - nextSum;
                nextSum += diff;
            }
            count += abs(diff);
        }
        sum = nextSum;
    }
    return count;
}

