ll N;  
vector<ll> A;

ll calc(){
	ll cost = 0;
	ll sum=0;
	rep(i, 0, N-1){
		sum+=A[i];
		if (i%2==0 && sum<=0){
			cost += abs(1-sum);
			sum=1;
		}
		else if (i%2==1 && sum>=0){
			cost += abs(-1-sum);
			sum=-1;
		}
	}
	return cost;
}

void solve()
{
	cin >> N;
	A = cinv<ll>(N);

	ll ans = calc();

	rep(i, 0, N-1) A[i] = -A[i];
	chmin(ans, calc());

	cout << ans << '\n';
}

