ll cal(vector<ll>& A, int N, int start)
{
  ll ret = 0;
  ll diff = 0;
  for (int i = 1, sign = start; i <= N; ++i, sign *= -1) {
    ll val = A[i] + diff;
    if (sign > 0 and val <= 0) {
      ret += abs(val) + 1;
      diff += abs(val) + 1;
    }
    else if (sign < 0 and val >= 0) {
      ret += val + 1;
      diff -= val + 1;
    }
  }
  return ret;
}

