int main() {
  int n;
  int A[100001];
  cin >> n;
  for(int i = 0; i < n; i++) {
    cin >> A[i];
  }

  int sum = 0;
  int counter = 0;
  // 偶数番目が正
  for(int i = 0; i < n; i++) {
    sum += A[i];

    if(i % 2 == 0) {
      while(sum <= 0){
        sum++;
        counter++;
      }
    } else {
      while(sum >= 0){
        sum--;
        counter++;
      }
    }
  }

  int counterNeg = 0;
  sum = 0;
  // A[0] < 0
  for(int i = 0; i < n; i++) {
    sum += A[i];

    if(i % 2 == 0) {
      while(sum >= 0){
        sum--;
        counterNeg++;
      }
    } else {
      while(sum <= 0){
        sum++;
        counterNeg++;
      }
    }
  }

  int ans = counter > counterNeg ? counterNeg : counter;
  cout << ans << endl;
  return 0;
}

