                        sum = -1;
                    }
                    count++;
                }
            }
        }
    }

    ll sum2 = 0;
    ll count2 =0;
    REP(i,n){
        if(i == 0){
            sum2+=a[i];
            if(sum2 == 0&&n!=1){
                sum2 = -1;
                count2++;
            }else if(sum2 == 0 && n == 1){count2++;}
        }else{
            ll was = sum2;
