int N;
int A[100010];

lint solve(int n)
{
	lint ret=0;
	lint tmp=0,sum=0;
	for(int i=0;i<N;i++)
	{
		tmp=sum+A[i];
		if(n%2==0)
		{
			if(i%2==0)
			{
				if(tmp<=0)
				{
					tmp=1;
					ret+=abs(tmp-sum-A[i]);
				}
			}
			else
			{
				if(tmp>=0)
				{
					tmp=-1;
					ret+=abs(tmp-sum-A[i]);
				}
			}
		}
		else
		{
			if(i%2==0)
			{
				if(tmp>=0)
				{
					tmp=-1;
					ret+=abs(tmp-sum-A[i]);
				}
			}
			else
			{
				if(tmp<=0)
				{
					tmp=1;
					ret+=abs(tmp-sum-A[i]);
				}
			}
		}
		sum=tmp;
	}
	return ret;
}

