ll solve(int a[], int x, int y) {
	ll sum = 0, cnt = 0, res = INF;
	for (int i = 0; i < n; i++) {

		if (sum + a[i] == 0) {
			(a[i] >= 0 ? a[i]++ : a[i]--);
			cnt++;
		}

		sum += a[i];

		if (i % 2 == x && sum < 0) {
			cnt += abs(sum) + 1;
			sum = 1;
		}
		if (i % 2 == y && sum > 0) {
			cnt += abs(sum) + 1;
			sum = -1;
		}
	}

	res = min(res, cnt);

	return res;
}

