#define POSITIVE 1
#define ZERO -1
#define NEGATIVE -1
#define SWAP_SIGN(s) (s * -1)

using namespace std;


int getsign(long long int n){
	if(n > 0){
		return POSITIVE;
	}
	if(n < 0){
		return NEGATIVE;
	}
	return ZERO;
}

long long int count(int sign0, vector<long long> a, int n){
	long long int sum = 0;
	long long int sign = sign0;
	long long int count = 0;

	for(int i=0; i<n; ++i){
		sum += a[i];
		if (getsign(sum) != sign){
			count += abs(sign - sum);
			sum = sign;
		}
		sign = SWAP_SIGN(sign);
	}

	return count;
}



int main(){
	int n;

	cin >> n;

	vector<long long> a(n);

	for(int i=0;i<n;++i){
		cin >> a[i];
	}

	cout << min(count(POSITIVE,a,n),count(NEGATIVE,a,n)) << endl;
	return 0;
}

