int atcoder(){
    //入力
    int n;
    cin >> n;
    ll ans = 0;
    ll a[110000]={};
    ll notzero = 0;
    for(int i=0; i<n; ++i){
        cin >> a[i];
        if(notzero==i && a[i]==0) notzero++;
    }
    ll tmpsum = a[0];

    //処理
    if(notzero%2 == 1){
        if(a[notzero]>0){
            ans++;
            tmpsum=-1;
        }else{
            ans++;
            tmpsum=1;
        }
    }else if(notzero%2==0 && notzero!=0){
        if(a[notzero]>0){
            ans++;
            tmpsum=1;
        }else{
            ans++;
            tmpsum=-1;
        }
    }

    for(auto i=1; i<n; ++i){
        if(tmpsum*(a[i]+tmpsum)>=0){
            if(a[i]+tmpsum>0){
                ans += a[i]+tmpsum+1;
                tmpsum = -1;
            }else if(a[i]+tmpsum<0){
                ans += -(a[i]+tmpsum)+1;
                tmpsum = 1;
            }else{
                ans++;
                if(tmpsum<0) tmpsum = 1;
                else if(tmpsum>0) tmpsum = -1;
            }
        }else tmpsum += a[i];
    }

    //出力
    cout << ans << ENT;
    return 0;
}

