ll seq(vector<ll> &a, ll sum, int beg, ll count){
	ll prev;
	while ( beg < a.size() ){
		prev = sum;
		sum += a[beg];
		if ( (sum ^ prev) >= 0LL || sum == 0LL ){
			if ( prev > 0 ){
				count += sum + 1;
				sum = -1;
			}else{
				count += 1 - sum;
				sum = 1;
			}
		}
		beg++;
	}
	return count;
}

