#include <iostream>
using namespace std;

long long solve(int* a, int n) {
	long long count = 0;
	long long calc = 0;
	int state, pstate;
	if (a[0] < 0) state = -1;
	if (a[0] > 0) state = 1;
	for (int i = 1; i < n; i++) {
		pstate = state;
		int tmp = a[i] + calc;
		if (tmp < 0) state = -1;
		if (tmp == 0) state = 0;
		if (tmp > 0) state = 1;
		if (pstate == state) {
			if (state == -1) {
				count += 1 - tmp;
				calc += 1 - tmp;
				state = 1;
			}
			else if (state == 1) {
				count += tmp + 1;
				calc += -1 - tmp;
				state = -1;
			}
		}
		if (state == 0) {
			if (pstate == -1) {
				count += 1;
				calc += 1;
				state = 1;
			}
			else if (pstate == 1) {
				count += 1;
				calc += -1;
				state = -1;
			}
		}
	}
	return count;
}

