Int solve(int n, const V& as, int s){
    Int sum = 0;
    Int ans = 0;
    for(auto a : as){
        sum += a;
        if(sign(sum) != s){
            ans += abs(sum - s);;
            sum -= sum - s;
            if(sum == 0){
                ans++;
                sum += s;
            }
        }
        s *= -1;
    }
    return ans;
}

Int solve(int n, V& as){
    return min(solve(n, as, 1), solve(n, as, -1));
}


