int64_t min(int64_t a,int64_t b) {
    if (a > b)
    {
        return b ;
    }else
    {
        return a ;
    }
}

int64_t solve(vector<int> a){
    bool nextposi = (a.at(0) < 0) ;
    int ans = 0 ;
    int sum = a.at(0) ;
    for (int i = 1; i < a.size(); i++)
    {
        sum += a.at(i) ;
        if (nextposi != (sum > 0))
        {
            if (nextposi == 1)
            {
                ans += abs(sum - 1) ;
                sum = 1 ;
            }else
            {
                ans += abs(sum + 1) ;
                sum = -1 ;
            }


        }

        nextposi = !nextposi ;
    }
    return ans ;

}

