    if (a.at(0) == 0)
    {
        a.at(0) = 1 ;
        ans = solve(a) ;
        a.at(0) = -1 ;
        ans = min(ans,solve(a)) + 1;
    }else
    {
        ans = solve(a) ;
    }

    cout << ans << endl ;
}

