int n;

int solve(vector<int> a) {
	int sum = a[0];
	int ans = 0;
	FOR(i, 1, n) {
		if (sum >= 0 and (sum + a[i]) >= 0) {
			while (sum + a[i] != -1) {
				a[i]--;
				ans++;
			}
		}
		else if (sum < 0 and (sum + a[i]) < 0) {
			while (sum + a[i] != 1) {
				a[i]++;
				ans++;
			}
		}
		sum += a[i];
	}
	if (sum == 0)
		ans++;
	return ans;
}

