	// negative first
	rep(i, n) {
		ll num = S[i] + add;

		// positive
		if (i % 2 == 1) {
			if (num > 0) continue;
			add += 1 - num;
			tmp += abs(1 - num);
		}
		// negative
		else {
			if (num < 0) continue;
			add += -1 - num;
			tmp += abs(-1 - num);
		}
	}
	ans = min(ans, tmp);

	cout << ans << endl;

