        cin >> A[i];

    long long sum1 = 0, res1 = 0;
    for (int i = 0; i < N; i++) {
        sum1 += A[i];
        if (i % 2 == 0 && sum1 <= 0) {
            res1 += (1 - sum1);
            sum1 = 1;
        }
        if (i % 2 == 1 && sum1 >= 0) {
            res1 += (sum1 + 1);
            sum1 = -1;
        }
