    for (int i = 0; i < N; i++) {
        sum2 += A[i];
        if (i % 2 == 0 && sum2 >= 0) {
            res2 += (1 + sum2);
            sum2 = -1;
        }
        if (i % 2 == 1 && sum2 <= 0) {
            res2 += (1 - sum2);
            sum2 = 1;
        }
    }

    cout << min(res1, res2) << endl;
    return 0;
}

