const long long INF = 1LL<<60;

ll foo(const vector<ll>& a, bool oddPositive)
{
  size_t n = a.size();

  vector<ll> b1(n);
  ll ans = 0;
  b1[0] = a[0];
  if (oddPositive && a[0] <= 0) {
    b1[0] = 1;
    ans += abs(a[0] + 1);
  }

  if (!oddPositive && a[0] => 0) {
    b1[0] = -1;
    ans += abs(a[0] + 1);
  }

  for (int i = 1; i < n; i++) {
    if ((b1[i-1] + a[i]) * b1[i-1] < 0) {
      b1[i] = b1[i-1] + a[i];
      continue;
    }
    if (a[i] + b1[i-1] == 0) {
      ans += 1;
    } else if (b1[i-1] * a[i] > 0) {
      // a[i], b[i-1] の符号が同じ
      ans += abs(a[i]) + abs(b1[i-1]) + 1;
    } else {
      // a[i], b[i-1] の符号が逆
      ans += abs(b1[i-1]) - abs(a[i]) + 1;
    }
    b1[i] = b1[i-1] < 0 ? 1 : -1;
  }
  return ans;
}

int main() {
  int n;
  cin >> n;
  vector<ll> a(n);
  rep(i, n) {
    ll tmp = 0;
    cin >> tmp;
    a[i] = tmp;
  }

  ll ans1 = foo(a, true);   // 奇数番目が正の数
  ll ans2 = foo(a, false);  // 奇数番目が負の数

  cout << min(ans1, ans2) << endl;

  return 0;
}

