ll solve(bool flag, ll sum) {
  ll res = 0;
  for (int i = 0; i < n; i++) {
    sum += a[i];
    if (flag) {
      if (sum >= 0) {
        res += sum + 1;
        sum = -1;
      }
    }
    else {
      if (sum <= 0) {
        res += -sum + 1;
        sum = 1;
      }
    }
    flag = !flag;
  }
  return res;
}

