        dp2[0] = a[0];
    }
    rep(i, 1, n){
        if(dp1[i-1] < 0){
            if(dp1[i-1] + a[i] > 0){
                dp1[i] = dp1[i-1] + a[i];
            }else{
                dp1[i] = 1;
                ans1 += 1 - (dp1[i-1] + a[i]);
            }
        }else{
            if(dp1[i-1] + a[i] < 0){
                dp1[i] = dp1[i-1] + a[i];
            }else{
                dp1[i] = -1;
                ans1 += (dp1[i-1] + a[i]) - (-1);
            }
        }


        if(dp2[i-1] < 0){
            if(dp2[i-1] + a[i] > 0){
                dp2[i] = dp2[i-1] + a[i];
            }else{
                dp2[i] = 1;
                ans2 += 1 - (dp2[i-1] + a[i]);
            }
        }else{
            if(dp2[i-1] + a[i] < 0){
                dp2[i] = dp2[i-1] + a[i];
            }else{
                dp2[i] = -1;
                ans2 += (dp2[i-1] + a[i]) - (-1);
            }
        }
    }

    cout << min(ans1, ans2) << endl;
    return 0;
}

