struct BIT{
    int N;
    VI bit; 
    BIT(VI s) : N(s.size()), bit(N, 0)  { 
        rep(i, 0, N) add(i, s[i]); //O(NlogN)
    }
    void add(int a, int w) { // v[a] += w. O(logN)
        for (int x = a; x < N;  x |= x + 1) bit[x] += w;
    }
    int sum(int a) { // [0, a) 和
        int ret = 0;
        for (int x = a - 1; x >= 0; x = (x & (x + 1)) - 1) 
            ret += bit[x];
        return ret;
    }
    int parsum(int a, int b){ // [a, b) 和.
        return sum(b) - sum(a);
    }
};

