int64_t solve(vector<int> a,bool next){
    bool nextposi = next ;
    int64_t ans = 0 ;
    int64_t sum = 0 ;
    for (int i = 0; i < a.size(); i++)
    {
        sum += a.at(i) ;
        if (nextposi != (sum > 0))
        {
            if (nextposi == 1)
            {
                ans += abs(sum - 1) ;
                sum = 1 ;
            }else
            {
                ans += abs(sum + 1) ;
                sum = -1 ;
            }


        }

        nextposi = !nextposi ;
    }
    return ans ;

}

