    {
        a.at(0) = 1 ;
        ans = min(solve(a,0),solve(a,1)) ;
        a.at(0) = -1 ;
        int64_t ansp = min(solve(a,0),solve(a,1)) ;
        ans = min(ans,ansp) + 1;
    }else
    {
        ans = min( solve(a,0), solve(a,1) ) ;
    }

