long long N;
vector<long long> A, W;
long long S[100002] = {INF*(-1)};
long long dp[100002] = {0};

int sign = 0;
int b;

void calcDP(int n){
	if(n == 1){
		if(sign == 1){
			if(W[1] > 0){
				dp[1] = 0;
			}
			else{
				dp[1] = abs(1 - W[1]);
				W[1] = 1;
			}
		}
		else if(sign == -1){
			if(W[1] < 0){
				dp[1] = 0;
			}
			else{
				dp[1] = abs(-1 -W[1]);
				W[1] = -1;
			}
		}
		S[1] = W[1];
		return;
	}
	else{
		S[n] = S[n-1] + W[n];
		if( ( S[n-1] < 0 && S[n] > 0 ) || ( S[n-1] > 0 && S[n] < 0 ) ){
			dp[n] = dp[n-1];
		}
		else{
			if(S[n-1] > 0){
				dp[n] = dp[n-1] + abs(-1 - S[n-1]  - W[n]);
				W[n] = -1 - S[n-1];
			}
			else{
				dp[n] = dp[n-1] + abs(1 - S[n-1] - W[n]);
				W[n] = 1 - S[n-1];
			}
			S[n] = S[n-1] + W[n];
		}
		return;
	}
}

int main(int argc, char* argv[]){
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N;
	W.push_back(0);
	S[0] = 0;
	long long m = 0;
	b = 1;
	for(int i=1; i<=N; i++){
		long long a;
		cin >> a;
		A.push_back(a);
		W.push_back(a);
		if(i == 1){
			S[1] = a;
		}
		else{
			S[i] = S[i-1] + a;
		}
		if(abs(a) > m){
			m = abs(a);
			b = i;
		}
	}
	if((b % 2) == 1){
		sign = abs(W[b]) / W[b];
	}
	else{
		sign = (abs(W[b]) / W[b]) * (-1);
	}

	for(int i=1; i<=N; i++){
		calcDP(i);
	}
	printf("%lld\n", dp[N]);
	return 0;
}

