                    ans_even += abs(tmp-1);
                    s_even[i] = 1;
                }
            }
        } else {
            ll tmp = s_even[i-1] + a[i];
            if(tmp<=-1) {
                s_even[i] = tmp;
            } else {
                ans_even += abs(tmp+1);
                s_even[i] = -1;
            }
        }
        // s[2m] < -1 & s[2m+1] > 1 のパターン
        if(i%2==0) {
            if(i==0) {
                if(a[0]<=-1) {
                    s_odd[i] = a[i];
                } else {
                    ans_odd += abs(a[i]+1);
                    s_odd[i] = -1;
                }
            } else {
                ll tmp = s_odd[i-1] + a[i];
                if(tmp<=-1) {
                    s_odd[i] = tmp;
                } else {
                    ans_odd += abs(tmp+1);
                    s_odd[i] = -1;
                }
            }
        } else {
            ll tmp = s_odd[i-1] + a[i];
            if(tmp>=1) {
                s_odd[i] = tmp;
            } else {
                ans_odd += abs(tmp-1);
                s_odd[i] = 1;
            }
        }
    }
    cout << min(ans_even, ans_odd) << endl;

    return 0;
}

