                a[i]++;
                q=1;
            }
            else
            {
                h++;
                a[i]--;
                q=1;
            }
        }
        else if(s<0)
        {
            int foo=abs(s);
            if(q==0)
            {
                h+=(foo+1);
                a[i]+=(foo+1);
                s+=(foo+1);
                q=1;
            }
            else
            {
                q=0;
