            int foo=(s);
            if(q==1)
            {
                h+=(foo+1);
                a[i]-=(foo+1);
                s-=(foo+1);
                q=0;
            }
            else
            {
                q=1;
            }
        }
        //cout<<"h=="<<h<<endl;
    }
    for(int i=0;i<n;i++)
