                if(sum+A[i]<=0){
                    counter += (-(sum+A[i])+1);
                    A[i] = (-sum+1);
                }
                sum += A[i];
            }
        }
        // for(int i=0;i<N;i++){
        //     cout << A[i] << " ";
        // }
