vector<int> num;

long long sequence(int s) {
  long long sum = s;
  long long res = 0;

  for (int i = 1; i < num.size(); i++) {
    if (sum > 0) {
      if (sum + num[i] >= 0) {
        res += 1 + num[i] + sum;
        sum = -1;
      } else {
        sum += num[i];
      }
    } else {
      if (sum + num[i] <= 0) {
        res += 1 - num[i] - sum;
        sum = 1;
      } else {
        sum += num[i];
      }
    }
  }

  return res;
}

