  long long ans2;

  if (num[0] == 0) {
    ans1 = sequence(1) + 1;
    ans2 = sequence(-1) + 1;
  } else if (num[0] > 0) {
    ans1 = sequence(num[0]);
    ans2 = sequence(-1) + num[0] + 1;
  } else {
    ans1 = sequence(1) + abs(num[0]) + 1;
    ans2 = sequence(num[0]);
  }

  printf("%d", min(ans1, ans2));
}

