typedef long long ll;

const int INF = 1e9;
const ll LLINF = 1e18;
const ll MOD = (ll)1e9 + 7;

ll cal(vector<ll>& A, int sign)
{
  int n = A.size();
  ll ret = 0, diff = 0;
  for (int i = 0, s = sign; i < n; ++i, s *= -1) {
    if (A[i] + diff > 0 and s < 0) {
      ret += A[i] + diff + 1;
      diff -= A[i] + diff + 1;
    }
    else if (A[i] + diff < 0 and s > 0) {
      ret += abs(A[i] + diff) + 1;
      diff += abs(A[i] + diff) + 1;
    }
    else if (A[i] + diff == 0) {
      if (s < 0) {
        ++ret;
        --diff;
      }
      else {
        ++ret;
        ++diff;
      }
    }
  }

  return ret;
}

int main()
{
  int N; scanf("%d", &N);
  vector<ll> A(N);
  for (int i = 0; i < N; ++i) {
    scanf("%lld", &A[i]);
  }
  for (int i = 1; i < N; ++i) {
    A[i] += A[i - 1];
  }

  ll ans = min(cal(A, 1), cal(A, -1));
  printf("%lld\n", ans);
  return 0;
}

