bool bxor(bool a, bool b) {
    return !a != !b;
}

long solve(bool f) {
    long sum = 0;
    long ans = 0;

    REP(i, N) {
        sum += A[i];
        if( !bxor(bxor(f, i%2==0), sum > 0) ) {
            long dist = bxor(f, i%2==0) ? (-1) : 1;
            ans += std::abs(sum - dist);
            sum = dist;
        }
    }
    return ans;
}

