    }

    int ans;
    if(a.at(0) != 0){
        ans = body(a);
    }else{
        a.at(0) = -1;
        int ans_a = body(a);
        a.at(0) = 1;
        int ans_b = body(a);
        ans = std::min(ans_a, ans_b);
    }

    std::cout << ans << std::endl;

}

