#include <bits/stdc++.h>
using namespace std;

void answer1() {
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int n;
  cin >> n;
  vector<int> a(n);
  for(int& a_i: a) {
    cin >> a_i;
  }

  int count = 0;
  int sum = 0;
  int count2 = 0;
  int sum2 = 0;
  bool is_positive = a.at(0) > 0;
  for (int i = 0; i < a.size(); i++) {
    sum += a.at(i);

    if (is_positive) {
      if (sum <= 0) {
        // 次は1になるまでインクリメント
        int diff = 1 - sum;
        count += diff;
        sum += diff;
      }
      if (sum2 >= 0) {
        // 次は-1になるまでデクリメント
        int diff = 1 + sum2;
        count2 += diff;
        sum2 -= diff;
      }
    } else {
      if (sum >= 0) {
        // 次は-1になるまでデクリメント
        int diff = 1 + sum;
        count += diff;
        sum -= diff;
      }
      if (sum2 <= 0) {
        // 次は1になるまでインクリメント
        int diff = 1 - sum2;
        count2 += diff;
        sum2 += diff;
      }
    }
    is_positive = ! is_positive;
  }
  cout << min(count, count2) << endl;

}

int main() {
  answer1();
}

