int f(int p) {
	int i, s = 0;
	for (i = 1; i < n; i++) {
		if (p > 0) {
			p += a[i];
			if (p >= 0) s += p + 1, p = -1;
		} else {
			p += a[i];
			if (p <= 0) s += -p + 1, p = 1;
		}
	}
	return s;
}

