int main(void) {
    int n;
    cin >> n;
    vector<lint> x(n);
    repeat(i, n) cin >> x[i];

    auto to_positive = [](lint n) -> lint {
        return (n <= 0 ? 1 - n : 0);
    };
    auto to_negative = [](lint n) -> lint {
        return (n >= 0 ? n + 1 : 0);
    };

    lint pans = to_positive(x[0]);
    lint nans = to_negative(x[0]);
    lint psum = x[0], nsum = x[0];
    psum = max(psum, 1LL);
    nsum = min(nsum, -1LL);

