            pans += to_positive(psum), psum = max(psum, 1LL);
            nans += to_negative(nsum), nsum = min(nsum, -1LL);
        }
        else {
            pans += to_negative(psum), psum = min(psum, -1LL);
            nans += to_positive(nsum), nsum = max(nsum, 1LL);
        }
    }
    cout << min(pans, nans) << endl;        
    return 0;
}

