typedef long long ll;
const int MAXN = 100010;

int n;
ll a[MAXN];

ll countNum(ll initialMove) {
  ll cnt = abs(initialMove);
  ll cur = a[0] + initialMove;
  for (int i=0;i<n-1;i++) {
    ll next = cur + a[i+1];
    if (cur > 0 && next >= 0) {
      cnt += next + 1;
      next = -1;
    }
    if (cur < 0 && next <= 0) {
      cnt += -next + 1;
      next = 1;
    }
    cur = next;
  }
  return cnt;
}

void solve() {
  ll minCnt = min(countNum(0), min(countNum(-a[0] + 1), countNum(-a[0] - 1)));
  cout << minCnt << endl;
}

int main() {
  cin >> n;
  for (int i=0;i<n;i++) {
    cin >> a[i];
  }
  solve();
}

