int64_t get_cost(const vector<int64_t>& as, const int initial_sgn)
{
    int64_t cost = 0;
    int64_t s = 0;
    int sgn = initial_sgn;

    for(auto a : as)
    {
        s += a;
        sgn *= -1;

        if(s * sgn > 0) continue;

        const auto d = abs(s) + 1;
        cost += d;
        s += sgn * d;
    }
    return cost;
};

