int main(int argc, char const *argv[]) {
	int n;
	std::cin >> n;
	std::vector<int> v(n);
	std::vector<int> sums(2,0);
	for (size_t i = 0; i < n; i++) {
		std::cin >> v[i];
		sums[i%2] += v[i];
	}

	ull ans = 0;
	// 奇数番目と偶数番目を足して大きい方が正、小さい方が負
	// なので、0番目の数字をその符号にしておく
	if (sums[0] > sums[1] && v[0] <= 0) {
		ans = ans + abs(v[0]) + 1;
		v[0] = 1;
	}
	else if (sums[0] < sums[1] && v[0] >= 0) {
		ans = ans + abs(v[0]) + 1;
		v[0] = -1;
	}
	// sums[0] == sums[1]
	else if (v[0] == 0) {
		ans += 1;
		v[0] = 1;
	}

	ll now,pre;
	now = pre = v[0];
	for (size_t i = 1; i < n; i++) {
		now = v[i] + pre;
		if (pre * now >= 0) {
			if (pre > 0) {
				ans = ans + abs(now) + 1;
				now = -1;
			}
			else if (pre < 0) {
				ans = ans + abs(now) + 1;
				now = 1;
			}
		}
		pre = now;
	}

	std::cout << ans << '\n';
	return 0;
}

