/*
the operators regarding bit

     x1: 0000 0001 0010 0101 0110 0111
     x2: xxxx 0001 0011 0100 0101 1000
x1 & x2: 0000 0001 0010 0100 0100 0000

      x: 1001 1010  1100 1011 1101  1111
x & - x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

x << y is x * 2 ** y
x >> y is rep(i, y) x = x // 2 
*/

const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, a[MAX_N], s[MAX_N];

void solve(){
    s[0] = 0;
    rep(i, n) {in1(a[i]); s[i + 1] = s[i] + a[i];}

    answer = INF;
    rep(j, 2){
        ll plus = 0; ll minus = 0;
        For(i, 1, n + 1){
            if (i % 2 == 1 - j){
                if (s[i] + plus - minus >= 0) minus += s[i] + plus - minus + 1;
            }else{
                if (s[i] + plus - minus <= 0) plus += 1 - s[i] - plus + minus;
            }
        }
        answer = min(plus + minus, answer);
    }
    prl(answer);
}

int main(void){
    in1(n);
    // assert(n <= 999);
    solve();

    return 0;
}

