void calcu(int p, char s) {
	if (p >= N)
		return;
	int x = A[p];
	if (s == '+') {
		if (sum + x <= 0)
			x = 1 - sum;
		sum += x;
		trn += abs(A[p] - x);
		calcu(++p, '-');
	}
	else {
		if (sum + x > 0)
			x = -1 - sum;
		sum += x;
		trn += abs(A[p] - x);
		calcu(++p, '+');
	}
}

