lint pow(lint num, lint e, lint MOD) {
    lint res = 1;
    lint cur_num = num;
    while (e) {
        if (e & 1) {
            res *= cur_num;
            res %= MOD;
        }
        cur_num *= cur_num;
        cur_num %= MOD;
        e >>= 1;
    }
    return res;
}

int main() {
    cin.tie(0); cout.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);
    lint n; cin >> n;
    vec<lint> a_list(n);
    range(i, 0, n) cin >> a_list.at(i);
    auto min_num_operations = [&](bool is_initial_positive) {
        bool is_positive = is_initial_positive;
        lint cur_sum = 0, num_ops = 0;
        for (const auto a : a_list) {
            if (is_positive and cur_sum + a <= 0) {
                num_ops += 1 - cur_sum - a;
                cur_sum = 1;
            }
            else if (!is_positive and cur_sum + a >= 0) {
                num_ops += cur_sum + a + 1;
                cur_sum = -1;
            } else cur_sum += a;
            is_positive = !is_positive;
        }
        return num_ops;
    };
    cout << min(min_num_operations(false), min_num_operations(true)) << "\n";
}

