void solve(void)
{
  int N; cin >> N;
  vector<ll> A(N);
  for(auto& i : A) cin >> i;
  ll sum{};

  // -, +, -, +, ...
  ll res0{};
  for (int i = 0; i < N; ++i) {
    sum += A[i];
    if (i % 2 == 0) {
      if (sum >= 0) {
        res0 += sum - (-1);
        sum = -1;
      }
    } else {
      if (sum <= 0) {
        res0 += 1 - sum;
        sum = 1;
      }
    }
  }

  // +, -, +, ...
  sum = 0;
  ll res1{};
  for (int i = 0; i < N; ++i) {
    sum += A[i];
    if (i % 2 != 0) {
      if (sum >= 0) {
        res1 += sum - (-1);
        sum = -1;
      }
    } else {
      if (sum <= 0) {
        res1 += 1 - sum;
        sum = 1;
      }
    }
  }

  auto ans = std::min(res0, res1);
  cout << ans << CRLF;
  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

