typedef long long ll;

ll chk(ll a[], int N, bool t)
{
  ll total = 0;
  ll ops = 0;
  for (int i = 0; i < N; i++) {
    total += a[i];
    if (t == true && (total < 1)) {
      ops += (1-total);
      total = 1;
    } else if (t == false && (total > -1)) {
      ops += (total+1);
      total = -1;
    }
    t = !t;
  }
  return ops;
}

