			{
				ans += a[i] + sum + 1;
				sum = -1;
			}
			else
			{
				sum += a[i];
			}
		}
		else
		{
			if (a[i] + sum <= 0)
			{
				ans += abs(a[i] + sum) + 1;
				sum = 1;
			}
			else
			{
				sum += a[i];
			}
		}
	}
