int sequence(int* a, bool sign){
    int sum = a[0], cnt = 0;
    FOR(i, 1, n){
        if(sign){
            sum += a[i];
            if(sum > 0){
                int rem = abs(-1 - sum);
                cnt += rem;
                sum = -1;
            }
            sign = false;
        }else{
            sum += a[i];
            if(sum < 0){
                int rem = abs(1 - sum);
                cnt += rem;
                sum = 1;
            }
            sign = true;
        }
    }
    if(sum == 0)    cnt++;
    return cnt;
}

