int calc(vector<long>& t, bool topPlus) {

  int sum = 0;
  int cnt = 0;
  for (int i = 0; i < t.size(); ++i) {
    sum += t.at(i);
    if ((i % 2 == 0 && topPlus == true) || 
        (i % 2 == 1 && topPlus == false)) {
      if (sum > 0) continue; 
      cnt += abs(sum) + 1;
      sum = 1;
    }
    else {
