void solve(int n, vector<int> a, int key) {
    int sum = 0;
    int cnt = 0;
    rep(i, n) {
        if ((key == 0 && i % 2 == 0) || (key == 1 && i % 2 != 0)) { // 正に
            sum += a[i];
            if (sum == 0) { cnt++; sum = 1; }
            else if (sum < 0) {
                cnt += -sum + 1;
                sum = 1;
            }

        } else {
            sum += a[i];
            if (sum == 0) { cnt++; sum = -1; }
            else if (sum > 0) {
                cnt += sum + 1;
                sum = -1;
            }
        }
    }
    chmin(ans, cnt);
}

