      if (wa < 0) {
        ans += -wa + 1;
        wa += -wa + 1;
      } else if (wa == 0) {
        ans++;
        wa++;
      }
    } else {
      if (a[i] > 0)
        wa--;
      else
        wa++;
    }
  }
