        sum += A[i] * s;
        if (i % 2 == 0) {
            if (sum <= 0) {
                cost += 1 - sum;
                sum = 1;
            }
        } else {
            if (sum >= 0)
                cost += 1 + sum, sum = -1;
        }
    }

    return cost;
};

