int f(int isum, vector<int>& a, int n, int ans){
  for (int i = 1; i < n; i++) {
    int temp = isum;
    isum += a[i];
    if (temp > 0) {
      if (isum >= 0) {
        ans += (1 + isum);
        isum = -1;
      }
    }
    else if(temp < 0) {
      if (isum <= 0) {
        ans += (1 + abs(isum));
        isum = 1;
      }
    }
  }
  return ans;
}
