        auto a_sum = a.sum(i+1);
        if((i&1)==0){
            if(a_sum > 0){
                a.add(i+1, -(abs(a_sum)+1));
                ans += abs(a_sum)+1;
            }
            else if(a_sum == 0){
                a.add(i+1, -1);
                ans += 1;   
            }
        }else{
            if(a_sum < 0){
                a.add(i+1, (abs(a_sum)+1));
                ans += abs(a_sum)+1;
            }
            else if(a_sum == 0){
                a.add(i+1, 1);
