#include <iostream>

int32_t sgn(int32_t val) { return (val > 0) - (val < 0); }

int main() {
  uint32_t n = 0;
  std::cin >> n;

  uint32_t op = 0;
  int32_t sum = 0;
  std::cin >> sum;
  for (size_t i = 1; i < n; i++) {
    int32_t a_i = 0;
    std::cin >> a_i;
    if (sgn(sum) * sgn(sum + a_i) != -1) {
      int32_t diff = -sgn(sum) - (sum + a_i);
      a_i += diff;
      op += std::abs(diff);
    }
    sum += a_i;
  }
  std::cout << op << std::endl;

  return 0;
}

