            if (t == 0) {
                sum1 = 1; ans1 = 1;
                sum2 = -1; ans2 = -1;
            }else {
                sum1 = t;
                sum2 = t > 0 ? -1 : 1;
                ans2 += t + 1;
            }
        }
        else {
            if (sum1 < 0 && sum1 + t <= 0){
                ans1 += 1 - sum1 - t;
                sum1 = 1;
            }else if (sum1 > 0 && sum1 + t >= 0){
                ans1 += abs(-1 - sum1 - t);
                sum1 = -1;
            }else{
                sum1 += t;
            }

            if (sum2 < 0 && sum2 + t <= 0){
                ans2 += 1 - sum2 - t;
                sum2 = 1;
            }else if (sum2 > 0 && sum2 + t >= 0){
                ans2 += abs(-1 - sum2 - t);
                sum2 = -1;
            }else{
                sum2 += t;
            }
        }
    }
    cout << min(ans1, ans2) << "\n";


    return 0;
}

