ll f(vector<ll>& a, bool flag)
{
    ll s = 0;
    ll pm = (flag) ? 1 : -1;
    ll ret = 0;
    for(int i=0; i<a.size(); i++){
        if((s + a[i]) * pm <= 0){
            ret += (s + a[i]) * pm * -1 + 1;
            s = pm;
        }
        else{
            s += a[i];
        }
        pm *= -1;
    }
    return ret;
}

