long long cal(long long b0, int n, long long* a, long long ans){

  long long b[n];
  b[0] = b0;
  for(int i=1; i<n; i++){

    b[i] = b[i-1] + a[i];

    if(b[i]==0){
      ans++;
      b[i] = -1 * b[i-1]/abs(b[i-1]);
    }
    if(a[i]*b[i-1]>0 || (abs(a[i])-abs(b[i-1]))<0){
      ans += abs(a[i]+b[i-1])+1;
      b[i] = -1 * b[i-1]/abs(b[i-1]);
    }
  }
  return ans;
}

