    int j = 1;
    while(sum == 0) {
        if(a[j] > 0) {
            ++res;
            sum = (j % 2 == 0) ? 1 : -1;
            plus = (j % 2 == 0) ? true : false;
        }
        else if(a[j] < 0) {
            ++res;
            sum = (j % 2 == 0) ? -1 : 1;
            plus = (j % 2 == 0) ? false : true;
