    rep(i, n - 1) {
        if(sum + a[i + 1] > 0) {
            if(plus == true) {
                res += sum + a[i + 1] + 1;
                sum = -1;
                plus = false;
            }
            else {
                sum += a[i + 1];
                plus = true;
            }
        }
        else if(sum + a[i + 1] < 0) {
            if(plus == false) {
                res += -(sum + a[i + 1] - 1);
                sum = 1;
                plus = true;
