/*
    ・第i項目までの和をSiとすると、Sは正負正負・・・か負正負正
    　・・・のどちらか
    ・Siが条件を満たしている(正か負のしたい方に既になっている)
    　場合、aiを操作する必要はない(ai+1を操作することで、aiの
    　値を変えずに同じことができるため)。
    ・正負正負・・・にする場合は
    　　i%2==0 かつ S<=0 のとき S=1にする(コスト1-S)
    　　i%2==1 かつ S>=0 のとき S=-1にする(コストS+1)
    　ことをする。(余分に操作する必要はない?)
    ・負正負正・・・にする場合も同じようにできるので、両方を
    　試して小さい方が答え。
*/

signed main()
{
    int N; cin>>N;
    vint a(N);
    REP(i,N) cin>>a[i];

    int cost1=0,S=0;
    REP(i,N){
        S+=a[i];
        if(i%2==0 and S<=0) cost1+=1-S,S=1;
        if(i%2==1 and S>=0) cost1+=S+1,S=-1;
    }

    int cost2=0; S=0;
    REP(i,N){
        S+=a[i];
        if(i%2==0 and S>=0) cost2+=S+1,S=-1;
        if(i%2==1 and S<=0) cost2+=1-S,S=1;
    }

    cout<<min(cost1,cost2)<<endl;

}

