enum PosiNega {
  POSITIVE = 0,
  NEGATIVE = 1
};

int solve(int N, int *a, PosiNega odd_posinega) {
  int ans = 0;
  int sum = 0;
  PosiNega posi_nega = odd_posinega;
  rep(i, 0, N) {
    sum += a[i];
    if (POSITIVE == posi_nega) {
      if (0 >= sum) {
        ans += 1-sum;
        sum = 1;
      }
      posi_nega = NEGATIVE;
    } else {
      if (0 <= sum) {
        ans += abs(-1-sum);
        sum = -1;
      }
      posi_nega = POSITIVE;
    }
  }
  return ans;
}

void _main() {
  int N;
  cin >> N;

  int a[N];
  rep(i, 0, N) cin >> a[i];

  int candidate1 = solve(N, a, POSITIVE);
  int candidate2 = solve(N, a, NEGATIVE);
  int ans = (candidate1 < candidate2) ? candidate1 : candidate2;

  cout << ans << "\n";
}

