using namespace std;
long long change_num(long long p[], int N) {
  long long res = 0;
  long long next_sum;
  long long sum = p[0];
  for (int i = 1; i < N; i++) {
    next_sum = sum + p[i];
    if((sum < 0 && next_sum > 0) || (sum > 0 && next_sum < 0)) {
      sum = next_sum;
      continue;
    } 
    if(sum > 0 && next_sum >= 0) {
      res += next_sum + 1;
      sum = -1;
      continue;
    }
    if (sum < 0 && next_sum <= 0) {
      res += 1 - next_sum;
      sum = 1;
      continue;
    }
  }
  return res;
}


