template<class T> inline bool chmax(T& a, T b) { if (a < b) { a = b; return true; } return false; }
template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return true; } return false; }

int main(void){
    int N;
    cin >> N;
    vector<ll> a(N), b(N);
    REP(i,N){cin >> a[i]; b[i] = a[i];}
    vector<ll> s(N);
    s[0] = a[0];

    ll ans = 0;
    if(a[0] <= 0){
        ans = -a[0]+1;
        s[0] = 1;
    }

    REP(i,N-1){
        if((s[i]+a[i+1])*s[i]>=0){
            ans += abs(s[i]+a[i+1])+1;
            a[i+1] += -(s[i]+a[i+1]);
            if(s[i] > 0) a[i+1]--;
            else a[i+1]++;
        }
        s[i+1] = s[i]+a[i+1];
    }

    ll ans1 = 0;
    s[0] = b[0];

    if(a[0] >= 0){
        ans1 = b[0]+1;
        s[0] = -1;
    }

    REP(i,N-1){
        if((s[i]+b[i+1])*s[i]>=0){
            ans1 += abs(s[i]+b[i+1])+1;
            b[i+1] += -(s[i]+b[i+1]);
            if(s[i] > 0) b[i+1]--;
            else b[i+1]++;
        }
        s[i+1] = s[i]+b[i+1];
    }
    cout << min(ans, ans1) << endl;
    return 0;
}

