int main()
{
    int n;
    cin >> n;
    vector<long> an(n);
    for (int i = 0; i < n; ++i)
    {
        cin >> an[i];
    }

    auto get_sign = [](int x) {
        return x >= 0 ? 1 : -1;
    };

    int cnt_min = INT_MAX;
    for (int j = -1; j < 1; ++j)
    {
        int sign = get_sign(j);
        long accum = an[0];
        int cnt = 0;
        if (accum * sign <= 0)
        {
            // accum + x = sign
            auto x = sign - accum;
            accum += x;
            cnt += abs(x);
        }

        for (int i = 1; i < n; ++i)
        {
            auto new_accum = accum + an[i];
            int new_sign = -sign;
            if (new_accum * get_sign(accum) >= 0)
            {
                // new_accum + x = new_sign
                int x = new_sign - new_accum;
                new_accum += x;
                cnt += abs(x);
            }
            accum = new_accum;
            sign = new_sign;
        }

        if (cnt < cnt_min)
        {
            cnt_min = cnt;
        }
    }
    cout << cnt_min << endl;
    return 0;
}

