long body(std::vector<long>& a, long base){
    long ans  = 0;

    std::vector<long> s(a.size());
    s.at(0) = a.at(0);
    for(unsigned long i = 1; i < a.size(); i++){
        s.at(i) = s.at(i-1) + a.at(i);
    }

    long diff = 0;
    long prev = base;
    for(unsigned long i = 0; i < s.size(); i++){
        s.at(i) += diff; // update
        long n = 0;
        if(prev > 0 && s.at(i) >= 0){
            n = s.at(i) + 1;
            ans += n;
            diff -= n;
            s.at(i) += diff;
        }else if(prev < 0 && s.at(i) <= 0){
            n = - s.at(i) + 1;
            ans += n;
            diff += n;
            s.at(i) += diff;
        }
        prev = s.at(i);
    }
    return ans;
}

