    for(long i = 0; i < n; i++){
        std::cin >> a.at(i);
    }

    long ans_a, ans_b;

    ans_a = body(a, -1);
    ans_b = body(a, 1);

    long ans = std::min(ans_a, ans_b);

    std::cout << ans << std::endl;

}

