int count_operate(vector<int> a){
  int N = a.size();
  vector<int> s(N,0);
  int retval = 0;
  s.at(0) = a.at(0);
  for (int i=1;i<N;i++){
    s.at(i) = a.at(i) + s.at(i-1);
    if (s.at(i-1)>0 && s.at(i)>=0){
      retval += abs(s.at(i))+1;
      s.at(i) = -1;
    }
    else if (s.at(i-1)<0 && s.at(i)<=0){
      retval += abs(s.at(i))+1;
      s.at(i) = 1;
    }
  }
  return retval;
};


