    long int ans = 0;   
    long int sum = 0;

    bool pre_pm;
    sum = T.at(0);

    if(0 <= sum) { 
        pre_pm = true;
        long int tmp1, tmp2;
        if(!sum) { sum++; ans++;
        tmp1 = check(sum, ans, T, N, pre_pm);}
        pre_pm = false;
        tmp2 = check(-1, 1+sum, T, N, pre_pm);

        cout << min(tmp1, tmp2) << endl;
    } else {
        pre_pm = false;
        long int tmp1 = check(sum, ans, T, N, pre_pm);
        pre_pm = true;
        long int tmp2 = check(1, 1 + sum, T, N, pre_pm);

        cout << min(tmp1, tmp2) << endl;

    }

    return 0;
}

