#define FOR(v, b, e)   for (int v = (b); v < (e); ++v)

int calc (int a0, vector<int>& a) {
	int sum   = a0;
	int count = 0;
	FOR (i, 1, a.size()) {
		if (sum < 0) {
			sum += a[i];
			if (sum <= 0) {
				count += 1 - sum;
				sum    = 1;
			}
			continue;
		}

		sum += a[i];
		if (sum >= 0) {
			count += sum + 1;
			sum    = -1;
		}
	}
	return count;
}

int main () {
	ios::sync_with_stdio(false);
	cin.tie(0);

	int N;
	cin >> N;

	vector<int> a(N);
	for (auto& ai : a) cin >> ai;

	int count = 0;
	if (a[0] == 0) {
		auto count1 = calc( 1, a) + 1;
		auto count2 = calc(-1, a) + 1;
		count       = min(count1, count2);
	} else {
		auto count1 = calc(a[0], a);
		auto count2 = calc(   1, a) + abs( 1 - a[0]);
		auto count3 = calc(  -1, a) + abs(-1 - a[0]);
		count       = min(count1, min(count2, count3));
	}

	cout << count << endl;
}

