		if(sum * (sum-a[i]) < 0); // ok
		else {
			// sumが正なら負に、sumが負なら正にする
			// sum が 0 のとき注意が必要
			if(sum == 0){
				if(sum-a[i] < 0){
					sum = 1;
					ans ++;
				} else {
					ans ++;
					sum = -1;
				}
			}
			else if(sum > 0){
				ans += (sum - (-1));
				sum = -1;
			} else {
				ans += (1 - sum);
				sum = 1;
			}
		}
	}
	ans = min(tmp,ans);
	cout << ans << endl;
}

