ll calc(bool init) {
    ll ans = 0;
    ll cur = 0;
    int s = init ? 1 : -1;
    forn(i, n) {
        ll temp = cur + a[i];
        if (temp * s > 0) {
            cur = temp;
        } else {
            ans += abs(temp) + 1;
            cur = s;
        }
        //cout << init << " " << cur << endl;
        s *= -1;
    }
    return ans;
}

