int change_num(long p[], int N) {
  int res = 0;
  long sum = p[0];
  for (int i = 1; i < N; i++) {
    if(sum * (sum + p[i]) < 0) {
      sum += p[i];
      continue;
    } 
    if(sum > 0 && sum + p[i] >= 0) {
      sum += p[i];
      while (sum >= 0) {
        res++;
        sum--;
      }
      continue;
    }
    if (sum < 0 && sum + p[i] <= 0) {
      sum += p[i];
      while (sum <= 0) {
        res++;
        sum++;
      }
      continue;
    }
  }
  return res;
}



