int calc(bool firstPositive, const int a[], int n) {
  bool positive = firstPositive;
  int cost = 0;
  long sum = 0;
  for (int i = 0; i < n; ++i) {
    int v = a[i];
    if (((sum + v) >= 0) != positive) {
      cost += abs(a[i]) + 1;
      v = positive ? 1 : -1;
    }
    if ((sum + v) == 0) {
      v += positive ? 1 : -1;
      ++cost;
    }
    sum += v;
    positive = !positive;
    std::cout << a[i] << "\t" << v << "\t" << sum << " " << cost << std::endl;
  }
  return cost;
}

