int n;
ll a[MAXN];
ll s[MAXN];

ll countNum(bool direction) {
  ll cnt = 0;
  ll carry = 0;
  if (a[0] == 0) {
    a[0] = 1;
    cnt = 1;
    carry = 1;
  }
  cnt = direction ? cnt : abs(a[0]);
  carry = direction ? carry : -a[0];
  s[0] = direction ? a[0] : -a[0];
  for (int i=1;i<n;i++) {
    s[i] = s[i-1] + a[i];
  }
  for (int i=1;i<n;i++) {
    if ((s[i] + carry) * s[i-1] >= 0) {
      cnt += abs(s[i]+carry) + 1;
      if (s[i-1] < 0) {
        carry += abs(s[i]+carry) + 1;
        s[i] = 1;
      } else {
        carry -= abs(s[i]+carry) + 1;
        s[i] = -1;
      }
    } else {
      s[i] += carry;
    }
  }
  return cnt;
}

void solve() {
  ll maxCnt = min(countNum(true), countNum(false));
  cout << maxCnt << endl;
}

