					x=-x;
				}
				aw += x;
				a[i] = -1-s[i-1];
				s[i]=s[i-1]+a[i];
			}
		}else {
			if (s[i]>0){
				continue;
			}else{
				x=s[i-1]+a[i]-1;
				if (x<0){
					x=-x;
				}
				aw += x;
				a[i] = 1-s[i-1];
				s[i]=s[i-1]+a[i];
			}			
		}
	}
	cout<<aw<<endl;
	return 0;
}

