int solve(bool b) {
    int count = 0;
    int sum = a[0];
    if(a[0] == 0) { sum = b ? 1 : -1; count++; }
    else if(b && a[0] < 0) { sum = 1; count = 1 - a[0]; }
    else if(!b && a[0] > 0) { sum = -1; count = a[0] + 1; }

    for(int i = 1; i < N; i++) {
        if(sum * a[i] < 0 && abs(sum) < abs(a[i])) {
            sum += a[i];
        } else {
            if(sum > 0) {
                count += a[i] + sum + 1;
                sum = -1;
            } else {
                count += 1 - sum - a[i];
                sum = 1;
            }
        }
    }
    return count;
}

