	cin.tie(0); ios::sync_with_stdio(false);
    ll n; cin >> n;
    vector<ll> a(n);
    for(auto& in:a) cin >> in;
    cout << min(
                calc(n,a,a[0]>0?0:abs(a[0])+1,a[0]>0?a[0]:1),
                calc(n,a,a[0]<0?0:abs(a[0])+1,a[0]<0?a[0]:-1)
    ) << endl;
	return 0;
}

