ll solve(bool p) {
    ll s = 0;
    ll ret = 0;
    rep(i, N) {
        s += A[i];
        if (p) {
            if (s <= 0) {
                ret += 1 - s;
                s += 1 - s;
            }
        } else {
            if (s >= 0) {
                ret += s + 1;
                s -= s + 1;
            }
        }
        p = !p;
    }
    return ret;
}


