int check(ll sum, ll ans){
    // cout << "----" << endl;
    for(int i=1; i<n; i++){
        ll t = sum + a[i];
        if((sum>=0 && t<0) || (sum<0 && t>=0)){
            sum = t;
            if(sum == 0){
                sum = 1;
                ans++;
            }
            continue;
        }

        ll at;
        if(sum >= 0) at = -1 - sum;
        else at = 1 - sum;

        // cout << i << " " << a[i] << " " << at << endl;

        ans  = ans + abs(a[i] - at);

        sum = sum + at;
    }
    // cout << ans << endl;
    return ans;
}

