using namespace std;

int N;
int solve(vector<int> A){
  int ret = 0;
  int sum = 0;
  REP(i, N-1) A[i+1] += A[i];
  FOR(i, 1, N){
    A[i] += sum;
    if(A[i]*A[i-1] >= 0){
      if(A[i] == 0){
        if(A[i-1] < 0){
          sum++;
          ret++;
          A[i] += 1;
        }else{
          sum--;
          ret++;
          A[i] -= 1;
        }
      }else if(A[i] > 0){
        sum -= A[i]+1;
        ret += A[i]+1;
        A[i] = -1;
      }else{
        sum += -A[i]+1;
        ret += -A[i]+1;
        A[i] = 1;
      }
    }
  }
  return ret;
}

