int getTotal(int n, int dir) {
  int total{}, sum{};
  for (int i{0}; i < n; ++i) {
    sum += a[i];
    if (dir > 0 && sum <= 0) {
      total += -sum + 1;
      sum = 1;
    } else if (dir < 0 && sum >= 0) {
      total += sum + 1;
      sum = -1;
    }
    dir *= -1;
  }
  return total;
}

