ll solve(bool isp){
    ll sum = 0LL;
    ll ret = 0LL;
    rep(i, n){
        sum += a[i];
        if(isp and sum <= 0){
            ret += -sum + 1;
            sum = 1LL;
        }
        if(not isp and sum >= 0){
            ret += sum + 1;
            sum = -1LL;
        }
        isp ^= 1;
    }
    return ret;
}

