ll calc(int id, ll sum) {
    ll ans = 0;
    for (int i = id; i < n; ++i) {
        ll cur = sum + a[i];
        //cerr << i << " " << sum << " " << cur << "\n";
        if (sum < 0 && cur > 0) {
            sum = cur; 
            continue;
        }
        if (sum > 0 && cur < 0) {
            sum = cur;
            continue;
        }
        if (cur == 0) {
            if (sum < 0)
                cur = 1;
            else
                cur = -1;
            sum = cur;
            ans++;
            continue;
        }
        if (sum < 0) {
            ans += 1 - cur;
            cur = 1;
        } else {
            ans += cur + 1;
            cur = -1;
        }
        sum = cur;
    }
    return ans;
}

