unsigned solve(unsigned N, const std::vector<long> &a, int flag)
{
  unsigned c = 0;

  long s = 0;
  for (unsigned n = 0; n < N; ++n) {
    long b = s + a[n];
    if (n % 2 == flag) {
      // 正
      if (b <= 0) {
        c += std::abs((+1) - b);
        s = +1;
      } else {
        s = b;
      }
    } else {
      // 負
      if (b >= 0) {
        c += std::abs((-1) - b);
        s = -1;
      } else {
        s = b;
      }
    }
  }

  return c;
}

