long long f(int a[], int n, bool plus) {
    long long ans = 0;
    int sum = a[0];

    if (sum == 0) {
        ans++;
        if (plus) {
            sum++;
        } else {
            sum--;
        }
    } else {
        plus = (sum > 0);
    }

    for (int i = 1; i < n; i++) {
       sum += a[i];

       if ((plus && sum < 0) || (!plus && sum > 0)) {
           plus = !plus;
           continue;
       }

       if (plus) {
           ans += (sum + 1);
           sum = -1;
       } else {
           ans += (-sum + 1);
           sum = 1;
       }
       plus = !plus;
    }

    return ans;
}

