  }
  sort(a.begin(),a.end());
  segtree d(n+1);
  d.Set(0,n+1,0);
  d.Set(n,n+1,n);
  vec dp(n+1);
  vec ans(n+1);
  dp[0]=1;
  ans[0]=dp[0];
  for(ll i=0;i<n;i++) {
    ll x=a[n-i-1].second;
    ll it=upper_bound(a.begin(),a.end(),pll(x,0))-a.begin();
    if(it==n-i) {
      d.Set(n-i-1,n-i,it);
    }
