#include <bits/stdc++.h>
using namespace std;

int main() {

  int n;
  cin >> n;
  vector<long long> vector;  
  long long temp;

  for(int i=0; i<n; i++) {
    cin >> temp;
    vector.push_back(temp);
  }

  long long answer=0;
  long long   sum=0;
  for(int i=0; i<n; i++) {
    if(sum == 0) 
      sum += vector[i];
    else if(sum < 0) {
      /* arr[1] = もし-1*arr[0]+1 > vector[i] なら までインクリメント
       * でなければ 
       *
       * arr[2] = arr[0]-1 までデクリメント
       * 以下同様
       * t番目を考える（t-1番目まで条件を満たしているとする）
       * t番目の符号はarr[0]の符号で決まる
       * t番目の絶対値 -> 条件を満たすならそのまま
       * 満たさない場合-> if(sum == 1) -2; (sum==-1) 2; sum < 0) -sum+1; sum>0 -sum-1;
       * -1 4 -4 2 -5 3
       * -3 4 -2 2 -2 2*/
      if(sum + vector[i] > 0){
	// answer -> answer
	sum += vector[i];
      }
      else {
	answer += abs((-1)*sum+1 - vector[i]);
	sum = 1;
      }
    }
    else {
      if(sum + vector[i] < 0) {
	//answer->answer
	sum += vector[i];
      }
      else {
	answer += abs((-1)*sum-1 - vector[i]);
	sum = -1;
      }
    }
  }
  cout << answer << endl;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
// fst == 1 -> odd plus, even minus
int f(const vector<int>& data, int n, int fst)
{
    vector<int> a = data;
    int s = 0, ret = 0, k;
    for(int i = 0; i < n; i++){
        k = (s + a[i]) * fst;
        if(k <= 0 &&   i & 1){
            ret  += (1 - k);
            a[i] += (1 - k) * fst;
        }
        if(k >= 0 && !(i & 1)){
            ret  += (k + 1);
            a[i] -= (k + 1) * fst;
        }
        s += a[i];
    }
    return ret;
}
int main()
{
    long long n;
    cin >> n;
    vector<int> a(n);
    for(int i = 0; i < n; i++){
        scanf("%d", &a[i]);
    }
    cout << min(f(a, n, 1), f(a, n, -1)) << endl;
    return 0;
}

