ll ch(int init)
{
	int t=A[0];
	ll res=init;
	for(int i=1;i<N;i++)
	{
		if(t+A[i]==0||t*(t+A[i])>0)
		{
			if(t>0)
			{
				res+=abs(t+1+A[i]);
				t=-1;
			}
			else
			{
				res+=abs(t)+1-A[i];
				t=1;
			}
		}
		else
		{
			t+=A[i];
		}
	}
	return res;
}

