    for ( int i=2; i<=n; i++ ) {
        mod[i]+=mod[i-1];
        long long now=pref[i]+mod[i];
        long long prev=pref[i-1]+mod[i-1];
        if ( now==0 ) {
            if ( prev>0 ) {
                res+=1;
                mod[i]-=1;
            } else {
                res+=1;
                mod[i]+=1;
            }
        }
        else {
            if ( prev>0&&now>0 ) {
                res+=now+1;
                mod[i]-=now+1;
            }
            if ( prev<0&&now<0 ) {
                res+=1-now;
                mod[i]+=1-now;
            }
        }
    }
    return res+x;
}

