int main(){
  int n; // 2 <= n <= 1e5
  cin >> n;
  vector<int64_t> a(n+10, 0);
  for (int i = 1; i <= n; ++i) {
    cin >> a[i];
  }

  // a_1を与えられた正負のどちらかの符号に決めて、
  // 残りを計算する

  int pn = 0; // plus num
  int mn = 0; // minus num
  const int64_t first = a[1];

  {
    int num = 0;
    int64_t total = 0; // plus total
    // a_1 Plus
    if (first <= 0) {
      num = 1 - first;
      total = 1;
    } else {
      total = first;
    }

    for (int i = 2; i <= n; ++i) {
      int64_t ai = a[i];
      if (i % 2 == 0) { // minus
        if (ai >= 0) {
          num += -(-1 - ai);
          ai = -1;
        }
        if (total + ai >= 0) {
          const int64_t back = ai;
          ai = -1 - total;
          num += abs(ai - back);
        }
        total += ai;
      } else { // plus
        if (ai <= 0) {
          num += 1 - ai;
          ai = 1;
        }
        if (total + ai <= 0) {
          const int64_t back = ai;
          ai = 1 - total;
          num += abs(ai - back);
        }
        total += ai;
      }
    }
    pn = num;
  }

  {
    int num = 0;
    int64_t total = 0; // minus total
    // a_1 Minus
    if (first >= 0) {
      num = -(-1 - first);
      total = -1;
    } else {
      total = first;
    }

    for (int i = 2; i <= n; ++i) {
      int64_t ai = a[i];
      if (i % 2 == 0) { // plus
        if (ai <= 0) {
          num += 1 - ai;
          ai = 1;
        }
        while (total + ai <= 0) {
          ++ai;
          ++num;
        }
        total += ai;
      } else { // minus
        if (ai >= 0) {
          num += -(-1 - ai);
          ai = -1;
        }
        while (total + ai >= 0) {
          --ai;
          ++num;
        }
        total += ai;
      }
    }

    mn = num;
  }

  cout << min(pn, mn) << endl;
  return 0;
}

