};

int main()
{
	struct calc_data calc_data = {0, 0, 0};
	long long n, ans, ans2;
	cin >> n;
	for (long long i = 0; i < n; i++)
	{
		cin >> a[i];
	}
	//最初を正
	calc_data.sign = 1;
	if (a[0] > 0)
	{
		calc_data.tmp = a[0];
		calc_data.cnt = 0;
	}
	else
	{
		calc_data.tmp = 1;
		calc_data.cnt = (-1 * a[0]) + 1;
	}
	ans = calc(a, n, calc_data);
	//最初を負
	calc_data.sign = 0;
	if (a[0] < 0)
	{
		calc_data.tmp = a[0];
		calc_data.cnt = 0;
	}
	else
	{
		calc_data.tmp = -1;
		calc_data.cnt = a[0] + 1;
	}
	ans2 = calc(a, n, calc_data);
	if (ans2 < ans) ans = ans2;
	cout << ans << endl;
	return 0;
}

long long calc(long long *a, long long n, struct calc_data calc_data)
{
	for (long long i = 0; i < n - 1; i++)
	{
		calc_data.tmp = calc_data.tmp + a[i + 1];
		if (calc_data.sign == 1)
		{
			if (calc_data.tmp >= 0)
			{
				calc_data.cnt += calc_data.tmp + 1;
				calc_data.tmp = -1;
			}
		}
		else
		{
			if (calc_data.tmp <= 0)
			{
				calc_data.cnt += (-1 * calc_data.tmp) + 1;
				calc_data.tmp = 1;
			}
		}
		calc_data.sign = get_sign(calc_data.tmp);
	}
	return calc_data.cnt;
}

long long get_sign(long long tmp)
{
	if (tmp < 0) return 0;
	else return 1;
}

