enum PosiNega {
  POSITIVE = 0,
  NEGATIVE = 1
};

int solve(int N, int *a, PosiNega odd_posinega) {
  int ans = 0;
  int sum = 0;
  PosiNega posi_nega = odd_posinega;
  rep(i, 0, N) {
    sum += a[i];
    if (POSITIVE == posi_nega) {
      if (0 >= sum) {
        ans += 1-sum;
        sum = 1;
      }
      posi_nega = NEGATIVE;
    } else {
      if (0 <= sum) {
        ans += 1+sum;
        sum = -1;
      }
      posi_nega = POSITIVE;
    }
  }
  return ans;
}

