  int a[N];
  rep(i, 0, N) cin >> a[i];

  int candidate1 = solve(N, a, POSITIVE);
  int candidate2 = solve(N, a, NEGATIVE);
  int ans = (candidate1 < candidate2) ? candidate1 : candidate2;

  cout << ans << "\n";
}

