  ll p = 0; // 同じく
  ll m_cnt = 0; // 各スタートでの操作回数
  ll p_cnt = 0;

  rep(i,n)
  {
    // minus start
    if( (i % 2 ? 1 : -1 ) * (m + a[i]) < 0)
    {
      // 符号が違っていたら
      ll b_m = m + a[i];
      m_cnt += 1 + abs(b_m);
      m = i % 2 ? 1 : -1;
    }
    else if(m + a[i] == 0)
    {
      m = i % 2 ? 1 : -1;
      m_cnt++;
    }
    else
    {
      // あっているなら次に行くだけ
      m += a[i];
    }

    // plus start
    if( (i % 2 ? -1 : 1 ) * (p + a[i]) < 0)
    {
      // 符号が違っていたら
      ll b_p = p + a[i];
      p_cnt += 1 + abs(b_p);
      p = i % 2 ? -1 : 1;
    }
    else if(p + a[i] == 0)
    {
      p = i % 2 ? 1 : -1;
      p_cnt++;
    }
    else
    {
      // あっているなら次に行くだけ
      p += a[i];
    }
  }

  cout << min(m_cnt,p_cnt) << endl;


  return 0;
}

