long f(vector<int>& A, int s) {
  long acc = 0, ans = 0;
  for (int i = 0; i < A.size(); i++) {
    acc += A[i];
    if (acc == 0 || s != ((acc < 0) ? -1 : 1)) {
      int d = abs(acc) + 1;
      acc += s * d;
      ans += d;
    }
    s *= (-1);
  }
  return ans;
}

