void solve() {
  int n; cin >> n;
  vector<int> a(n);
  for(int i=0; i<n; ++i) cin >> a.at(i);

  int ans=0;
  if(!a.at(0)) {
    if(a.at(1)>0) a.at(0)--;
    if(a.at(1)<0) a.at(0)++;
    ans++;
  }
  int sum=a.at(0);
  for(int i=1; i<n; ++i) {
    if(sum<0) {
      if(sum+a.at(i)<=0) {
        while(sum+a.at(i)<=0) {
          ++a.at(i);
          ++ans;
        }
      }
    } else {
      if(sum+a.at(i)>=0) {
        while(sum+a.at(i)>=0) {
          --a.at(i);
          ++ans;
        }
      }
    }
    sum+=a.at(i);
  }
    cout << ans << '\n';

  return;
}

