#include<iostream>
using namespace std;

int f(int a[], int N, bool positive) {
  int cnt = 0;
  int sum = a[0];
  for (int i = 1; i < N; i++) {
    int n = a[i];
    if (positive) {
      if (i % 2 == 0) {
        while (sum + n <= 0) n++, cnt++;
      } else {
        while (0 <= sum + n) n--, cnt++;
      }
    } else {
      if (i % 2 == 0) {
        while (0 <= sum + n) n--, cnt++;
      } else {
        while (sum + n <= 0) n++, cnt++;
      }
    }
    sum += n;
  }
  return cnt;
}

int main() {
  int N;
  cin >> N;

  int a[N];
  for (int i = 0; i < N; i++) cin >> a[i];

  int cnt = min(f(a, N, 1), f(a, N, 0));

  cout << cnt << endl;
  return 0;
}

