  rep(i, n) {
    c += a[i];
    if(i % 2 == 0 && c <= 0) {
      s += 1 - c;
      c = 1;
    } else if(i % 2 == 1 && c >= 0) {
      s += c + 1;
      c = -1;
    }
  }
  ans = s;
  s = 0, c = 0;
  rep(i, n) {
    c += a[i];
    if(i % 2 == 1 && c <= 0) {
      s += 1 - c;
      c = 1;
    } else if(i % 2 == 0 && c >= 0) {
      s += c + 1;
      c = -1;
    }
  }
  COUT(min(ans, s));
}


