#include <iostream>
#include <vector>

int body(std::vector<int>& a){
    int ans  = 0;

    std::vector<int> s(a.size());
    s.at(0) = a.at(0);
    for(unsigned int i = 1; i < a.size(); i++){
        s.at(i) = s.at(i-1) + a.at(i);
    }

    int diff = 0;
    for(unsigned int i = 1; i < s.size(); i++){
        s.at(i) += diff; // update
        int n = 0;
        if(s.at(i-1) > 0 && s.at(i) >= 0){
            n = s.at(i) + 1;
            ans += n;
            diff -= n;
            s.at(i) += diff;
        }else if(s.at(i-1) < 0 && s.at(i) <= 0){
            n = - s.at(i) + 1;
            ans += n;
            diff += n;
            s.at(i) += diff;
        }
    }
    return ans;
}

int main(int argc, char **argv)
{
    int n;
    std::cin >> n;

    std::vector<int> a(n);
    for(int i = 0; i < n; i++){
        std::cin >> a.at(i);
    }

    int ans;
    if(a.at(0) != 0){
        ans = body(a);
    }else{
        a.at(0) = -1;
        int ans_a = body(a);
        a.at(0) = 1;
        int ans_b = body(a);
        ans = std::min(ans_a, ans_b);
    }

    std::cout << ans << std::endl;

}

