using namespace std;
typedef unsigned long long ull;
typedef long long ll;

int n;
vector<ll> a;

enum State
{
  Plus,
  Minus,
  Zero
};

State GetState(ll sum)
{
  State state;
  if (sum > 0) state = Plus;
  else if (sum == 0) state = Zero;
  else state = Minus;

  return state;
}

ull Count(State initialState)
{
  ull count = 0;
  vector<ll> b = a;
  State state = GetState(b[0]);

  //メモ：1か-1を設定するかでも最終的なカウントが変わる
  if (state == Zero)
  {
    state = initialState;
    if (state == Plus) b[0] = 1;
    else if (state == Minus) b[0] = -1;
    count++;
  }

  ll sum = b[0];

  //cout << b[0] << " " << sum << endl;

  for (int i = 1; i < n; i++)
  {
    State nextState = GetState(sum + b[i]);

    switch (nextState)
    {
    case Plus:
      if (state == Plus)
      {
        ll bf_a = b[i];
        b[i] = -1 - sum;
        count += abs(b[i] - bf_a);
        nextState = Minus;
      }
      break;

    case Minus:
      if (state == Minus)
      {
        ll bf_a = b[i];
        b[i] = 1 - sum;
        count += abs(b[i] - bf_a);
        nextState = Plus;
      }
      break;

    case Zero:
      if (state == Plus)
      {
        ll bf_a = b[i];
        b[i] = -1 - sum;
        count += abs(b[i] - bf_a);
        nextState = Minus;
      }
      else if (state == Minus)
      {
        ll bf_a = b[i];
        b[i] = 1 - sum;
        count += abs(b[i] - bf_a);
        nextState = Plus;
      }

    default:
      break;
    }

    sum += b[i];

    //cout << b[i] << " " << sum << endl;
    state = nextState;
  }

  if (sum == 0) count++;

  return count;
}

int main()
{
  cin >> n;
  a.resize(n);

  for (int i = 0; i < n; i++)
    cin >> a[i];

  ull pCount = Count(Plus);
  ull mCount = Count(Minus);

  ull ans = pCount < mCount ? pCount : mCount;

  cout << ans << endl;
}

