					++dis;
				}
			}
			else if (ps && temp[i] > 0) {
				res += temp[i]+1;
				dis -= temp[i]+1;
			}
			else if (!ps && temp[i] < 0)  {
				res += -temp[i]+1;
				dis += -temp[i]+1;
			}
		}
	}
	return res;
}

