llp dp[NMAX][2] ={};
ll S[NMAX] = {};
ll ansp = 0, ansm = 0;

void solve(){
    // main algorithm
    for (int i = 1; i <= N; ++i)
    {
        // plus
        ll s = S[i] + dp[i-1][1].first - dp[i-1][1].second;
        if (s <= 0)
        {
            dp[i][0] = llp(dp[i-1][1].first + 1 - s, dp[i-1][1].second);
        }else{
            dp[i][0] = dp[i-1][1];
        }
        // minus
        s = S[i] + dp[i-1][0].first - dp[i-1][0].second;
        if (s >= 0)
        {
            dp[i][1] = llp(dp[i-1][0].first, dp[i-1][0].second + s + 1);
        }else{
            dp[i][1] = dp[i-1][0];
        }
    }
}
