		else if (a[i] > 0 && a[i - 1] > 0) {
			ret += a[i] + 1;
			a[i] = -1;
		}
		else if (a[i] < 0 && a[i - 1] < 0) {
			ret += 1 - a[i];
			a[i] = 1;
		}
	}
	return ret;
}

