llong calcSignChgTimes(const vector<int>& cnrvnNum)
{ 
  vector<llong> vnTimes(2);

  for (int nParity = 0; nParity < vnTimes.size(); nParity++)
  {
    llong nTimes = 0;
    llong nSum   = 0;
    for (int n = 0; n < cnrvnNum.size(); n++)
