int N;

ll		solve(vector<ll> &A, ll cur)
{
	ll ans = 0;
	for (int i = 1; i < N; i++)
	{
		if (cur > 0 && cur + A[i] >= 0)
		{
			ans += abs(-1-(cur+A[i]));
			cur = -1;
		}
		else if (cur < 0 && cur + A[i] <= 0)
		{
			ans += abs(1-(cur+A[i]));
			cur = 1;
		}
		else
			cur += A[i];
	}
	return (ans);
}

