          count1 += abs(na - a[i+1]);
          a[i+1] = na;
      }

    if(sum > 0 && sum + a[i+1] >=0){
          ll na = -1 -sum;//sumに何を足せば-1になるか これを新たなa[i+1]にする
          count1 += abs(na - a[i+1]);
          a[i+1] = na;
      }
    }

    copy_a[0] = -1;
    ll count2 = 1;
    ll sum2 = 0;

    for(int i = 0;i<n-1;i++){
        sum2 += copy_a[i];//i項までの和

      if(sum2 < 0 && sum2 + copy_a[i+1] <=0){
