// fst == 1 -> odd plus, even minus
long long f(const vector<long long>& data, int n, int fst)
{
    vector<long long> a = data;
    long long s = 0, ret = 0, k;
    for(int i = 0; i < n; i++){
        k = (s + a[i]) * fst;
        if(k <= 0 &&   i & 1){
            ret  += (1 - k);
            a[i] += (1 - k) * fst;
        }
        if(k >= 0 && !(i & 1)){
            ret  += (k + 1);
            a[i] -= (k + 1) * fst;
        }
        s += a[i];
    }
    return ret;
}
int main()
{
    long long n;
    cin >> n;
    vector<long long> a(n);
    for(int i = 0; i < n; i++){
        scanf("%lld", &a[i]);
    }
    cout << min(f(a, n, 1), f(a, n, -1)) << endl;
    return 0;
}

