void calcDP(int n){
	if(n == 1){
		if(sign == 1){
			if(W[1] > 0){
				dp[1] = 0;
			}
			else{
				dp[1] = abs(1 - W[1]);
				W[1] = 1;
			}
		}
		else if(sign == -1){
			if(W[1] < 0){
				dp[1] = 0;
			}
			else{
				dp[1] = abs(-1 -W[1]);
				W[1] = -1;
			}
		}
		S[1] = W[1];
		return;
	}
	else{
		S[n] = S[n-1] + W[n];
		if( ( S[n-1] < 0 && S[n] > 0 ) || ( S[n-1] > 0 && S[n] < 0 ) ){
			dp[n] = dp[n-1];
		}
		else{
			if(S[n-1] > 0){
				W[n] = -1 - S[n-1];
			}
			else{
				W[n] = 1 - S[n-1];
			}
			dp[n] = dp[n-1] + abs(A[n] - W[n]);
			S[n] = S[n-1] + W[n];
		}
		return;
	}
}

