void solve()
{
  int n; cin >> n;
  vector<llong> a(n); REP(i, n) cin >> a[i];
  vector<llong> ans = {0, 0};
  vector<int> signs = {1, -1};

  for (int si=0; si<2; si++) {
    llong sum=0;
    for (int i=0; i<n; i++) {
      sum+=a[i];
      if (i%2==0) {
        if (sum*signs[si] <= 0) {
          ans[si] += abs(sum)+1;
          sum += (abs(sum)+1)*signs[si];
        }
      } else {
        if (sum*signs[si] >= 0) {
          ans[si] += abs(sum)+1;
          sum -= (abs(sum)+1)*signs[si];
        }
      }
    }
  }

  cout << min(ans[0], ans[1]) << endl;
}

