  for(int i=0; i<n; i++){
    cin >> a[i];
    if(i==0){
      s[0]=a[0];
    }else{
      s[i]=s[i-1]+a[i];
    }
    //cout << s[i] << " ";
  }
  long long int ans = 0,tmp;
  for(int i=0; i<n; i++){
    if(i==0 && a[0] == 0){//初項が0のとき
      for(int j=0; j<n; j++){
        s[j]++;
      }
      ans++;
    }
    if(i!=0){
      if(s[i] == 0){//iまでの和が0のとき,a[i]に1だけ足すか引く
        if(s[i-1]<0){
          for(int j=i; j<n; j++){
            s[j]++;
          }
        }else{
          for(int j=i; j<n; j++){
            s[j]--;
          }
        }
        ans++;
      }else{//iまでの和が0じゃない
        if(s[i-1]>0 == s[i]>0){//i-1までの和とiまでの和の符号が同じ
          tmp=s[i];
          if(s[i]<0){//iまでの和が負なら
            for(int j=i; j<n; j++){
              s[j] += abs(tmp)+1;//a[i]に足してs[i]=1とする
            }
          }else{
            for(int j=i; j<n; j++){
              s[j] -= abs(tmp)+1;//a[i]から引いてs[i]=-1とする
            }
          }
          ans += abs(tmp)+1;
        }
      }
    }
  }
  cout << ans << endl;
}

