void solve() {
  int n;
  cin >> n;
  vi32 a(n);
  cin >> a;
  i64 ans = 1e18;
  auto f = [&](int sum) -> i64 {
    i64 cnt = 0;
    reps(i, n - 1) {
      if (sum > 0) {
        if (sum + a[i] >= 0) {
          cnt += abs(sum + a[i]) + 1;
          sum = -1;
        } else {
          sum += a[i];
        }
      } else {
        if (sum + a[i] <= 0) {
          cnt += abs(sum + a[i]) + 1;
          sum = 1;
        } else {
          sum += a[i];
        }
      }
    }
    return cnt;
  };
  if (a[0] == 0) {
    amin(ans, f(1));
    amin(ans, f(-1));
  } else {
    amin(ans, f(a[0]));
    amin(ans, f(a[0] > 0 ? -1 : 1) + abs(a[0]) + 1);
  }
  cout << ans << endl;
}

