ll cal() {
    ll t = a[0], ans = 0;
    for (int i = 1; i < n; ++i) {
        if (t < 0) {
            t += a[i];
            if (t <= 0) { ans += 1 - t; t = 1; } continue;
        }
        t += a[i];
        if (t >= 0) { ans += t + 1; t = -1; }
    }
    return ans;
}

