typedef pair<lint, lint> P;
const lint MOD = 1000000007;
const lint MOD9 = 998244353;
const lint INF = MOD * MOD;
const int MAX = 200005;

/* ...o(^-^)o... */
int n;
vector<lint> a;

lint solve(int f){
    vector<lint> b(n); lint sum = 0;
    rep(i, n){
        if(i == 0){
            if(f) b[0] = max(1LL, a[0]);
            else b[0] = min(-1LL, a[0]);
            continue;
        }
        sum += b[i-1];
        lint m, M;
        if(sum < 0){
            m = -sum+1;
            if(i < n-1) M = -sum-a[i+1]-1; else M = INF;
            if(m > M) M = INF;
        }
        else{
            M = -sum-1;
            if(i < n-1) m = -sum-a[i+1]+1; else m = -INF;
            if(m > M) m = -INF;
        }

        if(a[i] < m) b[i] = m;
        else if(a[i] <= M) b[i] = a[i];
        else b[i] = M;
    }
    lint res = 0;
    rep(i, n) res += abs(a[i] - b[i]);
    return res;
}

int main(){
    cin >> n;
    rep(i, n){
        lint x; cin >> x; a.push_back(x);
    }
    out(min(solve(0),solve(1)));
}

