using namespace std;

int solve(vector<int>& a, vector<int>& S, int signS0=+1) {

    int op = 0;
    S[0] = a[0];
    if (S[0]*signS0 <= 0) {
        op = abs(S[0]) + 1;
        S[0] = signS0;
    }

    for (size_t i=1; i<a.size(); ++i) {
        S[i] = S[i-1] + a[i];
        if (S[i] == 0) {
            S[i] = -(S[i-1] / abs(S[i-1]));
            ++op;
        }
        else {
            if(S[i-1]*S[i] > 0) {
                op = op + abs(S[i]) + 1;
                // set to +1 or -1.
                S[i] = - (S[i] / abs(S[i]));
            }
        }
    }
    return op;
}

int main() {
    uint n;
    cin >> n;
    vector<int> a(n, 0);
    vector<int> S(n, 0);
    for (auto &x: a) cin >> x;

    int op1 = solve(a, S, +1);
    int op2 = solve(a, S, -1);
    int op = min(op1, op2);
    cout << op << endl;
}

