ll calc(ll tag,vector<ll> a,int n)
{
    ll sum=tag;
    ll res=0;
    for(int i=1;i<n;i++)
    {
        if(sum<0&&sum+a[i]<=0)
        {
            res+=abs(a[i]-(1-sum));
            a[i]=1-sum;
        }
        else if(sum>0&&sum+a[i]>=0)
        {
            res+=abs(a[i]-(-1-sum));
            a[i]=-1-sum;

        }
        sum+=a[i];
    }

    return res;
}

