#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

ll calc(bool plus, vector<ll> a) {
	ll ret = 0;
	int n = a.size();
	if (a[0] == 0) {
		if (plus) {
			a[0] = 1;
		}
		else {
			a[0] = -1;
		}
		ret++;
	}
	else if (a[0] > 0 && !plus) {
		ret += 1 - a[0];
		a[0] = -1;
	}
	else if (a[0] < 0 && plus) {
		ret += a[0] + 1;
		a[0] = 1;
	}

	for (int i = 1; i <= n - 1; i++) {
		a[i] += a[i - 1];
		if (a[i] == 0) {
			if (a[i - 1] < 0) a[i] = 1;
			if (a[i - 1] > 0) a[i] = -1;
			ret++;
		}
		else if (a[i] > 0 && a[i - 1] > 0) {
			ret += a[i] + 1;
			a[i] = -1;
		}
		else if (a[i] < 0 && a[i - 1] < 0) {
			ret += 1 - a[i];
			a[i] = 1;
		}
	}
	return ret;
}

