    long long minus_ans = 0;
    a[0] = -1;
    minus_ans = change_num(a, N) + 1;

    if(plus_ans < minus_ans) {
      ans = plus_ans;
    } else {
      ans = minus_ans;
    }  
  } else {
    ans = change_num(a, N); 
  }

