    }

    long a0 = a.at(0);
    long ans_a, ans_b;

    { // 0th: +
        a.at(0) = a0;
        if(a.at(0) > 0){
            ans_a = body(a);
        }else{
            a.at(0) = 1;
            ans_a = body(a) + (-a0+1);
        }
    }
    { // 0th: -
        a.at(0) = a0;
        if(a.at(0) < 0){
            ans_b = body(a);
        }else{
            a.at(0) = -1;
            ans_b = body(a) + (a0+1);
        }
    }

    long ans = std::min(ans_a, ans_b);

    std::cout << ans << std::endl;

}

