        if (nsum <= 0) {
          op += 1 - nsum;
          nsum = 1;
        }
      } else {
        if (nsum >= 0) {
          op += nsum + 1;
          nsum = -1;
        }
      }
      sum = nsum;
    }
    chmin(ans, op);
  }
  wt(ans);
}

