			now = 1, b[i + 1] = now;
			ans += abs(1 - b[i] - a[i + 1]);
		}
	}
	now = min(-1LL, a[0]);
	ll ans1 = (now == a[0] ? 0 : 1 + a[0]);
	b[0] = now;
	rep(i, n - 1) {
		now += a[i + 1];
		if (now * b[i] < 0)
			b[i + 1] = now;
		else if (b[i] > 0) {
			now = -1, b[i + 1] = now;
			ans1 += abs(b[i] + 1 + a[i + 1]);
		} else {
			now = 1, b[i + 1] = now;
			ans1 += abs(1 - b[i] - a[i + 1]);
		}
	}
	cout << min(ans, ans1) << endl;
	return 0;
}

