int solve(vector<int> csum, int N){

    int cumOper = 0;

    int sign = csum[0]/abs(csum[0]);
    int count = 0;


    int signi;

    for(auto i = 1; i < N; i++){


        if( (csum[i]+cumOper) == 0){
            count++;
            cumOper -= sign;
        }

        signi = (csum[i]+cumOper)/abs(csum[i]+cumOper);

        if (signi!= sign) {
            sign = signi;
            continue;
        }

        ///  csum[i]+cumOperを (-sign)にする。


        /// sign = 1のとき、csum[i]+cumOper > 0なので、 -1になるまで減らす。
        /// sign = -1のとき、csum[i]+cumOper < 0なので、+1になるまで増やす

        if (sign == 1){
            count +=(csum[i] + cumOper + 1);
            cumOper += (-1) * (csum[i] + cumOper + 1);
        }else{
            count +=  (-(csum[i] + cumOper) + 1);
            cumOper += (1) * (-(csum[i] + cumOper) + 1);
        }

        sign = -sign;
    }

    return count;
}




