ll to(ll target, ll now_sum, ll n) {

    ll next_sum = now_sum + n;
    if (target == -1 && next_sum <= -1) return n;
    if (target == 1 && next_sum >= 1) return n;
    ll ab = abs(now_sum - target);

    if (target == -1) return -ab;
    return ab;

}

int main() {
    ll n;
