    vector<ll> numbers(n);
    rep(i, n)cin >> numbers[i];

    auto func = [&](int target) {
        ll now_sum = 0;

        vector<ll> changed = vector<ll>(n);
        for (ll i = 0; i < n; i++) {
            ll t = to(target, now_sum, numbers[i]);
            changed[i] = t;
            now_sum += t;
            target = -target;
        }

        ll now = 0;
        for (ll i = 0; i < n; i++) {
            now += abs(numbers[i] - changed[i]);
        }
        return now;
    };
    // 最初をマイナス
    ll ans = min(func(1), func(-1));

    cout << ans << endl;

}

