inline int sign( long long x ) {
    return x > 0 ? 1 : -1;
}

inline long long solve( int n ) {
    long long sum( arr[1] ), ans( 0 );

    for( int i = 2; i <= n; i ++ ) {
        long long aux( sum + arr[i] );

        if( aux == 0 ) {
            ans ++;

            if( sum < 0 ) aux ++;
            else          aux --;
        }

        if( sign( sum ) == sign( aux ) )
            ans += abs( aux ) + 1, sum = sign( -aux );
        else
            sum = aux;
    }

    return ans;
}

