        ans = solve( n );
    else {
        arr[1] = -1;
        ans = min( ans, 1 + solve( n ) );

        arr[1] = +1;
        ans = min( ans, 1 + solve( n ) );
    }

    cout << ans << endl;
    return 0;
}

