using namespace std;

typedef long long ll;
typedef pair<int, int> P;

ll solve(vector<ll> a_even, int flag){
	int n = (int)a_even.size();
	ll a_even_sum = 0LL;
	ll curr = 0LL;
	rep (i, n){
		if ((i + flag) % 2 == 0){
			if (a_even_sum + a_even[i] < 0LL){
				curr += abs(1LL - (a_even_sum + a_even[i]));
				a_even[i] = abs(1LL - a_even_sum);
			}else
			if (a_even_sum + a_even[i] == 0LL){
				++curr;
				a_even[i] = 1LL;
			} // end if
		}else{ // if ((i + flag) % 2 != 0)
			if (a_even_sum + a_even[i] > 0LL){
				curr += abs(-1LL - (a_even_sum + a_even[i]));
				a_even[i] = -abs(-1LL - a_even_sum);
			}else
			if (a_even_sum + a_even[i] == 0LL){
				++curr;
				a_even[i] = -1LL;
			} // end if
		} // end if
		a_even_sum += a_even[i];
	} // end rep
	return curr;
}

