	rep (i, n){
		cin >> a[i];
	} // end rep

	vector<ll> a_even = a;
	// 偶数を正とする
	ll res = solve(a_even, 0);

	// 奇数を正とする
	a_even = a;
	ll curr = solve(a_even, 1);
	res = min(res, curr);

	cout << res << endl;

	return 0;
}

