    for (i=1;i<N; i++){
      //最初が-なので奇数番めは+にしないと行けない
      if(i%2 == 1){
        sum += input.at(i);
        if (sum <= 0){
          while(sum <= 0){
            count += 1 - sum;
            sum = 1;
          }
        }
      }
      //最初が-なので偶数番めは-にしないと行けない
      if(i%2 == 0){
        sum += input.at(i);
