#define REP(i, n) for(ll i = 0; i < (ll)(n); i++)
#define REPR(i, n) for(ll i = n - 1; i >= 0; i--)
#define REPONE(i, n) for(ll i = 1; i <= (ll)(n); i++)
#define EACH(i, mp) for(auto i:mp)
#define FOR(i, m, n) for(ll i = m;i < n;i++)
int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};

const int MAX_N = int(1e5);
ll n, a[MAX_N], dp[MAX_N];

void solve() {
    ll sum_diff = 0, ans = 0;
    if (dp[0] == 0) {
        dp[0] = 1;
        sum_diff++;
        ans++;
    }
    REP(i, n - 1) {
        ll diff = 0;
        dp[i + 1] += sum_diff;
        if (dp[i] * dp[i + 1] > 0) {
            if (dp[i + 1] > 0) {
                diff = -1 - dp[i + 1];
                sum_diff += diff;
                dp[i + 1] = -1;
            } else {
                diff = 1 - dp[i + 1];
                sum_diff += diff;
                dp[i + 1] = 1;
            }
        }
        if (dp[i + 1] == 0) {
            if (dp[i] > 0) {
                sum_diff++, diff = 1;
                dp[i + 1] = 1;
            } else {
                sum_diff--, diff = -1;
                dp[i + 1] = -1;
            }
        }
        ans += abs(diff);
    }
    cout << ans << endl;
}

int main() {
    cin >> n;
    REP(i, n) {
        cin >> a[i];
        if (i == 0) dp[0] = a[0];
        else dp[i] = dp[i - 1] + a[i];
    }
    solve();
    return 0;
}

