int count(int sign0, vector<int> a, int n) {
    int count = 0;
    int total = 0;
    for (int i = 0; i < n; i++) {
        total += a.at(i);
        if (i % 2 == 1) {
            while(total * sign0 >= 0) {
                total -= sign0;
                count++;
            }
        } else {
            while(total * sign0 <= 0) {
                total += sign0;
                count++;
            }
        }
    }
    return count;
}

