		LL ret = 0;
		LL sum = 0;
		FOR(i, 0, N) {
			LL diff = sum + a[i];
			if (mode && diff <= 0) { // to + 
				ret += abs(diff) + 1;
				diff = 1;
			}
			if (!mode && diff >= 0) { // to -
				ret += abs(diff) + 1;
				diff = -1;
			}
			sum = diff;
			mode = !mode;
		}

		return ret;
	};
	LL ans = min(f(0), f(1));



	cout << (ans) << "\n";

	return 0;
}

