inline long long solve( int n ) {
    long long sum( arr[1] ), ans( 0 );

    for( int i = 2; i <= n; i ++ ) {
        if( sum < 0 && sum + arr[i] <= 0 )
            ans += 1 - sum - arr[i], sum = 1;
        else
        if( sum > 0 && sum + arr[i] >= 0 )
            ans += 1 + sum + arr[i], sum = -1;
        else
            sum += arr[i];
    }

    return ans;
}

