        long long cst = abs( arr[1] ) + 1;
        ans = min( ans, solve( n ) + 0 );

        arr[1] = arr[1] * -1 / abs( arr[1] );
        ans = min( ans, solve( n ) + cst );
    }
    else {
        arr[1] = -1;
        ans = min( ans, solve( n ) + 1 );

        arr[1] = +1;
        ans = min( ans, solve( n ) + 1 );
    }

    cout << ans << endl;
    return 0;
}

