int f(const vector<int>& A, int sign) {
	int sum = 0;
	int res = 0;
	for (auto& a : A) {
		sum += a;
		if (sign * sum < 0) {
			if (sum > 0) {
				res += (sum + 1);
				sum = -1;
			}
			else {
				res += -sum + 1;
				sum = 1;
			}
		}
		if (sum == 0) {
			res += 1;
			sum = sign;
		}
		sign *= -1;
	}
	return res;
}

