    else // S[i] + a[i + 1] <= 0
    {
      S[i + 1] = 1;
      ans_negative += abs(1 - S[i] - a[i + 1]);
    }
  }

  cout << min(ans_positive, ans_negative) << endl;
  return 0;
}

