       * -3 4 -2 2 -2 2*/
      if(sum + array[i] > 0){
	// answer -> answer
	sum += array[0];
      }
      else {
	answer += abs((-1)*sum+1 - array[i]);
	sum = 1;
      }
    }
    else {
      if(sum + array[i] < 0) {
	//answer->answer
	sum += array[i];
      }
      else {
	answer += abs((-1)*sum-1 - array[i]);
	sum = -1;
      }
    }
  }
