void getInput() {
	std::cin >> N;

	for(ull i=0; i<N; ++i) {
		ll A;
		std::cin >> A;
		Ai.push_back(A);
	}
}

//答えを求める
answerType calcAnswer() {
	ull answer = 0;
	bool plus = false;
	bool minus = false;
	ll temp = Ai.at(0);
	if(temp < 0) {
		minus = true;
	} else {
		plus = true;
	}
	for(ull i=1; i<N; ++i) {
		temp += Ai.at(i);
		if(plus) {
			plus = false;
			minus = true;
			while(temp >= 0) {
				--temp;
				++answer;
			}
			continue;
		}
		if(minus) {
			plus = true;
			minus = false;
			while(temp <= 0) {
				++temp;
				++answer;
			}
			continue;
		}
	}
	return answer;
}

