bool is_over(ll target, ll now) {
    assert(target == -1 || target == 1);
    if (target == 1) {
        return now >= 1;
    } else {
        return now <= -1;
    }
}

ll calc_to(ll target, ll now_sum, ll now) {
    if (is_over(target, now_sum + now)) {
        return now;
    } else {
        ll to = target - now_sum;
        assert(now_sum + to == target);
        return to;
    }
}


