using namespace std;


int solve(vector<int> A) {
    int res = 0;
    int sum = A[0];
    for (int i = 1; i < A.size(); i++)
    {
        if (sum > 0) {
            sum += A[i];
            while (sum >= 0) {
                res++;
                sum--;
            }
        }
        else if (sum < 0)
        {
            sum += A[i];
            while (sum <= 0) {
                res++;
                sum++;
            }
        }
    }
    return res;
}

int main() {
    int N;
    cin >> N;

    vector<int> A(N);
    for (int i = 0; i < N; i++)
    {
        cin >> A[i];
    }

    int res;
    if (A[0] != 0)
    {
        res = solve(A);
        cout << res << endl;
    }
    else
    {
        int res_first_plus=1, res_first_minus=1;
        A[0] = 1;
        res_first_plus += solve(A);

        A[0] = -1;
        res_first_minus += solve(A);
        res = min(res_first_plus, res_first_minus);
        cout << res << endl;
    }
}

