int main(){

    int n; cin >> n;
    ll a[n], b[n];
    rep(i, n){
        cin >> a[i];
        b[i] = a[i];
    }

    ll sum = a[0];
    if(sum == 0){
        sum = 1;
    }

    ll cnt1 = 0;
    reps(i, 1, n){
        ll sumNext = sum + a[i];
        if(sumNext*sum >= 0){
            if(sumNext <= 0){
                cnt1 += 1 - sumNext;
                sumNext = 1;
            }
            else{
                cnt1 += 1 + sumNext;
                sumNext = -1;
            }
        }
        sum = sumNext;
        // cout << i << " " << cnt << endl;
    }

    sum = a[0];
    if(sum == 0){
        sum = -1;
    }

    ll cnt2 = 0;
    reps(i, 1, n){
        ll sumNext = sum + b[i];
        if(sumNext*sum >= 0){
            if(sumNext <= 0){
                cnt2 += 1 - sumNext;
                sumNext = 1;
            }
            else{
                cnt2 += 1 + sumNext;
                sumNext = -1;
            }
        }
        sum = sumNext;
        // cout << i << " " << cnt << endl;
    }

    cout << min(cnt1, cnt2) << endl;

    return 0;
}

