				a[i+1] -= 2;
				count += 3;
			}
			continue;
		}else if(sum > 0){
			if(sum + a[i+1] > 0){
				while(sum + a[i+1] >= 0){
					a[i+1]--;
					count++;
				}
				continue;
			}
		}else if(sum < 0){
			if(sum + a[i+1] < 0){
				while(sum + a[i+1] <= 0){
					a[i+1]++;
					count++;
				}
			}
		}
	}

