    current_num += A[i];
    if (before_sign) {
      if (current_num >= 0) {
        ans += current_num + 1;
        current_num = -1;
      }
    } else {
      if (current_num <= 0) {
        ans += abs(current_num) + 1;
        current_num = 1;
      }
    }
    before_sign = !before_sign;
  }
  ANS;

  return 0;
}

