using namespace std;
using LLONG = long long;
const LLONG MOD = 1000000007;

const LLONG Solve(const bool isOddPositive, int N, const vector<LLONG> &as)
{
    LLONG ret = 0;
    LLONG sum = 0;
    // i番目までの総和が期待した符号になっているかどうか判定
    // 期待した符号になっていない場合は，和が最低限（±1）になるまで
    // aiを増減すればよい：O(N)
    for (int i = 0; i < N; ++i)
    {
        sum += as[i];
        bool shouldIncrease = isOddPositive ?
            (i % 2 == 0 && sum <= 0) : (i % 2 == 1 && sum <= 0);
        bool shouldDecrease = isOddPositive ?
            (i % 2 == 1 && sum >= 0) : (i % 2 == 0 && sum >= 0);
        // 和が1になるまでaiを増やす
        if (shouldIncrease)
        {
            ret += 1 - sum;
            sum = 1;
        }
        // 和が-1になるまでaiを減らす
        if (shouldDecrease)
        {
            ret += sum - (-1);
            sum = -1;
        }
    }
    return ret;
}

int main()
{
    int N; cin >> N;
    vector<LLONG> as(N); for (auto &ai : as) cin >> ai;
    // 総和が正から始まる場合と，負から始まる場合をそれぞれ計算し
    // 変更回数が少ない方を選ぶ：O(N)
    auto ans = min(Solve(true, N, as), Solve(false, N, as));
    cout << ans << endl;
}

#include <iostream>
#include <vector>

long body(std::vector<long>& a){
    long ans  = 0;

    std::vector<long> s(a.size());
    s.at(0) = a.at(0);
    for(unsigned long i = 1; i < a.size(); i++){
        s.at(i) = s.at(i-1) + a.at(i);
    }

    long diff = 0;
    for(unsigned long i = 1; i < s.size(); i++){
        s.at(i) += diff; // update
        long n = 0;
        if(s.at(i-1) > 0 && s.at(i) >= 0){
            n = s.at(i) + 1;
            ans += n;
            diff -= n;
            s.at(i) += diff;
        }else if(s.at(i-1) < 0 && s.at(i) <= 0){
            n = - s.at(i) + 1;
            ans += n;
            diff += n;
            s.at(i) += diff;
        }
    }
    return ans;
}

int main(int argc, char **argv)
{
    long n;
    std::cin >> n;

    std::vector<long> a(n);
    for(long i = 0; i < n; i++){
        std::cin >> a.at(i);
    }

    if(a.at(0) != 0){
        ans = body(a);
    }else{
        a.at(0) = -1;
        long ans_a = body(a) + 1;
        a.at(0) = 1;
        long ans_b = body(a) + 1;
        ans = std::min(ans_a, ans_b);
    }

    std::cout << ans << std::endl;

}

