void solve() {
  s[0] = a[0];
  for (int i=1;i<n;i++) {
    s[i] = s[i-1] + a[i];
  }
  ll cnt = 0;
  ll carry = 0;
  for (int i=1;i<n;i++) {
    if ((s[i] + carry) * s[i-1] >= 0) {
      cnt += abs(s[i]+carry) + 1;
      if (s[i-1] < 0) {
        carry += abs(s[i]) + 1;
        s[i] = 1;
      } else {
        carry -= abs(s[i]) + 1;
        s[i] = -1;
      }
    } else {
      s[i] += carry;
    }
  }
  cout << cnt << endl;
}

