  cin >> N;
  int sum = 0;
  rep(i,N) {
    int a;
    cin >> a; A[i] = a;
    sum += a; S[i] = sum;
  }
  bool pos = true;
  int plus, minus;
  plus = change(pos);
  pos = false;
  minus = change(pos);
  // cout << "minus: " << minus << "plus: " << plus << endl;
  cout << min(plus, minus) << endl;

}

