long long solve(const vector<long long> data, int sign) {
    int n = data.size();
    vector<long long> a = data;

    long long result = 0;
    long long sum = 0;
    for(int i=0; i<n; i++) {
        long long k = (sum + a[i]) * sign;
        if(i%2!=0) {
            if(k <= 0) {
                result += 1 - k;
                a[i] += (1 - k) * sign;
            }
        }
        else {
            if(k >= 0) {
                result += 1 + k;
                a[i] -= (1 + k) * sign;
            }
        }
        sum += a[i];
    }

    return result;

}

