int main(void) {
    int n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a.at(i);
    }

    // 全ての i に対し、i 項までの和と i+1 項までの和の符号が異なる
    // => 全ての i に対し、1~n 項までの和は 0 でない
    // これが成立する
    int sum = 0, sign = 1;
    int ans_a = 0;
    for (int i = 0; i < n; i++) {
        sum += a.at(i);
        if (sum <= 0 && sign == 1) {
            while (sum <= 0) {
                sum++;
                ans_a++;
            }
        }
        if (sum >= 0 && sign == -1) {
            while (sum >= 0) {
                sum--;
                ans_a++;
            }
        }
        sign *= -1;
    }

    sum = 0, sign = -1;
    int ans_b = 0;
    for (int i = 0; i < n; i++) {
        sum += a.at(i);
        if (sum <= 0 && sign == 1) {
            while (sum <= 0) {
                sum++;
                ans_b++;
            }
        }
        if (sum >= 0 && sign == -1) {
            while (sum >= 0) {
                sum--;
                ans_b++;
            }
        }
        sign *= -1;
    }

    int ans = min(ans_a, ans_b);
    cout << ans << endl;
}

