    accsums1[0] = accsums2[0] = temp0;
    rep (n-1, i){
        ll temp;
        scanf("%lld\n", &temp);
        accsums1[i+1] = temp + accsums1[i];
        accsums2[i+1] = temp + accsums1[i];
    }
    //even(0-indexed) > 0
    ll ans1 = 0;
    rep(n, i) {
        if ((i % 2 == 0 and accsums1[i] > 0) or (i % 2 != 0 and accsums1[i] < 0)) continue;
        if (i % 2 == 0) {
            ll diff = 1 - accsums1[i];
            ans1 += diff;
            Rep(i+1, n-1, j) accsums1[j] += diff;
        }
        else {
            ll diff = 1 + accsums1[i];
            ans1 += diff;
            Rep(i+1, n-1, j) accsums1[j] -= diff;
        }
    }
    //even(0-indexed) < 0
    ll ans2 = 0;
    rep(n, i) {
        if ((i % 2 == 0 and accsums2[i] < 0) or (i % 2 != 0 and accsums2[i] > 0)) continue;
        if (i % 2 != 0) {
            ll diff = 1 - accsums2[i];
            ans2 += diff;
            Rep(i+1, n-1, j) accsums2[j] += diff;
        }
        else {
            ll diff = 1 + accsums2[i];
            ans2 += diff;
            Rep(i+1, n-1, j) accsums2[j] -= diff;
        }
    }
    cout << min(ans1, ans2) << '\n';
}

