using namespace std;

int solve(vector<int> vec)
{
    ll n = vec.size();
    ll sum = vec[0];
    int ans = 0;
    for (ll i = 1; i < n; i++) {
        if (sum > 0) {
            if (sum + vec[i] >= 0) {
                ans += 1 + (sum + vec[i]);
                sum = -1;
            } else{
                sum += vec[i];
            }
        } else if (sum < 0) {
            if (sum + vec[i] <= 0) {
                ans += 1 - (sum + vec[i]);
                sum = 1;
            } else{
                sum += vec[i];
            }
        }
    }
    return ans;
}

int main() {
    int n, Ans;
    cin >> n;
    vector<int> as;

    for(int i = 0; i < n; i++) {
        int t;
        cin >> t;
        as.push_back(t);
    }
    vector<int> as1 = as; as1[0] = 1;
    vector<int> as2 = as; as2[0] = -1;
    Ans = min(solve(as), min(solve(as1) + abs(1-as[0]), solve(as2)+abs(-1-as[0])));
    cout << Ans << endl;
    return 0;
}

