    for(int i=0; i<n; i++){
        if(i!=0) os[i] = os[i-1]+a[i];
        if(i%2==0 && os[i]>=0){
            ocnt += abs(-1-os[i]);
            os[i] = -1;
        }
        else if(i%2!=0 && os[i]<=0){
            ocnt += abs(1-os[i]);
            os[i] = 1;
        }
    }

    cout << (ecnt<ocnt?ecnt:ocnt) << endl;
