typedef long long ll;

ll count(vector<int> a, bool positive) {
    ll total = 0, count = 0, diff = 0;
    for (int i = 0; i < a.size(); i++) {
        diff = 0;
        if (positive && (a[i] + total <= 0)) {
            diff = (1 - total) - a[i];
        } else if (!positive && (a[i] + total >= 0)) {
            diff = (-1 - total) - a[i];
        }
        positive = (positive) ? false : true;
        a[i] += diff;
        count += abs(diff);
        total += a[i];
    }
    return count;
}

