lint subfunc(lint n, std::vector<long long> a, bool isPlus){
    // isPlus: 今，和はプラスであるべきか，マイナスであるべきか

    lint b[n]; // 結果を示す(デバッグ用)
    lint total = 0LL; // ここまでのa[i]の和
    lint resCount = 0LL; // 置き換えた数 = 結果となるコスト

    REP(i, n){
        // まず，一旦，a[i]のまま値を設定　+ 和を取る
        total += a[i];
        b[i] = a[i];
        if (isPlus && total < 1) { // 和はplusであるべきなのに，和がマイナスか0なら
            resCount += (-total) + 1; // 和を+1にするまでインクリメント
            b[i] += (-total) + 1;
            total = 1; // 和を+1にする
        }
        else if(!isPlus && total > -1){ // 和は-であるべきなのに，和が+か0なら
            resCount += (total) + 1; // 和を-1にするまでデクリメント
            b[i] -= (total) + 1;
            total = -1; // 和を-1にする
        }
        isPlus = !isPlus; // 次の和は記号反転
    }
    // 以下のコメントアウト外すとこのパターンでのコストと数列が出る
    //cout << "res:"; REP(i, n) cout << " " << b[i]; cout << "\n";
    //cout << "cost:" <<resCount << "\n";
    return resCount;
}

int main(){

    long long n;
    lint res1, res2;
    scanf("%lld",&n);
    std::vector<long long> a(n);
    for(int i = 0 ; i < n ; i++){
        scanf("%lld",&a[i]);
    }

    // [注意] 以下の渡し方はaのcopyが走るので本当はうれしくない
    res1 = subfunc(n, a, true);  // パターン1: プラス始まり (+ - + -)
    res2 = subfunc(n, a, false); // パターン2: マイナス始まり (- + - +)
    cout << min(res1, res2) << "\n"; // で，コストが小さいほうを表示
    return 0;
}

