    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        if (i > 0)
            a[i] += a[i - 1];
    }

    ll add[2] = {0}, addcnt[2] = {0};
    for (int i = 0; i < n; ++i) {
        int sign = (i % 2 ? -1 : 1);
        ll tmp;

        // +, -, +, ...
        tmp = (a[i] + add[0]) * sign;
        if (tmp <= 0) {
            addcnt[0] += abs(tmp) + 1;
            add[0] += (abs(tmp) + 1) * sign;
        }

        // -, +, -, ...
        tmp = -(a[i] + add[1]) * sign;
        if (tmp <= 0) {
            addcnt[1] += abs(tmp) + 1;
            add[1] -= (abs(tmp) + 1) * sign;
        }
    }
    cout << min(addcnt[0], addcnt[1]) << endl;
    return 0;
}

