ll func(ll a[], int n) {
  ll cnt = 0;
  ll s = 0;
  for (int i = 1; i < n; i++) {
    s += a[i-1];
    ll t = 0, u;
    if (s > 0) {
      u = (-1)*s - 1;
      if (u < a[i]) {
        t = a[i] - u;
        a[i] = u;
      } 
    }
    else {
      u = (-1)*s + 1;
      if (u > a[i]) {
        t = u - a[i];
        a[i] = u;
      } 
    }
    cnt += t;
  }
  return cnt;
}

