int beginPositive(std::vector<int> &v) {
  int sum = v[0] + v[1];
  int count = 0;

  if (sum < 0) {
    count = 1 - sum;
    sum = 1;
  }
  for (int i = 2; i < v.size(); i++) {
    int tmp = sum + v[i];

    if (sum*tmp < 0) {
      sum = tmp;
      continue;
    }

    int next_sum = (-1) * sum / abs(sum);
    count += abs(next_sum-tmp);
    sum = next_sum;
  }
  return count;
}

int beginNegative(std::vector<int> &v) {
  int sum = v[0] + v[1];
  int count = 0;

  if (sum > 0) {
    count = sum + 1;
    sum = -1;
  }
  for (int i = 2; i < v.size(); i++) {
    int tmp = sum + v[i];

    if (sum*tmp < 0) {
      sum = tmp;
      continue;
    }

    int next_sum = (-1) * sum / abs(sum);
    count += abs(next_sum-tmp);
    sum = next_sum;
  }
  return count;
}

