int body(std::vector<int>& a){
    int ans  = 0;

    std::vector<int> s(a.size());
    s.at(0) = a.at(0);
    for(unsigned int i = 1; i < a.size(); i++){
        s.at(i) = s.at(i-1) + a.at(i);
    }

    for(unsigned int i = 1; i < s.size(); i++){
        if(s.at(i-1) > 0 && s.at(i) >= 0){
            int n = s.at(i) + 1;
            ans += n;
            for(unsigned int j = i; j < s.size(); j++){
                s.at(j) -= n;
            }
        }
        if(s.at(i-1) < 0 && s.at(i) <= 0){
            int n = -1 * s.at(i) + 1;
            ans += n;
            for(unsigned int j = i; j < s.size(); j++){
                s.at(j) += n;
            }
        }
    }
    return ans;
}

