int solve(bool idZeroPositive, int n, vector<int> a) {
	int ans = 0;
	if (idZeroPositive) {
		if (a[0] <= 0) {
			ans += -a[0] + 1;
			a[0] = 1;
		}
	}
	else {
		if (a[0] >= 0) {
			ans += a[0] + 1;
			a[0] = -1;
		}
	}

	int su = 0;
	rep(i, n) {
		su += a[i];
		if (idZeroPositive) {
			if (i % 2 == 0 && su <= 0) {
				ans += -su + 1;
				su = 1;
			}
			if (i % 2 == 1 && su >= 0) {
				ans += su + 1;
				su = -1;
			}
		}
		else {
			if (i % 2 == 1 && su <= 0) {
				ans += -su + 1;
				su = 1;
			}
			if (i % 2 == 0 && su >= 0) {
				ans += su + 1;
				su = -1;
			}
		}
	}
	return ans;
}

