using namespace std;

long long solve(const vector<int>& a, bool s)
{
    long long cnt = 0;
    long long sum = a[0];
    if (s) {
        if (sum <= 0) {
            cnt += -(sum - 1);
            sum = 1;
        }
    } else {
        if (sum >= 0) {
            cnt += (sum + 1);
            sum = -1;
        }
    }

    for (size_t i = 1; i < a.size(); ++i) {
        long long sum2 = sum + a[i];
        if (sum < 0) {
            if (sum2 <= 0) {
                cnt += -(sum2 - 1);
                sum2 = 1;
            }
        } else {
            if (sum2 >= 0) {
                cnt += (sum2 + 1);
                sum2 = -1;
            }
        }
        sum = sum2;
    }

    return cnt;
}

int main()
{
    int N;
    cin >> N;

    vector<int> a;
    for (int i = 0; i < N; ++i) {
        int ai;
        cin >> ai;
        a.push_back(ai);
    }


    cout << min(solve(a, true), solve(a,false)) << endl;

    return 0;
}

