void solve()
{
	int n;
	cin >> n;
	ll x, y, X, Y, a, i;
	x = y = X = Y = i = 0;
	while (cin >> a && ++i)
	{
		x += a, y += a;
		if (i % 2)
		{
			if (x > -1)
				X += x + 1, x = -1;
			if (y < 1)
				Y += 1 - y, y = 1;
		}
		else
		{
			if (y > -1)
				Y += y + 1, y = -1;
			if (x < 1)
				X += 1 - x, x = 1;
		}
	}
	cout << min(X, Y);
}

