int minuss(int n, vector<int> a){
  int x = 0;
  int sum = 0; //手前までの合計
  int counter = 0; //操作回数
  while(x < n){
    if(x % 2 == 0 && sum + a.at(x) >= 0){
      int olda = a.at(x);
      a.at(x) = -1 - sum;
      counter += abs(a.at(x) - olda);
    }
    if(x % 2 == 1 && sum + a.at(x) <= 0){
      int olda = a.at(x);
      a.at(x) = 1 - sum;
      counter += abs(a.at(x) - olda);
    }
    sum += a.at(x);
    x++;
  }
  return counter;
}

int pluss(int n, vector<int> a){
