      int olda = a.at(x);
      a.at(x) = 1 - sum;
      counter += abs(a.at(x) - olda);
    }
    if(x % 2 == 1 && sum + a.at(x) >= 0){
      int olda = a.at(x);
      a.at(x) = -1 - sum;
      counter += abs(a.at(x) - olda);
    }
