long first_plus(vector<long> &A) {
    long sum = 0;
    long res = 0;
    for (int i = 0; i < A.size(); i++)
    {
        sum += A[i];
        if (i % 2 == 0)
        {
            while (sum < 1)
            {
                sum++;
                res++;
            }
        }
        else
        {
            while (sum > -1) {
                sum--;
                res++;
            }
        }
    }
    return res;
}

long first_minus(vector<long> &A) {
    long sum = 0;
    long res = 0;
    for (int i = 0; i < A.size(); i++)
    {
        sum += A[i];
        if (i % 2 == 0)
        {
            while (sum > -1) {
                sum--;
                res++;
            }
        }
        else
        {
            while (sum < 1)
            {
                sum++;
                res++;
            }
        }
    }
    return res;
}

