#define FOR(v, b, e)   for (int v = (b); v < (e); ++v)

int calc (vector<int>& a) {
	int sum   = a[0];
	int count = 0;
	FOR (i, 1, a.size()) {
		if (sum < 0) {
			sum += a[i];
			if (sum <= 0) {
				count += 1 - sum;
				sum    = 1;
			}
			continue;
		}

		sum += a[i];
		if (sum >= 0) {
			count += sum + 1;
			sum    = -1;
		}
	}
	return count;
}

int main () {
	ios::sync_with_stdio(false);
	cin.tie(0);

	int N;
	cin >> N;

	vector<int> a(N);
	for (auto& ai : a) cin >> ai;

	int count = 0;
	int sum   = a[0];

	if (sum == 0) {
		a[0]        = 1;
		auto count1 = calc(a);

		a[0]        = -1;
		auto count2 = calc(a);

		count = min(count1, count2);
	} else {
		auto count1 = calc(a);

		a[0]        = 1;
		auto count2 = calc(a) + abs(1 - sum);

		a[0]        = -1;
		auto count3 = calc(a) + abs(-1 - sum);

		count = min(count1, min(count2, count3));
	}

	cout << count << endl;
}

