			s.at(i) = s.at(i - 1) + a.at(i);
			if (s.at(i - 1) * s.at(i) > 0 && s.at(i) < 0) {
				ans += 1 - s.at(i);
				s.at(i) = 1;
				continue;
			}
			if (s.at(i - 1) * s.at(i) > 0 && s.at(i) > 0) {
				ans += s.at(i) + 1;
				s.at(i) = -1;
				continue;
			}
			if (s.at(i - 1) * s.at(i) == 0) {
				if (s.at(i - 1) > 0) {
					s.at(i) = -1;
					ans++;
					continue;
				}
				if (s.at(i - 1) < 0) {
					s.at(i) = 1;
					ans++;
				}
			}
		}
	}
	cout << ans << endl;

	return 0;
}

