int calc (vector<int>& a) {
	int sum   = a[0];
	int count = 0;
	FOR (i, 1, a.size()) {
		if (sum < 0) {
			sum += a[i];
			if (sum <= 0) {
				count += 1 - sum;
				sum    = 1;
			}
			continue;
		}

		sum += a[i];
		if (sum >= 0) {
			count += sum + 1;
			sum    = -1;
		}
	}
}

