		return NEGATIVE;
	}
	return ZERO;
}

long long int count(int sign0, vector<long long> a, int n){
	long long int sum = 0;
	long long int sign = sign0;
	long long int count = 0;

	for(int i=0; i<n; ++i){
		sum += a[i];
		if (getsign(sum) != sign){
			count += abs(sign - sum);
			sum = sign;
		}
		sign = SWAP_SIGN(sign);
	}

	return count;
}



