            sum_diff--, ans++;
        }
    }
    REP(i, n - 1) {
        ll diff = 0;
        dp[i + 1] += sum_diff;
        if (dp[i] * dp[i + 1] > 0) {
            if (dp[i + 1] > 0) {
                diff = -1 - dp[i + 1];
                sum_diff += diff;
                dp[i + 1] = -1;
            } else {
                diff = 1 - dp[i + 1];
                sum_diff += diff;
                dp[i + 1] = 1;
            }
        }
        if (dp[i + 1] == 0) {
            if (dp[i] > 0) {
                sum_diff--, diff--;
                dp[i + 1] = -1;
            } else {
                sum_diff++, diff++;
                dp[i + 1] = 1;
            }
        }
        ans += abs(diff);
    }
    cout << ans << endl;
}

int main() {
    cin >> n;
    REP(i, n) {
        cin >> a[i];
        if (i == 0) dp[0] = a[0];
        else dp[i] = dp[i - 1] + a[i];
    }
    solve();
    return 0;
}

