template <typename T>
struct BIT
{
private:
    int n; // 配列の要素数(数列の要素数+1)
    vector<T> bit;

public:
    BIT(int n_) : n(n_ + 1), bit(n, 0) {}

    void add(int i, T x)
    {
        for (int idx = i; idx < n; idx += (idx & -idx))
        {
            bit[idx] += x;
        }
    }

    T sum(int i)
    {
        T s(0);
        for (int idx = i; idx > 0; idx -= (idx & -idx))
        {
            s += bit[idx];
        }
        return s;
    }
    // [l,r) の区間和を取得
    T query(int l, int r) { return sum(r - 1) - sum(l - 1); }
    int lower_bound(T w)
    { // a_1 + a_2 + ... + a_x >= w となるような最小の x を求める(ただし a_i >= 0)
        if (w <= 0)
        {
            return 0;
        }
        else
        {
            int x = 0, r = 1;
            while (r < n)
                r = r << 1;
            for (int len = r; len > 0; len = len >> 1)
            { // 長さlenは1段下るごとに半分に
                if (x + len < n && bit[x + len] < w)
                { // 採用するとき
                    w -= bit[x + len];
                    x += len;
                }
            }
            return x + 1;
        }
    }
};
//配列aの転倒数を高速に求める
ll inversion(vec a)
{
    ll siz = a.size();
    BIT<ll> inv(siz);
    ll ret = 0;
    loop(i, siz)
    {
        ret += (i - inv.sum(a[i]));
        inv.add(a[i], 1);
    }
    return ret;
}
/*
