bits.assign(x,n);
で長さnのBITをx本宣言
*/
/* BIT: 
    BIT<ll> data(n)等で宣言
    構造体内の関数はdata.add(l,x)等で使用
    初期値は a_1 = a_2 = ... = a_n = 0
    ・add(l,x): [l,l+1) に x を加算する(1-indexに注意！！(l>=1))
    ・sum(i): a_1 + a_2 + ... + a_i を計算する
    ・query(l,r):[l,r)の区間和を取得する
    ・lower_bound(w):a_1 + a_2 + ... + a_x >= w となるような最小の x を求める(ただし a_i >= 0)
    計算量は全て O(logn)
    (おまけ)
    BITとBIT上での二分探索を活用すると、集合を管理して、
　　・a が何番目に小さいか
　　・w 番目に小さい要素 a は何か
　　というのを以下のように O(logn) で高速に取得することが可能
    add(a,1): 集合への要素 a の追加(a 番目を 1 にする)
　　add(a,-1): 集合への要素 a の削除(a 番目を 1 から 0 にする)
　　sum(a): a が何番目に小さいか
　　lower_bound(w): w 番目に小さい要素 a は何か
*/
int main()
{
    cout << fixed << setprecision(30);
    ll N;
    cin >> N;
    vec a(N);
    loop(i, N) cin >> a[i];
    BIT<ll> data(N), data2(N);
    loop(i, N)
    {
        data.add(i + 1, a[i]);
        data2.add(i + 1, a[i]);
    }
    ll ans1 = 0, ans2 = 0;
    loop(i, N)
    {
        ll now = data.sum(i + 1);
        if (i % 2 == 0)
        {
            if (now <= 0)
            {
                ans1 += 1 - now;
                data.add(i + 1, 1 - now);
            }
        }
        else if (now >= 0)
        {
            ans1 += now + 1;
            data.add(i + 1, -1 - now);
        }
    }
    loop(i, N)
    {
        ll now = data2.sum(i + 1);
        if (i % 2 == 1)
        {
            if (now <= 0)
            {
                ans2 += 1 - now;
                data2.add(i + 1, 1 - now);
            }
        }
        else if (now >= 0)
        {
            ans2 += now + 1;
            data2.add(i + 1, -1 - now);
        }
    }
    putout(min(ans1, ans2));
    return 0;
}

