static std::uint64_t
solve(const std::vector<int>& va, int initSum, std::uint64_t initCnt = 0)
{
  int sum = initSum;
  std::uint64_t cnt = initCnt;
  for (std::remove_reference<decltype(va)>::type::size_type i = 1; i < va.size(); i++) {
    auto nextSum = sum + va[i];
    if (nextSum >= 0 && sum > 0) {
      cnt += nextSum + 1;
      sum = -1;
    } else if (nextSum <= 0 && sum < 0) {
      cnt += -nextSum + 1;
      sum = 1;
    } else {
      sum = nextSum;
    }
  }
  return cnt;
}


