        if ( k % 2 == 0 ) { // S[k] must be +1
          // cout << "Diff : " << 1 - ( S[k] + diff ) << endl;
          counter = abs(1- (S[k] + diff));
          // cout << "count : " << counter << endl;
          diff += 1 - ( S[k] + diff );
          cnt += counter;
        } else { // S[k] must be -1
          // cout << "Diff : " << -1 - ( S[k] + diff ) << endl;
          counter = abs((S[k] + diff) + 1);
          // cout << "count : " << counter << endl;
          diff += -1 - ( S[k] + diff );
          cnt += counter;
        }
      }
    }
    // if ( k == -1) return 0;
  } else {
    rep(i, N) {
      if (S[i] + diff > 0 && i%2 == 1) continue;
      else if (S[i] + diff < 0 && i%2 == 0) continue;
      else { // If S[i] doesn't satisfy the rule
        k = i;
        // cout << "Change-: " <<  k << endl;
        if ( k % 2 == 1 ) { // S[k] must be +1
          // cout << "Diff : " << 1 - ( S[k] + diff ) << endl;
          counter = abs(1 - (S[k] + diff));
          // cout << "count : " << counter << endl;
