  ll sum = a.at(0);
  for (int i = 1; i < n; i++) {
    sum = sum + a.at(i);
    // 奇数の場合、第1項と和の符号が異なる
    if (i % 2 == 1) {
      // 数列の第1項が正の数の場合
      if (is_positive) {
        // 対象の項が負の数なら、そのままでOK
        if (sum < 0) {
          continue;
        // 対象の項が正の数なら、負の数の最小である -1 まで操作する
        } else {
          ll target = sum - (-1);
          ans += target;
          a.at(i) -= target;
          sum -= target;
        }
      // 数列の第1項が負の数の場合
      } else {
        // 対象の項が正の数なら、そのままでOK
        if (sum > 0) {
          continue;
        // 対象の項が負の数なら、正の数の最小である +1 まで操作する
        } else {
          ll target = (1) - sum;
          ans += target;
          a.at(i) += target;
          sum += target;
        }
      }
    // 偶数の場合、第1項と和の符号が同じ
    } else {
      // 数列の第1項が正の数の場合
