          ans += target;
          a.at(i) += target;
          sum += target;
        }
      // 数列の第1項が負の数の場合
      } else {
        // 対象の項が負の数なら、そのままでOK
        if (sum < 0) {
          continue;
        // 対象の項が正の数なら、負の数の最小である -1 まで操作する
        } else {
          ll target = sum - (-1);
          ans += target;
          a.at(i) -= target;
          sum -= target;
        }
      }
    }
  }

  cout << ans << endl;
