ll plus_sequence(int n) {
	ll ans = 0, sum = a[0];
	if (a[0] <= 0) {
		ans = -a[0] + 1;
		sum = 1;
	}
	for (int i = 1;i < n;i++) {
		sum += a[i];
		if (i%2==1) {
			if (sum > 0) {
				ans = ans + sum + 1;
				sum = -1;
			}
			else {
				if (sum == 0) {
					ans++;
					sum--;
				}
			}
		}
		else {
			if (sum < 0) {
				ans = ans - sum + 1;
				sum = 1;
			}
			else {
				if (sum == 0) {
					ans++;
					sum++;
				}
			}
		}
	}
	return ans;
}

ll minus_sequence(int n) {
	ll ans = 0, sum = a[0];
	if (a[0] >= 0) {
		ans = a[0] + 1;
		sum = -1;
	}
	for (int i = 1;i < n;i++) {
		sum += a[i];
		if (i%2==0) {
			if (sum > 0) {
				ans = ans + sum + 1;
				sum = - 1;
			}
			else {
				if (sum == 0) {
					ans++;
					sum--;
				}
			}
		}
		else {
			if (sum < 0) {
				ans = ans - sum + 1;
				sum = 1;
			}
			else {
				if (sum == 0) {
					ans++;
					sum++;
				}
			}
		}
	}
	return ans;
}

