int ans(int n, int *s, int change){
  int Ans = 0;
  int b[110000];
  for(int i = 0; i < n; i++) b[i] = s[i];
  for(int i = 0; i < n; i++){
    switch (change) {
      case -1:
      while(b[i] > -1){
        for(int j = i; j < n; j++) --b[j];
        ++Ans;
      }
      change *= -1;
      break;

      case 1:
      while(b[i] < 1){
        for(int j = i; j < n; j++) ++b[j];
        ++Ans;
      }
      change *= -1;
      break;
    }
  }

  return Ans;
}

