#include <algorithm>
#include <iostream>

int calc(bool firstPositive, const int a[], int n) {
  bool positive = firstPositive;
  int cost = 0;
  long sum = 0;
  for (int i = 0; i < n; ++i) {
    int v = a[i];
    bool sumpos = (sum + v) >= 0;
    if (sumpos != positive) {
      cost += abs(sum + a[i]) + 1;
      v = -(sum + v) + (positive ? -1 : 1);
    }
    if ((sum + v) == 0) {
      v += sumpos ? -1 : 1;
      ++cost;
    }
    sum += v;
    positive = !positive;
  }
  return cost;
}

