	}
	// sums[0] == sums[1]
	else if (v[0] == 0) {
		ans += 1;
		v[0] = 1;
	}

	ll now,pre;
	now = pre = v[0];
	for (size_t i = 1; i < n; i++) {
		now = v[i] + pre;
		if (pre * now >= 0) {
			if (pre > 0) {
				ans = ans + abs(now) + 1;
				now = -1;
			}
			else if (pre < 0) {
				ans = ans + abs(now) + 1;
				now = 1;
			}
		}
		pre = now;
	}

	std::cout << ans << '\n';
	return 0;
}

