                auto x = new_sign - new_accum;
                new_accum += x;
                cnt += abs(x);
                cp[i] += x;
            }
            accum = new_accum;
            sign = new_sign;
        }

        cnt_min = min(cnt, cnt_min);
    }
    cout << cnt_min << endl;
