long long solve(int x) {
  long long ans = 0, now = 0;
  for(long long i = 0; i < n; ++i) {
    now += a[i];
    if((i % 2 ^ x) && (now >= 0)) {
      ans += now + 1;
      now = -1;
    }
    if(!(i % 2 ^ x) && (now <= 0)) {
      ans -= now - 1;
      now = 1;
    }
  }
  return ans;
}

