			i++;
		if (i % 2 == 0) {
			b[0] = 1;
			sum2 = 1;
		}
		else {
			b[0] = -1;
			sum2 = -1;
		}
		sum++;
	}
	for (ll i = 1; i < n; i++) {
		b[i] += sum2;
		if (b[i] == 0) {
			if (b[i - 1] > 0) {
				sum2--;
				sum++;
				b[i] = -1;
			}
			else {
				sum2++;
				sum++;
				b[i] = 1;
			}
		}
		else {
			if (b[i - 1] > 0 && b[i] > 0) {
				sum2 -= (b[i]+1);
				sum += (b[i] + 1);
				b[i] = -1;
			}
			else if (b[i] < 0 && b[i - 1] < 0) {
				sum2 += (0 - b[i] + 1);
				sum += (0 - b[i] + 1);
				b[i] = 1;
			}
		}
