    ll sum = 0;
    for (int i = 0; i < n; i++) {
        if (i % 2 == 0) {
            if (sum+a[i]>=0) {
                res0 += abs(a[i] + sum + 1);
                sum = -1;
            } else {
                sum += a[i];
            }
        } else {
            if (sum+a[i]<=0) {
                res0 += abs(a[i] + sum - 1);
                sum = 1;
            } else {
                sum += a[i];
            }
        }
    }

    ll res1 = 0;
    sum = 0;
    for (int i = 0; i < n; i++) {
