        sum = a[0];
        sum1 = -1;
        cnt1+= (abs(a[0]) + 1);
    } else if(a[0] < 0){
        sum = 1;
        cnt = a[0] + 1;
        sum1 = a[0];
    } else {
        sum = 1, sum1 = -1;
        cnt = 1, cnt1 = 1;
    }

    for(ll i = 1; i < n; i++) {
        if(sum*(sum + a[i]) < 0) sum+=a[i];
        else {
            cnt+= (abs(sum + a[i]) + 1);
            sum = (sum < 0 ? 1 : -1);
        }
        if(sum1*(sum1 + a[i]) < 0) sum1+=a[i];
        else {
            cnt1+= (abs(sum1 + a[i]) + 1);
            sum1 = (sum1 < 0 ? 1 : -1);
        }
    }
    cout << min(cnt1, cnt) << endl;
}

