//pattern=1は正負正負,-1は負正負正
ll calc(vi a, int pattern) {
    ll count = 0;
    ll sa;
    ll bi = 0;
    rep(i, a.size()) {
        if ((pattern == 1 && a[i] + bi > 0) || (pattern == -1 && a[i] + bi < 0)) {
            pattern *= -1;
            continue;
        }
        sa = a[i] + bi - pattern;
        bi -= sa;
        count += llabs(sa);
        pattern *= -1;
    }
    return count;
}

int main() {
    int n;
    cin >> n;
    vi a(n);
    rep(i, n) cin >> a[i];
    FOR(i, 1, n) a[i] += a[i - 1];
    ll mi = min(calc(a, 1), calc(a, -1));
    cout << mi << endl;
    return 0;
}

