int solve(){
    int Num = 0, Sum = 0;

    for(int i = 0; i < N; i++) {
        if(i % 2 == 0) {
            if(Sum + a[i] <= 0) {
                Num += 1 - (Sum + a[i]);
                Sum = 1;
            }else Sum += a[i];
        }else{
            if(Sum + a[i] >= 0) {
                Num += 1 + Sum + a[i];
                Sum = -1;
            }else Sum += a[i];
        }
    }
    return Num;
}

