    if (a[0] > 0)
    {
        case1 = 0;
        total = a[0];
    }
    else //if (a[0] <= 0)
    {
        case1 = 1 - a[0];
        total = 1;
    }
    for (int64_t i = 1; i < n; i++)
    {
        int64_t ttmp = total + a[i];
        int64_t atmp = a[i];
        if ((ttmp * total) < 0 && ttmp != 0)
        {
            total = ttmp;
        }
        else
        {
            if (total > 0)
            {
                a[i] = -total - 1;
            }
            else
            {
                a[i] = -total + 1;
            }
            total += a[i];
        }
        case1 += abs(a[i] - atmp);
    }

    //negative-positive... case
    int64_t case2;
    if (b[0] < 0)
    {
        case2 = 0;
        total = b[0];
    }
    else //if (a[0] >= 0)
    {
        case2 = -1 - b[0];
        total = -1;
    }
    for (int64_t i = 1; i < n; i++)
    {
        int64_t ttmp = total + b[i];
        int64_t atmp = b[i];
        if ((ttmp * total) < 0 && ttmp != 0)
        {
            total = ttmp;
        }
        else
        {
            if (total > 0)
            {
                b[i] = -total - 1;
            }
            else
            {
                b[i] = -total + 1;
            }
            total += b[i];
        }
        case2 += abs(b[i] - atmp);
    }
    cout << min(case1, case2) << endl;
}

