bool should_continue(int p_num, int n_sum) {
  if (p_num < 0 && n_sum > 0) {
    return true;
  }
  if (p_num > 0 && n_sum < 0) {
    return true;
  }
  return false;
}

int main() {

  int n;
  scanf("%d", &n);

  // int a[(int)std::pow(10, 5)];
  int a[n];
  for (int i=0; i<n; i++) {
    scanf("%d", a+i);
  }

  int p_sum = a[0];
  int n_sum = a[0] + a[1];
  int i = 2;
  int cnt = 0;

  while (true) {
    if (should_continue(p_sum, n_sum)) {
      if (i == n) {
        break;
      }
      p_sum = n_sum;
      n_sum += a[i];
      ++i;
      continue;
    }
    if (p_sum == 0) {
      if (n_sum > 0) {
        --p_sum;
        --n_sum;
      } else {
        ++p_sum;
        ++n_sum;
      }
    } else if (p_sum < 0) {
      ++n_sum;
    } else {
      --n_sum;
    }
    ++cnt;
  }
  printf("%d", cnt);
}

