ll pm(vector<int> a){
    ll ans=0, sum = 0;
    int len = a.size();
    for(int i = 0; i < len; i+=2)
    {
        sum += a[i];
        if(sum <= 0){
            ans += abs(1-sum);
            sum = 1;
        }
        if(i+1 > len-1) break; 
        sum += a[i+1];
        if(sum >= 0){
            ans += abs(-1-sum);
            sum = -1;
        }
    }

    return ans;    
}

