#define FOR(v, b, e)   for (int v = (b); v < (e); ++v)

typedef long long           ll;
typedef unsigned long long  ull;

ll calc (int a0, vector<int>& a) {
	ll total  = a0;
	ll result = 0;
	FOR (i, 1, a.size()) {
		if (total < 0) {
			total += a[i];
			if (total <= 0) {
				result += 1 - total;
				total   = 1;
			}
			continue;
		}

		total += a[i];
		if (total >= 0) {
			result += total + 1;
			total   = -1;
		}
	}
	return result;
}

