ll get_sum(vector<int> a, ll ans, ll sum) {
  for (int i = 1; i < a.size(); i++) {
    if (sum > 0) {
      sum += a[i];
      if (sum > -1) {
        ans += sum + 1;
        sum = -1;
      }
    } else {
      sum += a[i];
      if (sum < 1) {
        ans += -sum + 1;
        sum = 1;
      }
    }
  }

  return ans;
}

