int main() {
  int n;
  cin >> n;
  int a[n];
  for (int i = 0; i < n; i++) cin >> a[i];

  // 貪欲法で操作回数の最小値を求める
  // プラスから始まるパターンとマイナスから始まるパターンの2パターン試す
  ll ans1 = 0;
  bool flag = true;
  ll sum = a[0];
  if (sum <= 0) {
    ans1 += -sum + 1;
    sum = 1;
  }
  for (int i = 1; i < n; i++) {
    if (flag) {
      flag = false;
      sum += a[i];
      if (sum < 0) continue;
      ans1 += sum + 1;
      sum = -1;
    } else {
      flag = true;
      sum += a[i];
      if (sum > 0) continue;
      ans1 += -sum + 1;
      sum = 1;
    }
  }
  // マイナスから始まるパターン
  ll ans2 = 0;
  flag = false;
  sum = a[0];
  if (sum >= 0) {
    ans2 += sum + 1;
    sum = -1;
  }
  for (int i = 1; i < n; i++) {
    if (flag) {
      flag = false;
      sum += a[i];
      if (sum < 0) continue;
      ans2 += sum + 1;
      sum = -1;
    } else {
      flag = true;
      sum += a[i];
      if (sum > 0) continue;
      ans2 += -sum + 1;
      sum = 1;
    }
  }

  // 解答
  cout << min(ans1, ans2) << endl;
  return 0;
}

