    auto solve = [](auto as) {
        i64 total = 0;
        u64 retval = 0;

        FORE (a, as) {
            if (total != 0 && total * (total + a) >= 0) {
                // total -> (total + a)で符号が変わらないまたは0になる
                retval += abs(total + a) + 1;
                a -= (total + a); // total + a = 0にする
                if (total > 0) {
                    a -= 1;
                } else {
                    a += 1;
                }
            }
            total += a;
        }
        return retval;
    };

    if (as[0] == 0) {
        auto as2 = as;
        as2[0] = 1;
        auto r1 = solve(as2);
        as[0] = -1;
        auto r2 = solve(as);
