long int operation(int n,ll cnt,vector<ll>sum,vector<ll> a) {
	for (int i = 1; i < n; i++) {
		sum[i] = sum[i - 1] + a[i];
		if (sum[i - 1] > 0) {
			if (sum[i] >= 0) {
				cnt += sum[i] + 1;
				sum[i] = -1;
			}
