const int N = 100010;
ll f[N], g[N], fm[N], gm[N], a[N], n;

int main() {
	scanf("%lld", &n);
	for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
	f[0] = (a[0] > 0) ? 0 : -a[0] + 1;
	fm[0] = (a[0] > 0) ? a[0] : 1;
	g[0] = (a[0] < 0) ? 0 : a[0] + 1;
	gm[0] = (a[0] < 0) ? -a[0] : 1;

	for (int i = 1; i < n; i++) {
		f[i] = g[i - 1];
		g[i] = f[i - 1];

		if (a[i] > gm[i - 1]) fm[i] = a[i] - gm[i - 1];
		else {
			f[i] += (gm[i - 1] - a[i] + 1); 
			fm[i] = 1;
		}

		if (-a[i] > fm[i - 1]) gm[i] = -a[i] - fm[i - 1];
		else {
			g[i] += (fm[i - 1] + a[i] + 1);
			gm[i] = 1;
		}
	}
	printf("%lld\n", min(f[n - 1], g[n - 1]));
}

