int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);

  int n;
  cin >> n;
  vector<int> a(n);
  for (int i = 0; i < n; ++i) {
    cin >> a[i];
  }

  int min_ans = INT_MAX;
  for (int mod = 0; mod < 2; ++mod) {  // a[i] % 2 == mod must be plus
    int ans = 0;
    int sum = 0;
    for (int i = 0; i < n; ++i) {
      int sign = ((i % 2) == mod) * -2 + 1;  // -1 or 1
      sum += a[i];
      if (sign * sum <= 0) {
        int diff = sign - sum;
        sum += diff;
        ans += abs(diff);
      }
    }
    min_ans = min(min_ans, ans);
  }
  cout << min_ans << "\n";
}

