ll det(int n, int a[], int l) {
    int sum = 0;
    ll rez = 0;
    for (int i = 1; i <= n; i++, l = 1 - l) {
        sum += a[i];
        if (l == 0 && sum <= 0) {
            rez += 1 - sum;
            sum = 1;
        }
        else if (l == 1 && sum >= 0) {
            rez += 1 + sum;
            sum = -1;
        }
    }
    return rez;
}

