bool meet(vi a) {
  bool ret = true;
  bool pos = (a[0] > 0);
  int sum = a[0];
  FOR(i, 1, a.size()) {
    sum += a[i];
    if ((pos && i % 2 && sum >= 0) || (pos && !(i % 2) && sum <= 0) ||
        (!pos && i % 2 && sum <= 0) || (!pos && !(i % 2) && sum >= 0)) {
      ret = false;
      break;
    }
  }
  return ret;
}

uint64_t solve(vi a, uint64_t res) {
  int sum = a[0];
  bool pos = (a[0] > 0);
  FOR(i, 1, a.size()) {
    if ((pos && i % 2 && sum + a[i] >= 0) ||
        (!pos && !(i % 2) && sum + a[i] >= 0)) {
      res += abs(sum + a[i] - (-1));
      a[i] = -1 - sum;
    } else if ((pos && !(i % 2) && sum + a[i] <= 0) ||
               (!pos && i % 2 && sum + a[i] <= 0)) {
      res += abs(sum + a[i] - 1);
      a[i] = 1 - sum;
    }
    sum += a[i];
  }
  return res;
}

