  bool isZero = (a[0] == 0);
  uint64_t res = 0;
  if (isZero) {
    res++;
    a[0] = 1;
  }
  uint64_t res1 = solve(a, res);

  res = 0;
  if (pos) {
    res += abs(a[0] - (-1));
    a[0] = -1;
  } else if (isZero) {
    res++;
    a[0] = -1;
  } else {
    res += abs(a[0] - 1);
    a[0] = 1;
  }
  uint64_t res2 = solve(a, res);

  res = min(res1, res2);
  if (flg) res = 0;

  cout << res << endl;
}

