long long calc (int n, long long* a, bool isPositive) {
    long long nCount = 0, sum = 0;

    for (int i=0; i<n; ++i) {
        if (isPositive) {
            if ((a[i] + sum) < 0) {
                sum += a[i];
            } else {
                nCount +=  abs(a[i] + sum) + 1;
                sum = -1;
            }
            isPositive = !isPositive;
        } else {
            if ((a[i] + sum) > 0) {
                sum += a[i];
            } else {
                nCount += abs(a[i] + sum) + 1;
                sum = 1;
            }
            isPositive = !isPositive;
        }
    }
    return nCount;
}

