            int64_t dif1 = max(0L, 1 - s1);
            s1 += dif1;
            result1 += dif1;

            int64_t dif2 = max(0L, s2 - (-1));
            s2 -= dif2;
            result2 += dif2;
        } else {
            int64_t dif1 = max(0L, s1 - (-1));
            s1 -= dif1;
            result1 += dif1;

            int64_t dif2 = max(0L, 1 - s2);
            s2 += dif2;
            result2 += dif2;
        }
    }

    cout << min(result1, result2) << endl;
    return 0;
}

