    else if (i % 2 == 0) {
      int minus = 1 + sum1;
      sum1 -= minus;
      ans1 += minus;
    } else if (sum1 > 0) continue;
    else {
      int plus = 1 - sum1;
      sum1 += plus;
      ans1 += plus;
    }
  }

  vector<int> a2; a2 = a;
