    if (i == 1 && sum2 < 0) continue;
    else if (i == 1) {
      int minus = 1 + sum2;
      sum2 -= minus;
      ans2 += minus;
    }

    if (i % 2 == 0 && sum2 > 0) continue;
    else if (i % 2 == 0) {
      int plus = 1 - sum2;
      sum2 += plus;
      ans2 += plus;
    } else if (sum2 < 0) continue;
    else {
