int f(int a[], int N, bool positive) {
  int cnt = 0;
  int sum = a[0];
  for (int i = 1; i < N; i++) {
    int next = a[i];
    int nextSum = sum + next;
    if (positive) {
      if (i % 2 == 0) {
        if (nextSum <= 0) {
          int des = abs(nextSum) + 1;
          next += des;
          cnt += des;
        }
      } else {
        if (0 <= nextSum) {
          int des = abs(nextSum) + 1;
          next -= des;
          cnt += des;
        }
      }
    } else {
      if (i % 2 == 0) {
        if (0 <= nextSum) {
          int des = abs(nextSum) + 1;
          next -= des;
          cnt += des;
        }
      } else {
        if (nextSum <= 0) {
          int des = abs(nextSum) + 1;
          next += des;
          cnt += des;
        }
      }
    }
    sum += next;
  }
  return cnt;
}

