    ios::sync_with_stdio(false);

    // input
    ll N;
    cin >> N;
    vector<ll> vec(N);
    REP(i, N) cin >> vec[i];

    // calculation
    ll res, partial, distance_0;

    vector<ll> res_vec;
    bool flag_before;
    for (ll n = 0; n < 2; ++n) {
        res = 0;
        if (vec[0] == 0) {
            if (n == 0) {
                partial = +1;
            } else {
                partial = -1;
            }
        } else {
            partial = vec[0];
        }

        flag_before = partial > 0;
        for (ll i = 1; i < N; ++i) {
            partial += vec[i];  // 累積和の更新
            distance_0 = abs(partial) + 1;  // 0 までの距離 + 1
            if (flag_before) {
                // 前項までの累積和が正
                // 負なら何もしない
                if (partial >= 0) {
                    res += distance_0;
                    partial -= distance_0;
                }
            } else {
                // 前項までの累積和が負
                // 正なら何もしない
                if (partial <= 0) {
                    res += distance_0;
                    partial += distance_0;
                }
            }
            flag_before = !flag_before;
        }
        res_vec.push_back(res);
    }

    cout << *MIN(res_vec) << "\n";

    return 0;
}

