    rep(i, n) cin >> a[i];
    // 偶数にplus
    int sum = 0;
    bool plus = true;
    int64_t ans1 = 0;
    rep(i, n) {
        sum += a[i];
        if (plus) {
            if (sum < 0) {
                ans1 += abs(sum) + 1;
                sum = 1;
            }
        } else {
            if (sum > 0) {
                ans1 += abs(sum) + 1;
                sum = -1;
            }
        }
        plus ^= true;
    }
    // 奇数
    sum = 0;
    plus = false;
    int64_t ans2 = 0;
    rep(i, n) {
        sum += a[i];
        if (plus) {
            if (sum < 0) {
                ans2 += abs(sum) + 1;
                sum = 1;
            }
        } else {
            if (sum > 0) {
                ans2 += abs(sum) + 1;
                sum = -1;
            }
        }
        plus ^= true;
    }
