    vector<ll> c_sum(n);
    for(int i = 0; i < n; i++){
        if(i == 0)  c_sum[i] = a[i];
        else    c_sum[i] = c_sum[i - 1] + a[i];
    }

    bool flag = true;
    for(int i = 1; i < n; i++){
        if(c_sum[i - 1] * c_sum[i] >= 0){
            flag = false;
        }
    }
    if(flag){       // flag = trueならば入力時点で成立
        cout << 0 << endl;
        return 0;
    }

    vector<ll> temp1(n), temp2(n);      // 走査用に累積和を格納しておくコンテナ
    for(int i = 0; i < n; i++){
        temp1[i] = c_sum[i];
        temp2[i] = c_sum[i];
    }

    ll ans;
    ll change = 0;
    ll cnt = 0;

    // a[0] > 0     正→負→正…
    for(int i = 0; i < n; i++){
        if(i % 2 == 0){
            temp1[i] += change; 
            if(temp1[i] <= 0){
                change += 1 - temp1[i];
                cnt += abs(1 - temp1[i]);
                temp1[i] = 1;
            }
        }
        else{
            temp1[i] += change;
            if(temp1[i] >= 0){
                change += -1 - temp1[i];
                cnt += abs(-1 - temp1[i]);
                temp1[i] = -1;
            }
        }
    }
    ans = cnt;

    // a[0] < 0     負→正→負…
    change = 0;
    cnt = 0;
    for(int i = 0; i < n; i++){
        if(i % 2 == 0){
            temp2[i] += change;
            if(temp2[i] >= 0){
                change += -1 - temp2[i];
                cnt += abs(-1 - temp2[i]);
                temp2[i] = -1;
            }
        }
        else{
            temp2[i] += change;
            if(temp2[i] <= 0){
                change += 1 - temp2[i];
                cnt += abs(1 - temp2[i]);
                temp2[i] = 1;
            }
        }
    }
    ans = min(ans, cnt);

    cout << ans << endl;
}

