ll f(vector<int> a, int op) {
  ll res = 0;

  ll sum = 0;
  rep(i, a.size()) {
    sum += a[i];

    if (op > 0 && sum <= 0) {
      res += (1 - sum);
      sum = 1;
    }
    if (op < 0 && sum >= 0) {
      res += abs(-1 - sum);
      sum = -1;
    }

    op *= -1;
  }

  return res;
}

