using namespace std;

int main() {
  int n;
  cin >> n;

  int first;
  cin >> first;

  int oddSum, evenSum;
  long oddCount, evenCount;

  if (first == 0) {
    oddSum = -1;
    oddCount = 1;
    evenSum = 1;
    evenCount = 1;
  } else if (first > 0) {
    oddSum = -1;
    oddCount = first + 1;
    evenSum = first;
    evenCount = 0;
  } else if (first < 0) {
    oddSum = first;
    oddCount = 0;
    evenSum = 1;
    evenCount = first * -1 + 1;
  }

  for (int i = 1; i < n; i++) {
    int a;
    cin >> a;

    int nextOddSum = oddSum + a;
    int nextEvenSum = evenSum + a;

    if ((oddSum > 0 && nextOddSum < 0) || (oddSum < 0 && nextOddSum > 0)) {
      oddSum = nextOddSum;
    } else if (nextOddSum == 0) {
      oddSum = oddSum > 0 ? -1 : 1;
      oddCount += 1;
    } else if (nextOddSum > 0) {
      oddSum = -1;
      oddCount += nextOddSum + 1;
    } else if (nextOddSum < 0) {
      oddSum = 1;
      oddCount += nextOddSum * -1 + 1;
    }

    if ((evenSum > 0 && nextEvenSum < 0) || (evenSum < 0 && nextEvenSum > 0)) {
      evenSum = nextEvenSum;
    } else if (nextEvenSum == 0) {
      evenSum = evenSum > 0 ? -1 : 1;
      evenCount += 1;
    } else if (nextEvenSum > 0) {
      evenSum = -1;
      evenCount += nextEvenSum + 1;
    } else if (nextEvenSum < 0) {
      evenSum = 1;
      evenCount += nextEvenSum * -1 + 1;
    }
  }

  long answer = min(oddCount, evenCount);

  cout << answer << endl;
}

