LL check(vector<int> v, int o = 1)
{
	for (auto& x : v) x *= o;
	LL sum = 0;
	LL ans = 0;
	for (int i = 0; i < v.size(); i++)
	{
		sum += v[i];
		if (i % 2 == 0)
		{
			LL o = max(0LL, 1 - sum);
			sum += o;
			ans += o;
		}
		else
		{
			LL o = max(0LL, sum + 1);
			sum -= o;
			ans += o;
		}
	}
	return ans;
}
