int pl(int &a, int b){
  if(a + b <= 0){
    int c = - a - b + 1;
    a = 1;
    return c;
  }
  else{
    a += b;
    return 0;
  }
}

int mi(int &a, int b){
  if(a + b >= 0){
    int c = a + b + 1;
    a = - 1;
    return c;
  }
  else{
    a += b;
    return 0;
  }
}

