int main()
{
    ll N;
    cin >> N;
    vec A(N);
    cin >> A;

    vec sum(N);
    rep(i, N){
        if(!i) sum[i] = A[i];
        else sum[i] = A[i] + sum[i - 1];
    }

    auto solve = [&](bool pos)->ll{
        ll add = 0;
        ll ct = 0;
        rep(i, N){
            ll now = sum[i] + add;
            if(now == 0){
                if(pos){
                    ++add;
                    ++ct;
                }else{
                    --add;
                    ++ct;
                }
                pos = !pos;
                continue;
            }

            if(!(pos ^ (now > 0))){
                pos = !pos;
                continue;
            }

            //posが正で、nowが負
            if(pos){
                add += abs(now) + 1;
                ct += abs(now) + 1;
            }
            //posが負で、nowが正
            else{
                add -= now + 1;
                ct += abs(now) + 1;
            }

            pos = !pos;
        }
        return ct;
    };

    print(min({solve(true), solve(false)}));

    return 0;
}

#include <iostream>
using namespace std;

int solve(int* a, int n) {
	int count = 0;
	int calc = 0;
	int state, pstate;
	if (a[0] < 0) state = -1;
	if (a[0] > 0) state = 1;
	for (int i = 1; i < n; i++) {
		pstate = state;
		int tmp = a[i] + calc;
		if (tmp < 0) state = -1;
		if (tmp == 0) state = 0;
		if (tmp > 0) state = 1;
		if (pstate == state) {
			if (state == -1) {
				count += 1 - tmp;
				calc += 1 - tmp;
				state = 1;
			}
			else if (state == 1) {
				count += tmp + 1;
				calc += -1 - tmp;
				state = -1;
			}
		}
		if (state == 0) {
			if (pstate == -1) {
				count += 1;
				calc += 1;
				state = 1;
			}
			else if (pstate == 1) {
				count += 1;
				calc += -1;
				state = -1;
			}
		}
	}
	return count;
}

int main() {
	int n;
	int ans;
	int *a;
	cin >> n;
	a = new int[n];
	for (int i = 0; i < n; i++)
		cin >> a[i];
	for (int i = 1; i < n; i++)
		a[i] = a[i - 1] + a[i];
	if (a[0] == 0) {
		int bs, cs;
		int *b = new int[n];
		int *c = new int[n];
		for (int i = 0; i < n; i++) b[i] = a[i] + 1;
		for (int i = 0; i < n; i++) c[i] = a[i] - 1;
		bs = solve(b, n);
		cs = solve(c, n);
		ans = bs < cs ? bs : cs;
	}
	else ans = solve(a, n);
	cout << ans << endl;
	return 0;
}

