int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int n;
  cin >> n;
  V<i64> a(n);
  cin >> a;
  i64 c1 = 0, c2 = 0, s1 = 0, s2 = 0;  // costs and sums.
  if (a[0] == 0) {
    c1 = c2 = 1;
    s1 = 1;
    s2 = -1;
  } else if (a[0] > 0) {
    c1 = 0;
    s1 = a[0];
    c2 = a[0] + 1;
    s2 = -1;
  } else {
    c1 = -a[0] + 1;
    s1 = 1;
    c2 = 0;
    s2 = a[0];
  }

  // 1: s[0] > 0
  // 2: s[0] < 0
  auto calc = [&](i64 c, int s, bool flip) -> i64 {
    V<i64> seq(n);
    seq[0] = s;
    for (int i = 1; i < n; ++i) {
      bool neg = flip ^ (i % 2 == 1);
      if (neg) {
        assert(s > 0);
      } else {
        assert(s < 0);
      }
      if (a[i] == 0) {
        c += abs(s) + 1;
        s = (i % 2) ? -1 : 1;
      } else if (a[i] > 0 and neg) {
        c += abs(s + a[i]) + 1;
        s = -1;
      } else if (a[i] < 0 and not neg) {
        c += abs(s + a[i]) + 1;
        s = 1;
      } else if (a[i] > 0 and not neg) {
        s += a[i];
        if (s <= 0) {
          c += -s + 1;
          s = 1;
        }
      } else if (a[i] < 0 and neg) {
        s += a[i];
        if (s >= 0) {
          c += s + 1;
          s = -1;
        }
      } else {
        assert(false);
      }
      seq[i] = s;
    }
    DEBUG(seq);
    return c;
  };
  i64 ans = min(calc(c1, s1, false), calc(c2, s2, true));
  cout << ans << endl;
}

