int main() {
    ll n; cin >> n;
    vector<ll> a(n);
    rep(i, n) cin >> a[i];
    ll ans = 0, sum = 0;

    // +-+-...
    rep(i, n) {
        sum += a[i];
        // +
        if((i%2) == 0) {
            if(sum <= 0) {
                ans += (my_abs(sum)+1);
                sum += (my_abs(sum)+1);
            }
        }
        // -
        else {
            if(sum >= 0) {
                ans += (sum+1);
                sum -= (sum+1);
            }
        }

    }

    ll tmp = 0;
    sum = 0;
    // -+-+...
    rep(i, n) {
        sum += a[i];
        // +
        if((i%2) == 1) {
            if(sum <= 0) {
                tmp += (my_abs(sum)+1);
                sum += (my_abs(sum)+1);
            }
        }
        // -
        else {
            if(sum >= 0) {
                tmp += (sum+1);
                sum -= (sum+1);
            }
        }
    }

    if(ans > tmp) ans = tmp;
    cout << ans << endl;
    return 0;
}

ll my_abs(ll a) {
    if(a >= 0) return a;
    else return -1 *a;
}

ll a_n(ll a, ll n) { 
    if(n == 0) return 1;

    ll ret = a, count = 1;
    while(count * 2 < n) {
        ret *= ret;
        count *= 2;
    }
    if(count == n) return ret;
    else return (ret * a_n(a, n-count));
}

ll my_gcd(ll a, ll b) {
    if(b == 0) return a;
    return my_gcd(b, a%b);
}

ll inv(ll a) {
    return a_n(a, MOD-2);
}

ll madd(ll a, ll b, ll c) {
    ll ret = (a+b) % MOD;
    return (ret+c) % MOD;
}

ll msub(ll a, ll b) {
    if(a < b) return (a-b+MOD) % MOD;
    else return (a-b) % MOD;
}

ll mtime(ll a, ll b, ll c) {
    ll ret = (a*b) % MOD;
    return (ret*c) % MOD;
}

