    i = 0;
    s = 0;
    while(i < n){
        news = as[i] + s;
        if(news > -1){
            s -= news + 1;
            count1 += news + 1;
        }
        if(++i >= n) break;

        news = as[i] + s;
        if(news < 1){
            s += 1 - news;
            count1 += 1 - news;
        }
        i++;
    }

    i = 0;
    s = 0;
    while(i < n){
        news = as[i] + s;
        if(news < 1){
            s += 1 - news;
            count2 += 1 - news;
        }
        if(++i >= n) break;

        news = as[i] + s;
        if(news > -1){
            s -= news + 1;
            count2 += news + 1;
        }
        i++;
    }

    cout << (count1 < count2 ? count1 : count2) << endl;
}

