int get_sign(int x){
	if(0 < x) return 1;
	else if(x < 0) return -1;
	else return 0;
}

int main(){
	cin >> n;
	for(int i = 0; i < n; ++i) cin >> a[i];

	int standard = get_sign(a[0]);

	for(int i = 0; i < n; ++i){
		sum += a[i];
		if(standard != get_sign(sum)){
			int add = abs(sum) + 1;
			ans += add;
			if(sum > 0) sum -= add;
			else if(sum < 0) sum += add;
		}else if(get_sign(sum) == 0){
			ans++;
			sum = get_sign(a[i+1]) * (-1);
		}
		standard *= (-1);
	}
	cout << ans << endl;
}


