void solve() {
    ll sum_diff = 0, ans = 0;
    if (dp[0] == 0) {
        if (dp[1] < 0) {
            dp[0] = 1;
            sum_diff++, ans++;
        } else {
            dp[0] = -1;
            sum_diff--, ans++;
        }
    }
    REP(i, n - 1) {
        ll diff = 0;
        dp[i + 1] += sum_diff;
        if (dp[i] * dp[i + 1] > 0) {
            if (dp[i + 1] > 0) {
                diff = -1 - dp[i + 1];
                sum_diff += diff;
                dp[i + 1] = -1;
            } else {
                diff = 1 - dp[i + 1];
                sum_diff += diff;
                dp[i + 1] = 1;
            }
        }
        if (dp[i + 1] == 0) {
            if (dp[i] > 0) {
                sum_diff--, diff = -1;
                dp[i + 1] = -1;
            } else {
                sum_diff++, diff = 1;
                dp[i + 1] = 1;
            }
        }
        ans += abs(diff);
    }
    cout << ans << endl;
}

