unsigned long long func(vector<long long int>& s, vector<int>& hugo, long long int k){
  unsigned long long int ret = 0;
  for(int i = 1; i < n; i++){
    if(s[i] == k){
      if(hugo[i - 1] == 0){
        hugo[i] = 1;
        ret++;
        k++;
      }
      else{
        hugo[i] = 0;
        ret++;
        k--;
      }
    }
    else if(s[i] > k){
      if(hugo[i - 1] == 0){
        hugo[i] = 1;
        ret += s[i] - k + 1;
        k += s[i] - k + 1;
      }
      else{
        hugo[i] = 0;
      }
    }
    else{
      if(hugo[i - 1] == 0){
        hugo[i] = 1;
      }
      else{
        hugo[i] = 0;
        ret += k - s[i] + 1;
        k -= k - s[i] + 1;
      }
    }
  }
  return ret;
}

