        plus_flag = true;
      }
      else if(sum < 0)
      {
        minus_flag = true;
      }
      else if(sum == 0)
      {

        ope_count++;

        if(a.at(i+1) <= 0)
        {
          sum++;
          plus_flag = true;
        }
        else if(a.at(i+1) > 0)
        {
          sum--;
          minus_flag = true;
        }

      }

    }

    else if(plus_flag == true)
    {

      while(sum >= 0)
      {
        ope_count++;
        sum--;
      }

      plus_flag  = false;
      minus_flag = true;

    }

    else if(minus_flag == true)
    {

      while(sum <= 0)
      {
        ope_count++;
        sum++;
      }

