    for (int i1 = 0; i1 < n; ++i1) {
        ll a;
        cin >> a;
        sum[i1] = a + (i1 == 0 ? 0 : sum[i1 - 1]);
    }

    ll f = sum[0];
    ll s = sum[1];
    ll ope = 0;
    if (f == 0) {
        ope++;
        int d = s < 0 ? 1 : -1;
        for (int i = 0; i < n; ++i) {
            sum[i] += d;
        }
    }

    for (int i = 1; i < n - 1; ++i) {
        ll f = sum[i];
        ll s = sum[i + 1];
        if (f * s < 0) {
            continue;
        }
        ll d = abs(s) + 1;
        ope += d;
        if (0 < f && 0 < s) {
            d *= -1;
        }
        for (int j = i + 1; j < n; ++j) {
            sum[j] += d;
        }
    }
    ll p = sum[n - 2];
    ll t = sum[n - 1];
    if (p * t > 0) {
        ll d = abs(t) + 1;
        ope += d;
        if (0 < p && 0 < t) {
            d *= -1;
        }
        sum[n - 1] += d;
    }
    cout << ope << endl;

