{

  /* Variable_Proclamation */
  int n;    // input

  int i;    // subscript

  int  sum;
  bool default_flag;
  bool plus_flag, minus_flag;
  int  ope_count;


  /* Input, Array_Proclamation */
  cin >> n;
  vector<int> a(n);


  for(i=0; i<n; i++)
  {
    cin >> a.at(i);
  }


  /* Initialize */
  sum = 0;
  ope_count = 0;

  default_flag = true;
  plus_flag    = false;
  minus_flag   = false;


  /* Calculation */
  for(i=0; i<n; i++)
  {

    sum += a.at(i);

    if(default_flag == true)
    {

      default_flag = false;

      if(sum > 0)
      {
        plus_flag = true;
      }
      else if(sum < 0)
      {
        minus_flag = true;
      }
      else if(sum == 0)
      {

        ope_count++;

        if(a.at(i+1) <= 0)
        {
          sum++;
          plus_flag = true;
        }
        else if(a.at(i+1) > 0)
        {
          sum--;
          minus_flag = true;
        }

      }

    }

    else if(plus_flag == true)
    {

      while(sum >= 0)
      {
        ope_count++;
        sum--;
      }

      plus_flag  = false;
      minus_flag = true;

    }

    else if(minus_flag == true)
    {

      while(sum <= 0)
      {
        ope_count++;
        sum++;
      }

      plus_flag  = true;
      minus_flag = false;

    }

  }


  /* Output */
