#define up(i,s,e,d) for(int i=(s);i<(e);i+=(d))

ll counting(vector<ll> &A, int N, bool OddEven){//OddEven: odd true, even false
	ll c = 0, csum = 0;
	up(i,0,N,1){
		csum += A[i];
		if(i%2==OddEven && csum<=0){// -0 NG
			c += abs(csum) + 1;
			csum = 1;
		}
		if(i%2==!OddEven && csum>=0){// +0 NG
			c += abs(csum) + 1;
			csum = -1;
		}
	}
	return c;
}

int main(){
	int N; cin>>N;
	vector<ll> A(N);
	up(i,0,N,1) cin>>A[i];
	ll a = counting(A,N,true);
	ll b = counting(A,N,false);
	cout<< (a<b?a:b) <<endl;
}

