long long check(int n, int s, long long a[]) {
    long long cnt = 0;
    long long na[n];

    for (int i = 0; i < n; i++) {
        na[i] = a[i];
        // sum += na[i];

        if (s == 0) {
            sumFirstPositive += na[i];
            // 偶数番目のsumが負の場合
            if (i % 2 == 0 && sumFirstPositive <= 0) {
                // 変更する差分
                long long dx = 1 - sumFirstPositive;
                na[i] += dx;
                cnt += abs(dx);
                sumFirstPositive += dx;

                // cout << "dx: " << dx << endl;
                // cout << "cnt: " << cnt << endl;

            } else if (i % 2 != 0 && sumFirstPositive >= 0) {
                // 変更する差分
                long long dx = -1 - sumFirstPositive;
                na[i] += dx;
                cnt += abs(dx);
                sumFirstPositive += dx;

                // cout << "dx: " << dx << endl;
                // cout << "cnt: " << cnt << endl;

            }
        }

        if (s == 1) {
            sumFirstNegative += na[i];
            // 奇数番目のsumが負の場合
            if (i % 2 != 0 && sumFirstNegative <= 0) {
                // 変更する差分
                long long dx = 1 - sumFirstNegative;
                na[i] += dx;
                cnt += abs(dx);
                sumFirstNegative += dx;

                // cout << "dx: " << dx << endl;
                // cout << "cnt: " << cnt << endl;

            } else if (i % 2 == 0 && sumFirstNegative >= 0) {
                // 変更する差分
                long long dx = -1 - sumFirstNegative;
                na[i] += dx;
                cnt += abs(dx);
                sumFirstNegative += dx;

                // cout << "dx: " << dx << endl;
                // cout << "cnt: " << cnt << endl;
            }
        }
    }

    return cnt;
}

