using namespace std;

static uint64_t calc_count(vector<long long> &vec, int64_t sign)
{
  unsigned long long count = 0;

  long long total = vec[0];
  if (total == 0) {
    total = sign;
    count++;
  }

  for (uint64_t i = 1; i < vec.size(); i++) {
    sign *= -1;

    total += vec[i];

    if ((total == 0) || (sign * total < 0)) {
      count += abs(sign - total);
      total = sign;
    }
  }

  return count;
}

int32_t main()
{
  uint64_t N;
  cin >> N;

