    ios::sync_with_stdio(false);

    ll N;
    cin >> N;

    ll score = 0;
    ll hard;

    for (ll i=1; i<=N; i++){
        score += i;
        if (score >= N) {
            hard = i;
            break;
        }
    }

    vector<ll> ans;
    ans.push_back(hard);
    N -= hard;
    for (ll i=hard-1; i>0; i--){
        if (N >= i) {
            ans.push_back(i);
            N -= i;
        }
    }

    REP(i, ans.size()) {
        cout << ans[i] << "\n";
    }
}

