long long solve(unsigned N, const std::vector<long long> &a, int flag)
{
  long long c = 0;

  long long s = 0;
  for (unsigned n = 0; n < N; ++n) {
    long long b = s + a[n];
    if (n % 2 == flag) {
      // 正
      if (b <= 0) {
        c += std::abs((+1) - b);
        s = +1;
      } else {
        s = b;
      }
    } else {
      // 負
      if (b >= 0) {
        c += std::abs((-1) - b);
        s = -1;
      } else {
        s = b;
      }
    }
  }

  return c;
}

