const ll INF = 1e9;
const ll MOD = 1e9+7;
const ll LINF = 1e18;

// 与えられる数列の偶数番目と奇数番目をプラス側かマイナス側どちらにするかを決め打ちすれば、
// それぞれ必要な最小コストは一意に定まる
// +-+- ... または -+-+ ...

// 今2番目の項を見ているとして、それがプラスにすべき項だとする。
// これまでの累積和が負であり、1項目が-2以下ならば、今の項に足すか前の項を足すか、また両方に足すかを選べるが
// これはどれを選択しても後の項の操作に変化はない
// なぜならば、どれを選択肢てもプラス側の累積和とマイナス側の累積和の和は変わらず、
// その後の項をプラス側もしくはマイナス側にするためのコストも同じになるからである

signed main()
{
  cin.tie( 0 ); ios::sync_with_stdio( false );
  ll n; cin>>n;
  vll a(n);
  rep(i,n) cin>>a[i];

  ll ans=LINF;
  // +-+-...
  {
    ll p=0, m=0;
    ll tmp=0;
    rep(i,n){
      if(i%2==0){
        p+=a[i];
        if(p+m<=0){ // 累積和がプラスになるべき項だがマイナスになる場合
          tmp+=abs(p+m)+1;
          p+=abs(p+m)+1;
        }
      }else{ // 累積和がマイナスになるべき項だがプラスになる場合
        m+=a[i];
        if(p+m>=0){
          tmp+=abs(p+m)+1;
          m-=abs(p+m)+1;
        }
      }
    }
    chmin(ans,tmp);
  }

  // -+-+...
  {
    ll p=0, m=0;
    ll tmp=0;
    rep(i,n){
      if(i%2==1){ // 上記の実装のうちこの箇所だけ変更すればよい
        p+=a[i];
        if(p+m<=0){
          tmp+=abs(p+m)+1;
          p+=abs(p+m)+1;
        }
      }else{
        m+=a[i];
        if(p+m>=0){
          tmp+=abs(p+m)+1;
          m-=abs(p+m)+1;
        }
      }
    }
    chmin(ans,tmp);
  }

  cout<<ans<<endl;
}

