      sumPlus = 1;
    } else if (i % 2 == 1 && sumPlus >= 0) {
      minPlus += sumPlus + 1;
      sumPlus = -1;
    }
  }
  REP(i, n) {
    sumMinus += a[i];
    if (i % 2 == 0 && sumMinus >= 0) {
      minMinus += sumMinus + 1;
      sumMinus = -1;
    } else if (i % 2 == 1 && sumMinus <= 0) {
      minMinus += 1 - sumMinus;
      sumMinus = 1;
    }
  }
  res = min(minPlus, minMinus);
  cout << res << endl;
  return 0;
}

