long long N;
vector<long long> A, W;
long long S[100002] = {INF*(-1)};
long long dp[100002] = {0};

void calcDP(int n){
	if(n == 1){
		if(W[1] != 0){
			dp[1] = 0;
		}
		else{
			dp[1] = 1;
			if(W[2] <= 0){
				W[1] = 1;
			}
			else{
				W[1] = -1;
			}
			S[1] = W[1];
		}
		return;
	}
	else{
		S[n] = S[n-1] + W[n];
		if(S[n-1] * S[n] < 0){
			dp[n] = dp[n-1];
		}
		else{
			dp[n] = dp[n-1] + abs(0 - S[n-1] - W[n]) + 1;
			W[n] = 0 - S[n-1] - ( abs(S[n-1]) / S[n-1] );
			S[n] = S[n-1] + W[n];
		}
		return;
	}
}

