		A.push_back(a);
		W.push_back(a);
		if(i == 1){
			S[1] = a;
		}
		else{
			S[i] = S[i-1] + a;
		}
	}
	for(int i=1; i<=N; i++){
		calcDP(i);
	}
	printf("%lld\n", dp[N]);
	return 0;
}

