				a[i] = 1 - s[i-1];
			}
			else {
				cost += std::abs(- 1 - s[i-1] - a[i]);
				a[i] = - 1 - s[i-1];
			}
		}
		s[i] = s[i-1] + a[i];
	}

	//for(int i = 0; i < n; ++i) {
	//	std::cout << a[i] << std::endl;
	//}

	std::cout << cost << std::endl;

	return 0;
}

