        }

        if (x > 0 && y > 0) {
            diff -= (y + 1);
            cnt += (y + 1);
        } else if (x < 0 && y < 0) {
            diff += (abs(y) + 1);
            cnt += (abs(y) + 1);
        }
    }

    cout << cnt << endl;
}

