   cin>>a;    // 各iまでの和の符号を正負交互にするので、
    sum1+=a;  // この問題は各和の奇数番目と偶数番目を操作して、どちらが小さくなるかという話になるの
    sum2+=a;
    if(i%2!=0){ // 各和の奇数番目の操作。正と負の場合に分ける
       if(sum1<=0){ // 和が負なら正にする
         ans1+=1-sum1; // 負の値が正の＋1になる回数分足す
         sum1=1; } // 上記の操作をしたのでsum1=1にする
       if(sum2>=0){ // 和が正なら負にする
         ans2+=1+sum2; // 正の値が負の―1になる回数分足す
         sum2=-1; }  // 上記の操作をしたのでsum2=-1にする
    }

    else{ // 各和の偶数番目の操作。正と負の場合に分ける
       if(sum1>=0){ // 和が正なら負にする
         ans1+=1+sum1; // ans1はsum1に初項＋で操作していった場合の操作回数
         sum1=-1; }
       if(sum2<=0){ // 和が負なら正にする
         ans2+=1-sum2; // ans2はsum2に初項―で操作していった場合の操作回数
         sum2=1;  }    
    }  
  }

 cout<<min(ans1, ans2);
}

