void Solve(){
  ll n;
    cin>>n;
  vll A(n);
  vll B(n);
  FOR(i,0,n){
    cin>>A[i];
  }

  ll ans=0;
  ll all=A[0];
  bool can=true;
  FOR(i,1,n){
    if((all+A[i])*all>=0){
      can=false;
      break;
    }
    all+=A[i];
  }


  if(can){
    cout<<"0\n";
    return;
  }

  //B[0]>0から見る
  B[0]=A[0];
  if(A[0]<=0){
    B[0]=1;
    ans+=abs(A[0])+1;
  }
  FOR(i,1,n){
    B[i]=B[i-1]+A[i];

    if(B[i]*B[i-1]<0){
      continue;
    }

    ans+=abs(B[i])+1;
    if(B[i-1]<0){
      B[i]=1;
    }
    else{
      B[i]=-1;
    }
  }

  //B[0]<0を見る
  ll reans=0;
  B[0]=A[0];
  if(A[0]>=0){
    B[0]=-1;
    reans+=abs(A[0])+1;
  }
  FOR(i,1,n){
    B[i]=B[i-1]+A[i];

    if(B[i]*B[i-1]<0){
      continue;
    }

    reans+=abs(B[i])+1;
    if(B[i-1]<0){
      B[i]=1;
    }
    else{
      B[i]=-1;
    }
  }

  cout<<min(ans,reans)<<"\n";
}

