int check(vector<double> &sum, int n){
	for(int i=0;i<n;i++){
		if(sum[i] == 0)
			return i;
		if(i<n-1 && sum[i]*sum[i+1] > 0)
			return i+1;
	}

	return 0;
}

void kasan(vector<double> &sum, int index, int pm, int n){
	if(pm == 0){
		for(int i=index;i<n;i++)
			sum[i]++;
	}
	if(pm == 1){
		for(int i=index;i<n;i++)
			sum[i]--;
	}
	for(int j=0;j<n;j++){
		cout << sum[j] << endl;
	}
	cout << "" << endl;
}


