		cin >> a;
		sum += a;
		sums[i] = sum;
	}

	int count = 0;
	while(check(sums, n) > 0){
		int j = check(sums,n);
		if(sums[j-1] > 0)
			kasan(sums, j, 1, n);
		else if(sums[j-1] < 0)
			kasan(sums, j, 0, n);
		else if(sums[j] == 0){
			if(sums[j-1] > 0)
				kasan(sums, j, 1, n);
			else if(sums[j-1] < 0)
				kasan(sums, j, 0, n);
		}

		count++;
	}

