#include <bits/stdc++.h>
using namespace std;
using ll = long long;

bool is_odd(int n) {
  return (n % 2 == 1);
}

bool is_even(int n) {
  return (n % 2 == 0);
}

int main() {
  int n;
  cin >> n;

  vector<ll> a(n);
  for (int i = 0; i < n; i++) {
    cin >> a.at(i);
  }

  ll ans = 0;
  bool is_positive = (a.at(0) > 0);
  bool is_negative = (a.at(0) < 0);
  ll sum = a.at(0);
  for (int i = 1; i < n; i++) {
    sum = sum + a.at(i);

    // 第1項が正の数
    // 奇数番目の要素の場合、第1項と和の符号が異なる
    // 第1項が正の数の場合、負の数の最小である -1 まで操作する
    if (is_positive && is_odd(i) && sum >= 0) {
      ll num_of_operations = sum - (-1);
      ans += num_of_operations;
      sum -= num_of_operations;
    }

    // 第1項が正の数
    // 偶数番目の要素の場合、第1項と和の符号が同じ
    // 第1項が正の数の場合、正の数の最小である +1 まで操作する
    if (is_positive && is_even(i) && sum <= 0) {
      ll num_of_operations = (1) - sum;
      ans += num_of_operations;
      sum += num_of_operations;
    }

    // 第1項が負の数
    // 奇数番目の要素の場合、第1項と和の符号が異なる
    // 第1項が負の数の場合、正の数の最小である +1 まで操作する
    if (is_negative && is_odd(i) && sum <= 0) {
      ll num_of_operations = (1) - sum;
      ans += num_of_operations;
      sum += num_of_operations;
    }

    // 第1項が負の数
    // 偶数番目の要素の場合、第1項と和の符号が同じ
    // 第1項が負の数の場合、負の数の最小である -1 まで操作する
    if (is_negative && is_even(i) && sum >= 0) {
      ll num_of_operations = sum - (-1);
      ans += num_of_operations;
      sum -= num_of_operations;
    }
  }

  cout << ans << endl;
  return 0;
}

