const ll INFTY = 1e+16;

int main()
{
    int N;
    cin >> N;
    vector<ll> a(N + 1), b(N + 1);
    for (int i = 0; i < N; ++i)
    {
        cin >> a[i];
        b[i] = a[i];
        if (i != 0)
        {
            a[i] += a[i - 1];
            b[i] += b[i - 1];
        }
    }

    ll ans = INFTY;
    bool sign;
    for (int j = 0; j < 2; ++j)
    {
        sign = j;
        if (j == 1)
        {
            for (int i = 0; i < N + 1; ++i)
            {
                a[i] = b[i];
            }
        }
        ll v = 0, count = 0;
        for (int i = 0; i < N; ++i)
        {
            if (sign)
            {
                if (a[i] >= 0)
                {
                    count += abs(-a[i] - 1);
                    v -= abs(-a[i] - 1);
                }
            }
            else
            {
                if (a[i] <= 0)
                {
                    count += abs(-a[i] + 1);
                    v += abs(-a[i] + 1);
                }
            }
            a[i + 1] += v;
            sign = !(sign);
        }
        ans = min(ans, count);
    }
    cout << ans << endl;
}

