int getsign(long long int n){
	if(n > 0){
		return POSITIVE;
	}
	if(n < 0){
		return NEGATIVE;
	}
	return ZERO;
}

int count(int sign0, long long a[], int n){
	long long int sum = 0;
	int sign = sign0;
	long long int count = 0;

	for(int i=0; i<n; ++i){
		sum += a[i];
		if (getsign(sum) != sign){
			count += abs(sign - sum);
			sum = sign;
		}
		sign = SWAP_SIGN(sign);
	}

	return count;
}

