  long long tmp = abs(a[0]) + 1;
  sum = (a[0] >= 0 ? -1 : 1);
  FOR(i, 1, n) {
    if (diff(sum + a[i], sum)) {
      sum += a[i];
    } else {
      long long need = (sum > 0 ? -1 : 1);
      long long now = need - sum;
      tmp += abs(now - a[i]);
      sum = need;
    }
  }
  cout << min(ans, tmp) << '\n';
  return 0;
}

