Int calc(const vector<Int> &a, Int n, Int tem) {
    Int ans = 0;
    if (tem == 0) {
        if (0 <= a[1]) {
            tem = -1;
            ans++;
        } else {
            tem = 1;
            ans++;
        }
    }

    for (int i = 1; i < n; i++) {
        if ((0 < tem + a[i] && tem < 0) || (tem + a[i] < 0 && 0 < tem)) {
            tem += a[i];
        } else {
            if (0 <= tem + a[i] && 0 <= tem) {
                ans += abs(-1 - (tem + a[i]));
                tem = -1;
            } else {
                ans += abs(1 - (tem + a[i]));
                tem = 1;
            }
        }
    }

    return ans;
}

