        cin >> a[i];
    }

    Int aa, bb, ansdelb, ansdela;
    if (abs(a[0]) != 1) {
        aa = 1;
        ansdela = abs(a[0]) - 1;
    } else {
        ansdela = 0;
    }
    if (0 <= a[0]) {
        bb = -1;

    } else {
        bb = 1;
    }
    ansdelb = abs(a[0]) + 1;

    Int ans = min(calc(a, n, aa) + ansdela, calc(a, n, bb) + ansdelb);

    cout << ans << endl;

    return 0;
}

