long num_operate(long n, long sum, long* a){
    long j;
    for (long i = 1; i < n; i++){
       if (sum * (sum + a[i]) < 0) sum += a[i];
       else{
           j += abs(sum + a[i]) + 1;
           if (sum < 0) sum = 1;
           else if (sum > 0) sum = -1;
       }
   }
   return j;
}

