  if (a[0] == 0) {
    a[0]++;
    count++;
  }

  long long sum = 0;
  rep(i, N-1) {
    sum += a[i];
    long long next_sum = sum + a[i+1];

    if ((sum < 0 && next_sum > 0) || (sum > 0 && next_sum < 0)) {
      // do nothing
    } else {
      if (sum < 0) {
        count += 1 - next_sum;
        a[i+1] += 1 - next_sum;
      } else {
        count += next_sum + 1;
        a[i+1] -= (next_sum + 1);
      }
    }
  }

  cout << count << endl;

  return 0;
