vector<long long> sum;

long long calc_cost(bool ps) {
	long long res,dis;
	res = dis = 0;
	vector<long long> temp = sum;
	for (int i = 0; i < temp.size(); ++i) {
		temp[i] += dis;
		if (i%2 == 0) {
			if (temp[i] == 0) {
				++res;
				if (ps) {
					++dis;
				}
				else {
					--dis;
				}
			}
			else if (ps && temp[i] < 0) {
				res += -temp[i]+1;
				dis += -temp[i]+1;
			}
			else if (!ps && temp[i] > 0) {
				res += temp[i]+1;
				dis -= temp[i]+1;
			}
		}
		else {
			if (temp[i] == 0) {
				++res;
				if (ps) {
					--dis;
				}
				else {
					++dis;
				}
			}
			else if (ps && temp[i] > 0) {
				res += temp[i]+1;
				dis -= temp[i]+1;
			}
			else if (!ps && temp[i] < 0)  {
				res += -temp[i]+1;
				dis += -temp[i]+1;
			}
		}
	}
	return res;
}

