        ans += abs(sum[i]) + 1;
        sum[i] = -1;
      }

      if (i < n - 1) {
        sum[i + 1] = sum[i] + a[i + 1];
      }
    }

  } else if (sign < 0) {
    for (i = 0; i < n; i++) {

      if (i % 2 == 1 && sum[i] <= 0) {
        ans += abs(sum[i]) + 1;
        sum[i] = 1;
      }

      if (i % 2 == 0 && sum[i] >= 0) {
        ans += abs(sum[i]) + 1;
        sum[i] = -1;
      }

      if (i < n - 1) {
        sum[i + 1] = sum[i] + a[i + 1];
      }
    }

  } else {
    exit(1);
  }

  return ans;
}

