            sum = -1;
            continue;
        }
        if(sum < 0){ // 次は正に
            if(a[i+1]+sum > 0) sum += a[i+1];
            else{
                ans2 += abs(1-(a[i+1]+sum));
                sum = 1;
            }
        }else{  // 次は負に
            if(a[i+1]+sum < 0) sum += a[i+1];
            else{
                ans2 += abs(-1-(a[i+1]+sum));
                sum = -1;
            }
        }
    }
    cout << min(ans1,ans2) << endl;
}

