		{
			a[1] = 1;
			ans += 1;
		}
	}
	sum = a[1];
	for (i = 2; i <= n; i++)
	{
		if (sum == 0)
		{
			if (a[i-1] > 0)
			{
				ans++;
				sum--;
			}
			else
			{
				ans++;
				sum++;
			}
		}
		if (sum > 0)
		{
			if (a[i] + sum >= 0)
			{
				ans += a[i] + sum + 1;
				sum = -1;
			}
			else
			{
				sum += a[i];
			}
		}
		else
		{
			if (a[i] + sum <= 0)
			{
				ans += abs(a[i] + sum) + 1;
				sum = 1;
			}
			else
			{
				sum += a[i];
			}
		}
	}
	cout << ans << endl;
}

