int main() {
  int N = in();
  vector<int> a(N);
  rep(i, N) a[i] = in();

  int prev = a[0];
  int sum = 0;
  for (int i=1; i<N; i++) {
    int curr = prev + a[i];
    dr_elem(prev); dr_elem(curr) dr_end();
    if (prev < 0 && curr < 0) {
      sum += abs(curr) + 1;
      curr = 1;
    } else if (prev > 0 && curr > 0) {
      sum += abs(curr) + 1;
      curr = -1;
    } else if (prev > 0 && curr == 0) {
      curr -= 1;
      sum++;
    } else if (prev < 0 && curr == 0){
      curr += 1;
      sum++;
    }
    prev = curr;
    dr_elem(sum) dr_end();
  }
  output(sum);
}

