                sum = 1;
            } 

            plus = false;
        } else {
            if (sum == 0) {
                ++cnt;
                sum -= 1;
            } else if (sum > 0) {
                cnt += (sum + 1);
                sum = -1;
            } 

            plus = true;
        }
    }

    return cnt;
}

