template<typename T>
struct BIT{
  int n;
  vector<T> d;
  BIT(int n = 0):n(n),d(n+1){}
  void add(int i,T x=1){
    for(i++;i<=n;i += i&-i){
      d[i] += x;
    }
  }
  T sum(int i){
    T x = 0;
    for(i++;i>0;i -= i&-i){
      x += d[i];
    }
    return x;
  }
};

int main(){
  int n;cin >> n;
  vector<int> a(n);
  BIT<ll> tree1(100005),tree2(100005);
  rep(i,n) {
    cin >> a[i];
    tree1.add(i,a[i]);
    tree2.add(i,a[i]);
  }

  ll ans = 1e18;
  ll count = 0;
  int flag;
  if(a[0]>0) flag = 1;
  else flag = -1;

  for(int i = 1;i < n;i++){
    ll sum = tree1.sum(i);
    if(sum*flag>=0) {
      tree1.add(i,-(abs(sum)+1)*flag);
      count += abs(sum)+1;
    } 
    flag *= -1;
  }
  ans = min(ans,count);

  if(a[0]>0) flag = 1;
  else flag = -1;
  count = 0;

  for(int i = 0;i < n;i++){
    ll sum = tree2.sum(i);
    if(sum*flag>=0) {
      tree2.add(i,-(abs(sum)+1)*flag);
      count += abs(sum)+1;
    } 
    flag *= -1;
  }
  ans = min(ans,count);
  cout << ans << endl;


}

