int solve(bool sign, vi &a, int N)
{
    // initialize
    int S = a.at(0);
    int ans = 0;
    if(sign) {    // make S positive
        if(S <= 0) {
            ans = -S + 1;
            S = 1;
        }
    } else {    // make S negative
        if(S >= 0) {
            ans = S + 1;
            S = -1;
        }
    }

    FOR(i, 1, N)  {
        if(S > 0) {
            S += a.at(i);
            if(S >= 0) {
                ans += (S+1);
                S = -1; 
            }
        } else {
            S += a.at(i);
            if(S <= 0) {
                ans += (-S+1);
                S = 1;
            }
        }
    }
    return ans;
}

