enum State
{
  Plus,
  Minus,
  Zero
};

State GetState(ll sum)
{
  State state;
  if (sum > 0) state = Plus;
  else if (sum == 0) state = Zero;
  else state = Minus;

  return state;
}

int main()
{
  int n;
  cin >> n;
  vector<ll> a(n);

  cin >> a[0];
  ull count = 0;
  State state = GetState(a[0]);

  if (state == Zero)
  {
    a[0] = -1;
    state = Minus;
    count++;
  }

  ll sum = a[0];

  //cout << a[0] << " " << sum << endl;

  for (int i = 1; i < n; i++)
  {
    cin >> a[i];

    State nextState = GetState(sum + a[i]);

    switch (nextState)
    {
    case Plus:
      if (state == Plus)
      {
        ll bf_a = a[i];
        a[i] = -1 - sum;
        count += abs(a[i] - bf_a);
        nextState = Minus;
      }
      break;

    case Minus:
      if (state == Minus) 
      {
        ll bf_a = a[i];
        a[i] = 1 - sum;
        count += abs(a[i] - bf_a);
        nextState = Plus;
      }
      break;

    case Zero:
      if (state == Plus)
      {
        ll bf_a = a[i];
        a[i] = -1 - sum;
        count += abs(a[i] - bf_a);
        nextState = Minus;
      }
      else if (state == Minus)
      {
        ll bf_a = a[i];
        a[i] = 1 - sum;
        count += abs(a[i] - bf_a);
        nextState = Plus;
      }

    default:
      break;
    }

    sum += a[i];

    //cout << a[i] << " " << sum << endl;
    state = nextState;
  }

  if (sum == 0) count++;

  cout << count << endl;
}

