unsigned long greed(vector<int> &a){
    unsigned long op=0;
    int sum = a[0];
    for(int i=1; i<a.size(); i++){
        if(sum > 0){
            if(sum+a[i]>=0){
                op += sum+a[i]+1;
                sum = -1;    
            }else{
                sum += a[i];
            }
        }else{
            if(sum+a[i]<=0){
                op += 1-sum-a[i];
                sum = 1;
            }else{
                sum += a[i];
            }
        }
    }
    return op;
}

