unsigned solve(unsigned N, const std::vector<long> &a, int flag)
{
  unsigned c = 0;

  long s = 0;
  for (unsigned n = 0; n < N; ++n) {
    if (n % 2 == flag) {
      // 正
      if (s + a[n] < 0) {
        c += std::abs(1 - (s + a[n]));
        s = 1;
      } else {
        s += a[n];
      }
    } else {
      // 負
      if (s + a[n] > 0) {
        c += std::abs((-1) - (s + a[n]));
        s = -1;
      } else {
        s += a[n];
      }
    }
  }

  return c;
}

