    if(i % 2 == 0) {
      if(sum < 0) {
        int diff = 1 - sum;
        sum += diff;
        counter += diff;
      }
    } else {
      if(sum > 0) {
        int diff = sum + 1;
        sum -= diff;
        counter += diff;
      }
    }
  }

  int counterNeg = 0;
  sum = 0;
  // A[0] < 0
  for(int i = 0; i < n; i++) {
    sum += A[i];

    if(i % 2 == 0) {
      if(sum > 0) {
        int diff = sum + 1;
        sum -= diff;
        counterNeg += diff;
      }
    } else {
      if(sum < 0) {
        int diff = 1 - sum;
        sum += diff;
        counterNeg += diff;
      }
    }
  }

  int ans = counter > counterNeg ? counterNeg : counter;
  cout << ans << endl;
  return 0;
}

