#include <iostream>
#include <vector>

long body(std::vector<long>& a){
    long ans  = 0;

    std::vector<long> s(a.size());
    s.at(0) = a.at(0);
    for(unsigned long i = 1; i < a.size(); i++){
        s.at(i) = s.at(i-1) + a.at(i);
    }

    long diff = 0;
    for(unsigned long i = 1; i < s.size(); i++){
        s.at(i) += diff; // update
        long n = 0;
        if(s.at(i-1) > 0 && s.at(i) >= 0){
            n = s.at(i) + 1;
            ans += n;
            diff -= n;
            s.at(i) += diff;
        }else if(s.at(i-1) < 0 && s.at(i) <= 0){
            n = - s.at(i) + 1;
            ans += n;
            diff += n;
            s.at(i) += diff;
        }
    }
    return ans;
}

int main(int argc, char **argv)
{
    long n;
    std::cin >> n;

    std::vector<long> a(n);
    for(long i = 0; i < n; i++){
        std::cin >> a.at(i);
    }

    long a0 = a.at(0);

    long ans_a, ans_b;

    { // 0th: +
        if(a.at(0) > 0){
            ans_a = body(a);
        }else{
            a.at(0) = 1;
            ans_a = body(a) + (-a0+1);
        }
    }
    { // 0th: -
        if(a.at(0) < 0){
            ans_b = body(a);
        }else{
            a.at(0) = -1;
            ans_b = body(a) + (a0+1);
        }
    }

    long ans = std::min(ans_a, ans_b);

    std::cout << ans << std::endl;

}

