#define MOD 1000000007

int main()
{
	const int N = 100000;
	int n; 
	ll a[N];
	ll sum = 0, ans, ans1 = 0, ans2 = 0;
	//bool sign1;

	cin >> n;
	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}
	// 奇数番目までの和が正の場合と偶数番目までの和が正の場合を考える
	// 2回の試行で良い方を答えとする
	// 各試行においては，もし決めた符号と一致していたら操作は行わない
	// 不一致の場合，和を1もしくは-1になるように操作する
	// その操作回数は(sumの絶対値 + 1)回
	// 操作後の和は1もしくは-1になる
	for (int i = 0; i < n; i++) { // 奇数番目までの和が正の場合
		sum += a[i];
		if (((i + 1) % 2) != 0) { // 奇数番目まで → sum > 0
			if (sum == 0) {
				sum++;
				ans1++;
			} else if (sum < 0){
				ans1 += abs(sum) + 1;
				sum = 1;
			}
		} else { // 偶数番目まで → sum < 0
			if (sum == 0) {
				sum--;
				ans1++;
			} else if (sum > 0){
				ans1 += abs(sum) + 1;
				sum = -1;
			}
		}
	}
	//cout << ans1 << endl;
	sum = 0;
	for (int i = 0; i < n; i++) { // 偶数番目までの和が正の場合
		sum += a[i];
		if (((i + 1) % 2) == 0) { // 偶数番目まで → sum > 0
			if (sum == 0) {
				sum++;
				ans2++;
			} else if (sum < 0){
				ans2 += abs(sum) + 1;
				sum = 1;
			}
		} else { // 奇数番目まで → sum < 0
			if (sum == 0) {
				sum--;
				ans2++;
			} else if (sum > 0){
				ans2 += abs(sum) + 1;
				sum = -1;
			}
		}
	}
	//cout << ans2 << endl;
	if (ans1 <= ans2) ans = ans1;
	else ans = ans2;

	cout << ans << endl;

	return (0);
}

