using namespace std;
typedef long long int LLI;

bool diff_sign( LLI a, LLI b )
{
	if( a > 0 and b < 0 or a < 0 and b > 0 )
		return true;
	return false;
}

void set_starting_values( LLI & tmp, LLI & neg, LLI & pos, LLI & neg_sum, LLI & pos_sum)
{
	if( tmp < 0 ){
		neg = tmp;
		neg_sum = 0;
		pos = 1;
		pos_sum = abs(tmp) + 1;
	}else if( tmp > 0 ){
		neg = -1;
		neg_sum = abs(tmp) + 1;
		pos = tmp;
		pos_sum = 0;
	}else{
		neg = -1;
		pos = 1;
		neg_sum = 1;
		pos_sum = 1;
	}
}

void analyze_step_by_step( LLI & tmp, LLI & neg, LLI & pos, LLI & neg_sum, LLI & pos_sum, bool & neg_state, bool & pos_state)
{
	// Set the sign
	if( pos_state == true ){
		pos_state = false;
		neg_state = true;
	}else{
		pos_state = true;
		neg_state = false;
	}

	if( pos == -tmp ){
		pos_sum++;
		if( pos_state == true )
			pos = 1;
		else
			pos = -1;
	}else if( !diff_sign(pos,pos+tmp) ){
		pos_sum += abs(pos+tmp) + 1;
		if( pos_state == true )
			pos = 1;
		else
			pos = -1;
	}else{
		pos += tmp;
	}

	if( neg == -tmp ){
		neg_sum++;
		if( neg_state == true )
			neg = 1;
		else
			neg = -1;
	}else if( !diff_sign(neg,neg+tmp) ){
		neg_sum += abs(neg+tmp) + 1;
		if( neg_state == true )
			neg = 1;
		else
			neg = -1;
	}else{
		neg += tmp;
	}

}

int main()
{
	LLI n, tmp, pos, neg, pos_sum, neg_sum;
	bool pos_state = true, neg_state = false;
	cin >> n >> tmp;

	set_starting_values( tmp, neg, pos, neg_sum, pos_sum );

	for(int i = 1; i < n; i++)
	{
		cin >> tmp;
		analyze_step_by_step( tmp, neg, pos, neg_sum, pos_sum, neg_state, pos_state );
	}

	if( pos_sum > neg_sum )
		cout << neg_sum;
	else
		cout << pos_sum;
}

