static int64_t calcCost(bool isPlus)
{
	int64_t sum = 0, cost = 0;
	for (int32_t i = 0; i < n; i++) {
		if (isPlus && sum + a[i] < 1) {
			cost += abs(a[i] - (1 - sum));
			sum += 1 - sum;
		} else if (!isPlus && sum + a[i] > -1) {
			cost += abs(a[i] - (-1 - sum));
			sum += -1 - sum;
		} else {
			sum += a[i];
		}
		isPlus = !isPlus;
	}
	return cost;
}

