int func(int N, int *a){


	int ocost=0;//odd index element is positive
	int ecost=0;
	int	temp=0;


	for(int i=0; i < N; i++){
		temp += a[i];
		if(i%2 == 0){
			if(temp <= 0){
				ocost += 1-temp;
				temp = 1;
			}
		}
		else{
			if(temp >= 0){
				ocost += 1+temp;
				temp =-1;
			}
		}
	}


	temp=0;
	for(int i=0; i < N; i++){
		temp += a[i];
		if(i%2 == 0){
			if(temp >= 0){
				ecost += 1+temp;
				temp = -1;
			}
		}
		else{
			if(temp <= 0){
				ecost += 1-temp;
				temp =1;
			}
		}
	}

	return min(ocost,ecost);

}

