int count(int sign0, vector<int> a, int n) {
    int count = 0;
    int total = 0;
    for (int i = 0; i < n; i++) {
        if (i % 2 == 1) {
            if ((total + a.at(i)) * sign0 < 0) total += a.at(i);
            else {
                count += abs(total + a.at(i)) + 1;
                total = -1 * sign0;
            }
        } if (i % 2 == 0) {
            if ((total + a.at(i)) * sign0 > 0) total += a.at(i);
            else {
                count += abs(total + a.at(i)) + 1;
                total = sign0;
            }
        }
    }
    return count;
}

