long solve(vector<long> A) {
    long res = 0;
    long sum = A[0];
    for (int i = 1; i < A.size(); i++)
    {
        if (sum > 0) {
            sum += A[i];
            while (sum >= 0) {
                res++;
                sum--;
            }
        }
        else if (sum < 0)
        {
            sum += A[i];
            while (sum <= 0) {
                res++;
                sum++;
            }
        }
    }
    return res;
}

