using namespace std;

int n;
vector<int> cumulative;

void reCalc(int index, int value) {
    for (int i = index; i < n; ++i) cumulative[i] -= value;
}

int main() {
    cin >> n;
    vector<int> input;
    for (int i = 0; i < n; ++i) {
        int a; cin >> a;
        input.push_back(a);
    }

    auto itr = input.begin();
    for (int i = 0; i < n; ++i) cumulative.push_back(accumulate(itr, itr + i + 1, 0));

    int ans = 0;
    bool isPositive = cumulative[0] > 0;
    for (int i = 1; i < n; ++i) {
        if (isPositive) {
            if (cumulative[i] > 0) {
                ans += cumulative[i] + 1;
                reCalc(i, cumulative[i] + 1);
            } else if (cumulative[i] == 0) {
                ++ans;
                reCalc(i, 1);
            }
        } else {
            if (cumulative[i] < 0) {
                int diff = (0 - cumulative[i]) + 1;
                ans += diff;
                reCalc(i, -diff);

            } else if (cumulative[i] == 0) {
                ++ans;
                reCalc(i, -1);
            }
        }

        isPositive = cumulative[i] > 0;
    }

    if (accumulate(cumulative.begin(), cumulative.end(), 0) == 0) cout << 1 << endl;
    else                                                          cout << ans << endl;

    return 0;
}

