  ll ops = 0;
  for (int i = 0; i < a.size(); i++) {
    currSum += a[i];
    if (i % 2) {
      if (currSum <= 0) {
        ops += abs(currSum) + 1;
        currSum = 1;
      }
    } else {
      if (currSum >= 0) {
        ops += abs(currSum) + 1;
        currSum = -1;
      }
    }
  }
  currSum = 0;
  ll ops2 = 0;
  for (int i = 0; i < a.size(); i++) {
    currSum += a[i];
    if ((i % 2) == 0) {
      if (currSum <= 0) {
        ops2 += abs(currSum) + 1;
        currSum = 1;
      }
    } else {
      if (currSum >= 0) {
        ops2 += abs(currSum) + 1;
        currSum = -1;
      }
    }
  }
  cout <<  min(ops, ops2) << endl;
}

