        if (sum > 0) {
            if (sum + vec[i] > 0) {
                ans += (sum + vec[i] + 1);
                sum = -1;
            } else if (sum + vec[i] == 0) {
                ans++;
                sum = -1;
            } else{
                sum += vec[i];
            }
        } else if (sum < 0) {
            if (sum + vec[i] < 0) {
                ans += (abs(sum + vec[i]) + 1);
                sum = 1;
            } else if (sum + vec[i] == 0) {
                ans++;
                sum = 1;
            } else{
                sum += vec[i];
            }
        }
    }
    return ans;
}




