bool meet(vi a) {
  bool ret = true;
  bool pos = (a[0] > 0);
  int sum = a[0];
  FOR(i, 1, a.size()) {
    sum += a[i];
    if ((pos && i % 2 && sum >= 0) || (pos && !(i % 2) && sum <= 0) ||
        (!pos && i % 2 && sum <= 0) || (!pos && !(i % 2) && sum >= 0)) {
      ret = false;
      break;
    }
  }
  return ret;
}

