using namespace std;

long long func(string sign, vector<long long> a) {
  long long sum = a.at(0);
  long long res = 0;
  if (sign == "plus" && a.at(0) <= 0) {
    res += 1 - a.at(0);
    sum = 1;
  }
  else if (sign == "minus" && a.at(0) >= 0) {
    res += a.at(0) + 1;
    sum = -1;
  }
  for (int i = 1; i < a.size(); i++) {
    long long next = a.at(i);
    long long step = 0;
    if (sum > 0 && sum + next >= 0) {
      step = next + sum + 1;
      sum = -1;
    }
    else if (sum < 0 && sum + next <= 0) {
      step = 1 - sum - next;
      sum = 1;
    }
    else sum += next;
    res += step;
  }
  return res;
}

int main() {
  int n;
  cin >> n;
  vector<long long> a(n);
  for (int i = 0; i < n; i++) cin >> a.at(i);
  cout << min(func("plus", a), func("minus", a)) << endl;
}

