// 決め打ち二分探索 with めぐる式二分探索

// 答えを key としたときに、問題が求める条件を満たせるかどうか
bool isOK(ll key) {
  // okを適当に大きめの値に設定した場合、配列外参照やコーナーケースに注意
  ll pmcnt = 0; // +-+-+... としていく場合の処理回数
  ll mpcnt = 0; // -+-+-... としていく場合の処理回数
  bool pmok = true;
  bool mpok = true;

  // 第1項からここまでの和
  ll pmsum = 0;
  ll mpsum = 0;

  rep(i, N){
    // i : 0 ~ N-1
    if (i == 0){
      // + -
      if (as[i] <= 0){
        // 1 にしないといけない
        pmcnt += 1 - as[i];
        pmsum = 1;
      }
      else pmsum = as[i];

      // - +
      if (as[i] >= 0){
        // -1 にしないといけない
        mpcnt += as[i] + 1;
        mpsum = -1;
      }
      else mpsum = as[i];
    }
    else{
      // + -
      if (pmsum < 0){
        // + にしないといけない
        pmsum += as[i];
        if (pmsum <= 0){
          // 非正なら、1にする
          pmcnt += 1 - pmsum;
          pmsum = 1;
        }
      }
      else{
        // - にしないといけない
        pmsum += as[i];
        if (pmsum >= 0){
          // 非負なら、-1にする
          pmcnt += pmsum + 1;
          pmsum = -1;
        }
      }

      // - +
      if (mpsum < 0){
        // + にしないといけない
        mpsum += as[i];
        if (mpsum <= 0){
          // 非正なら、1にする
          mpcnt += 1 - mpsum;
          mpsum = 1;
        }
      }
      else{
        // - にしないといけない
        mpsum += as[i];
        if (mpsum >= 0){
          // 非負なら、-1にする
          mpcnt += mpsum + 1;
          mpsum = -1;
        }
      }
    }

    // 判定
    if (pmcnt > key){
      pmok = false;
    }
    if (mpcnt > key){
      mpok = false;
    }

  }

  if (pmok || mpok){
    return true;
  }
  else{
    return false;
  }

}

// 汎用的な二分探索のテンプレ
ll BinarySearch() {
  ll ng = -1; //「index = 0」が条件を満たすこともあるので、初期値は -1
  ll ok = 1000000000000000LL;
  // okは"1つも満たさない"場合があることに注意して設定。ex) = (ll)vec.size();
  // 二分探索はO(logN)なので大きめでもいいが、配列外参照やコーナーケースは注意

  // ok と ng のどちらが大きいかわからないことを考慮
  while (abs(ok - ng) > 1) {
    ll mid = (ok + ng) / 2;

    if (isOK(mid)) ok = mid;
    else ng = mid;
  }
  return ok;
}


