            diff -= n;
            s.at(i) += diff;
        }else if(s.at(i-1) < 0 && s.at(i) <= 0){
            n = - s.at(i) + 1;
            ans += n;
            diff += n;
            s.at(i) += diff;
        }
    }
    return ans;
}

