    for(int i = 1; i <= n; i++, s ^= 1) {
        tmp = x;
        x += a[i];
        if(sign(x) != s) ans2 += f(tmp, a[i], s);

        if(not s) x = min(-1, x);
        else x = max(1, x);
    }

    cout << min(ans1, ans2) << endl;
    return 0;
}

