  long sum = 0;
  long count = 0;
  int n = a.size();
  for (int i = 0; i < n; i++) {
    plus = !plus;
    sum += a.at(i);
    if (plus) {
      if (sum > 0) {
        continue;
      } else {
        count += 1 - sum;
        sum = 1;
      }
    } else {
      if (sum < 0) {
        continue;
      } else {
        count += 1 + sum;
        sum = -1;
      }
    }
  }
  return count;
}

