int change_num(int a[], int N)
  int res
  int sum = a[0];
  for (int i = 1; i < N; i++) {
    if(sum * (sum + a[i]) < 0) continue;

    if(sum > 0 && sum + a[i] >= 0) {
      sum += a[i];
      while (sum + a[i] >= 0) {
        res++;
        sum--;
      }
    } else if (sum < 0 && sum + a[i] < 0) {
      while (sum + a[i] <= 0) {
        res++;
        sum++;
      }
    }
  }
  return res;
}



