Int large0(std::vector<Int> a, Int n) {
	Int ans = 0;
	Int sum = a[0];

	for (Int i = 1; i < n; i++) {
		sum += a[i];
		if (i % 2 == 1 && sum >= 0) {

			ans += sum + 1;
			sum = -1;
		}
		if (i % 2 == 0 && sum <= 0) {

			ans += 1 - sum;
			sum = 1;
		}
	}
	return ans;
}

Int small0(std::vector<Int> a, Int n) {
	Int ans = 0;
	Int sum = a[0];

	for (Int i = 1; i < n; i++) {
		sum += a[i];
		if (i % 2 == 1 && sum <= 0) {

			ans += 1 - sum;
			sum = 1;
		}
		if (i % 2 == 0 && sum >= 0) {

			ans += sum + 1;
			sum = -1;
		}
	}
	return ans;
}

