long getTotal(int *a, int n, int dir) {
  long total{0}, sum{0};
  for (int i{0}; i < n; ++i) {
    sum += a[i];
    if (dir > 0 && sum <= 0) {
      total += -sum + 1;
      sum = 1;
    } else if (dir < 0 && sum >= 0) {
      total += sum + 1;
      sum = -1;
    }
    dir *= -1;
  }
  return total;
}

