  int n; scanf("%d", &n);
  int a[n];
  for (int i{0}; i < n; ++i) scanf("%d", &a[i]);

  long try1 = getTotal(a, n, 1);
  long try2 = getTotal(a, n, -1);

  printf("%ld\n", MIN(try1, try2));
  return 0;
}

