  cin>>n;
  long long  sum = 0;
  REP(i,0,n){
    cin>>a[i];
    sum += a[i];
    dp[i] = sum;
  }

  long long diff = 0, ans = 0;
  REP(i,1,n){
    if(dp[i] + diff == 0){
      if(dp[i-1] + diff < 0) diff++, ans++;
      if(dp[i-1] + diff > 0) diff--, ans++;
      continue;
    }
    if((dp[i-1] + diff)/abs(dp[i-1] + diff) == (dp[i] + diff)/abs(dp[i] + diff)){
      if(dp[i] + diff >= 0){
        ans += abs(dp[i] + diff) + 1;
        diff -= abs(dp[i] + diff) + 1;
      }else{
        ans += abs(dp[i] + diff) + 1;
        diff += abs(dp[i] + diff) + 1;
      }
    }
  }
  cout<<ans<<endl;

  return 0;
}

