#include <bits/stdc++.h>
using namespace std;

void answer1() {
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int n;
  cin >> n;
  vector<int> a(n);
  for(int& a_i: a) {
    cin >> a_i;
  }

  long long count = 0;
  long long sum = 0;
  long long count2 = 0;
  long long sum2 = 0;
  bool is_positive = a.at(0) > 0;
  for (int i = 0; i < a.size(); i++) {
    sum += a.at(i);
    sum2 += a.at(i);

    if (is_positive) {
      if (sum <= 0) {
        // 次は1になるまでインクリメント
        long long diff = 1 - sum;
        count += diff;
        sum += diff;
      }
      if (sum2 >= 0) {
        // 次は-1になるまでデクリメント
        long long diff = 1 + sum2;
        count2 += diff;
        sum2 -= diff;
      }
    } else {
      if (sum >= 0) {
        // 次は-1になるまでデクリメント
        long long diff = 1 + sum;
        count += diff;
        sum -= diff;
      }
      if (sum2 <= 0) {
        // 次は1になるまでインクリメント
        long long diff = 1 - sum2;
        count2 += diff;
        sum2 += diff;
      }
    }
    is_positive = ! is_positive;
  }
  cout << min(count, count2) << endl;

}

void answer2() {
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int n;
  cin >> n;
  vector<int> a(n);
  for(int& a_i: a) {
    cin >> a_i;
  }

  long long count = 0;
  long long sum = 0;
  long long count2 = 0;
  long long sum2 = 0;

  for (int i = 0; i < a.size(); i++) {
    sum += a.at(i);
    sum2 += a.at(i);
    if (i % 2 == 0) {
      // 偶数番目が正
      if (sum <= 0) {
        long long diff = 1 - sum;
        count += diff;
        sum = 1;
      }
      // 偶数番目が負
      if (sum >= 0) {
        long long diff = 1 + sum;
        count += diff;
        sum = -1;
      }
    } else {
      // 奇数番目が負
      if (sum >= 0) {
        long long diff = 1 + sum;
        count += diff;
        sum = -1;
      }
      // 奇数番目が正
      if (sum <= 0) {
        long long diff = 1 - sum;
        count += diff;
        sum = 1;
      }
    }
  }
  cout << min(count, count2) << endl;
}

