int main()
{
  int N;
  cin >> N;
  vector<long long int>A(N);
  for(int i=0; i < N; i++)
    cin >> A[i];
  vector<long long int>B(N);
  B[0] = A[0];
  for(int i=1 ; i < N; i++)
    B[i] = B[i-1] + A[i];
  long long int ans=0;
  long long int base=0;
  for(int i=1; i < N; i++){
    if((B[i]+base)*(B[i-1]+base) > 0){
      if(B[i]+base > 0){
	  ans += abs(B[i]+base)+1;
	  base -= abs(B[i]+base)+1;
	continue;
      }else if(B[i]+base < 0){
	  ans += abs(B[i]+base)+1;
	  base += abs(B[i]+base)+1;
	continue;
      }
    }
    if(i==1 && B[i-1]+base == 0){
      if(B[i]+base > 0){
	ans++;
	base -= 1;
      }else{
	ans++;
	base += 1;
      }
    }
    if(i < N-1){
      if(B[i]+base == 0){
        if(B[i-1]+base > 0){
	  ans += 1;
	  base -= 1;
	  continue;
        }else if(B[i-1]+base < 0){
	  ans += 1;
	  base += 1;
	  continue;
        }
      }
    }else{
      if(B[i]+base == 0)
	ans++;
    }
  }
  cout << ans << endl;
  return 0;
}

