            ans2 += diff;
            accsum += diff;
        }
        else {
            ll diff = max(0LL, 1LL + accsum);
            ans2 += diff;
            accsum -= diff;
        }
    }
    cout << min(ans1, ans2) << '\n';
    printf("Debug\n");
}

