const int MAX_N = int(1e5);
ll n, a[MAX_N], dp[MAX_N], dp1[MAX_N];

void solve() {
    ll even_plus = 0, even_minus = 0;
    ll diffs = 0;
    REP(i, n) {
        ll diff = 0;
        dp1[i] += diffs;
        if (i % 2 == 0 && dp1[i] <= 0) {
            diff = 1 - dp1[i];
            diffs += diff;
            dp1[i] = 1;
        } else if (i % 2 != 0 && dp1[i] >= 0) {
            diff = -1 - dp1[i];
            diffs += diff;
            dp1[i] = -1;
        }
        even_plus += abs(diff);
    }
    diffs = 0;
    REP(i, n) {
        ll diff = 0;
        dp[i] += diffs;
        if (i % 2 == 0 && dp[i] >= 0) {
            diff = -1 - dp[i];
            diffs += diff;
            dp[i] = -1;
        } else if (i % 2 != 0 && dp[i] <= 0) {
            diff = 1 - dp[i];
            diffs += diff;
            dp[i] = 1;
        }
        even_minus += abs(diff);
    }
    cout << (even_minus < even_plus ? even_minus : even_plus) << endl;
}

