        if(i % 2 == 0 && sum > 0) {
            cost += 1+sum;
            sum -= 1+sum;
        }
        if(i % 2 != 0 && sum < 0) {
            cost += 1-sum;
            sum += 1-sum;
        }
        if(sum == 0 && i % 2 == 0) {
            sum--;
            cost++;
        }else if(sum == 0 && i % 2 != 0) {
            sum++;
            cost++;
        }
