  if(sign>0 && a.at(0)<=0){
    ans += -a.at(0)+1;
    a.at(0) += -a.at(0)+1;
  }else if(sign<0 && a.at(0)>=0){
    ans += a.at(0)+1;
    a.at(0) -= a.at(0)+1;
  }
  int sum = a.at(0);
  for(int i=1; i<a.size(); i++){
    if(sum>0){
      if(a.at(i)+sum>=0){
        ans += a.at(i)+sum+1;
        a.at(i) -= a.at(i)+sum+1;
      }
    }else if(sum<0){
      if(a.at(i)+sum<=0){
        ans += -(a.at(i)+sum-1);
        a.at(i) += -(a.at(i)+sum-1);
      }
    }
    sum += a.at(i);
  }
  return ans;
}

