int main() {
    int N; cin >> N;
    vector<int> S(N + 1);

    for (int i = 1; i <= N; ++i) {
        cin >> S[i];
        S[i] += S[i - 1];
    }

    int ans = 0;
    int add = 0;
    int sign = ((S[1] >> 31) << 1) + 1;
    for (int i = 2; i <= N; ++i) {
        S[i] += add;

        int sign_i = ((S[i] >> 31) << 1) + 1;
        if (sign_i == sign) {
            ans += abs(-sign_i - S[i]);
            add += -sign_i - S[i];
            S[i] = -sign_i;
            sign_i = -sign_i;
        }
        else if (S[i] == 0) {
            ans += 1;
            add += -sign;
            S[i] += -sign;
            sign_i = -sign;
        }
        sign = sign_i;
    }

    cout << ans << endl;
}

