using namespace std;

bool DifSign(int a, int b)
{
	if (a == 0 || b == 0)
		return false;

	return ((a > 0 && 0 > b) || (b > 0 && 0 > a));
}

int solver(vector<int> A, int dsum)
{
	int ans = 0;
	for (int i = 1; i < A.size(); i++)
	{
		if (!DifSign(dsum, dsum + A[i]))
		{
			int addnum = abs(dsum + A[i]) + 1;
			ans += addnum;

			if (dsum + A[i] > 0)
				A[i] -= addnum;
			else if (dsum + A[i] < 0)
				A[i] += addnum;
			else
			{
				if (dsum > 0)
					A[i] -= addnum;
				else
					A[i] += addnum;
			}

		}

		dsum += A[i];
	}

	return ans;
}

int main()
{
	int N;
	int dsum = 0;
	int ans1 = 0;
	int ans2 = 0;
	cin >> N;

	vector<int> A(N);
	vector<int> B(N);
	for (int i = 0; i < N; i++)
	{
		cin >> A[i];
		B[i] = A[i];
	}

	// + - + ...
	if (A[0] < 0)
	{
		ans1 += abs(A[0]) + 1;
		A[0] = 1;
	}
	dsum += A[0];
	ans1 += solver(A, dsum);

	// - + - ...
	dsum = 0;
	if (B[0] > 0)
	{
		ans2 += abs(B[0]) + 1;
		B[0] = -1;
	}
	dsum += B[0];
	ans2 += solver(B, dsum);

	cout << min(ans1, ans2) << endl;

	return 0;
}

