  int n; cin>>n;
  vector<long long>a(n);
  for(int i=0;i<n;i++)cin>>a[i];
  long long cost=0;
  for(int i=0;i<n;i++){
    if(i%2==0){
      if(a[i]<=0)cost+=1-a[i];
    }else{
      if(a[i]>=0)cost+=a[i]+1;
    }
  }
  long long cost2=0;
  for(int i=0;i<n;i++){
    if(i%2!=0){
      if(a[i]<=0)cost2+=1-a[i];
    }else{
      if(a[i]>=0)cost2+=a[i]+1;
    }
  }
  cout<<min(cost,cost2)<<endl;
}

