  ll ans=0;
  if(sum[0]==0){
    ans=1;
    sum[0]=1;
  }
  rep1(i,n-1){
    ll t=sum[i-1]+a[i];
    //    cout << sum[i-1] << endl;
    if(t==0){
      ans+=1;
      sum[i]=-abs(sum[i-1])/sum[i-1];
    }
