  ll ans2=0;
  if(a[0]==0){
    ans2=1;
    sum[0]=-1;
  }else{
    sum[0]=-abs(a[0])/a[0];
    ans2=abs(a[0])+1;
  }
  rep1(i,n-1){
    ll t=sum[i-1]+a[i];
    if(t==0){
