using namespace std;
typedef long long ll;

vector<int> v(1e5);

ll solve(int n)
{
    ll sum = v[0];
    ll ans = 0;
    for (int i = 1; i < n; i++) {
        //cout << v[i] << ": " << sum << "\n";
        if (sum < 0 && sum + v[i] > 0) sum += v[i];
        else if (sum > 0 && sum + v[i] < 0) sum += v[i];

        else if (sum < 0 && sum + v[i] <= 0) ans += abs(sum+v[i]) + 1, sum = 1;
        else if (sum > 0 && sum + v[i] >= 0) ans += abs(sum+v[i]) + 1, sum = -1;
        //cout << ">> " << sum << "\n";
    }

    //cout << ans;
    return ans;
}

int main()
{
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) cin >> v[i];

    ll ans = solve(n);

    for (int i = 0; i < n; i++) v[i] *= -1;
    ans = max(ans, solve(n));

    cout << ans;
}

