using namespace std;


int getCount(vector<int>a){
    long long int sum=a[0];
    long long int count=0;
    bool pos=true;
    if(sum<0)
    pos=false;
    for(int i=1;i<a.size();i++)
    {

        if(!pos){
            sum+=a[i];
            if(sum<=0){
                count+=abs(sum)+1;
                sum=1;
            }
            pos=true;
        }
        else
        {
            sum+=a[i];
            if(sum>=0){
                count+=sum+1;
                sum=-1;
            }
            pos=false;
        }
    }
    return count;
}
