			count1 += abs(sum) - a[i] + 1;
			sum = 1;
		}
		else if (sum > 0 && sum + a[i] > 0) {
			count1 += abs(sum + a[i] + 1);
			sum = -1;
		}
		else {
			sum += a[i];
		}
