			count1 += 1;
			if (i % 2) {
				sum = -1;
			}
			else {
				sum = 1;
			}
		}
	}
	sum = a[0] + a[1];
	if (sum == 0) {
		count2 += 1;
	}
	else if (sum < 0) {
		count2 += 1 - sum;
	}
	else {
		count2 += sum - 1;
	}
	sum = 1;
