			}
			w += a[i];
		}
		else {
			if (w >= abs(a[i])) {
				a[i] = -1 * (w + 1);
			}
			w += a[i];
		}
	}
	w = t[0];
	if (w >= 0) {
		w = -1;
		t[0] = -1;
	}
	rep(i, 1, n) {
		if (i % 2 == 1) {
			if (abs(w) >= t[i]) {
				t[i] = abs(w) + 1;
			}
			w += t[i];
		}
		else {
			if (w >= abs(t[i])) {
				t[i] = -1 * (w + 1);
			}
			w += t[i];
		}
	}
