long long seq(int a,vector<int> b){
  long long count=0;
  if(0<=b[0]*a){
    if(b[0]==0){
      b[0]=a;
      count++;
    }
    long long s=b[0];
    for(int i=1;i<b.size();i++){
      int k = (1-2*(i%2))*a;
      s += b[i];
      if(s*k<=0){
        count += 1-k*s;
      	s = k;
      }
    }
  }
  return count;
}
