const ll INF = 1LL << 60;

struct edge {
  ll to, cost;
};
vector<vector<edge> > edges;

vector<ll> dist;
bool bellman_ford(int n, int s) {
  dist = vector<ll>(n, INF);
  dist[s] = 0;
  for (int i = 0; i < n; i++) {
    for (int v = 0; v < n; v++) {
      for (int k = 0; k < edges[v].size(); k++) {
        edge e = edges[v][k];
        if (dist[e.to] > dist[v] + e.cost) {
          dist[e.to] = dist[v] + e.cost;
          if (i == n - 1 && e.to == n - 1) {
            return false;
          }
        }
      }
    }
  }
  return false;
}

