using namespace std;

vector<int> num;

long long sequence(int s) {
  long long sum = s;
  long long res = 0;

  for (int i = 1; i < num.size(); i++) {
    if (sum > 0) {
      if (sum + num[i] >= 0) {
        res += 1 + num[i] + sum;
        sum = -1;
      } else {
        sum += num[i];
      }
    } else {
      if (sum + num[i] <= 0) {
        res += 1 - num[i] - sum;
        sum = 1;
      } else {
        sum += num[i];
      }
    }
  }

  return res;
}

int main() {
  int n; cin >> n;

  num.resize(n);
  for (int i = 0; i < n; i++) cin >> num[i];

  long long ans1;
  long long ans2;

  if (num[0] == 0) {
    ans1 = sequence(1) + 1;
    ans2 = sequence(-1) + 1;
  } else if (num[0] > 0) {
    ans1 = sequence(num[0]);
    ans2 = sequence(-1) + num[0] + 1;
  } else {
    ans1 = sequence(1) + abs(num[0]) + 1;
    ans2 = sequence(num[0]);
  }

  cout << min(ans1, ans2) << endl;
}

