long int check(int sum, long int ans, vector<int> T, int N, bool pre_pm) {
    for(int i = 1; i < N; i ++) {
        if(pre_pm) {
            sum += T.at(i);
            while (0 <= sum) {
                sum--;
                ans++;
            }
            pre_pm = false;
        } else {
            sum += T.at(i);
            while (sum <= 0 ) {
                sum++;
                ans++;
            }
            pre_pm = true;
        }
    }
    return ans;
}

int main()
{
    int N;
    vector<int> T;

    cin >> N;

    for(int i = 0; i < N; i++) {
        int tmp;
        cin >> tmp;
        T.push_back(tmp);
    }

    //sort(T.begin(), T.end());

    //for(int i = 0; i < N; i++) { //cout << T.at(i) << endl; }
    long int ans = 0;   
    int sum = 0;

    bool pre_pm;
    sum = T.at(0);

    if(0 <= sum) { 
        pre_pm = true;
        long int tmp1 = check(sum, ans, T, N, pre_pm);
        pre_pm = false;
        long int tmp2 = check(-1, 1+sum, T, N, pre_pm);

        cout << min(tmp1, tmp2) << endl;
    } else {
        pre_pm = false;
        long int tmp1 = check(sum, ans, T, N, pre_pm);
        pre_pm = true;
        long int tmp2 = check(1, 1 + sum, T, N, pre_pm);

        cout << min(tmp1, tmp2) << endl;

    }

    return 0;
}

