int64_t solve(const vector<int>& a, int ra) {
  int64_t ans = 0;
  int64_t s = 0;
  for (int i = 0; i < a.size(); i++) {
    auto e = a[i];
    if (i % 2 == ra) {
      // s + e <= -1?
      if (s + e >= 0) {
        ans += abs(-1 - s - e);
        s = -1;
        continue;
      }
    } else {
      // s + e >= 1?
      if (s + e <= 0) {
        ans += abs(1 - s - e);
        s = 1;
        continue;
      }
    }
    s += e;
  }
  return ans;
}

