	while ( beg < a.size() ){
		prev = sum;
		sum += a[beg];
		if ( (sum ^ prev) >= 0LL || sum == 0LL ){
			if ( prev > 0 ){
				count += sum + 1;
				sum = -1;
			}else{
				count += 1 - sum;
				sum = 1;
			}
		}
		beg++;
	}
	return count;
}

int main( int argc, char *argv[] ) {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	int n;
	cin >> n;

	vector<ll> a(n);
	for ( int i = 0 ; i < n ; i++ )
		cin >> a[i];

	ll res;
	if ( a[0] == 0 )
		res = max(seq(a, 1, 1, 1), seq(a, -1, 1, 1));
	else
		res = seq(a, a[0], 1, 0);

	std::cout << res << std::endl;
	return 0;
}

