                na[i] += dx;
                cnt += abs(dx);
                sum[s] += dx;
            }
        }
        // 奇数番目のsumが正の場合の操作回数をカウントする
        if (s == 1) {
            sum[s] += na[i];
            // 奇数番目のsumが負の場合、差分を計算する
            if (i % 2 != 0 && sum[s] <= 0) {
