int solve(vector<int> vec)
{
    ll n = vec.size();
    ll sum = vec[0] + vec[1];
    int ans = 0;
    for (ll i = 2; i < n; i++) {
        if (sum > 0) {
            if (sum + vec[i] >= 0) {
                ans += 1 + (sum + vec[i]);
                sum = -1;
            } else{
                sum += vec[i];
            }
        } else if (sum <= 0) {
            if (sum + vec[i] <= 0) {
                ans += 1 - (sum + vec[i]);
                sum = 1;
            } else{
                sum += vec[i];
            }
        }
    }
    return ans;
}

