long int check(long int sum, long int ans, vector<int> T, int N, bool pre_pm) {
    for(int i = 1; i < N; i ++) {
        if(pre_pm) {
            sum += T.at(i);
            while (0 <= sum) {
                sum--;
                ans++;
            }
            pre_pm = false;
        } else {
            sum += T.at(i);
            while (sum <= 0 ) {
                sum++;
                ans++;
            }
            pre_pm = true;
        }
    }
    return ans;
}

