    ll count = 0;
    if (a.at(0) == 0) {
        a.at(0) = 1;
        count = 1;
    }
    ll sum = a.at(0);
    for (ll i = 0; i < n - 1; i++) {
        ll next_sum = sum + a.at(i + 1);
        if (sum > 0 && next_sum >= 0) {
            ll diff = 1 + next_sum;
            count += diff;
            a.at(i + 1) -= diff;
            next_sum -= diff;
        }
        else if (sum < 0 && next_sum <= 0) {
            ll diff = 1 - next_sum;
            count += diff;
            a.at(i + 1) += diff;
            next_sum += diff;
        }
        sum = next_sum;
    }

    cout << count << endl;

    return 0;
}

