unsigned int manipulation(vector<int>& a) {
  unsigned int m = 0;
  if (a[0]==0) {
    m++;
    if (a[1] == 0)
      a[0] = 1;
    else if (a[1] == 1)
      a[0] = -1;
    else if (a[1] > 1)
      a[0] = -a[1]+1;
    else if (a[1] == -1)
      a[0] = 1;
    else 
      a[0] = -a[1]+1;
  }
  int sum = a[0];
  bool is_sum_above_0 = sum > 0;
  for (unsigned int ii=1; ii<a.size(); ++ii) {
    sum += a[ii];
    if (is_sum_above_0) {
      while(sum>=0) {
	m++; sum--;
      }
    } else {
      while(sum<=0) {
	m++; sum++;
      }
    }
    is_sum_above_0 = !is_sum_above_0;
  }
  return m;
}

