//負の数始まり
ll minuss(ll n, vector<ll> a){
  ll x = 0;
  ll sum = 0; //手前までの合計
  ll counter = 0; //操作回数
  while(x < n){
    if(x % 2 == 0 && sum + a.at(x) >= 0){
      ll olda = a.at(x);
      a.at(x) = -1 - sum;
      counter += abs(a.at(x) - olda);
    }
    if(x % 2 == 1 && sum + a.at(x) <= 0){
      ll olda = a.at(x);
      a.at(x) = 1 - sum;
      counter += abs(a.at(x) - olda);
    }
    sum += a.at(x);
    x++;
  }
  return counter;
}

ll pluss(ll n, vector<ll> a){
  ll x = 0;
  ll sum = 0; //手前までの合計
  ll counter = 0; //操作回数
  while(x < n){
    if(x % 2 == 0 && sum + a.at(x) <= 0){
      ll olda = a.at(x);
      a.at(x) = 1 - sum;
      counter += abs(a.at(x) - olda);
    }
    if(x % 2 == 1 && sum + a.at(x) >= 0){
      ll olda = a.at(x);
      a.at(x) = -1 - sum;
      counter += abs(a.at(x) - olda);
    }
    sum += a.at(x);
    x++;
  }
  return counter;
}

