std::vector<int> seq, sum;

long compare(bool which) {
	bool is_plus = which;
	long ans = 0;
	long dif = 0;
	if (which && sum[0] <= 0) {
		dif += 1 - sum[0];
		ans += dif;
	} else if (!which && sum[0] >= 0) {
		dif += -1 - sum[0];
		ans += -dif;
	}
	for (int i = 1; i < sum.size(); i++) {
		long num = sum[i] + dif;
		if (is_plus && num >= 0) {
			long tmp = -1 - num;
			dif += tmp;
			ans += -tmp;
		} else if (!is_plus && num <= 0) {
			long tmp = 1 - num;
			dif += tmp;
			ans += tmp;
		}
		is_plus = !is_plus;
	}
	return ans;
}

