ll hoge(ll x) {
    ll sum = x;
    ll res = 0;
    rep(i, n - 1) {
        ll y = a[i + 1];
        if(sum > 0) {
            if(sum + y < 0) sum += y;
            else {
                res +=  sum + y - (-1);
                sum = -1LL;
            }
        } else {
            if(sum + a > 0) sum += y;
            else {
                res += 1LL - (sum + y);
                sum = 1LL;
            }
        }
    }
    return res;
}

void solve() {
    cin >> n;
    rep(i, n) {
        cin >> a[i];
    }
    ll c = max(a[0], 1LL), d = min(a[0], -1LL);
    ll ans = min(hoge(c) + (c == 1LL ? abs(a[0] - 1) : 0), hoge(d) + (d == -1LL ? abs(a[0] + 1) : 0));
    cout << ans << endl;
}

