using namespace std;

long chk(long a[], int N, bool t)
{
  long total = 0;
  long ops = 0;
  for (int i = 0; i < N; i++) {
    total += a[i];
    if (t == true && (total < 1)) {
      ops += (1-total);
      total = 1;
    } else if (t == false && (total > -1)) {
      ops += (total+1);
      total = -1;
    }
    t = !t;
  }
  return ops;
}

int main ()
{
  long N;
  cin >> N;
  long a[100001];

  for (long i = 0; i < N; i++) {
    cin >> a[i];
  }

  printf("%d\n", min(chk(a, N, true), chk(a, N, false)));

}

#include<iostream>
using namespace std;

long f(int a[], int N, bool positive) {
  long cnt = 0;
  long sum = a[0];
  for (int i = 1; i < N; i++) {
    int next = a[i];
    int nextSum = sum + next;
    if (positive) {
      if (i % 2 == 0) {
        if (nextSum <= 0) {
          int des = abs(nextSum) + 1;
          next += des;
          cnt += des;
        }
      } else {
        if (0 <= nextSum) {
          int des = abs(nextSum) + 1;
          next -= des;
          cnt += des;
        }
      }
    } else {
      if (i % 2 == 0) {
        if (0 <= nextSum) {
          int des = abs(nextSum) + 1;
          next -= des;
          cnt += des;
        }
      } else {
        if (nextSum <= 0) {
          int des = abs(nextSum) + 1;
          next += des;
          cnt += des;
        }
      }
    }
    sum += next;
  }
  return cnt;
}

int main() {
  int N;
  cin >> N;

  int a[N];
  for (int i = 0; i < N; i++) cin >> a[i];

  long cnt = min(f(a, N, 1), f(a, N, 0));

  cout << cnt << endl;
  return 0;
}

