    cin >> N;
    vector<int> a(N),S(N+7);
    for (int i=0; i<N; i++) {
        cin>>a[i];
    }

    int ans=0;

    S[0]=a[0];
    // S[0]が0の場合、第一項目は次に０でない値が出てくる位置とその正負で決める。
    if (S[0]==0) {
        for (int i=0; i<N; i++) {
            if (a[i]>0) {
                if (i%2==0) {
                    S[0]=1;
                    ans++;
                    break;
                }
                else{
                    S[0]=-1;
                    ans++;
                    break;
                }
            }
            else if (a[i]<0){
                if (i%2==0) {
                    S[0]=-1;
                    ans++;
                    break;
                }
                else{
                    S[0]=1;
                    ans++;
                    break;
                }
            }
            else if (i==N-1 && a[i]==0){
                ans=(2*N)-1;
                cout << ans << endl;
                return 0;
            }
        }
    }

    // 累積和を計算
    for (int i=1; i<N; i++) {
        S[i] = S[i-1] + a[i];
    }

    for (int i=1; i<N; i++) {
        if (S[i-1]>0&&S[i]>=0) {
            ans+=abs(S[i])+1;
            S[i]=-1;
            if (i!=N-1) {
                S[i+1]=S[i]+a[i+1];
            }
        }
        else if (S[i-1]<0&&S[i]<=0){
            ans+=abs(S[i])+1;
            S[i]=1;
            if (i!=N-1) {
                S[i+1]=S[i]+a[i+1];
            }
        }
    }
    cout << ans << endl;
    return 0;
}

