ll calc(int mod)
{
    ll sum = 0, res = 0;
    for (int i = 1; i <= n; i++){
        sum += a[i];
        if (i % 2 == mod && sum <= 0){
            res += (1 - sum);
            sum = 1;
        }
        else if(i % 2 != mod && sum >= 0){
            res += (sum + 1);
            sum = -1;
        }
    }
    return res;
}

