using namespace std;
using namespace lib;

class C {
public:



  void solve(std::istream &in, std::ostream &out) {
    ios::sync_with_stdio(false);
    int n;
    in >> n;
    vector<long long int> a(n), p(n);
    for (int i = 0; i < n; ++i) {
      in >> a[i];
    }
    long long int steps = 0;
    long long int steps2 = 0;

    if (a[0] == 0) {
      p[0] = 1;
      ++steps;
    }else{
      p[0] = a[0];
    }

    for (int i = 0; i < n - 1; ++i) {
      p[i + 1] = p[i] + a[i + 1];
      if (sgn(p[i]) != -sgn(p[i + 1])) {
        steps += abs(p[i + 1]) + 1;
        p[i + 1] = -sgn(p[i]);
      }
    }
    steps2 = abs(a[0]) + 1;
    p[0] = -sgn(p[0]);
    for (int i = 0; i < n - 1; ++i) {
      p[i + 1] = p[i] + a[i + 1];
      if (sgn(p[i]) != -sgn(p[i + 1])) {
        steps2 += abs(p[i + 1]) + 1;
        p[i + 1] = -sgn(p[i]);
      }
    }
    steps = min(steps, steps2);
    out << steps << endl;
  }

};


int main() {
	C solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

