    long long cost1 = 0;
    long long sum1 = 0;
    for (int i = 0; i < n; i++){

        sum1 += a[i];

        if (i % 2 == 0 && sum1 > 0) continue;
        else if (i % 2 == 0 && sum1 <= 0){
            cost1 += abs(sum1) + 1;
            sum1 = 1;
        }
        else if (i % 2 == 1 && sum1 >= 0){
            cost1 += abs(sum1) + 1;
            sum1 = -1;
        }
        else{
            continue;
        } 
    }

     // negative -> positive -> negative .... の場合に関して,操作回数を調べる
