int N;

int solve(int ans, vector<int> A, vector<int> cu) {
	rep(i, N) {
		//0なら
		if (cu[i] == 0) {
			ans++;
			if (i == 0) {
				if (cu[i + 1] < 0) {
					cu[i] = 1;
				}
				else {
					cu[i] = -1;
				}
			}
			else {
				if (cu[i - 1] < 0) {
					cu[i] = 1;
				}
				else {
					cu[i] = -1;
				}
			}
		}

		if (i == N - 1) {
			break;
		}

		//符号が同じなら
		if (cu[i] < 0 == cu[i + 1] < 0) {
			if (cu[i + 1] > 0) {
				ans += cu[i + 1] + 1;
				cu[i + 1] -= cu[i + 1] + 1;
			}
			else {
				ans += -cu[i + 1] + 1;
				cu[i + 1] += -cu[i + 1] + 1;
			}
		}
		cu[i + 2] = cu[i + 1] + A[i + 2];
	}
	return ans;
}

signed main() {

	cin >> N;
