	vector<int> cu(N + 2);
	int su = 0;
	rep(i, N) {
		cin >> A[i];
		su += A[i];
		cu[i] = su;
	}

	int ans1 = 0, ans2 = 0;
	ans1 = solve(ans1, A, cu);

	if (A[0] < 0) {
		ans2 = -A[0] + 1;
		A[0] = 1;
	}
	else {
		ans2 = A[0] + 1;
		A[0] = -1;
	}


	su = 0;
	rep(i, N) {
		su += A[i];
		cu[i] = su;
	}

	ans2 = solve(ans2, A, cu);

	cout << min(ans1, ans2) << "\n";

	return 0;

}

