int64_t Cost(const vector<int64_t> &vec, bool positive_sum)
{
    int64_t cost = 0;
    int64_t sum = 0;

    for (const auto &num : vec) {
        sum += num;
        if (sum >= 0 && !positive_sum) {
            cost += sum + 1;
            sum = -1;
        } else if (sum <= 0 && positive_sum) {
            cost += 1 - sum;
            sum = 1;
        }
        positive_sum = !positive_sum;
    }
    return cost;
}

