            if (sum2 > -1) {
                y += (1 + sum2);
                sum2 = -1;
            }
        } else { // 奇数項
            if (sum2 < 1) {
                y += (1 - sum2);
                sum2 = 1;
            }
        }
        if (y >= x) {
            break;
        }
    }

    cout << min(x, y) << endl;
