ll dfs(int cur, ll acc, ll pre){
  if(cur == N) return 0;
  ll Sum = v[cur] + acc;
  ll ret;
  if(pre*Sum < 0) return dfs(cur+1, acc,  Sum);
  if(Sum == 0){
    if(pre>0) ret =  dfs(cur+1, acc-1, -1) +1;
    else ret =  dfs(cur+1, acc+1, +1) +1;
  }else{
    if(pre>0) ret =  dfs(cur+1, acc-Sum-1, -1) +abs(Sum) +1;
    else ret = dfs(cur+1, acc-Sum+1, 1) +abs(Sum) +1;
  }
  return ret;
}

