int execOne(const vector<int> &a)
{
	int sum = 0;
	int ans = 0;
	for (int i = 0; i < a.size();) {
		sum += a[i];
		if (0 <= sum) {
			ans += (abs(sum) + 1);
			sum = -1;
		}
		i++;
		if (i == a.size()) {
			break;
		}

		sum += a[i];
		if (0 >= sum) {
			ans += (abs(sum) + 1);
			sum = 1;
		}
		i++;
	}

	return ans;
}

int execOneRev(const vector<int> &a)
{
