pair<LL , LL> maxP(vll a , ll size){
    pair <ll , ll> p;
    ll Max = a[0];
    ll place = 0;
    REP(i,size){
        if(a[i] > Max){
            Max = a[i];
            place = i;
        }
    }
    p.first = Max;
    p.second = place;
    return p;
}

pair<LL , LL> minP(vll a , ll size){
    pair <ll , ll> p;
    ll min = a[0];
    ll place = 0;
    REP(i,size){
        if(a[i] < min){
            min = a[i];
            place = i;
        }
    }
    p.first = min;
    p.second = place;
    return p;
}

ll sumL(vll a , ll size){
    ll sum = 0;
    REP(i,size){
        sum += a[i];

    }
    return sum;
}

