long long f(int sign, const vector<long long>& a)
{
	long long cnt = 0;
	long long sum = 0;

	for(int i=0; i<a.size(); i++)
	{
		sum += a[i];
		if(sign*sum <= 0)
		{
			long long d = sign - sum;
			sum += d;
			cnt += abs(d);
		}

		sign *= -1;
	}

	return cnt;
}

