int N;
vector<int> a;

long long solve(bool b) {
    long long count = 0;
    long long sum = a[0];
    if(a[0] == 0) { sum = b ? 1 : -1; count++; }
    else if(b && a[0] < 0) { sum = 1; count = 1 - a[0]; }
    else if(!b && a[0] > 0) { sum = -1; count = a[0] + 1; }

    for(int i = 1; i < N; i++) {
        if(sum * a[i] < 0 && abs(sum) < abs(a[i])) {
            sum += a[i];
        } else {
            if(sum > 0) {
                count += a[i] + sum + 1;
                sum = -1;
            } else {
                count += 1 - sum - a[i];
                sum = 1;
            }
        }
    }
    return count;
}

int main()
{
    cin >> N;
    a.resize(N);
    for(int i = 0; i < N; i++) cin >> a[i];

    cout << min(solve(true), solve(false)) << endl;
    return 0;
}

