void operation_test(bool &Next_plus,ll &sum,ll Next_number,ll &operation){
  if(Next_plus){
    if(sum+Next_number>0){
      Next_plus=false;
      sum+=Next_number;
    }else{
      Next_plus=false;
      operation+=abs((1-sum)-Next_number);
      sum=1;
    }
  }else{
    if(sum+Next_number<0){
      Next_plus=true;
      sum+=Next_number;
    }else{
      Next_plus=true;
      operation+=abs((-1-sum)-Next_number);
      sum=-1;
    }
  }
}

