int main()
{
	long long n, ans, ans2;
	long long tmp, sign = 0, cnt;
	cin >> n;
	for (long long i = 0; i < n; i++)
	{
		cin >> a[i];
	}
	//最初を正
	sign = 1;
	if (a[0] > 0)
	{
		tmp = a[0];
		cnt = 0;
	}
	else
	{
		tmp = 1;
		cnt = (-1 * a[0]) + 1;
	}
	ans = calc(a, n, sign, tmp, cnt);
	//最初を負
	sign = 0;
	if (a[0] < 0)
	{
		tmp = a[0];
		cnt = 0;
	}
	else
	{
		tmp = -1;
		cnt = a[0] + 1;
	}
	ans2 = calc(a, n, sign, tmp, cnt);
	if (ans2 < ans) ans = ans2;
	cout << ans << endl;
	return 0;
}

long long calc(long long *a, long long n, long long sign, long long tmp, long long cnt)
{
	for (long long i = 0; i < n - 1; i++)
	{
		tmp = tmp + a[i + 1];
		if (sign == 1)
		{
			if (tmp >= 0)
			{
				cnt += tmp + 1;
				tmp = -1;
			}
		}
		else
		{
			if (tmp <= 0)
			{
				cnt += (-1 * tmp) + 1;
				tmp = 1;
			}
		}
		sign = get_sign(tmp);
	}
	return cnt;
}

long long get_sign(long long tmp)
{
	if (tmp < 0) return 0;
	else return 1;
}

