int64_t Compute(const std::vector<int> &arr, const bool flag)
{
    int sign = flag ? +1 : -1;
    int64_t sum = 0;
    int64_t count = 0;
    for (size_t i = 0; i < arr.size(); ++i)
    {
        sum += arr[i];
        if (sum == 0)
        {
            ++count;
            sum = sign;
        }
        else if (sum * sign > 0)
        {
            // 条件を満たす
        }
        else
        {
            // 条件を満たさない
            count += abs(sum) + 1;
            sum = sign;
        }
        sign *= -1;
    }

    return count;
}

