ll solve(vector<int> a) {
  ll res = 0, _sum = 0;
  bool is_sei = true;

  for(auto ai : a) {
    if((is_sei && _sum+ai>0) || (!is_sei && _sum+ai<0)) {
      _sum = _sum + ai;
