using namespace std;
const int MaxN = 2e5 + 5;
typedef long long LL;
int box[MaxN];
int n;
LL solve1(){
	LL sum = box[1];
	LL res = 0;
	if(sum == 0){
		sum = 1;
		res = 1;
	}
	for(int i = 2; i <= n; i++){
		LL temp = box[i] + sum;
		if(temp * box[i] >= 0){
			res += abs(temp) + 1;
			if(sum > 0) sum = -1;
			else sum = 1;
		}
		else sum = temp;
	}
	return res;
}
LL solve2(){
	LL sum = box[1];
	LL res = 0;
	if(sum == 0){
		sum = -1;
		res = 1;
	}
	for(int i = 2; i <= n; i++){
		LL temp = box[i] + sum;
		if(temp * sum >= 0){
			res += abs(temp) + 1;
			if(sum > 0) sum = -1;
			else sum = 1;
		}
		else sum = temp;
	}
	return res;
}

int main(){
	while(~scanf("%d", &n)){
		for(int i = 1; i <= n; i++) scanf("%d", &box[i]);
		LL ans = 1LL << 60;
		ans = min(ans, solve1());
		ans = min(ans, solve2());
		printf("%lld\n", ans);
	}
	return 0;
}

