ll cal(vector<ll>& A, int sign)
{
  int n = A.size();
  ll ret = 0, diff = 0;
  for (int i = 0, s = sign; i < n; ++i, s *= -1) {
    ll val = A[i] + diff;
    if (s < 0) {
      if (val < 0) { continue; }
      ret += val + 1;
      diff -= (val + 1);
    }
    else if (s > 0) {
      if (val > 0) { continue; }
      ret += abs(val) + 1;
      diff += abs(val) + 1;
    }
  }

  return ret;
}

int main()
{
  int N; scanf("%d", &N);
  vector<ll> A(N);
  for (int i = 0; i < N; ++i) {
    scanf("%lld", &A[i]);
  }
  for (int i = 1; i < N; ++i) {
    A[i] += A[i - 1];
  }

  ll ans = min(cal(A, 1), cal(A, -1));
  printf("%lld\n", ans);
  return 0;
}

