void solve() {
    ll N; cin >> N;
    vec A(N); cin >> A;

    ll sum = 0;
    ll p_res = 0;
    rep(i,N){
        sum += A[i];
        if(i%2==0){
            if(sum<=0){
                p_res += abs(sum) + 1;
                sum = 1;
            }
        }
        else{
            if(sum>=0){
                p_res += abs(sum) + 1;
                sum = -1;
            }
        }
    }

    sum=0;
    ll m_res = 0;
    rep(i,N){
        sum += A[i];
        if(i%2==1){
            if(sum<=0){
                m_res += abs(sum) + 1;
                sum = 1;
            }
        }
        else{
            if(sum>=0){
                m_res += abs(sum) + 1;
                sum = -1;
            }
        }
    }

    cout << min(p_res, m_res) << endl;
}

