typedef long long ll;

int n;
ll f(vector<ll>& sum, vector<ll>& pm)
{
	int tmp;
	tmp = 0;
	rep(i, n - 1)
	{
		sum[i + 1] += pm[i];
		if (sum[i] * sum[i + 1] >= 0)
		{
			if (sum[i + 1] == 0)
			{
				if (sum[i] < 0)
					sum[i + 1] = pm[i + 1] = 1;
				else
					sum[i + 1] = pm[i + 1] = -1;
			}
			else if (sum[i + 1] < 0)
			{
				pm[i + 1] = 1 - sum[i + 1];
				sum[i + 1] = 1;
			}
			else if (sum[i + 1] > 0)
			{
				pm[i + 1] = -1 - sum[i + 1];
				sum[i + 1] = -1;
			}
			tmp += abs(pm[i + 1]);
		}
	}
	return tmp;
}

