bool eqsig(ll a, ll b){
    if(a<0 && b>0)
        return true;
    if(a>0 && b<0)
        return true;
    return false;
}

int solve(){
    int ans=0;
    For(i,n-1){
        sum[i+1]=sum[i]+a[i+1];
        if(eqsig(sum[i],sum[i+1]))
            continue;
        if(sum[i]<0){
