    for (int i = 1; i < N; i++) {
        if(positive){
            if(sum+arr[i] < 0){
                sum = sum + arr[i];
                positive = false;
            }else{
                int must = -sum-1;
                int diff = abs(arr[i] - must);
                count += diff;
                sum += must;
                positive = false;
