            if(sum + arr[i] > 0){
                sum = sum + arr[i];
                positive = true;
            }else{
                int must = -sum + 1;
                int diff = abs(must - arr[i]);
                count += diff;
                sum += must;
                positive = true;
            }
        }
    }

    printf("%d", count);

    return 0;
}

