long long ope_cnt(vector<long long> a, int n, bool plus) {
	long long sum = 0, ret = 0;
	for (int i = 0; i < n; i++) {
		sum += a[i];
		if (plus && sum <= 0) {
			ret += 1 - sum;
			sum = 1;
		}
		else if (!plus && sum >= 0) {
			ret += 1 + sum;
			sum = -1;
		}
		plus = !plus;
	}
	return ret;
}

