bool isPositive(int i) {
    return i >= 0;
}

bool isNegative(int i) {
    return i < 0;
}

int operation(vector<int> a) {
    int opeCount = 0;
    int preSum = 0;
    int sum = 0;
    int i = 0;
    while (i < a.size()) {
        if(i == 0) { // 1回目
//            cout << "i : " << i << endl;
//            cout << "a[i] :  " << a[i] << endl;
            if(a[i] == 0) {
                if(isPositive(a[i + 1])) { // 次をチェックして0番目を増減
                    a[i] = a[i] - 1;
                    opeCount++;
                } else {
                    a[i] = a[i] + 1;
                    opeCount++;
                }
            }
            preSum = a[i];  // preSum作る
            i++;
        } else { // 2回目以降
//            cout << "i : " << i << endl;
//            cout << "a[i] :  " << a[i] << endl;
            sum = preSum + a[i];
//            cout << "preSum :  " << preSum << endl;
//            cout << "sum :  " << sum << endl;
//            cout << "opeCount :  " << opeCount << endl;
            if (sum == 0) { // 合計ゼロなら増減してもう一度
                if(isPositive(preSum)) {
                    a[i] = a[i] - 1;
                    opeCount++;
                } else {
                    a[i] = a[i] + 1;
                    opeCount++;
                }
            } else { // 合計ゼロじゃない時
                if (isPositive(sum) && isPositive(preSum)) { // PPなら今のを減らす
                    a[i] = a[i] - 1;
                    opeCount++;
                } else if (isNegative(sum) && isNegative(preSum)) { // NNなら今のを足す
                    a[i] = a[i] + 1;
                    opeCount++;
                } else { // PN, NP ならiを増やして次へ
                    preSum = sum; // preSum作る
                    i++;
                }
            }
        }
    }
    return opeCount;
}

int main() {
    int n, ai;
    cin >> n;
    vector<int> a;
    for (int i = 0; i < n; ++i) {
        cin >> ai;
        a.push_back(ai);
    }
    int result = operation(a);
    cout << result << endl;
    return 0;
}

