using namespace std;

long foo(long first, const vector<long> &vec) {
  long current = 0;
  long limit = first;
  long ret = 0;
  for (auto num: vec) {
    current += num;
    if (limit == 1 and current < 1) {
      ret += limit - current;
      current = limit;
    } else if (limit == -1 and current > -1) {
      ret += current - limit;
      current = limit;
    }
    limit *= -1;
  }
  return ret;
}

void solve() {
  long n;
  cin >> n;
  vector<long> a(n);
  rep (i, n) cin >> a[i];
  cout << min(foo(-1, a), foo(1, a)) << endl;
}

