int main(){    
    int n;
    cin >> n;

    vector <long long> a(n);
    vector <long long> sum1(n), sum2(n);
    for (int i = 0; i < n; i++){
        cin >> a[i];
        if (i == 0){
            sum1[i] = a[i];
        }else{
            sum1[i] = sum1[i - 1] + a[i];
        }
        sum2[i] = sum1[i];
    }

    long long count1 = 0, count2 = 0;

    for (int i = 0; i < n; i++){
        if (i % 2 == 0){
            if (sum1[i] <= 0){
                long long add = 1 - sum1[i];
                count1 += add;
                for (int j = i + 1; j < n; j++){
                    sum1[j] += add;
                }
            }
        }else{
            if (sum1[i] >= 0){
                long long add = sum1[i] + 1;
                count1 += add;
                for (int j = i + 1; j < n; j++){
                    sum1[j] -= add;
                }
            }
        }   
    }

    for (int i = 0; i < n; i++){
        if (i % 2 == 0){
            if (sum2[i] >= 0){
                long long add = sum2[i] + 1;
                count2 += add;
                for (int j = i + 1; j < n; j++){
                    sum2[j] -= add;
                }
            }            
        }else{
            if (sum2[i] <= 0){
                long long add = 1 - sum2[i];
                count2 += add;
                for (int j = i + 1; j < n; j++){
                    sum2[j] += add;
                }
            }            
        }
    }    

    long long ans = min(count1, count2);

    cout << ans << endl;

    return 0;
}

