  for (int i = 0; i < a.size(); i++) {
    sum += a.at(i);
    sum2 += a.at(i);

    if (is_positive) {
      if (sum <= 0) {
        // 次は1になるまでインクリメント
        long long diff = 1 - sum;
        count += diff;
        sum += diff;
      }
      if (sum2 >= 0) {
        // 次は-1になるまでデクリメント
        long long diff = 1 + sum2;
        count2 += diff;
        sum2 -= diff;
      }
    } else {
      if (sum >= 0) {
        // 次は-1になるまでデクリメント
        long long diff = 1 + sum;
        count += diff;
        sum -= diff;
      }
      if (sum2 <= 0) {
        // 次は1になるまでインクリメント
        long long diff = 1 - sum2;
        count2 += diff;
        sum2 += diff;
      }
    }
    is_positive = ! is_positive;
  }
  cout << min(count, count2) << endl;

}

