            v[i + 1] += sum;
        sign *= -1;
    }
    sum = 0;
    int cnt2 = 0;
    sign *= v[0] / abs(v[0]) * -1;
    for (int i = 0; i < n; i++)
    {
        if (v[i] * sign >= 0)
        {
            int d = (sign > 0 ? (v[i] + 1) * -1 : (v[i] - 1) * -1);
            sum += d;
            cnt2 += abs(d);
        }
        if (i < n - 1)
            v[i + 1] += sum;
        sign *= -1;
    }
    cout << min(cnt1, cnt2) << "\n";
}

