ll calc(ll a[],int n)
{
    ll sum=a[0];
    ll res=0;
    for(int i=1;i<n;i++)
    {
        if(sum<0&&sum+a[i]<=0)
        {
            res+=1-sum-a[i];
            a[i]+=1-sum-a[i];
        }
        else if(sum>0&&sum+a[i]>=0)
        {
            res+=abs(a[i]-(-1-sum));
            a[i]=-1-sum;

        }
        sum+=a[i];
    }
    return res;
}

