vector<int> num;

long long sequence(int s1, int c1, int s2, int c2) {
  for (int i = 1; i < num.size(); i++) {
    if (s1 > 0) {
      if (s1 + num[i] >= 0) {
        c1 += 1 + num[i] + s1;
        s1 = -1;
      } else {
        s1 += num[i];
      }
    } else {
      if (s1 + num[i] <= 0) {
        c1 += 1 - num[i] - s1;
        s1 = 1;
      } else {
        s1 += num[i];
      }
    }
    if (s2 > 0) {
      if (s2 + num[i] >= 0) {
        c2 += 1 + num[i] + s2;
        s2 = -1;
      } else {
        s2 += num[i];
      }
    } else {
      if (s2 + num[i] <= 0) {
        c2 += 1 - num[i] - s2;
        s2 = 1;
      } else {
        s2 += num[i];
      }
    }
  }

  return min(c1, c2);
}

