// Body
void body() {
    auto n = read<i32>();
    auto as = read<i64>(n);

    auto solve = [](auto as) {
        i64 total = 0;
        u64 retval = 0;

        FORE (a, as) {
            if (total != 0 && total * (total + a) >= 0) {
                // total -> (total + a)で符号が変わらないまたは0になる
                retval += abs(total + a) + 1;
                a -= (total + a); // total + a = 0にする
                if (total > 0) {
                    a -= 1;
                } else {
                    a += 1;
                }
            }
            total += a;
        }
        return retval;
    };

    u64 retval = numeric_limits<u64>::max();
    if (as[0] >= 0) {
        // a_1を-1に
        auto as2 = as;
        as2[0] = -1;
        auto r = solve(as2) + abs(as[0]) + 1;
        retval = min(r, retval);
    }
    if (as[0] <= 0) {
        // a_1を1に
        auto as2 = as;
        as2[0] = 1;
        auto r = solve(as2) + abs(as[0]) + 1;
        retval = min(r, retval);
    }
    if (as[0] != 0) {
        auto r = solve(as);
        retval = min(r, retval);
    }

    cout << retval << endl;
}

// main function (DO NOT EDIT)
int main () {
    ios_base::sync_with_stdio(false);
    body();
    return 0;
}

