        if (i % 2 == 0) sm[0] += a[i];
        else
            sm[1] = a[i];
    }

    ll ans = 0;

    int plus  = (sm[0] >= sm[1]) ? 0 : 1;
    int minus = 1 - plus;
    rep(i, n) {
        bt.add(i+1,a[i]);
    }

    rep(i,n){
        ll rsum = bt.sum(i+1);
        if(i%2 == plus && rsum <= 0){
            bt.add(i+1,abs(rsum)+1);
            ans += abs(rsum)+1;
        } else if(i%2 == minus && rsum >= 0){
            bt.add(i+1,-1*abs(rsum)-1);
            ans += abs(rsum)+1;
        }
    }
    cout << ans << endl;
}

