    e[i] = e[i - 1] + a[i];
    o[i] = o[i - 1] + a[i];
    if (i % 2 == 0 && e[i] <= 0) {
      even += abs(e[i]) + 1;
      e[i] = 1;
    } else if (i % 2 != 0 && e[i] >= 0) {
      even += abs(e[i]) + 1;
      e[i] = -1;
    } else if (i % 2 != 0 && o[i] <= 0) {
      odd += abs(o[i]) + 1;
      o[i] = 1;
    } else if (i % 2 == 0 && o[i] >= 0) {
      odd += abs(o[i]) + 1;
      o[i] = -1;
    }
  }
  cout << min(even, odd) << endl;
}

