const int N = 1234567;

int n;
int a[N];

int solve(){
	int res = 0;
	int cur = 0;
	rep(i,0,n){
		cur += a[i];
		if(i%2 == 0){
			if(cur <= 0){
				res += (abs(cur) + 1);
				cur += res;
			}
			else{
				continue;
			}
		}
		else{
			if(cur >= 0){
				res += (abs(cur) + 1);
				cur -= res;
			}
			else{
				continue;
			}
		}
	}
	return res;
}

