using namespace std;

typedef vector < int > vi;

int getS(int val){
    if (val < 0) return -1;
    if (val > 0) return 1;
    return 0;
}

int minNum(vi &arr, int n, int sign){
    int acu =0, sol =0;
    for (int i= 0; i<n ; i++){
        acu += arr[i];
        if(getS(acu) != sign ){
            sol += abs(sign-acu);
            acu = sign;
        }
        sign = sign*-1;
    }
    return sol;
}

