            if(sumb*(sumb+B[i])>=0){
                if(sumb>0){
                    ansb+=abs(sumb*(-1)-1-B[i]);
                    sumb=-1;
                }else{
                    ansb+=abs(sumb*(-1)+1-B[i]);
                    sumb=1;
                }
            }else sumb+=B[i];
        }
        ans=min(ans,ansb);
    }
    cout<<ans<<endl;
}

