ll solve(vector<ll> As, bool flag) {
    ll ans = 0;
    for (auto A : As) {
        if (flag && A <= 0) ans += 1 - A;
        else if (!flag && A >= 0) ans += 1 + A;
        flag = !flag;
    }
    return ans;
}

