            a[i] = 1;
            cntA += abs(tmp_a) + 1LL;
        } else if (i % 2 == 1 && tmp_a >= 0) {
            a[i] = -1;
            cntA += abs(tmp_a) + 1LL;
        } else {
            a[i] = tmp_a;
        }
        long long tmp_b = b[i - 1] + v[i];
        if (i % 2 == 0 && tmp_b >= 0) {
            b[i] = -1;
            cntB += abs(tmp_b) + 1LL;
        } else if (i % 2 == 1 && tmp_b <= 0) {
            b[i] = 1;
            cntB += abs(tmp_b) + 1LL;
        } else {
            b[i] = tmp_b;
        }
    }
    cout << min(cntA, cntB) << endl;
}

