				ans +=((-soma)+1);
				soma = 1;
			}
		}else{

			if(soma == 0){
				ans++;
				soma--;
			}else if(soma > 0){

				ans += (soma +1);
				soma = -1;
			}
		}
		f = 1-f;
}
