int64_t Solve(std::vector<int64_t> a, int n, bool is_plus) {
  int64_t result = 0;
  int64_t cum    = 0;
  for (int i = 0; i < n; i++) {
    cum += a[i];
    if (is_plus) {
      if (cum >= 0) {
        result += cum + 1;
        cum     = -1;
        is_plus = false;
      } else {
        is_plus = false;
      }
    } else {
      if (cum > 0) {
        is_plus = true;
      } else {
        result += (-cum) + 1;
        cum     = 1;
        is_plus = true;
      }
    }
  }
  return result;
}

