int solve(std::vector<int> &v, bool positiveStart) {
  int sum = v[0];
  int count = 0;

  if (positiveStart && sum < 0) {
    count = 1 - sum;
    sum = 1;
  }
  if (!positiveStart && sum > 0) {
    count = sum - (-1);
    sum = -1;
  }
  for (int i = 1; i < v.size(); i++) {
    int tmp = sum + v[i];

    if (sum*tmp < 0) {
      sum = tmp;
      continue;
    }

    int next_sum = (-1) * sum / abs(sum);
    count += abs(next_sum-tmp);
    sum = next_sum;
  }
  return count;
}

