int main() {
    int n;
    cin >> n;
    vector<int> arr(n, 0);
    for(int& val: arr)
        cin >> val;
    // 1st term is positive
    ll tmp = 0, tmp2 = 0;
    ll acc = 0;
    for(int i = 0; i < n; i++) {
        acc += arr[i];
        if (i % 2 == 0) { // pos
            if (acc <= 0) {
                tmp += (1-acc);
                acc = 1;
            }
        } else { // neg
            if (acc >= 0) {
                tmp += acc - (-1);
                acc = -1;
            }
        }
    }
    // 1st term is negative
    acc = 0;
    for(int i = 0; i < n; i++) {
        acc += arr[i];
        if (i % 2 == 0) { // neg
            if (acc >= 0) {
                tmp2 += acc - (-1);
                acc = -1;
            }
        } else { // pos
            if (acc <= 0) {
                tmp2 += 1 - acc;
                acc = 1;
            }
        }
    }
    cout << min(tmp, tmp2) << endl;
    return 0;
}

