long func(const vector<int>& a)
{
    long res=0;
    long s=a[0];
    for(int i=1; i<a.size(); ++i) {
        if (s<0 and s+a[i]<=0) {
            res+=-(s+a[i])+1;
            s=1;
        }
        else if (s>0 and s+a[i]>=0) {
            res+=s+a[i]+1;
            s=-1;
        }
        else {
            s+=a[i];
        }
    }
    return res;
}

