#include <iostream>
#include <cstdlib>

using namespace std;

long long calcSum(int i, long long na[]) {
    long long sum = 0;
    for (int j = 0; j <= i; j++) {
        sum += na[j];
    }
    return sum;
}

long long check(int n, int s, long long a[]) {
    long long cnt = 0;
    long long na[n];

    for (int i = 0; i < n; i++) {
        na[i] = a[i];
        long long sum = calcSum(i, na);

        if (s == 0) {
            // 偶数番目のsumが負の場合
            if (i % 2 == 0 && sum <= 0) {
                // 変更する差分
                long long dx = 1 - sum;
                na[i] += dx;
                cnt += abs(dx);

            } else if (i % 2 != 0 && sum >= 0) {
                // 変更する差分
                long long dx = -1 - sum;
                na[i] += dx;
                cnt += abs(dx);
            }
        }

        if (s == 1) {
            // 奇数番目のsumが負の場合
            if (i % 2 != 0 && sum <= 0) {
                // 変更する差分
                long long dx = 1 - sum;
                na[i] += dx;
                cnt += abs(dx);

            } else if (i % 2 == 0 && sum >= 0) {
                // 変更する差分
                long long dx = -1 - sum;
                na[i] += dx;
                cnt += abs(dx);
            }
        }
    }

    return cnt;
}

int main()
{
    int n; cin >> n;
    long long a[100000];

    for (int i = 0; i < n; i++) cin >> a[i];

    cout <<min(check(n, 0, a), check(n, 1, a)) << endl;


    return 0;
}

