lint subfunc(lint n, std::vector<long long> a, bool isPlus){
    lint b[n]; // 結果を示す
    lint total = 0LL; // ここまでのa[i]の和
    lint resCount = 0LL; // 置き換えた数
    memset(b, 0, sizeof b);

    REP(i, n){
        total += a[i];
        b[i] = a[i];
        if (isPlus && total < 1) { // plusであるべきなのに，マイナスなら
            resCount += (-total) + 1;
            b[i] += (-total) + 1;
            total = 1;
        }
        else if(!isPlus && total > -1){
            resCount += (total) + 1;
            b[i] += (total) + 1;
            total = -1;
        }
        isPlus = !isPlus;
    }

    //cout << "res:"; REP(i, n) cout << " " << b[i]; cout << "\n";
    //cout << "cost:" <<resCount << "\n";
    return resCount;
}

