int calc_sum(int N, vector<int> a, int sum, int start) {
  int prev = start;
  for (int i=1; i<N; i++) {
    int curr = prev + a[i];
    dr_elem(prev); dr_elem(curr); dr_elem(a[i]) dr_end();
    if (prev < 0 && curr < 0) {
      sum += abs(curr) + 1;
      curr = 1;
    } else if (prev > 0 && curr > 0) {
      sum += abs(curr) + 1;
      curr = -1;
    } else if (prev > 0 && curr == 0) {
      curr -= 1;
      sum++;
    } else if (prev < 0 && curr == 0){
      curr += 1;
      sum++;
    }
    prev = curr;
  }
  return sum;
