		cin >> a[i];
	for (int i = 1; i < n; i++)
		a[i] = a[i - 1] + a[i];
	if (a[0] == 0) {
		long long bs, cs;
		long long *b = new long long[n];
		long long *c = new long long[n];
		for (int i = 0; i < n; i++) b[i] = a[i] + 1;
		for (int i = 0; i < n; i++) c[i] = a[i] - 1;
		bs = solve(b, n) + 1;
		cs = solve(c, n) + 1;
		ans = bs < cs ? bs : cs;
	}
	else ans = solve(a, n);
	cout << ans << endl;
	return 0;
}

