long long calc(long long *a, long long n)
{
	long long cnt = 0;
	int sign = 0;
	long long tmp;
	if (a[0] > 0)
	{
		sign = 1;
	}
	tmp = a[0];
	for (long long i = 0; i < n - 1; i++)
	{
		tmp = tmp + a[i + 1];
		if (sign == 1)
		{
			if (tmp >= 0)
			{
				cnt += tmp + 1;
				tmp = -1;
			}
		}
		else
		{
			if (tmp <= 0)
			{
				cnt += (-1 * tmp) + 1;
				tmp = 1;
			}
		}
		sign = get_sign(tmp);
	}
	return cnt;
}

int get_sign(long long tmp)
{
	if (tmp < 0) return 0;
	else return 1;
}

