int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};

const int MAX_N = int(1e5);
ll n, a[MAX_N], dp[MAX_N];

void solve() {
    ll sum_diff = 0, ans = 0;
    REP(i, n - 1) {
        ll diff = 0;
        dp[i + 1] += sum_diff;
        if (dp[i] * dp[i + 1] > 0) {
            if (dp[i + 1] > 0) {
                diff = -1 - dp[i + 1];
                sum_diff += diff;
                dp[i + 1] = -1;
            } else {
                diff = 1 - dp[i + 1];
                sum_diff += diff;
                dp[i + 1] = 1;
            }
        }
        if (dp[i + 1] == 0) {
            sum_diff++, diff = 1;
            dp[i + 1] = 1;
        }
        ans += abs(diff);
    }
    cout << ans << endl;
}

