#include <stdio.h>
#include <stdlib.h>

#define SIZE_NUM 100000
#define FLG_INIT 0
#define FLG_PLUS 1
#define FLG_MINUS -1


int main(void)
{
	/* 変数宣言 */
	int iNum[SIZE_NUM] = {0};	// 入力データ
	int iNumber = 0;			// 入力データ個数
	int iLoop;					// ループカウンタ
	int iSum = 0;				// 和
	int iFlg = FLG_INIT;		// プラスマイナスフラグ
	int iResult = 0;			// 操作回数

	/* データ読み込み */
	scanf("%d", &iNumber);

	for(iLoop = 0; iLoop < iNumber; iLoop++)
	{
		scanf("%d", &iNum[iLoop]);
	}

	/* 操作回数計算 */

	for(iLoop = 0; iLoop < iNumber; iLoop++)
	{
		/* 最初から0が続く場合だけ特別処理 */
		if(iFlg == FLG_INIT && iNum[iLoop] == 0)
		{
			if(iLoop == 0)
			{
				iResult++;
			}
			else
			{
				iResult += 2;
			}
			continue;
		}

		/* 和を算出 */
		iSum += iNum[iLoop];

		/* フラグが立ってない場合、フラグを立てて次のループへ */
		if(iFlg == FLG_INIT)
		{
			if(iNum[iLoop] > 0)
			{
				iFlg = FLG_PLUS;
			}
			else
			{
				iFlg = FLG_MINUS;
			}
			continue;
		}

		/* フラグ(1 or -1)と当該ループまでの和の符号確認 */
		/* 積の符号が同じまたは0だとだめ */
		if(iFlg * iSum >= 0)
		{
			iResult += abs(iSum) + 1;
			iSum = iFlg * -1;	// フラグと異なる符号の絶対値1の数
		}
		iFlg *= -1;			// フラグの符号を反転させる
	}

	/* 結果出力 */
	printf("%d\n", iResult);

	return 0;
}

