#define rep(i,n) for(int i = 0; i < n; i++)
#define MIN(a,b) ((a<b) ? a : b)

int main(void) {
  int n;
  scanf("%d", &n);

  int64_t a[100000];
  rep(i, n) {
    scanf("%ld", &a[i]);
  }

  //+ start
  int64_t P_ANS = 0;
  int64_t P_SUM = 0;
  rep(i, n) {
    P_SUM += a[i];
    if((i % 2) == 0) {// Even-Plus
      if(P_SUM <= 0) {
	P_ANS += (1 - P_SUM);
	P_SUM = 1;
      }
    } else {// Odd-Minus
      if(P_SUM >= 0) {
	P_ANS += (1 + P_SUM);
	P_SUM = -1;
      }
    }
  }

  //- start
  int64_t M_ANS = 0;
  int64_t M_SUM = 0;
  rep(i, n) {
    M_SUM += a[i];
    if((i % 2) == 1) {// Odd-Plus
      if(M_SUM <= 0) {
	M_ANS += (1 - M_SUM);
	M_SUM = 1;
      }
    } else {// Even-Minus
      if(M_SUM >= 0) {
	M_ANS += (1 + M_SUM);
	M_SUM = -1;
      }
    }
