#include <inttypes.h>

uint64_t solve(int32_t n, const int32_t* a) {
	int32_t i;
	uint64_t cost = 0;
	int64_t value = 0;
	int64_t target = 1;
	for (i = 0; i < n; i++) {
		value += a[i];
		if (value == 0 || (value > 0) != (target > 0)) {
			int64_t diff = value - target;
			if (diff < 0) diff = -diff;
			cost += diff;
			value = target;
		}
		target = -target;
	}
	return cost;
}

int main(void) {
	int32_t n;
	int32_t* a;
	int32_t i;
	uint64_t c1, c2;
	if (scanf("%" SCNd32, &n) != 1) return 1;
	a = malloc(sizeof(*a) * n);
	if (a == NULL) return 2;
	for (i = 0; i < n; i++) {
		if (scanf("%" PRId32, &a[i]) != 1) return 1;
	}
	c1 = solve(n, a);
	for (i = 0; i < n; i++) a[i] = -a[i];
	c2 = solve(n, a);
	printf("%" PRIu64 "\n", c1 <= c2 ? c1 : c2);
	free(a);
	return 0;
}

