// 最小回数の更新
int
fUpMin(
	int piSign					// <I> 符号 [1]＋ [-1]－
)
{
	int i;

	long long llCnt = 0;
	long long llSum = 0;

	for (i = 0; i < siACnt; i++) {

		// 符号の反転
		piSign *= -1;

		// 値の加算
		llSum += si1Array[i];

		// 符号のチェック
		if (llSum * (long long)piSign > 0) {	// OK
			continue;
		}

		// 回数加算
		llCnt += llabs(llSum) + (long long)1;

		// 合計値更新
		llSum = piSign;
	}

	// 最小回数更新
	if (llMin > llCnt) {
		llMin = llCnt;
	}

	return 0;
}

