long long sign(long long n){
	if (n>0)return 1;
	else if (n<0)return -1;
	return 0;
}

long long myabs(long long n){
	return (n>0)?n:(-n);
}

long long calc(long long *a,int n, long long bias,long long cost)
{
	int i;
	assert(a[0]!=0);
	long long sum = a[0];
	long long sum_eval_prev = sum + bias;
	for (i=1;i<n;i++){
		sum += a[i];
		long long sum_eval = sum + bias;
		if (sign(sum_eval_prev) == sign(sum_eval) || sign(sum_eval)==0){
			bias += -1*sign(sum_eval_prev) - sum_eval;
			cost += myabs(-1*sign(sum_eval_prev) - sum_eval);
			//printf("cost+=%lld\n",myabs(-1*sign(sum_eval_prev) - sum_eval));
		}
		//printf("%lld %lld %lld\n",sum_eval, -1*sign(sum_eval_prev) - sum_eval, cost);
		sum_eval_prev = sum + bias; // apply updated bias
	}
	return cost;
}

