	{
	    if (sum < 0)
	    {
		counter_even = counter_even + abs(sum) + 1;
		sum = 1;
	    }
	}
	else
	{
	    if (sum >= 0)
	    {
		counter_even = counter_even + abs(sum) + 1;
		sum = -1;
	    }
	}
    }
    if (0 == sum)
    {
	counter_even++;
    }

    // 奇数番目までの合計を正にする場合
    counter_odd = 0;
    sum = 0;
    for (int i = 0; i < n; i++)
    {
	sum += sequence[i];

	if (1 == (i + 1) % 2)	// 奇数番目？
	{
	    if (sum < 0)
	    {
		counter_odd = counter_odd + abs(sum) + 1;
		sum = 1;
	    }
	}
	else
	{
	    if (sum >= 0)
	    {
		counter_odd = counter_odd + abs(sum) + 1;
		sum = -1;
	    }
	}
    }
