static long long try(int sign, long long a[100000], int n)
{
	int i;
	long long t = 0, c = 0;
	for ( i = 0; i < n; i++ ){
		if ( sign < 0 ){
			if ( t+a[i] >= 0 ){
				c += t+a[i]+1;
				t = -1;
			} else {
				t += a[i];
			}
		} else {
			if ( t+a[i] <= 0 ){
				c += llabs(t+a[i]-1);
				t = 1;
			} else {
				t += a[i];
			}
		}
		sign *= -1;
	}
	return c;
}

