#include <stdio.h>

long long int count(long long int n){
    long long int a,i,S[2]={},C[2]={};
    for(i=0;i<n;i++){
        scanf("%lld",&a);
        S[0]+=a;
        S[1]+=a;
        if(i%2==0){
            if(S[0]>=0){
                C[0] += S[0] + 1;
                S[0] = -1;
            }
            if(S[1]<=0){
                C[1] += -1*S[1] + 1;
                S[1] = 1;
            }
        }
        else{
            if(S[0]<=0){
                C[0] += -1*S[0] + 1;
                S[0] = 1;
            }
            if(S[1]>=0){
                C[1] += S[1] + 1;
                S[1] = -1;
            }
        }
    }
    if(C[0]<C[1]) return C[0];
    else return C[1];
}

