// 和の符号のパターンはpos,neg,...かneg,pos,...のどちらかなので両方探索して小さいほうをとる

long long mysign(long long n){
	if (n>0)return 1;
	else if (n<0)return -1;
	return 0;
}

long long myabs(long long n){
	return (n>0)?n:(-n);
}

long long calc(long long *a,int n, long long cost, long long tgt_sgn)
{
	int i;
	long long sum = 0;
	long long bias = 0;
	for (i=0;i<n;i++){
		sum += a[i];
		long long sum_eval = sum + bias;
		if (tgt_sgn != mysign(sum_eval)){
			bias += tgt_sgn - sum_eval;
			cost += myabs(tgt_sgn - sum_eval);
		}
		tgt_sgn *= -1;
	}
	return cost;
}

