val MOD: Long = (1e+9 + 7).toLong()

fun solve(initialState: Boolean, aList: MutableList<Long>): Long {
	var numExecute = 0L 
	var sum = 0L 
	var isPlus = initialState
	aList.forEachIndexed { i, a ->
		val newA = if(isPlus && sum + a <= 0L) {
			val num = 1L - (sum + a)
			numExecute += num
			a + num
		} else if(!isPlus && sum + a >= 0L) {
			val num = sum + a + 1
			numExecute += num
			a-num	
		} else {
			a
		}
		isPlus = !isPlus
		aList[i] = newA
		sum += newA
	}
	return numExecute
}

