fun abc059c() {
    val n = readLine()!!.toInt()
    val aList = readLine()!!.split(" ").map { it.toLong() }.toTypedArray()

    // 偶数index目までの和の符号を正、奇数までを負とするパターン
    var changeCountEvenPositiveCase: Long = 0
    var sumEvenPositiveCase: Long = 0
    val aListEvenPositiveCase = aList.clone()
    for (i in 0 until n) {
        val it = aListEvenPositiveCase[i]
        sumEvenPositiveCase += it
        if (i % 2 == 0) {
            // 偶数index目なのでここまでの和の符号が正でない場合は、1まで加算
            if (sumEvenPositiveCase <= 0) {
                val addValue = Math.abs(sumEvenPositiveCase) + 1
                aListEvenPositiveCase[i] += addValue
                sumEvenPositiveCase += addValue
                changeCountEvenPositiveCase += addValue
            }
        } else {
            // 奇数index目なのでここまでの和の符号が負でない場合は、-1まで減算
            if (sumEvenPositiveCase >= 0) {
                val minusValue = Math.abs(sumEvenPositiveCase) + 1
                aListEvenPositiveCase[i] -= minusValue
                sumEvenPositiveCase -= minusValue
                changeCountEvenPositiveCase += minusValue
            }
        }
    }

    // 偶数index目までの和の符号を負、奇数までを正とするケース
    var changeCountOddPositiveCase: Long = 0
    var sumOddPositiveCase: Long = 0
    val aListOddPositiveCase = aList.clone()
    for (i in 0 until n) {
        val it = aListOddPositiveCase[i]
        sumOddPositiveCase += it
        if (i % 2 == 0) {
            // 偶数index目なのでここまでの和の符号が負でない場合は、-1まで減算
            if (sumOddPositiveCase >= 0) {
                val minusValue = Math.abs(sumOddPositiveCase) + 1
                aListOddPositiveCase[i] -= minusValue
                sumOddPositiveCase -= minusValue
                changeCountOddPositiveCase += minusValue
            }
        } else {
            // 奇数index目なのでここまでの和の符号が正でない場合は、1まで減算
            if (sumOddPositiveCase <= 0) {
                val addValue = Math.abs(sumOddPositiveCase) + 1
                aListOddPositiveCase[i] += addValue
                sumOddPositiveCase += addValue
                changeCountOddPositiveCase += addValue
            }
        }
    }

    println(Math.min(changeCountEvenPositiveCase, changeCountOddPositiveCase))
}

