fun getAnswer(a: List<Long>, initial: Boolean): Long {
    var answer = 0L
    var total = 0L
    var isPlus = initial
    for (x in a) {
        total += x

        if (isPlus) {
            if (total <= 0) {
                answer += -total + 1
                total = 1
            }
        } else {
            if (total >= 0) {
                answer += total + 1
                total = -1
            }
        }

        isPlus = !isPlus
    }

    return answer
}

