        when{
            dp[i - 1][1].second + a[i] > 0L -> {
                dp[i][0] = Pair(dp[i - 1][1].first, dp[i - 1][1].second + a[i])
            }
            dp[i - 1][1].second + a[i] == 0L -> {
                dp[i][0] = Pair(dp[i - 1][1].first + 1, 1)
