    IO io = new IO();

    /// ********** 本体 ********** ///

    void solve() {
        int n = io.Int();
        int[] a = new int[n];
        REP(n,integer -> a[integer]=io.Int());
        long cost1=0,cost2=0;
        long sum1=0,sum2=0;
        //sum is +-+...
        for(int i=0;i<n;++i){
            if(i%2==0){
                //sum is +
                sum1+=a[i];
                long addVal =
                        sum1<0?(-sum1)+1:
                        sum1==0?1:0;
                sum1+=addVal;
                cost1+=Math.abs(addVal);
            }else{
                //sum is -
                sum1+=a[i];
                long addVal =
                        sum1>0?(-sum1)-1:
                        sum1==0?-1:0;
                sum1+=addVal;
                cost1+=Math.abs(addVal);
            }
        }
        //sum is -+-...
        for(int i=0;i<n;++i){
            if(i%2!=0){
                //sum is +
                sum2+=a[i];
                long addVal =
                        sum2<0?(-sum2)+1:
                                sum2==0?1:0;
                sum2+=addVal;
                cost2+=Math.abs(addVal);
            }else{
                //sum is -
                sum2+=a[i];
                long addVal =
