			sums[i] = tempSum;
		}
		int result = 0;

		for(int i = 1; i < n; i++){
			boolean flag = check(sums) == false;
			if(flag){
				if(sums[i] * sums[i - 1] >= 0){
					if(sums[i - 1] > 0){
						result += Math.abs(-1 - sums[i]);
						int temp = (-1 - sums[i]);
						for(int j = i; j < n; j++){
							sums[j] += temp;
						}
						temp = 0;
					}
					else if(sums[i - 1] < 0){
						result += Math.abs(1 - sums[i]);
						int temp = (1 - sums[i]);
						for(int j = i; j < n; j++){
							sums[j] += temp;
						}
						temp = 0;
					}
				}
			}
			else{
				break;
			}
		}

		System.out.println(result);

