	public static boolean check(int[] sums){
		for(int i = 0; i < sums.length; i++){
			if(sums[i] == 0)
				return false;
			else if(i >= 1 && sums[i] * sums[i - 1] >= 0)
				return false;
		}
		return true;
	}
