				if(a_sum[i]<0){
					cnt1 += (-a_sum[i]) + 1;
					a_sum[i] = 1;
				}else if(a_sum[i]==0){
					cnt1 += 1;
					a_sum[i] = 1;
				}
			}else if(i%2==1){
				if(a_sum[i]>0){
					cnt2 -= a_sum[i] + 1;
					a_sum[i] = -1;
				}else if(a_sum[i]==0){
					cnt2 -= 1;
					a_sum[i] = -1;
				}
			}
		}

		//奇数番目までの和を負に、偶数番目までの和を正にする
