public class Main {
	public static void main(String[] args) throws IOException{
		Sequence solver = new Sequence();
		solver.readInput();
		solver.solve();
		solver.writeOutput();
	}


	static class Sequence {
		private int n;
		private int a[];

		private int output;
		private Scanner scanner;

		public Sequence() {
			this.scanner = new Scanner(System.in);
		}

		public void readInput() {
			n = Integer.parseInt(scanner.next());
			a = new int[n];
			for(int i=0; i<n; i++) {
				a[i] = Integer.parseInt(scanner.next());
			}
		}

		private int count(boolean sign) {
			int count=0;
			long sum=0;
			for(int i=0; i<n; i++) {
				sum += a[i];
				if((i%2==0) == sign) {
					// a[i]までの合計を正にするとき
					if(sum<=0) {
						count += Math.abs(sum)+1;
						sum = 1;
					}
				} else if((i%2==0) != sign){
					// a[i]までの合計を負にするとき
					if(0<=sum) {
						count += Math.abs(sum)+1;
						sum = -1;
					}
				}
			}
			return count;
		}

		public void solve() {
			output = Math.min(count(true), count(false));
		}

		public void writeOutput() {
			System.out.println(output);
		}
	}

}

import java.util.Scanner;

public class Main {

	public static double sequence(int a[], double start) {
		double count = 0.0, presum = -1.0 * start, sum = 0.0;

		for(int i = 0; i < a.length; ++i) {
			sum += (double)a[i];
			if(i == 0)sum = start;
			if(sum * presum > 0) {
				double min = Math.abs(sum) + 1;
				if(presum > 0)sum -= min;
				else sum += min;
				count += min;
			}

			if(sum == 0) {
				if(presum > 0)sum--;
				else sum++;
				++count;
			}

			presum = sum;
		}

		return count;
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n, a[];
		double count = 0.0, tmp2 = 0.0, tmp3 = 0.0;

		n = sc.nextInt();
		a = new int[n];

		for(int i = 0; i < n; ++i) a[i] = sc.nextInt();

		sc.close();


		if(a[0] == 0) {
			a[0]++;
			++tmp3;
		}

		int tmp = Math.abs(a[0]) + 1;

		if(a[0] > 0) {
			tmp2 = tmp + tmp3;
			tmp = a[0] - tmp;
		}
		else { 
			tmp2 = tmp + tmp3;
			tmp = a[0] + tmp;
		}

		count = Math.min((tmp3 + sequence(a, (double)a[0])),(tmp2 + sequence(a, (double)tmp)));

		System.out.printf("%.0f\n", count);
	}

}

