			a[i] = sc.nextLong();
		}

		long sum = a[0];
		long x = 0;

		if(a[0] == 0) {
			if(a[1] >= 0) {
				sum = -1;
				x++;
			} else {
				sum = 1;
				x++;
			}
		}

		long count = 0;

