  }

  private static long solve(boolean evenPlus, int[] a) {

    long ans = 0;
    long sum = 0;
    for (int i = 0; i < a.length; i++) {
      sum += a[i];
      if (((evenPlus && i%2 == 0)
          || (!evenPlus && i%2 == 1))
          && sum <= 0) {
        long diff = 1 - sum;
        sum += diff;
        ans += diff;
      } else if (((evenPlus && i%2 == 1)
                  || (!evenPlus && i%2 == 0))
                  && sum >= 0) {
        long diff = sum + 1;
        sum -= diff;
        ans += diff;
      }
    }
    return ans;
  }
}

