import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
	private static final int MOD = (int)Math.pow(10, 9);
	public static void main(String[] args) {
		FastReader sc = new FastReader();
		int n = sc.nextInt();
		int[] nums = new int[n];

		for (int i = 0; i < nums.length; i++) {
			nums[i] = sc.nextInt();
		}
		long firstDigitPostive = 0;

		long prefixSum = 0;
		for (int i = 0; i < nums.length; i++) {
			prefixSum += nums[i];
			if (i % 2 == 0) {
				// odd is postive
				if (prefixSum == 0) {
					prefixSum--;
					firstDigitPostive++;
				} else if (prefixSum < 0) {
					firstDigitPostive += (1 - prefixSum);
					prefixSum += 1 - prefixSum;
				}
			} else {
				// even is negative
				if (prefixSum == 0) {
					prefixSum++;
				} else if (prefixSum > 0) {
					firstDigitPostive += (1 + prefixSum);
					prefixSum -= (prefixSum + 1) ;
				}
			}
		}

		prefixSum = 0;
		long firstDigitNegative = 0;
		for (int i = 0; i < nums.length; i++) {
			prefixSum += nums[i];
			if (i % 2 == 0) {
				// odd is negative
				if (prefixSum == 0) {
					prefixSum++;
				} else if (prefixSum > 0) {
					firstDigitNegative += (1 + prefixSum);
					prefixSum -= (prefixSum + 1) ;
				}
			} else {
				// even is postive
				if (prefixSum == 0) {
					prefixSum--;
					firstDigitNegative++;
				} else if (prefixSum < 0) {
					firstDigitNegative += (1 - prefixSum);
					prefixSum += 1 - prefixSum;
				}
			}
		}

		System.out.println(Math.min(firstDigitPostive, firstDigitNegative));
	}

    static class FastReader {
	    BufferedReader br;
	    StringTokenizer st;

	    public FastReader() {
	      br = new BufferedReader(new InputStreamReader(System.in));
	    }

	    String next() { 
	      while (st == null || !st.hasMoreElements()) {
	        try {
	          st = new StringTokenizer(br.readLine());
	        } catch (IOException  e) {
	          e.printStackTrace();
	        }
	      }
	      return st.nextToken();
	    }

	    int nextInt() {
	      return Integer.parseInt(next());
	    }

	    long nextLong() {
	      return Long.parseLong(next());
	    }

	    double nextDouble() { 
	      return Double.parseDouble(next());
	    }

	    String nextLine() {
	      String str = "";
	        try{
	            str = br.readLine();
	        } catch (IOException e) {
	            e.printStackTrace();
	        }
	        return str;
	      }
	  }
}

import java.util.Scanner;

class Main {
	int n;
	int[] a;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		Main m = new Main(sc);
		m.solve();
		sc.close();
	}

	Main(Scanner sc) {
		n = sc.nextInt();
		a = new int[n];
		for(int i=0;i<n;i++){
			a[i] = sc.nextInt();
		}
	}

	void solve() {
		int sign = (a[0]>=0)?1:-1;
		long cnt = (a[0]==0)?1:0;
		long sum = (a[0]==0)?1:a[0];
		for(int i=1;i<n;i++){
			sum += a[i];
			if(sum*sign>=0){
				cnt += Math.abs(sum) + 1;
				sum = -sign;
			}
			sign *= -1;
		}
		System.out.println(cnt);
	}
}

import java.util.Scanner;
import java.util.Arrays;

public class Main{
  static int n;
  static long[] a;

  static final boolean DEBUG = false;

  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);

    n = sc.nextInt();
    a = new long[n];
    for(int i = 0; i < n; i++){
      a[i] = sc.nextInt();
    }

    long count = 0, count2 = 0;
    long sum = a[0];
    long sum2 = a[0] < 0 ? 1 : -1;
    count2 = Math.abs(sum2 - a[0]);

    if(a[0] == 0){
      sum = 1;
      count = count2 = 1;
      sum2 = -1;
    }

    for(int i = 1; i < n; i++){
      long val = a[i], val2 = a[i];
      if(!((sum > 0 && sum + a[i] < 0) || 
            (sum < 0 && sum + a[i] > 0))){
        val = -sum + ((sum < 0) ? 1 : -1);
        count += Math.abs(val - a[i]);
      }
      if(!((sum2 > 0 && sum2 + a[i] < 0) || 
            (sum2 < 0 && sum2 + a[i] > 0))){
        val2 = -sum2 + ((sum2 < 0) ? 1 : -1);
        count2 += Math.abs(val2 - a[i]);
      }
      sum += val;
      sum2 += val2;
    }

    if(DEBUG){
      System.out.println(Arrays.toString(a));
    }

    System.out.println(Math.min(count, count2));
  }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();
		List<Long> alist = new ArrayList<>();
		for (int i = 0; i < n; i++) {
			alist.add(sc.nextLong());
		}

		long cntOdd = 0;
		long cntEvn = 0;
		long sum = 0;

		for (int i = 0; i < n; i++) {

			sum += alist.get(i);

			//iが偶数のとき正
			if(i%2 == 0) {
				if(sum > 0) {
					continue;
				} else {
					long diff = 1-sum;
					cntEvn += 1-sum;
					sum += diff;
				}
			} else {
				if(sum < 0) {
					continue;
				} else {
					long diff = 1+sum;
					cntEvn += 1+sum;
					sum -= diff;
				}
			}
		}

		sum =0;

		for (int i = 0; i < n; i++) {

			sum += alist.get(i);

			//iが偶数のとき負
			if (i%2 == 0) {
				if(sum < 0) {
					continue;
				} else {
					long diff = 1+sum;
					cntOdd += 1+sum;
					sum -= diff;
				}
			} else {
				if(sum > 0) {
					continue;
				} else {
					long diff = 1-sum;
					cntOdd += 1-sum;
					sum += diff;
				}
			}
		}
		if(cntOdd <= cntEvn) {
			System.out.println(cntOdd);
		} else {
			System.out.println(cntEvn);
		}
	}
}

