			alist.add(sc.nextInt());
		}

		int cntOdd = 0;
		int cntEvn = 0;
		int sum = 0;

		for (int i = 0; i < alist.size(); i++) {

			sum += alist.get(i);

			if(i%2 != 0) {
				if(sum >= 0) {
					while(sum >= 0) {
						sum--;
						cntOdd++;
					}
				} else {
					continue;
				}
			} else {
				if(sum <= 0) {
					while(sum <= 0) {
						sum++;
						cntOdd++;
					}
				} else {
					continue;
				}
			}
		}

		sum = 0;

		for (int i = 0; i < alist.size(); i++) {

			sum += alist.get(i);

			if (i%2 != 0) {
				if(sum <= 0) {
					while(sum <= 0) {
						sum ++;
						cntEvn++;
					}
				} else {
				continue;
				}
			} else {
				if(sum >= 0) {
					while(sum >= 0) {
						sum --;
						cntEvn++;
					}
				} else {
					continue;
				}
			}
		}
