		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();
		long[] a = new long[n];
		long[] ac = new long[n];

		for (int i = 0; i < n; i++) {
			a[i] = sc.nextLong();
		}

		long answer = Long.MAX_VALUE;
		for (int i = 0; i < 2; i++) {
			long t = 0;
			ac[0] = a[0];

			for (int j = 0; j < n; j++) {
				if ((i + j) % 2 == 0) {
					if (ac[j] >= 0) {
						t += ac[j] + 1;
						ac[j] = -1;
					}
				} else {
					if (ac[j] <= 0) {
						t += Math.abs(ac[j]) + 1;
						ac[j] = 1;
					}
				}
				if (j < n - 1) ac[j + 1] = ac[j] + a[j + 1];
			}

			answer = Math.min(answer, t);
		}

		System.out.println(answer);
	}
}

import java.io.IOException;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) throws IOException{
		Sequence solver = new Sequence();
		solver.readInput();
		solver.solve();
		solver.writeOutput();
	}


	static class Sequence {
		private int n;
		private int a[];

		private int output;
		private Scanner scanner;

		public Sequence() {
			this.scanner = new Scanner(System.in);
		}

		public void readInput() {
			n = Integer.parseInt(scanner.next());
			a = new int[n];
			for(int i=0; i<n; i++) {
				a[i] = Integer.parseInt(scanner.next());
			}
		}

		private int count(boolean sign) {
			int count=0;
			long sum=0;
			for(int i=0; i<n; i++) {
				sum += a[i];
				if((i%2==0) == sign) {
					// a[i]までの合計を正にするとき
					if(sum<=0) {
						count += Math.abs(sum)+1;
						sum = 1;
					}
				} else {
					// a[i]までの合計を負にするとき
					if(0<=sum) {
						count += Math.abs(sum)+1;
						sum = -1;
					}
				}
			}
			return count;
		}



		public void solve() {
			output = Math.min(this.count(true), this.count(false));
		}

		public void writeOutput() {
			System.out.println(output);
		}
	}

}

