import java.util.Arrays;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int[] a = new int[n];
		long[] s1 = new long[n];

		for (int i = 0; i < n; i++) {
			a[i] = sc.nextInt();
		}

		long sum1 = 0;
		s1[0] = a[0];
		// - + - + となる場合
		while (s1[0] >= 0) {
			s1[0]--;
			sum1++;
		}
		for (int i = 1; i < n; i++) {
			s1[i] = s1[i-1] + a[i];
			// iが奇数の場合は正にする
			if (i % 2 != 0) {
				if (s1[i-1]*s1[i] >= 0) {
					sum1 = sum1 + 1 - s1[i];
					s1[i] = 1;
				}
			}
			// iが偶数の場合は負にする
			else {
				if (s1[i-1]*s1[i] >= 0) {
					sum1 = sum1 + 1 + s1[i];
					s1[i] = -1;
				}
			}
		}

		Arrays.fill(s1, 0);
		long sum2 = 0;
		s1[0] = a[0];
		// + - + - となる場合
		while (s1[0] <= 0) {
			s1[0]++;
			sum2++;
		}
		for (int i = 1; i < n; i++) {
			s1[i] = s1[i-1] + a[i];
			// iが奇数の場合は負にする
			if (i % 2 != 0) {
				if (s1[i-1]*s1[i] >= 0) {
					sum2 = sum2 + 1 + s1[i];
					s1[i] = -1;
				}
			}
			// iが偶数の場合は正にする
			else {
				if (s1[i-1]*s1[i] >= 0) {
					sum2 = sum2 + 1 - s1[i];
					s1[i] = 1;
				}
			}
		}

		System.out.println(Math.min(sum1, sum2));
	}

}

import java.util.Scanner;

class Main {
	int n;
	int[] a;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		Main m = new Main(sc);
		m.solve();
		sc.close();
	}

	Main(Scanner sc) {
		n = sc.nextInt();
		a = new int[n];
		for(int i=0;i<n;i++){
			a[i] = sc.nextInt();
		}
	}

	void solve() {
		long cnt1 = (a[0]>0)?0:(Math.abs(a[0])+1);
		int sign = 1;
		long sum = (a[0]>0)?a[0]:1;
		for(int i=1;i<n;i++){
			sum += a[i];
			if(sum*sign>=0){
				cnt1 += Math.abs(sum) + 1;
				sum = -sign;
			}
			sign *= -1;
		}

		long cnt2 = (a[0]<0)?0:(Math.abs(a[0])+1);
		sign = -1;
		sum = (a[0]<0)?a[0]:-1;
		for(int i=1;i<n;i++){
			sum += a[i];
			if(sum*sign>=0){
				cnt2 += Math.abs(sum) + 1;
				sum = -sign;
			}
			sign *= -1;
		}

		System.out.println(Math.min(cnt1, cnt2));
	}
}

import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner((System.in));
		int N = sc.nextInt();
		int[] n = new int[N + 1];

		// 入力値を設定
		for (int i = 0; i < N; i++) {
			n[i] = sc.nextInt();
		}

		int s = n[0];
		int m = 0;
		for (int i = 1; i <= N; i++) {
			while (Math.signum(s) != Math.pow(-1, i % 2)) {
				if (Math.pow(-1, i % 2) > 0) {
					s++;
				} else {
					s--;
				}
				m++;
			}
			s += n[i];
		}

		s = n[0];
		int p = 0;
		for (int i = 1; i <= N; i++) {
			while (Math.signum(s) != Math.pow(-1, (i + 1) % 2)) {
				if (Math.pow(-1, (i + 1) % 2) > 0) {
					s++;
				} else {
					s--;
				}
				p++;
			}
			s += n[i];
		}

		if (m > p) {
			System.out.print(p);
		} else {
			System.out.print(m);
		}

		sc.close();
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;


public class Main {
    public static void main(String[] args) {
        try {
            BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
            int n = Integer.parseInt(br.readLine());
            String[] inputString = br.readLine().split(" ");
            long[] input = new long[n];
            for(int i = 0 ; i < n ; i++) {
                input[i] = Integer.parseInt(inputString[i]);
            }
            long result = -1, keyValue = result;
            while(keyValue == -1){
            	keyValue = result;
            	result = 0;
            	long count = 0;
            	for(int i = 0 ; i < n ; i++){
            		if(i % 2 == 0 && (count + input[i]) * Math.signum(keyValue) >= 0){
            			result += Math.abs(count + input[i]) + 1;
            			count = (int)Math.signum(keyValue) * -1;
            		}else if(i % 2 != 0 && (count + input[i]) * Math.signum(keyValue) <= 0){
            			result += Math.abs(count + input[i]) + 1;
            			count = (int)Math.signum(keyValue);
            		}else{
            			count += input[i];
            		}
            	}
            	result = (keyValue != -1)? Math.min(result, keyValue): result;
            }
            System.out.println(result);
        } catch (Exception e) {
        	e.printStackTrace();
        }
    }

}

