			long[] wa = new long[N + 1];
			long[] wa2 = new long[N + 1];
			for (int i = 1; i <= N; i++) {
				wa[i] += wa[i - 1] + A[i - 1];
				wa2[i] += wa2[i - 1] + A[i - 1];
			}
			//out.println("A:" + Arrays.toString(A));
			//out.println("W:" + Arrays.toString(wa));

			boolean plus = wa[1] >= 0 ? true : false;
			long cntp = 0;
			long cntm = 0;

			for (int i = 1; i <= N; i++) {
				wa[i] += cntp - cntm;
				if (!plus && wa[i] >= 0) {
					long p = Math.abs(wa[i]) + 1;
					cntm += p;
					wa[i] -= p;
					A[i - 1] -= p;
				} else if (plus && wa[i] <= 0) {
					long m = Math.abs(wa[i]) + 1;
					cntp += m;
					wa[i] += m;
					A[i - 1] += m;
				}
				plus = !plus;
			}

			long ans = cntp + cntm;
			//out.println("W:" + Arrays.toString(wa));

			//out.println("WM:" + Arrays.toString(wa2));
			boolean minus = wa2[1] <= 0 ? true : false;
			long cntps = 0;
			long cntms = 0;

			for (int i = 1; i <= N; i++) {
				wa2[i] += cntps - cntms;
				if (!minus && wa2[i] <= 0) {
					long p = Math.abs(wa2[i]) + 1;
					cntps += p;
					wa2[i] += p;
					A[i - 1] += p;
				} else if (minus && wa2[i] >= 0) {
					long m = Math.abs(wa2[i]) + 1;
					cntms += m;
					wa2[i] -= m;
					A[i - 1] -= m;
				}
				minus = !minus;
			}

			ans = Math.min(ans, cntps + cntms);

			//out.println("A:" + Arrays.toString(A));
			//out.println("WM:" + Arrays.toString(wa2));

			out.println(ans);

		} catch (ArithmeticException ae) {
			//ae.printStackTrace();
			throw new RuntimeException();
		} catch (Exception e) {
			e.printStackTrace();
			throw new RuntimeException();
		} finally {
			out.flush();
			out.close();
		}

	}

	// 高速なScanner
	static class InputReader {
		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;

		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}
}

