    static long count;
    static  long sum;
    public static void main(String[] args) throws IOException{
        MyReader r = new MyReader();
        n = r.i();
        a = r.ll();
        sum = a[0];
        count = 0;
        if(a[0] == 0){
            count = 1;
            sum = 1;
            solve();
            long temp = count;
            count = 1;
            sum = -1;
            solve();
            count = Math.min(count, temp);
        } else {
            solve();
            long temp = count;
            sum = -a[1]-1;
            count = Math.abs(a[0]+a[1]+1);
            solve();
            temp = Math.min(temp, count);
            sum = -a[1]+1;
