import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Main {
    public static void main(final String[] args) {
        final Scanner scanner = new Scanner(System.in);
        final int n = scanner.nextInt();
        final List<Long> list = IntStream.range(0, n)
                .mapToObj(i -> scanner.nextLong())
                .collect(Collectors.toList());

        final long answer;
        if (list.get(0) != 0) {
            answer = sum(list.get(0), 0, list);
        } else {
            answer = Math.min(sum(1, 1, list), sum(-1, 1, list));
        }

        System.out.println(answer);
    }

    private static long sum(final long firstValue, final long firstCost, final List<Long> list) {
        long sum1 = firstValue, sum2 = firstValue;
        long cost1 = firstCost, cost2 = firstCost;
        long sign1 = 1, sign2 = -1;
        for (int i = 1; i < list.size(); i++) {
            final long a = list.get(i);
            sum1 += a;
            sum2 += a;

            if (sign1 == 1 && sum1 < 1) {
                cost1 += 1 - sum1;
                sum1 = 1;
            } else if (sign1 == -1 && sum1 > -1) {
                cost1 += sum1 + 1;
                sum1 = -1;
            }

            if (sign2 == 1 && sum2 < 1) {
                cost2 += 1 - sum2;
                sum2 = 1;
            } else if (sign2 == -1 && sum2 > -1) {
                cost2 += sum2 + 1;
                sum2 = -1;
            }

            sign1 *= -1;
            sign2 *= -1;
        }

        return Math.min(cost1, cost2);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        long a[] = new long[n];

        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
        }

        long odd = f(a, n, 1);
        long even = f(a, n, -1);

        System.out.println(Math.min(odd, even));
    }

    static long f(long a[], int n, int sign) {
        long total = 0;
        long man = 0;
        for (int i = 0; i < n; i++) {
            total += a[i];
            if (total * sign <= 0) {
                long x = Math.abs(total) + 1;
                total += sign * x;
                man += x;
            }
            sign = -sign;
        }
        return man;
    }
}

import java.util.Arrays;
import java.util.Scanner;
import java.util.stream.IntStream;

public class Main {

	public static void main(String[] args) {
		try (Scanner scanner = new Scanner(System.in)) {
			int n = scanner.nextInt();
			int[] a = new int[n];
			IntStream.range(0, n).forEach(i -> a[i] = scanner.nextInt());
			// sum1=[1,-1,...], sum2=[-1,1,...]
			int[] sum1 = new int[n], sum2 = new int[n];
			Arrays.fill(sum1, 1);
			Arrays.fill(sum2, -1);
			IntStream.range(0, n / 2).forEach(i -> {
				sum1[2 * i + 1] = -1;
				sum2[2 * i + 1] = 1;
			});
			System.out.println(Math.min(getResult(a, sum1), getResult(a, sum2)));
		}
	}

	/**
	 * @param a   数値配列
	 * @param sum 変更したい合計値の配列
	 * @return 変更すべきステップ数
	 */
	private static int getResult(final int[] a, final int[] sum) {
		int n = a.length, now = 0, result = 0;
		for (int i = 0; i < n; i++) {
			now += a[i];
			if (sum[i] * now <= 0) {
				result += Math.abs(sum[i] - now);
				now = sum[i];
			}
		}
		return result;
	}
}

