import java.util.Scanner;

public class Main {

    static long ANS_POSI;
    static long ANS_NEGA;
    static int N;

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);
        N = Integer.parseInt(sc.nextLine());

        long[] a = new long[N];
        for (int i = 0; i < N; i++) {
            long elm = Long.parseLong(sc.next());
            a[i] = elm;
        }

        solve(a);

        System.out.println(Math.min(ANS_POSI, ANS_NEGA));
    }


    private static void solve(long[] a) {
        long posi = 0;
        long nega = 0;
        for (int i = 0; i < N; i++) {
            // 前回のループで変更があった場合は、1か-1になっている値に配列値を合算して合計値としている。
            posi += a[i];
            nega += a[i];
            if (i % 2 == 0) {
                if (posi >= 0) {
                    ANS_POSI += posi + 1;
                    posi = -1;
                }
                if (nega <= 0) {
                    ANS_NEGA -= nega - 1;
                    nega = 1;
                }
            } else {
                if (posi <= 0) {
                    ANS_POSI -= posi - 1;
                    posi = 1;
                }
                if (nega >= 0) {
                    ANS_NEGA += nega + 1;
                    nega = -1;
                }
            }
        }
    }
}

import java.util.Scanner;

public class Main {

	public static double sequence(int a[], double start) {
		double count = 0.0, presum = start, sum = start;

		for(int i = 1; i < a.length; ++i) {
			sum += (double)a[i];
			if(sum * presum > 0) {
				double min = Math.abs(sum) + 1;
				if(presum > 0)sum -= min;
				else sum += min;
				count += min;
			}

			if(sum == 0) {
				if(presum > 0)sum--;
				else sum++;
				++count;
			}

			presum = sum;
		}

		return count;
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n, a[];
		double count = 0.0, tmp2 = 0.0, tmp3 = 0.0;

		n = sc.nextInt();
		a = new int[n];

		for(int i = 0; i < n; ++i) a[i] = sc.nextInt();

		sc.close();


		if(a[0] == 0) {
			a[0]++;
			++tmp3;
		}

		int tmp = Math.abs(a[0]) + 1;

		if(a[0] > 0) {
			tmp2 = tmp - tmp3;
			tmp = a[0] - tmp;
		}
		else { 
			tmp2 = tmp + tmp3;
			tmp = a[0] + tmp;
		}

		count = Math.min((tmp3 + sequence(a, (double)a[0])),(tmp2 + sequence(a, (double)tmp)));

		System.out.printf("%.0f\n", count);
	}

}

