        if (0 <= sum1) {
          count1 += (sum1 + 1);
          sum1 = -1;
        }
      }

    }

    // -+-+_...の場合
    long sum2 = a[0];
    long count2 = 0;

    for (int i = 1; i < n; i++) {

      sum2 += a[i];

      if (i % 2 == 0) {
        if (0 <= sum2) {
          count2 += (sum2 + 1);
          sum2 = -1;
        }
      } else {
        if (sum2 <= 0) {
          count2 += (1 - sum2);
          sum2 = 1;
        }
      }

    }

