	public void run() {
		try {
			int N = sc.nextInt();
			long[] A = new long[N];
			for (int i = 0; i < N; i++) {
				A[i] = sc.nextLong();
			}

			long[] wa = new long[N + 1];
			for (int i = 1; i <= N; i++) {
				wa[i] += wa[i - 1] + A[i - 1];
			}
			//out.println("A:" + Arrays.toString(A));
			//out.println("W:" + Arrays.toString(wa));

			boolean plus = wa[1] >= 0 ? true : false;
			long cntp = 0;
			long cntm = 0;

			for (int i = 1; i <= N; i++) {
				wa[i] += cntp - cntm;
				if (!plus && wa[i] >= 0) {
					long p = Math.abs(wa[i]) + 1;
					cntm += p;
					wa[i] -= p;
					A[i - 1] -= p;
				} else if (plus && wa[i] <= 0) {
					long m = Math.abs(wa[i]) + 1;
					cntp += m;
					wa[i] += m;
					A[i - 1] += m;
				}
				plus = !plus;
			}
			//out.println("A:" + Arrays.toString(A));
			//out.println("W:" + Arrays.toString(wa));

			out.println(cntp + cntm);

		} catch (ArithmeticException ae) {
