		int m = 0;
		for (int i = 1; i <= N; i++) {
			while (Math.signum(s) != Math.pow(-1, i % 2)) {
				if (Math.pow(-1, i % 2) > 0) {
					s++;
				} else {
					s--;
				}
				m++;
			}
			s += n[i];
		}
