		List<Long> alist = new ArrayList<>();
		for (int i = 0; i < n; i++) {
			alist.add(sc.nextLong());
		}

		int cntOdd = 0;
		int cntEvn = 0;
		long sum = 0;

		for (int i = 0; i < alist.size(); i++) {

			sum += alist.get(i);

			//iが偶数のとき正
			if(i%2 == 0) {
				if(sum > 0) {
					continue;
				} else {
					long diff = 1-sum;
					cntEvn += 1-sum;
					sum += diff;
				}
			} else {
				if(sum < 0) {
					continue;
				} else {
					long diff = 1+sum;
					cntEvn += 1+sum;
					sum -= diff;
				}
			}
		}

		sum =0;

		for (int i = 0; i < alist.size(); i++) {

			sum += alist.get(i);

			//iが偶数のとき負
			if (i%2 == 0) {
				if(sum < 0) {
					continue;
				} else {
					long diff = 1+sum;
					cntOdd += 1+sum;
					sum -= diff;
				}
			} else {
				if(sum > 0) {
					continue;
				} else {
					long diff = 1-sum;
					cntOdd += 1-sum;
					sum += diff;
				}
			}
