            if((i+1) % 2 == 0){
                if(sum[i+1] <= 0){
                    count += 1 - sum[i+1];
                    sum[i+1] = 1;
                }
            }
        }
        return count;
    }
    public static int solve2(int[] sum,int[] a,int count){
        if(sum[0] >= 0){
            count += 1 + sum[0];
            sum[0] = -1;
        }
        for(int i = 0;i < sum.length-1;i++){
            sum[i+1] = sum[i] + a[i+1];
            if((i+1) % 2 == 1){
