	public static double sequence(int a[], double start) {
		double count = 0.0, presum = -1.0 * start, sum = 0.0;

		for(int i : a) {
			sum += (double)i;
			if(i == 0)sum += start;
			if(sum * presum > 0) {
				double min = Math.abs(sum) + 1;
				if(presum > 0)sum -= min;
				else sum += min;
				count += min;
			}

			if(sum == 0) {
				if(presum > 0)sum--;
				else sum++;
				++count;
			}

			presum = sum;
		}

		return count;
	}

