						cnt_M += (-sum_M + 1);
						sum_M = 1;
					}
				}
			}
        	cnt_P += (sum_P == 0 ? 1 : 0);
        	cnt_M += (sum_M == 0 ? 1 : 0);
        	prn(Math.min(cnt_P, cnt_M));
        }
