	private static long count(int n, int []a, int pat) {

		long count = 0;
		long sum = 0;
		sum += a[0];

		int temp = (int)Math.pow(-1, 1+pat);

		if(sum == 0) {
			count++;
			sum = temp ;
		}

		for(int i = 1 ; i < n ; i++) {
			sum += a[i];
			temp *= -1;
			if(temp * sum <= 0) {
				count += Math.abs(sum) + 1 ;
				sum = temp;
			}

		}

		return count;
	}
}

