    private static int count(int n , boolean pastPlus, int[] sum, long carry){
        int count2 = 0;
        for (int i = 1; i <= n; i++) {
            long cur = sum[i] + carry;

            if (pastPlus && cur >= 0) {
                // minus nisinaito
                count2 += cur + 1;
                carry = - cur - 1;
            }
            if (!pastPlus && cur <= 0) {
                count2 += -cur + 1;
                carry = -cur + 1;
            }

            pastPlus = !pastPlus;
        }

        return count2;
    }
