		sign = -1;
		sum = 0;
		for(int i = 0; i < n; i++) {
			sum += a[i];
			if(sum * sign <= 0) {
				c2 += Math.abs(sum) + 1;
				sum = sign;
			}
			sign *= -1;
		}
		System.out.println(Math.min(c1, c2));
	}
}

