        count = 0;
        if(a[0] == 0){
            count = 1;
            sum = 1;
            solve();
            long temp = count;
            count = 1;
            sum = -1;
            solve();
            count = Math.min(count, temp);
        } else {
            solve();
            long temp = count;
            sum = -a[1]-1;
            count = Math.abs(a[0]+a[1]+1);
            solve();
            temp = Math.min(temp, count);
            sum = -a[1]+1;
            count = Math.abs(-a[0]+a[1]+1);
            solve();
            count = Math.min(temp, count);
        }
        println(count);
    }

    static void solve(){
        for(int i = 1; i < n; i++){
            if(sum < 0){
                if(a[i]+sum <= 0){
                    count += -(a[i]+sum)+1;
                    sum = 1;
                } else
                    sum = a[i]+sum;
            } else{
                if(a[i]+sum>=0){
                    count += a[i]+sum+1;
                    sum = -1;
                } else
                    sum = a[i]+sum;
