    public static int solve1(int[] sum,int[] a,int count){
        if(sum[0] == 0){
            count++;
            sum[0] = 1;
        }
        for(int i = 0;i < sum.length-1;i++){
            sum[i+1] = sum[i] + a[i+1];
            if((i+1) % 2 == 1){
                if(sum[i+1] >= 0){
                    count += 1 + sum[i+1];
                    sum[i+1] = -1;
