            List<Long> aList = getLongList(sc, n);

            long sum = 0;
            long result1 = 0;
            long result2 = 0;

            long margin = 0;
            // even +1
            for (int i = 0; i < n; i++) {
                sum += aList.get(i);
                if (i%2 == 0){
                    if (sum>0){
                        continue;
                    }else {
                        margin = Math.abs(sum)+1;
                        result1 += margin;
                        sum = 1;
                    }
                }else {
                    if (sum<0){
                        continue;
                    }else {
                        margin = Math.abs(sum)+1;
                        result1 += margin;
                        sum = -1;
                    }
                }
            }
            sum = 0;
            // even -1
            for (int i = 0; i < n; i++) {
                sum += aList.get(i);
                if (i%2 == 0){
                    if (sum<0){
                        continue;
                    }else {
                        margin = Math.abs(sum)+1;
                        result2 += margin;
                        sum = -1;
                    }
                }else {
                    if (sum>0){
                        continue;
                    }else {
                        margin = Math.abs(sum)+1;
                        result2 += margin;
                        sum = 1;
                    }
                }
            }
            out.println(Math.min(result1, result2));


        }
