        }

        int countB = 0;
        sum = 0;
        for (int i = 0; i < n; i++) {
            sum += array[i];
            if (i % 2 == 1) {
                if (sum <= 0) {
                    countB += sum * (-1) + 1;
                    sum = 1;
                }
            } else {
                if (sum >= 0) {
                    countB += sum + 1;
                    sum = -1;
                }
            }
        }

        System.out.println(Math.min(countA, countB));
    }
}

