	private static long calc(long[] a, boolean b) {
		long sum = a[0];
		long ret = 0;
		if (b) {
			ret = Math.abs(sum)+1;
			if (sum<0) {
				sum = 1;

			} else {
				sum = -1;
			}
		}
		long tmp = 0;
		for (int i = 1;i < a.length;i++) {
			long num = a[i];
			tmp = sum;
			sum += num;
			if ((tmp<0&&sum>=0)||(tmp>=0&&sum<0)) continue;
			long l = Math.abs(sum)+1;
			if (sum>=0) {
				sum -= l;
			} else {
				sum += l;
			}
			ret += l;
		}
		if (sum==0) ret++;
