		for (int i = 0; i < n; i++) {
			a[i] = in.nextLong();
		}
		long[] b = a.clone();
		for (int i = 0; i < b.length; i++) {
			b[i] = -b[i];
		}

		System.out.println(Math.min(f(a), f(b)));

	}
	long f(long[] a) {
		int n = a.length;

		long sum = 0;
		long ret = 0;
		for (int i = 0; i < n; i++) {
			sum += a[i];
			if (i % 2 == 0) {
				// +
				long d = Math.max(0, 1 - sum);
				sum += d;
				ret += d;

			} else {
				// -
				long d = Math.max(0, sum + 1);
				sum -= d;
				ret += d;
			}
		}

		return ret;
	}
