        solve();
        out.flush();
    }

    static void solve() {
        int N = sc.nextInt();
        long[] a = sc.nextLongArray(N);
        long c1 = 0;
        long c2 = 0;
        long sum = 0;
        long c = 1;

        for (int i = 0; i < N; i++) {
            sum += a[i];
            if (sum * c <= 0) {
                c1 += Math.abs(sum) + 1;
                sum = c;
            }
            c *= -1;
        }

        sum = 0;
        c = -1;
        for (int i = 0; i < N; i++) {
            sum += a[i];
            if (sum * c <= 0) {
                c2 += Math.abs(sum) + 1;
                sum = c;
            }
            c *= -1;
        }

        out.println(Math.min(c1, c2));
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
