        long A = 0;
        long ANS = 0;
        long ans = 0;
        long q = 1;
        a[0] = sc.nextLong();
        A = a[0];
        for (int i = 1; i < n; i++) {
            a[i] = sc.nextLong();
            A += a[i];
            q = q * -1;
            if (A <= 0 && q == 1) {
                ans += Math.abs(A - 1);
                A += Math.abs(A - 1);
            } else if (A >= 0 && q == -1) {
                ans += Math.abs(A + 1);
                A -= Math.abs(A + 1);
            }
        }
        ANS = ans;
        A = 0;
        ans = 0;
        q = -1;
        for (int i = 0; i < n; i++) {
            A += a[i];
            if (A <= 0 && q == 1) {
                ans += Math.abs(A - 1);
                A += Math.abs(A - 1);
            } else if (A >= 0 && q == -1) {
                ans += Math.abs(A + 1);
                A -= Math.abs(A + 1);
            }
            q = q * -1;
        }
        ANS = Math.min(ANS, ans);
        System.out.println(ANS);
    }
}

