using System;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder
{
    class Program
    {
        static int n;
        static List<int> a;

        static void Main(string[] args)
        {
            //[summary]C - Sequence
            n = int.Parse(Console.ReadLine());
            a = ReadLine();

            //偶数のインデックスを1にするケース
            long count1 = CountOperations(0);

            //奇数のインデックスを1にするケース
            long count2 = CountOperations(1);

            if (count1 < count2)
            {
                Console.WriteLine(count1);
            }
            else
            {
                Console.WriteLine(count2);
            }
        }

        static long CountOperations(int mod)
        {
            var b = GetNewNumbers(mod);
            long count = 0;

            for (int i = 0; i < n; i++)
            {
                count += Math.Abs(a[i] - b[i]);
            }

            return count;
        }

        static List<int> GetNewNumbers(int mod)
        {
            var b = new List<int>(a);
            long sum = 0;

            for (int i = 0; i < n; i++)
            {
                if (i % 2 == mod)
                {
                    //i項までの和をプラスに
                    if (sum + b[i] <= 0)
                    {
                        //i項までの和を1にする
                        b[i] += (int)Math.Abs(sum + b[i]) + 1;
                    }
                }
                else
                {
                    //i項までの和をマイナスに
                    if (sum + b[i] >= 0)
                    {
                        //i項までの和を-1にする
                        b[i] -= (int)(Math.Abs(sum + b[i]) + 1);
                    }
                }

                sum += b[i];
            }

            return b;
        }

        static List<int> ReadLine()
        {
            var line = Console.ReadLine();
            var array = line.Split(' ');

            return array.Select(x => int.Parse(x)).ToList();
        }
    }
}

