                else if (sum == 0)
                {
                    if (sign == 1)
                    {
                        sum--;
                        ans++;
                    }
                    else
                    {
                        sum++;
                        ans++;
                    }
                }
                sign = -sign;
            }

            Console.WriteLine(ans);
        }
    }
}

