class Program
{
    public static void Main()
    {
        var n = int.Parse(ReadLine());
        var a = ReadLine().Split().Select(long.Parse).ToArray();
        var b = new long[2, n];
        var sum = new long[2, n];
        var count = new int[2];
        for(int i = 0; i < n; i++)
        {
            b[0, i] = a[i];
            b[1, i] = -a[i];
        }
        for(int i = 0; i < 2; i++)
        {
            for(int j = 0; j < n; j++)
            {
                if(j == 0)
                    sum[i, j] = b[i, j];
                else
                    sum[i, j] = b[i, j] + sum[i, j - 1];
                if(j % 2 == 0)
                {
                    while(sum[i, j] <= 0)
                    {
                        b[i, j]++;
                        count[i]++;
                        if(j == 0)
                            sum[i, j] = b[i, j];
                        else
                            sum[i, j] = b[i, j] + sum[i, j - 1];
                    }
                }
                else
                {
                    while(sum[i, j] >= 0)
                    {
                        b[i, j]--;
                        count[i]++;
                        if(j == 0)
                            sum[i, j] = b[i, j];
                        else
                            sum[i, j] = b[i, j] + sum[i, j - 1];
                    }
                }
            }
        }
        WriteLine(count.Min());
    }
