			{
				sign0 = (sum > 0) ? 1 : -1;
				int j = i;
				while (j > 0)
				{
					sign0 *= -1;
					j--;
				}
				break;
			}
		}
		// もし最後まで0なら調整
		if(sign0 == 0)
		{
			array[0] += 1;
