namespace ABC059Sequence
{
    class Program
    {
        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            long[] a = new long[n];
            string[] vals = Console.ReadLine().Split(' ');

            for (int i = 0; i < n; i++)
                a[i] = long.Parse(vals[i]);

            if(a[0] != 0)
            {
                long num = calc(a);
                Console.WriteLine(num);
            }

            else
            {
                a[0] = 1;
                long num1 = calc(a) + 1;

                a[0] = -1;
                long num2 = calc(a) + 1;

                Console.WriteLine(Math.Min(num1, num2)); 
            }

        }

        static long calc(long[] a)
        {
            long num = 0;
            int n = a.Length;

            long[] cum = new long[n + 1];
            for (int i = 1; i < n; i++)
            {
                cum[i] = cum[i - 1] + a[i - 1];
                long t;
                if (cum[i] > 0)
                {
                    t = cum[i] * -1 - 1;
                }
                else
                {
                    t = cum[i] * -1 + 1;
                }

                //Console.WriteLine("target: {0}", t);

                long u;
                if (t > 0)
                {
                    if (a[i] < t)
                    {
                        u = t - a[i];

                        //Console.WriteLine("u={0}", u);
                        a[i] += u;
                        num += u;
                    }
                }
                else
                {
                    if (a[i] > t)
                    {
                        u = a[i] - t;
                        //Console.WriteLine("u=-{0}", u);

                        a[i] -= u;
                        num += u;
                    }
                }
            }

            return num;
        }

    }
}

