namespace ConsoleApp108 {
    class Program {
        static void Main(string[] args) {
            long n = long.Parse(Console.ReadLine());
            var a = Console.ReadLine().Split().Select(long.Parse).ToArray();

            var V = new long[n];
            V[0] = a[0];
            for (int i = 1; i < n; i++) {
                V[i] = V[i - 1] + a[i];
            }

            //パターンA
            //[偶数]までの和が正で、[奇数]までの和が負のパターン
            long cost_A = 0;
            bool open_A = true;
            long nowsum_A = 0;
            for (int i = 0; i < n; i++) {
                if (open_A) {
                    if (i % 2 == 0) {
                        if (V[i] <= 0) {
                            open_A = false;
                        }
                    } else {
                        if (V[i] >= 0) {
                            open_A = false;
                        }
                    }
                    if (i >= 1) {
                        nowsum_A = V[i - 1];
                    }
                } 

                if (!open_A) {
                    nowsum_A += a[i];
                    if (i % 2 == 0) {
                        if (nowsum_A <= 0) {
                            cost_A += Math.Abs(nowsum_A - 1);
                            nowsum_A = 1;
                        }
                    } else {
                        if (nowsum_A >= 0) {
                            cost_A += Math.Abs(nowsum_A - (-1));
                            nowsum_A = -1;
                        }
                    }
                }
            }


            //パターンB
            //[偶数]までの和が負で、[奇数]までの和が正のパターン
            long cost_B = 0;
            bool open_B = true;
            long nowsum_B = 0;
            for (int i = 0; i < n; i++) {
                if (open_B) {
                    if (i % 2 == 1) {
                        if (V[i] <= 0) {
                            open_B = false;
                        }
                    } else {
                        if (V[i] >= 0) {
                            open_B = false;
                        }
                    }
                    if (i >= 1) {
                        nowsum_B = V[i - 1];
                    }
                }

                if (!open_B) {
                    nowsum_B += a[i];
                    if (i % 2 == 1) {
                        if (nowsum_B <= 0) {
                            cost_B += Math.Abs(nowsum_B - 1);
                            nowsum_B = 1;
                        }
                    } else {
                        if (nowsum_B >= 0) {
                            cost_B += Math.Abs(nowsum_B - (-1));
                            nowsum_B = -1;
                        }
                    }
                }
            }


            Console.WriteLine(Math.Min(cost_A, cost_B));

        }
    }
}

