class Program {
    static Scanner sc = new Scanner();

    internal static void Main(string[] args) {
        var N = sc.nextInt();
        var a = sc.ArrayInt(N);

        var psum = 0;
        var msum = 0;
        var pcnt = 0;
        var mcnt = 0;
        for (int i = 0; i < N; i++) {
            psum += a[i];
            msum += a[i];
            if (i % 2 == 0) {
                if (psum <= 0) {
                    pcnt += 1 - psum;
                    psum = 1;
                }
                if (msum >= 0) {
                    mcnt += Math.Abs(-1 - msum);
                    msum = -1;
                }
            } else {
                if (psum >= 0) {
                    pcnt += Math.Abs(-1 - psum);
                    psum = -1;
                }
                if (msum <= 0) {
                    mcnt += 1 - msum;
                    msum = 1;
                }
            }
        }

        WriteLine(Math.Min(pcnt, mcnt));
    }
}



