    class Program
    {
        static void Main(string[] args)
        {
            var cin = new Scanner();
            var n = cin.nextLong();
            var a = cin.ArrayLong((int)n);

            // odd+
            long ans1 = 0;
            var acc = new long[n];
            for (int i = 0; i < n; i++)
            {
                var now = a[i];
                if(i == 0)
                {
                    acc[i] = a[i];
                }
                else
                {
                    acc[i] = acc[i - 1] + a[i];
                }

                var sum = acc[i];
                if(i % 2 == 0)
                {
                    if(sum >= 0)
                    {
                        //偶数番目が+なら-1にする
                        ans1 += sum + 1;
                        acc[i] = -1;
                    }
                }
                else
                {
                    if(sum <= 0)
                    {
                        //奇数番目が-なら1にする
                        ans1 += Math.Abs(sum) + 1;
                        acc[i] = 1;
                    }
                }
            }

            // odd-
            long ans2 = 0;
            acc = new long[n];
            for (int i = 0; i < n; i++)
            {
                var now = a[i];
                if (i == 0)
                {
                    acc[i] = a[i];
                }
                else
                {
                    acc[i] = acc[i - 1] + a[i];
                }

                var sum = acc[i];
                if (i % 2 != 0)
                {
                    if (sum >= 0)
                    {
                        // 奇数番目が+なら
                        ans2 += sum + 1;
                        acc[i] = -1;
                    }
                }
                else
                {
                    if (sum <= 0)
                    {
                        // 偶数番目が-なら
                        ans2 += Math.Abs(sum) + 1;
                        acc[i] = 1;
                    }
                }
            }

            Console.WriteLine(Math.Min(ans1,ans2));
        }
    }

    static class C
    {
        public static long LowerBound(long[] a, long key)
        {
            long l = 0;
            long r = a.Length;
            long mid;
            while (l < r)
            {
                mid = ((r - l) / 2) + l;
                if (a[mid] <= key)
                    l = mid + 1;
                else
                    r = mid;
            }
            return l;
        }
    }

    static class Subsequence
    {
       /// <summary>
       /// 最長増加部分列
       /// </summary>
       /// <param name="a">long[]</param>
       /// <returns></returns>
        public static long LIS(long[] a)
        {
            var dp = Enumerable.Range(0, a.Length).Select(x => long.MaxValue).ToArray();
            for (int i = 0; i < a.Length; i++)
            {
                dp[C.LowerBound(dp, a[i])] = a[i];
            }
            return C.LowerBound(dp, long.MaxValue-1);
        }
    }

