			long[] a = cin.ArrayLong(n);

			{
				bool ok = true;
				long sum = 0;
				for (int i = 0; i < n; i++) {
					long next = sum + a[i];
					if (next == 0 || sum * next >= 0) {
						ok = false;
						break;
					}

					sum = next;
				}

				if (ok) {
					Console.WriteLine(0);
