			long ans1 = 0;
			{
				long current = a[0];
				if (current <= 0) {
					current = 1;
					ans1 += Math.Abs(a[0]) + 1;
				}
				for (int i = 1; i < n; i++) {
					long next = current + a[i];
					if (current * next < 0) {
						current = next;
						continue;
					}

					long temp = current * a[i];
					if (temp > 0) {
						ans1 += Math.Abs(a[i]) + Math.Abs(current) + 1;
						current = current > 0 ? -1 : 1;
					} else if (temp < 0) {
						ans1 += Math.Abs(current + a[i]) + 1;
						current = current > 0 ? -1 : 1;
					} else {
						ans1 += Math.Abs(current) + 1;
						current = current > 0 ? -1 : 1;
					}
				}
			}

			long ans2 = 0;
			{
				long current = a[0];
				if (current >= 0) {
					current = -1;
					ans2 += Math.Abs(a[0]) + 1;
				}
				for (int i = 1; i < n; i++) {
					long next = current + a[i];
					if (current * next < 0) {
						current = next;
