using System.Linq;
using static System.Math;

namespace ConsoleApp1
{
    class Program
    {
        static long Solve(long[] A, bool positive)
        {
            long sum = 0, ans = 0;
            foreach (var value in A)
            {
                sum += value;
                if (positive && sum <= 0)
                {
                    long add = 1 - sum;
                    ans += add;
                    sum += add;
                }
                else if (!positive && sum >= 0)
                {
                    long add = sum - (-1);
                    ans += add;
                    sum -= add;
                }

                positive = !positive;
            }

            return ans;
        }

        static void Main(string[] args)
        {
            Console.ReadLine();
            long[] A = Console.ReadLine().Split().Select(long.Parse).ToArray();
            long ans = Min(Solve(A, true), Solve(A, false));
            Console.WriteLine(ans);
        }
    }
}

