        public void Solve(ConsoleInput cin)
        {
            var n = cin.ReadInt;
            var a = cin.ReadLongArray(n);
            var ans = 0L;
            var pre = a[0];
            for(int i = 1; i < n; i++)
            {
                var now = pre + a[i];
                if(pre * now < 0)
                {
                    pre += a[i];
                    continue;
                }

