			var sum = new long[n];
			bool isPositiveBefore = true;
			for (int i = 0; i < n; i++)
			{
				if (i == 0) sum[0] = a[0];
				else sum[i] = sum[i - 1] + a[i];

				if (isPositiveBefore)
				{
					if (sum[i] >= 0)
					{
						ansa += sum[i] + 1;
						sum[i] = -1;
					}
				}
				else
				{
					if (sum[i] <= 0)
					{
						ansa += 1 - sum[i];
						sum[i] = 1;
					}
				}

				isPositiveBefore = !isPositiveBefore;
			}

			sum = new long[n];
			isPositiveBefore = false;
