namespace ABC059C
{
    class Program
    {
        // -1 4 3  2 -5 4
        // -1 4 -4 2 -5 5 -> 8
        static long sequentialize(int[] a, bool firstPlus)
        {
            var n = a.Length;
            var changeCount = 0L;

            if (firstPlus && a[0] <= 0)
            {
                changeCount += 1 - a[0];
                a[0] = 1;
            }
            else if (!firstPlus && a[0] >= 0)
            {
                changeCount += 1 + a[0];
                a[0] = -1;
            }

            var sum = a[0];
            int v = a[0] > 0 ? 1 : -1;

            for (int i = 1; i < n; i++)
            {
                var temp = sum + a[i];

                if (sum > 0 && temp > 0)
                {
                    // tempを-1にしたい
                    var prev = a[i];
                    a[i] = -sum - 1;
                    changeCount += Math.Abs(prev - a[i]);
                }
                else if (sum < 0 && temp < 0)
                {
                    // tempを+1にしたい
                    var prev = a[i];
                    a[i] = -sum + 1;
                    changeCount += Math.Abs(prev - a[i]);
                }
                else if (temp == 0)
                {
                    changeCount += 1;
                    a[i] = v;
                }

                sum += a[i];
                v = -v;
            }

            return changeCount;
        }

        static void Solve()
        {
            var n = Input.NextInt();
            var a = Input.NextInt(n).ToArray();
            var b = new int[n];

            a.CopyTo(b, 0);

            var changeCount1 = sequentialize(a, true);
            var changeCount2 = sequentialize(b, false);

            Console.WriteLine(Math.Min(changeCount1, changeCount2));
        }

