class Program
{
    static void Main(string[] args)
    {
        // 入力
        //var s = Console.ReadLine();
        var n = long.Parse(Console.ReadLine());
        long[] a = Console.ReadLine().Split().Select(long.Parse).ToArray();

        long[] sum = new long[n];
        sum[0] = a[0];
        for (int i = 1; i < n; i++)
        {
            sum[i] = sum[i - 1] + a[i];
        }

        var ans = long.MaxValue;

        //+-+=
        var flag = true;
        long count = 0;
        long tmp = 0;
        for (int i = 0; i < n; i++)
        {
            //前処理
            sum[i] += tmp;

            if (flag)
            {
                //0より大きい数字であることを確認
                if (sum[i] <= 0)
                {
                    tmp += sum[i] * (-1) + 1;
                    count += Math.Abs(sum[i] * (-1) + 1);
                    sum[i] += sum[i] * (-1) + 1;
                }
            }
            else
            {
                //0より小さい数字であることを確認
                if (sum[i] >= 0)
                {
                    tmp += sum[i] * (-1) - 1;
                    count += Math.Abs(sum[i] * (-1) - 1);
                    sum[i] += sum[i] * (-1) - 1;
                }
            }
            flag = !flag;
        }

        ans = Math.Min(ans, count);

        //-+-+
        sum[0] = a[0];
        for (int i = 1; i < n; i++)
        {
            sum[i] = sum[i - 1] + a[i];
        }

        flag = false;
        count = 0;
        tmp = 0;
        for (int i = 0; i < n; i++)
        {
            //前処理
            sum[i] += tmp;

            if (flag)
            {
                //0より大きい数字であることを確認
                if (sum[i] <= 0)
                {
                    tmp += sum[i] * (-1) + 1;
                    count += Math.Abs(sum[i] * (-1) + 1);
                    sum[i] += sum[i] * (-1) + 1;
                }
            }
            else
            {
                //0より小さい数字であることを確認
                if (sum[i] >= 0)
                {
                    tmp += sum[i] * (-1) - 1;
                    count += Math.Abs(sum[i] * (-1) - 1);
                    sum[i] += sum[i] * (-1) - 1;
                }

            }
            flag = !flag;
        }

        ans = Math.Min(ans, count);

        // 出力
        Console.WriteLine(ans);
    }
}

