            if (list[0] == 0) {
                var index = list.FindIndex(x => x != 0);
                if (index == -1) list[0] = 1;
                else if ((index % 2 == 1) == (list[index] < 0)) list[0] = 1;
                else list[0] = -1;
                count++;
            }

