class Program{
	static int n;
	static long ans,b;
	static int[] s; 
	static void Main(){
		n=int.Parse(Console.ReadLine());
		s=Array.ConvertAll(Console.ReadLine().Split(),int.Parse);
		int[] a=new int[n];
		for(int i=0;i<n;i++){a[i]=s[i];}
		if(s[0]==0){s[0]=fu(1);ans++;}
		for(int i=1;i<n;i++){
			s[i]+=s[i-1];
			if(s[i]==0){s[i]=-Math.Sign(s[i-1]);ans++;}
			else if(Math.Sign(s[i])==Math.Sign(s[i-1])){
				ans+=Math.Abs(s[i])+1;
				s[i]=-Math.Sign(s[i]);
			}
		}
		b+=Math.Abs(a[0])+1;
		a[0]=-Math.Sign(s[0]);
		for(int i=1;i<n;i++){
			a[i]+=a[i-1];
			if(a[i]==0){a[i]=-Math.Sign(a[i-1]);b++;}
			else if(Math.Sign(a[i])==Math.Sign(a[i-1])){
				b+=Math.Abs(a[i])+1;
				a[i]=-Math.Sign(a[i]);
			}
		}
		Console.WriteLine("{0}",Math.Min(ans,b));
	}
	static int fu(int z){
		if(z==n){return 1;}
		else if(s[z]==0){s[z]=fu(z+1);ans++;}
		return s[z]<0?1:-1;
	}
