    static void Solve()
    {
        var N = sc.ReadInt();
        var A = sc.ReadIntArray(N);
        var ans = long.MaxValue;
        for (int i = 0; i < 2; i++)
        {
            var res = 0L;
            var sum = 0;
            var plus = i == 0;
            foreach (var a in A)
            {
                sum += a;
                if (plus && sum <= 0)
                {
                    res += Math.Abs(sum) + 1;
                    sum = 1;
                }
                else if (!plus && sum >= 0)
                {
                    res += Math.Abs(sum) + 1;
                    sum = -1;
                }
                plus = !plus;
            }
            ans = Math.Min(ans, res);
        }
