using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace ABC059Sequence
{
    class Program
    {
        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            long[] a = new long[n];
            long[] b = new long[n];
            string[] vals = Console.ReadLine().Split(' ');

            for (int i = 0; i < n; i++)
            {
                a[i] = long.Parse(vals[i]);
                b[i] = a[i];
            }

            long m = 0;
            long num1, num2;
            if(a[0] <= 0)
            {
                m = a[0] * -1 + 1;
                a[0] += m;
            }
            num1 = calc(a) + m;

            m = 0;
            if(b[0] >= 0)
            {
                m = b[0] + 1;
                b[0] -= m;
            }
            num2 = calc(b) + m;

            Console.WriteLine(Math.Min(num1, num2));
        }

        static long calc(long[] a)
        {
            long num = 0;
            int n = a.Length;

            long[] cum = new long[n + 1];
            for (int i = 1; i < n; i++)
            {
                cum[i] = cum[i - 1] + a[i - 1];
                long t;
                if (cum[i] > 0)
                {
                    t = cum[i] * -1 - 1;
                }
                else
                {
                    t = cum[i] * -1 + 1;
                }

                //Console.WriteLine("target: {0}", t);

                long u;
                if (t > 0)
                {
                    if (a[i] < t)
                    {
                        u = t - a[i];

                        //Console.WriteLine("u={0}", u);
                        a[i] += u;
                        num += u;
                    }
                }
                else
                {
                    if (a[i] > t)
                    {
                        u = a[i] - t;
                        //Console.WriteLine("u=-{0}", u);

                        a[i] -= u;
                        num += u;
                    }
                }
            }

            return num;
        }

    }
}

