                    {
                        if (sum[i - 1][j] > 0)
                        {
                            cnt[j] += sum[i][j] + 1;
                            sum[i][j] = -1;
                        }
                        else
                        {
                            cnt[j] += 1 - sum[i][j];
                            sum[i][j] = 1;
                        }
                    }
                }
            }

            var ans = cnt.Min();
