using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static void Main(string[] args)
    {
        var N = sc.ReadInt();
        var A = sc.ReadLongArray(N);
        var sum = new long[N];
        sum[0] = A[0];
        for (int i = 1; i < N; i++)
        {
            sum[i] = sum[i - 1] + A[i];
        }

        // + - + - ..
        long res1 = 0;
        long x = 0;
        for (int i = 0; i < N; i++)
        {
            var now = sum[i] + x;
            if (i % 2 == 0 && now <= 0)
            {
                x += 1 - now;
                res1 += Math.Abs(1 - now);
            }
            else if (i % 2 == 1 && now >= 0)
            {
                x += -1 - now;
                res1 += Math.Abs(now + 1);
            }
        }
        // - + - + ..
        long res2 = 0;
        x = 0;
        for (int i = 0; i < N; i++)
        {
            var now = sum[i] + x;
            if (i % 2 == 1 && now <= 0)
            {
                x += 1 - now;
                res2 += Math.Abs(1 - now);
            }
            else if (i % 2 == 0 && now >= 0)
            {
                x += -1 - now;
                res2 += Math.Abs(now + 1);
            }
        }

        var ans = Math.Min(res1, res2);
        Console.WriteLine(ans);
    }
    static Scanner sc = new Scanner();
}

class Scanner
{
    string[] S = new string[0];
    int Index = 0;
    char[] Separators = new char[] { ' ' };

    public string Next()
    {
        if (this.Index < this.S.Length) return this.S[this.Index++];
