namespace Practice
{
    class Program
    {
        static void Main(string[] args)
        {
            Solve();
        }
        private const long MOD = 1000000007;

        static void Solve()
        {
            int n = ReadAndParseInt();
            var a = ReadAndParseLongArr();

            long cost0 = CalcCost(a, i => i % 2 == 0);
            long cost1 = CalcCost(a, i => i % 2 == 1);
            long ans = Math.Min(cost0, cost1);
            Console.WriteLine(ans);
        }
        private static long CalcCost(long[] a, System.Func<int, bool> plusCondition)
        {
            long cost = 0;
            long sum = 0;
            for (int i = 0; i < a.Length; ++i)
            {
                var val = a[i];
                sum += val;
                if (plusCondition(i))
                {
                    // +にする
                    if (sum <= 0)
                    {
                        long add = 1 - sum;
                        cost += add;
                        sum += add;
                    }
                }
                else
                {
                    // - にする
                    if (sum >= 0)
                    {
                        long sub = -sum - 1;
                        cost += Math.Abs(sub);
                        sum += sub;
                    }
                }
            }
            return cost;
        }
        #region よく使う便利関数
        private static bool isPrime(long x)
        {
            if (x == 2) { return true; }
            if (x < 2 || x % 2 == 0) { return false; }
            long i = 3;
            while (i * i <= x)
            {
                if (x % i == 0) { return false; }
                i = i + 2;
            }
            return true;
        }
        private static long lcm(long x, long y)
        {
            return x / gcd(x, y) * y;
        }
        private static long gcd(long x, long y)
        {
            return y > 0 ? gcd(y, x % y) : x;
        }
        private static long pow(long x, long n)
        {
            if (n == 0) { return 1; }
            long res = pow(x * x % MOD, n / 2);
            if (n % 2 == 1)
            {
                res = res * x % MOD;
            }
            return res;
        }
        private static int ReadAndParseInt()
        {
            return int.Parse(Console.ReadLine());
        }
        private static int[] ReadAndParseIntArr()
        {
            return Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
        }
        private static long ReadAndParseLong()
        {
            return long.Parse(Console.ReadLine());
        }
        private static long[] ReadAndParseLongArr()
        {
            return Array.ConvertAll(Console.ReadLine().Split(' '), long.Parse);
        }
        #endregion
    }
}

