    //プラス、マイナス、プラスの順にするコストを求める
    static long Solve1(int[] pArr)
    {
        long Cost = 0;
        long RunSum = 0;

        for (int I = 0; I <= pArr.GetUpperBound(0); I++) {
            RunSum += pArr[I];
            if (I % 2 == 0) {
                if (RunSum > 0) continue;
                Cost += Math.Abs(RunSum) + 1;
                RunSum = 1;
            }
            else {
                if (RunSum < 0) continue;
                Cost += Math.Abs(RunSum) + 1;
                RunSum = -1;
            }
        }
        return Cost;
    }

    //マイナス、プラス、マイナスの順にするコストを求める
    static long Solve2(int[] pArr)
    {
        long Cost = 0;
        long RunSum = 0;

        for (int I = 0; I <= pArr.GetUpperBound(0); I++) {
            RunSum += pArr[I];
            if (I % 2 == 1) {
                if (RunSum > 0) continue;
                Cost += Math.Abs(RunSum) + 1;
                RunSum = 1;
            }
            else {
                if (RunSum < 0) continue;
                Cost += Math.Abs(RunSum) + 1;
                RunSum = -1;
            }
        }
        return Cost;
    }
