            int sum = 0;
            if (a[0] < 0) f = 1;
            if (a[0] == 0)
            {
                if (a[1] >= 0)
                {
                    a[0] = -1;
                }else
                {
                    a[0] = 1;
                }
                x++;
            }
            for(int i = 0; i < n; i++)
            {
                sum += a[i];
                if (f == 1 && sum >= 0)
                {
                    x += (sum + 1);
                    f = 0;
                    sum = -1;
                }else if (f == 0 && sum <= 0)
                {
                    x += (1 - sum);
                    f = 1;
                    sum = 1;
                }else
                {
                    f = 1 - f;
                }
            }
            Console.WriteLine(x);
        }
    }
