            var EveAns = 0L;
            var pre = 0L;
            //奇数正
            for (int i = 0; i < n; i++)
            {
                var now = pre + a[i];
                if((i + 1) % 2 == 1)
                {
                    if (now > 0)
                    {
                        pre += a[i];
                        continue;
                    }
                    else
                    {
                        OddAns += 1 - now;
                        pre += a[i] + 1 - now;
                    }
                }
                else
                {
                    if (now < 0)
                    {
                        pre += a[i];
                        continue;
                    }
                    else
                    {
                        OddAns += now + 1;
                        pre += a[i] - now - 1;
                    }
                }
            }
            pre = 0L;
            for(int i = 0; i < n; i++)
            {
                var now = pre + a[i];
                if((i + 1) % 2 == 0)
                {
                    if(now > 0)
                    {
                        pre += a[i];
                        continue;
                    }
                    else
                    {
                        EveAns += 1 - now;
                        pre += a[i] + 1 - now;
                    }
                }
                else
                {
                    if(now < 0)
                    {
                        pre += a[i];
                        continue;
