        public void Solve(ConsoleInput cin)
        {
            var n = cin.ReadInt;
            var a = cin.ReadLongArray(n);
            var ans = 0L;
            for(int i = 1; i < n; i++)
            {
                var pre = (long)a.Take(i).Sum();
                var now = (long)a.Take(i + 1).Sum();
                if(pre * now < 0)
                {
                    continue;
                }
                if(now > 0)
                {
                    ans += a[i] + (pre + 1);
                    a[i] = -1 * (pre + 1);
                }
                else
                {
                    ans += -1 * (pre - 1) - a[i];
                    a[i] = -1 * (pre - 1);
                }
            }
            WriteLine(ans);
        }



