using System.Linq;

namespace ProgramingStudying2
{
    class Program
    {

        static void Main(string[] args)
        {
            var n = int.Parse(Console.ReadLine());
            var a = Console.ReadLine().Split().Select(long.Parse).ToArray();

            long Solve(long first)
            {
                long sum = first;
                long ans = 0;

                for(int i = 1; i < n; i++)
                {
                    if (sum > 0)
                    {
                        sum += a[i];
                        if (sum >= 0)
                        {
                            ans += sum + 1;
                            sum = -1;
                        }
                    }

                    else if(sum < 0)
                    {
                        sum += a[i];
                        if (sum <= 0)
                        {
                            ans += -sum + 1;
                            sum = 1;
                        }
                    }
                }
                return ans;
            }

            if(a[0] > 0)
            {
                Console.WriteLine(Math.Min(Solve(a[0]), Solve(-1) + a[0] + 1)); 
            }
            else if(a[0] < 0)
            {
                Console.WriteLine(Math.Min(Solve(a[0]), Solve(1) - a[0] + 1));
            }
            else
            {
                Console.WriteLine(Math.Min(Solve(1) + 1, Solve(-1) + 1));
            }
        }
    }
}

using System;

class Program
{
    static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        var inp = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);
        long ans = 0;
        long cumsum = inp[0];
        for (int i = 1; i < n; i++)
        {
            if (cumsum * inp[i] >= 0)
            {
                ans += Math.Abs(cumsum + inp[i]) + 1;
                inp[i] = inp[i] > 0 ? -(cumsum + 1) : cumsum + 1;
            }
            else if (Math.Abs(cumsum) >= Math.Abs(inp[i]))
            {
                ans += Math.Abs(cumsum + inp[i]) + 1;
                inp[i] = inp[i] > 0 ? Math.Abs(cumsum) + 1 : -(Math.Abs(cumsum) + 1);
            }
            cumsum += inp[i];
        }
        Console.WriteLine(ans);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace AtCoder
{
    class Code3
    {
        static void Main(string[] args)
        {
            string s1 = Console.ReadLine();
            string s2 = Console.ReadLine();

            Console.WriteLine(funcMain(s1,s2));
        }


        static private string funcMain(string arg1, string arg2)
        {
            long ret = 0;
            long sum = 0;
            foreach (string buf in arg2.Split())
            {
                if (sum == 0)
                    sum = long.Parse(buf);
                else
                {
                    if (sum > 0)
                    {
                        sum += long.Parse(buf);
                        if (sum >= 0)
                        {
                            ret += sum + 1;
                            sum = -1;
                        }
                    }
                    else
                    {
                        sum += long.Parse(buf);
                        if (sum <= 0)
                        {
                            ret += (sum * -1) + 1; // 絶対値の関数探すのがめんどくさかった
                            sum = 1;
                        }
                    }
                }
            }

            return ret.ToString();
        }

        static private void test()
        {
            string arg1, arg2;
            arg1 = "4";
            arg2 = "1 -3 1 0";
            Console.WriteLine("4" == funcMain(arg1, arg2));
            arg1 = "5";
            arg2 = "3 -6 4 -5 7";
            Console.WriteLine("0" == funcMain(arg1, arg2));
            arg1 = "6";
            arg2 = "-1 4 3 2 -5 4";
            Console.WriteLine("8" == funcMain(arg1, arg2));
            Console.ReadKey();
        }
    }
}

using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Text;

class Program
{
    static int n;
    static int[] a;

    public static void Main(string[] args)
    {
        n = Input.NextInt();
        var a = Input.LineInt();

        int minmove = int.MaxValue;
        minmove = Calc(a);
        for (int i = 0; i < a.Length; i++)
        {
            a[i] = -a[i];
        }
        minmove = Math.Min(minmove, Calc(a));

        Console.WriteLine(minmove);
    }

    private static int Calc(int[] a)
    {
        int curr = 0;
        int move = 0;
        for (int i = 0; i < a.Length; i++)
        {
            int dif = 0;
            switch (i % 2)
            {
                case 0:
                    {
                        var newc = curr + a[i];
                        dif = newc <= 0 ? 1 - newc : 0;
                    }
                    break;
                case 1:
                    {
                        var newc = curr + a[i];
                        dif = newc >= 0 ? -1 - newc : 0;
                    }
                    break;
            }
            curr += a[i] + dif;
            move += Math.Abs(dif);
        }

        return move;
    }
}

