using System;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Text;

namespace ABC059C
{
    class Program
    {
        // -1 4 3  2 -5 4
        // -1 4 -4 2 -5 5 -> 8
        static long sequentialize(int[] a)
        {
            var n = a.Length;
            var sum = a[0];
            var changeCount = 0L;
            int v = a[0] > 0 ? 1 : -1;

            for (int i = 1; i < n; i++)
            {
                var temp = sum + a[i];

                if (sum > 0 && temp > 0)
                {
                    // tempを-1にしたい
                    var prev = a[i];
                    a[i] = -sum - 1;
                    changeCount += Math.Abs(prev - a[i]);
                }
                else if (sum < 0 && temp < 0)
                {
                    // tempを+1にしたい
                    var prev = a[i];
                    a[i] = -sum + 1;
                    changeCount += Math.Abs(prev - a[i]);
                }
                else if (temp == 0)
                {
                    changeCount += 1;
                    a[i] = v;
                }

                sum += a[i];
                v = -v;
            }

            return changeCount;
        }

        static void Solve()
        {
            var n = Input.NextInt();
            var a = Input.NextInt(n).ToArray();
            var b = new int[n];

            a.CopyTo(b, 0);

            var changeCount1 = sequentialize(a);

            // 先頭の符号反転
            b[0] = b[0] / -b[0];
            var changeCount2 = sequentialize(b) + Math.Abs(b[0]) + 1;

            Console.WriteLine(Math.Min(changeCount1, changeCount2));
        }

        #region Competitive Template
        public static void Main(string[] args)
        {
            var needsFlushOutput = true;
            if (needsFlushOutput)
            {
                // 細かく出力しないようにする
                var sw = new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
                Console.SetOut(sw);
            }

            // 仮想的に標準入力をセットする
            // NextLine系を使っていると使えない
            //Input.SetText("");

            Solve();

            Console.Out.Flush();
        }

        static class Input
        {
            static char[] separator = { ' ' };
            public static bool IsEof { get; set; }
            static Queue<string> q { get; set; }

            static Input()
            {
                IsEof = false;
                q = new Queue<string>();
            }

            /// <summary>
            /// 入力予約
            /// </summary>
            /// <param name="items"></param>
            public static void SetText(IEnumerable<string> items)
            {
                foreach (var item in items)
                {
                    SetText(item);
                }
            }

            /// <summary>
            /// 入力予約
            /// </summary>
            /// <param name="s"></param>
            /// <returns></returns>
            public static bool SetText(string s)
            {
                if (s == null) return false;

                foreach (var elem in s.Trim().Split(separator, StringSplitOptions.RemoveEmptyEntries))
                {
                    q.Enqueue(elem);
                }

                return true;
            }

            /// <summary>
            /// 内部queueに入力からの値をsplitして格納する
            /// </summary>
            /// <returns></returns>
            static bool read()
            {
                var s = Console.ReadLine();
                if (s == null) return false;

                foreach (var elem in s.Trim().Split(separator, StringSplitOptions.RemoveEmptyEntries))
                {
                    q.Enqueue(elem);
                }

                if (!q.Any()) return read();

                return true;
            }

            /// <summary>
            /// 次のstringを一つ読み込む
            /// </summary>
            /// <returns></returns>
            public static string Next()
            {
                if (!q.Any())
                {
                    if (!read())
                    {
                        IsEof = true;
                        return "";
                    }
                }

                return q.Dequeue();
            }

            public static int NextInt() => int.Parse(Next());
            public static long NextLong() => long.Parse(Next());
            public static double NextDouble() => double.Parse(Next());

            public static List<string> Next(int n) => Enumerable.Range(0, n).Select(_ => Next()).ToList();
            public static List<int> NextInt(int n) => Next(n).Select(x => int.Parse(x)).ToList();
            public static List<long> NextLong(int n) => Next(n).Select(x => long.Parse(x)).ToList();
            public static List<double> NextDouble(int n) => Next(n).Select(x => double.Parse(x)).ToList();

            public static List<string> NextLine() => Console.ReadLine().Trim().Split(separator, StringSplitOptions.RemoveEmptyEntries).ToList();
            public static List<int> NextIntLine() => NextLine().Select(x => int.Parse(x)).ToList();
            public static List<long> NextLongLine() => NextLine().Select(x => long.Parse(x)).ToList();
            public static List<double> NextDoubleLine() => NextLine().Select(x => double.Parse(x)).ToList();
        }
        #endregion
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder
{
    class Program
    {
        static int n;
        static List<long> a;

        static void Main(string[] args)
        {
            //[summary]C - Sequence
            n = int.Parse(Console.ReadLine());
            a = ReadLine();

            //偶数のインデックスを1にするケース
            long count1 = CountOperations(0);

            //奇数のインデックスを1にするケース
            long count2 = CountOperations(1);

            if (count1 < count2)
            {
                Console.WriteLine(count1);
            }
            else
            {
                Console.WriteLine(count2);
            }
        }

        static long CountOperations(int mod)
        {
            var b = GetNewNumbers(mod);
            long count = 0;

            for (int i = 0; i < n; i++)
            {
                count += Math.Abs(a[i] - b[i]);
            }

            return count;
        }

        static List<long> GetNewNumbers(int mod)
        {
            var b = new List<long>(a);
            long sum = 0;

            for (int i = 0; i < n; i++)
            {
                if (i % 2 == mod)
                {
                    //i項までの和をプラスに
                    if (sum + b[i] <= 0)
                    {
                        //i項までの和を1にする
                        b[i] += Math.Abs(sum + b[i]) + 1;
                    }
                }
                else
                {
                    //i項までの和をマイナスに
                    if (sum + b[i] >= 0)
                    {
                        //i項までの和を-1にする
                        b[i] -= (Math.Abs(sum + b[i]) + 1);
                    }
                }

                sum += b[i];
            }

            return b;
        }

        static List<long> ReadLine()
        {
            var line = Console.ReadLine();
            var array = line.Split(' ');

            return array.Select(x => long.Parse(x)).ToList();
        }
    }
}

