using System;
using static System.Console;
using static System.Convert;

class Program
{
    static void Main(string[] args)
    {
        var length = ToInt32(ReadLine());
        long result = 0;
        var nums = Array.ConvertAll(ReadLine().Split(' '), long.Parse);
        var sum = nums[0];
        if (sum == 0) { sum++; result++; }
        var lastSum = sum;
        for(var i = 1; i < length; i++)
        {
            sum += nums[i];
            while (!IsDifferentSign(lastSum, sum)||sum==0)
            {
                if (!IsDifferentSign(lastSum, sum))
                { result += Math.Abs(sum) + 1; sum = lastSum > 0 ? -1 : 1;}
                if (sum == 0) { sum = lastSum > 0 ? --sum : ++sum; result++; }
            }
            lastSum = sum;
        }
        WriteLine(result);
    }

    private static bool IsDifferentSign(long lastSum,long sum)
    {
        return (lastSum > 0 && sum < 0) || (lastSum < 0 && sum > 0);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using static System.Console;
using System.Runtime.CompilerServices;
using static MyUtil;

class MyUtil
{
    public static int[] ReadIntArray()
    {
	return ReadLine().Split().Select(x => int.Parse(x)).ToArray();
    }
}

class Program
{
    public static void Main()
    {
	int n = int.Parse(ReadLine());
	int[] a = ReadIntArray();

	long[] s = new long[n];
	s[0] = a[0];
	for (int i = 1; i < n; i++)
	{
	    s[i] = s[i-1] + a[i];
	}

	// ty1: +-+-..., ty2: -+-+...
	long n1 = 0, n2 = 0;
	long offset1 = 0, offset2 = 0;

	for (int i = 0; i < n; i++)
	{
	    long gap1 = 0, gap2 = 0;
	    if ((i&1) == 0)
	    {
		if (s[i] + offset1 <= 0)
		{
		    gap1 =  1 - (s[i] + offset1);
		}

		if (s[i] + offset2 >= 0)
		{
		    gap2 = -1 - (s[i] + offset2);
		}
	    }
	    else
	    {
		if (s[i] + offset1 >= 0)
		{
		    gap1 =  -1 - (s[i] + offset1);
		}

		if (s[i] + offset2 <= 0)
		{
		    gap2 = 1 - (s[i] + offset2);
		}
	    }
	    n1 += Math.Abs(gap1);
	    offset1 += gap1;
	    n2 += Math.Abs(gap2);
	    offset2 += gap2;
	}
	WriteLine(Math.Min(n1, n2));
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace AtCoderBeginnerContest
{
    public class Program
    {
        public static void Main(string[] args)
        {
            // C
            var n = long.Parse(Console.ReadLine());
            var a = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();

            long sum = a[0];
            long count = 0;
            for (int i = 1; i < n; i++)
            {
                // 差し引き0になってしまうとき
                if (i != n - 1 && sum + a[i] == 0)
                {
                    if (i < n - 1)
                    {
                        if (a[i + 1] > 0) sum = -1;
                        else sum = 1;
                        count++;
                    }
                }
                // sumとsum+a[i]の符号が違うとき
                else if ((sum > 0 && sum+a[i] < 0) || (sum < 0 && sum + a[i] > 0))
                {
                    sum = sum + a[i];
                }
                // sumとsum+a[i]の符号が同じとき
                else
                {
                    if (Math.Abs(sum + a[i]) > Math.Abs(sum))
                    {
                        count += Math.Abs(sum) + 1;
                        sum = sum > 0 ? sum = -1 + a[i] : sum = 1 + a[i];
                    }
                    else
                    {
                        count += Math.Abs(sum+a[i]) + 1;
                        sum = sum > 0 ? sum = -1 : sum = 1;
                    }
                }
            }
            Console.WriteLine(count);
        }
    }
}

