using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace AtCoder
{
    class Code3
    {
        static void Main(string[] args)
        {
            string s1 = Console.ReadLine();
            string s2 = Console.ReadLine();

            Console.WriteLine(funcMain(s1,s2));
        }


        static private string funcMain(string arg1, string arg2)
        {
            long cnt = 0;
            long ret = 0;
            long ret1 = 0;
            long ret2 = 0;
            long sum = 0;
            short sign = 0;

            for (int i = 0; i <= 1; i++) // 0はそのまま、1は逆符号
            {
                cnt = sum = ret = 0;
                foreach (string buf in arg2.Split())
                {
                    cnt++;
                    if (cnt > long.Parse(arg1)) break;
                    if (sum == 0)
                    { 
                        sum = long.Parse(buf);
                        if (sum >= 0)
                            sign = 1;
                        else
                            sign = -1;

                        if (i == 1)
                        {
                            ret += Math.Abs(sum) + 1;
                            sum = sign * -1;
                            sign *= -1;
                        }
                    }
                    else
                    {
                        sum += long.Parse(buf);
                        if ((sum * sign) >= 0)
                        {
                            ret += Math.Abs(sum) + 1;
                            sum = sign * -1;
                        }
                        sign *= -1;
                    }
                }
                if (i == 0)
                    ret1 = ret;
                else
                    ret2 = ret;
            }

            ret = Math.Min(ret1, ret2);

            return ret.ToString();
        }

        static private void test()
        {
            string arg1, arg2;
            arg1 = "4";
            arg2 = "1 -3 1 0";
            Console.WriteLine("4" == funcMain(arg1, arg2));
            arg1 = "5";
            arg2 = "3 -6 4 -5 7";
            Console.WriteLine("0" == funcMain(arg1, arg2));
            arg1 = "6";
