            long ret1 = 0;
            long ret2 = 0;
            long sum = 0;

            for(int i = 0; i <= 1; i++) // 0はそのまま、1は逆符号
            {
                sum = ret = 0;
                foreach (string buf in arg2.Split())
                {
                    if (sum == 0)
                    { 
                        sum = long.Parse(buf);
                        if (i == 1)
                        {
                            if (sum >= 0)
                            {
                                ret += sum + 1;
                                sum = -1;
                            }
                            else
                            { 
                                ret += (sum * -1) + 1;
                                sum = 1;
                            }
                        }
                    }
                    else
                    {
                        if (sum > 0)
                        {
                            sum += long.Parse(buf);
                            if (sum >= 0)
                            {
