namespace AtCoder
{
    class Program
    {
        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            int[] a = new int[n];
            int[] sum = new int[n];
            string[] lines = Console.ReadLine().Split(' ');
            for (int i = 0; i < n; i++)
            {
                a[i] = int.Parse(lines[i]);
            }

            int ans = 0;
            int diff = 0;
            int sign = (a[0] == 0 ? 0 : (a[0] > 0 ? 1 : -1));
            sum[0] = a[0];
            for (int i = 1; i < n; i++)
            {
                if (sum[i-1] + a[i] > 0)
                {
                    if (sign > 0)
                    {
                        diff = +(sum[i-1] + 1);
                        ans += diff;
                        sum[i] = sum[i-1] - diff;
                    }
                    else
                    {
                        sum[i] = a[i] + sum[i-1];
                    }
                }
                else if (sum[i-1] + a[i] < 0)
                {
                    if (sign < 0)
                    {
                        diff = -(sum[i - 1] - 1);
                        ans += diff;
                        sum[i] = sum[i - 1] + diff;
                    }
                    else
                    {
                        sum[i] = a[i] + sum[i - 1];
                    }
                }
                else if (sum[i-1] + a[i] == 0)
                {
                    if (sign > 0)
                    {
                        diff = +(sum[i - 1]);
                        ans += diff;
                        sum[i] = sum[i - 1] - diff;
                    }
                    else
                    {
                        diff = -(sum[i - 1] );
                        ans += diff;
                        sum[i] = sum[i - 1] + diff;
                    }
                }
                if (sign == 0)
                {
                    sign = (a[i] > 0 ? 1 : -1);
                }
                else
                {
                    sign = -sign;
                }
            }

            Console.WriteLine(ans);
        }
    }
}

using System;
using System.Linq;
using System.Collections.Generic;

namespace Algorithm
{
    class Program
    {
        static int N = 0;
        static int[] A;

        static void Main(string[] args)
        {
            N = int.Parse(Console.ReadLine());
            A = Console.ReadLine().Split().Select(int.Parse).ToArray();
            Console.WriteLine(Math.Min(Calc(0), Calc(1)));
        }

        static long Calc(int flag)
        {
            var acum = 0;
            var ope = 0L;

            for (var i = 0; i < N; i++)
            {
                var diff = acum + A[i];
                if (i % 2 == flag)
                {
                    if (diff <= 0)
                    {
                        ope += -diff + 1;
                        acum = 1;
                    }
                    else acum += A[i];
                }
                else
                {
                    if (diff >= 0)
                    {
                        ope += diff + 1;
                        acum = -1;
                    }
                    else acum += A[i];
                }
            }

            return ope;
        }
    }
}

