        public long SolveLong()
        {
            var n = Read;
            var a = Arr(n);

            var a0 = a[0];
            var res1 = Slv(a, a0 >= 0 ? -1 : a0);
            var res2 = Slv(a, a0 <= 0 ? 1 : a0);

            return Math.Min(res1, res2);
        }

        long Slv(IReadOnlyList<long> a, long initial)
        {
            var res = Math.Abs(initial - a[0]);
            var sum = initial;

            foreach (var aa in a.Skip(1))
            {
                var s2 = sum + aa;
                if (sum > 0 && s2 >= 0)
                {
                    res += Math.Abs(s2 + 1);
                    s2 = -1;
                }
                else if (sum < 0 && s2 <= 0)
                {
                    res += Math.Abs(s2 - 1);
                    s2 = 1;
                }

                sum = s2;
            }

            return res;
        }

