        static long cand(long sum, int[] a)
        {
            long ret = 0;
            for (int i = 1; i < a.Length; i++)
            {
                if (sum < 0)
                {
                    sum += a[i];
                    if (sum < 1)
                    {
                        ret += 1 - sum;
                        sum = 1;
                    }
                }
                else if (sum > 0)
                {
                    sum += a[i];
                    if (sum > -1)
                    {
                        ret += sum + 1;
                        sum = -1;
                    }
                }
            }
            return ret;
        }

