                        {
                            ret += Math.Abs(sum) + 1;
                            sum = sign * -1;
                            sign *= -1;
                        }
                    }
                    else
                    {
                        sum += long.Parse(buf);
                        if ((sum * sign) >= 0)
                        {
                            ret += Math.Abs(sum) + 1;
                            sum = sign * -1;
                        }
                        sign *= -1;
                    }
                }
                if (i == 0)
