class Program
{
    static int n;
    static long[] a;

    public static void Main(string[] args)
    {
        n = Input.NextInt();
        a = Input.LineLong();

        long minmove = Calc(a);
        for (int i = 0; i < a.Length; i++)
        {
            a[i] = -a[i];
        }
        minmove = Math.Min(minmove, Calc(a));

        Console.WriteLine(minmove);
    }

    private static long Calc(long[] a)
    {
        checked
        {
            long curr = 0;
            long move = 0;
            for (long i = 0; i < a.Length; i++)
            {
                long dif = 0;
                switch (i % 2)
                {
                    case 0:
                        {
                            var newc = curr + a[i];
                            dif = newc <= 0 ? 1 - newc : 0;
                        }
                        break;
                    case 1:
                        {
                            var newc = curr + a[i];
                            dif = newc >= 0 ? -1 - newc : 0;
                        }
                        break;
                }
                curr += a[i] + dif;
                move += Math.Abs(dif);
            }

            return move;
        }
    }
}

