			for (var i = 1; i < list.Count; i++)
			{
				sum += list[i];
				if (isPreviousSumPositive && sum >= 0)
				{
					count += sum + 1;
					sum = -1;
				}
				else if (!isPreviousSumPositive && sum <= 0)
				{
					count += -sum + 1;
					sum = 1;
				}

				if (sum > 0)
				{
					isPreviousSumPositive = true;
				}
				else
				{
					isPreviousSumPositive = false;
				}
			}

			return count;
		}
	}
}

