        }


        static private string funcMain(string arg1, string arg2)
        {
            long ret = 0;
            long ret1 = 0;
            long ret2 = 0;
            long sum = 0;
            short sign = 0;

            for (int i = 0; i <= 1; i++) // 0はそのまま、1は逆符号
            {
                sum = ret = 0;
                foreach (string buf in arg2.Split())
                {
                    if (sum == 0)
                    { 
                        sum = long.Parse(buf);
                        if (sum >= 0)
                            sign = 1;
                        else
                            sign = -1;

                        if (i == 1)
                        {
                            ret += Math.Abs(sum) + 1;
                            sum = sign * -1;
                            sign *= -1;
                        }
                    }
                    else
                    {
                        sum += long.Parse(buf);
                        if ((sum * sign) >= 0)
                        {
                            ret += Math.Abs(sum) + 1;
                            sum = sign * -1;
                        }
                        sign *= -1;
                    }
                }
                if (i == 0)
                    ret1 = ret;
                else
                    ret2 = ret;
            }

            ret = Math.Min(ret1, ret2);

            return ret.ToString();
