    private object Calc()
    {
        var N = cr.Int;
        arr = cr.Repeat(N).Int;
        return Math.Min(Calc(false), Calc(true));
    }

    long Calc(bool cur)
    {
        long res = 0;
        long sum = arr[0];
        if (cur)
        {
            if (sum <= 0)
            {
                res += 1 - sum;
                sum = 1;
            }
        }
        else
        {
            if (sum >= 0)
            {
                res += 1 + sum;
                sum = -1;
            }
        }
        cur = !cur;
        for (int i = 1; i < arr.Length; i++, cur = !cur)
        {
            sum += arr[i];
            if (cur)
            {
                if (sum <= 0)
                {
                    res += 1 - sum;
                    sum = 1;
                }
            }
            else
            {
                if (sum >= 0)
                {
                    res += 1 + sum;
                    sum = -1;
                }
            }
        }
        return res;
    }

