            var oddCount = 0L; {
                var sum0 = a[0] < 0 ? a[0] : -1;
                var count = a[0] < 0 ? 0 : Abs (a[0]);
                foreach (var i in Enumerable.Range (1, n - 1)) {
                    var sum1 = sum0 + a[i];
                    if (IsOdd (i) && sum1 < 0) {
                        count += Abs (sum1) + 1;
                        sum0 = 1;
                    } else if (IsEven (i) && sum1 > 0) {
                        count += Abs (sum1) + 1;
                        sum0 = -1;
                    } else {
                        sum0 = sum1;
                    }
                }
                if (sum0 == 0) count += 1;
                oddCount = count;
            }
            Print (Min (evenCount, oddCount));
        }
    }

