using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        var N = Int32.Parse(Console.ReadLine());
        var a = Console.ReadLine().Split().Select(x => Int64.Parse(x)).ToArray();
        var ans = Math.Min(GetNumberOfOperations(a,true), GetNumberOfOperations(a, false));
        Console.WriteLine(ans);
    }
    static long GetNumberOfOperations(long[] array, bool isPositiveNumberFirst)
    {
        var length = array.Length;
        var count = 0L;
        var num = 0L;
        var isPositiveNumber = isPositiveNumberFirst;
        for (int i=0;i<length;++i)
        {
            if (isPositiveNumber && (num + array[i] < 1))
            {
                count += Math.Abs(1 - (num + array[i]));
                num = 1;
            }
            else if (!isPositiveNumber && (-1 < num + array[i]))
            {
                count += Math.Abs(-1 - (num + array[i]));
                num = -1;
            }
            else num += array[i];

            isPositiveNumber = !isPositiveNumber;
        }
        return count;
    }
}

