            var count = new long[] { 0, 0 };

            for (int i = 0; i < count.Length; i++)
            {
                long sum = 0;
                var isPositive = i == 0;

                for (int j = 0; j < a.Length; j++)
                {
                    isPositive = !isPositive;
                    if (sum + a[j] >= 0 && !isPositive)
                    {
                        var diff = -1 - (sum + a[j]);
                        count[i] += Math.Abs(diff);
                        sum += a[j] + diff;
                    }
                    else if (sum + a[j] <= 0 && isPositive)
                    {
                        var diff = 1 - (sum + a[j]);
                        count[i] += Math.Abs(diff);
                        sum += a[j] + diff;

                    }
                    else
                    {
                        sum += a[j];
                    }
                }
            }

