    static void Main()
    {
        ReadInts();
        var nums = ReadInts();

        var e = nums.AsEnumerable<int>().GetEnumerator();

        var zeroCount = 0;
        var f = false;
        while ((f = e.MoveNext()) && e.Current == 0)
            zeroCount++;

        var sum = 0;
        var count = 0;

        if (zeroCount != 0)
        {
            count = zeroCount * 2 - 1;

        }
        while (f)
        {
            var c = e.Current;

            var ps = Math.Sign(sum);

            var ns = Math.Sign(sum + c);

            if (ps == 0)
                ps = -ns;

            if (ns == 0)
            {
                sum = -ps;
                count++;
            }
            else if (ps == ns)
            {
                count += Math.Abs(sum + c) + 1;
                sum = -ps;
            }
            else
            {
                sum += c;
            }
            f = e.MoveNext();
        }

        Console.WriteLine(count);

    }

