    public static long culc0m(long[] a)
    {
        var count = 0L;
        var sum = a[0];
        if (sum >= 0) { count += sum + 1; sum = -1; }
        for (int i = 1; i < a.Length; i++)
        {
            if (i % 2 == 1)
            {
                if (sum + a[i] > 0) sum += a[i];
                else { count += -(sum + a[i]) + 1; sum = 1; }
            }
            else
            {
                if (sum + a[i] < 0) sum += a[i];
                else { count += (sum + a[i]) + 1; sum = -1; }
            }
        }
        return count;
    }
    public static long culc0p(long[] a, long b)
    {
        var count = 0L;
        var sum = a[0];
        if (sum <= 0) { count += -sum + 1; sum = 1; }
        for (int i = 1; i < a.Length; i++)
        {
            if (i % 2 == 1)
            {
                if (sum + a[i] < 0) sum += a[i];
                else { count += (sum + a[i]) + 1; sum = -1; }
            }
            else
            {
                if (sum + a[i] > 0) sum += a[i];
                else { count += -(sum + a[i]) + 1; sum = 1; }
            }
            if (count > b) return -1;
        }
        return count;
    }
