                            sum = 1;
                        }
                    }
                    else
                    {
                        if (sum >= 0)
                        {
                            step += 1 + sum;
                            sum = -1;
                        }
                    }
                }
                answer = Math.Min(answer, step);
            }

            Console.WriteLine(answer);
        }
    }
