func calc(sign, a, sum int) (int, int64) {
	nsum := sum + a
	if sign < 0 && nsum < 0 || 0 < sign && 0 < nsum {
		//println(sign, a, sum, " -> ", 0, nsum)
		return nsum, 0
	}

	if sign > 0 {
		nsum = 1
		na := nsum - sum
		//println(sign, a, sum, " -> ", na, absInt(na-a), nsum)
		return nsum, int64(absInt(na - a))
	} else {
		nsum = -1
		na := nsum - sum
		//println(sign, a, sum, " -> ", na, absInt(na-a), nsum)
		return nsum, int64(absInt(na - a))
	}
}

