	"os"
	"strconv"
)

func main() {
	var n int
	fmt.Scan(&n)
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	const (
		unknown = 0 + iota
		plus
		minus
	)
	preSign := unknown
	sum, operationNum := 0, 0
	for i := 0; i < n; i++ {
		sc.Scan()
		a, _ := strconv.Atoi(sc.Text())
		sum = sum + a
		if sum != 0 {
			if preSign == unknown {
				if sum > 0 {
					preSign = plus
				} else {
					preSign = minus
				}
			} else if preSign == plus {
				if sum > 0 {
					operationNum += (sum + 1)
					sum = -1
				}
				preSign = minus
			} else { // preSign == minus
				if sum < 0 {
					operationNum -= (sum - 1)
					sum = 1
				}
				preSign = plus
			}
		} else {
			if preSign == plus {
				operationNum++
				sum = -1
				preSign = minus
			} else {
				operationNum++
				sum = 1
				preSign = plus
			}
		}
	}
	fmt.Printf("%d\n", operationNum)
}

