func solve(a []int, r int) int {
	cnt := 0
	sum := 0

	for i := 0; i < len(a); i++ {
		if i%2 == r {
			if a[i]+sum <= 0 {
				cnt += abs(1 - a[i] - sum)
				sum = 1
			} else {
				sum += a[i]
			}
		} else {
			if a[i]+sum >= 0 {
				cnt += abs(-1 - a[i] - sum)
				sum = -1
			} else {
				sum += a[i]
			}
		}
	}
	return cnt
}

