func min(a, b int) int {
	if a > b {
		return b
	}
	return a
}

func solve(p bool, a []int) int {
	var sum, cnt int
	m, n := 1, 0
	if p {
		m, n = 0, 1
	}
	for i := 0; i < len(a); i++ {
		sum += a[i]
		if i%2 == m && sum <= 0 {
			cnt += 1 - sum
			sum = 1
		}
		if i%2 == n && sum >= 0 {
			cnt += sum + 1
			sum = -1
		}
	}
	return cnt
}

