}

func main() {
	var n int
	fmt.Scan(&n)
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	a := make([]int64, n)
	for i := 0; i < n; i++ {
		sc.Scan()
		x, _ := strconv.Atoi(sc.Text())
		a[i] = int64(x)
	}
	ans := int64(0)
	if a[0] == 0 {
		a[0] = -1
		ans = solve(a, 0)
		a[0] = 1
		ans = min(ans, solve(a, 1))
	} else {
		ans = min(solve(a, 0), solve(a, 1))
	}
	fmt.Println(ans)
}

func solve(a []int64, ra int) int64 {
	s := int64(0) // S_i = \sum_i a[i]
	ans := int64(0)
	for i, e := range a {
		if i%2 == ra {
			if s+e >= 0 {
				ans += abs(-1 - s - e)
				s = -1
				continue
			}
		} else {
			if s+e <= 0 {
				ans += abs(1 - s - e)
				s = 1
				continue
			}
		}
		s += int64(e)
	}
	return ans
}

