func getNextString(scanner *bufio.Scanner) string {
	scanner.Scan()
	return scanner.Text()
}

func getNextInt(scanner *bufio.Scanner) int {
	i, _ := strconv.Atoi(getNextString(scanner))
	return i
}

func getNextInt64(scanner *bufio.Scanner) int64 {
	i, _ := strconv.ParseInt(getNextString(scanner), 10, 64)
	return i
}

func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := getScanner(fp)

	writer := bufio.NewWriter(os.Stdout)

	n := getNextInt(scanner)

	aa := make([]int64, n)
	ss := make([]int64, n+1)
	for i := 0; i < n; i++ {
		aa[i] = getNextInt64(scanner)
		ss[i+1] = ss[i] + aa[i]
	}

	var ans, adjust int64
	// i%2 == 0を正
	for i := 1; i < n+1; i++ {
		if i%2 == 0 {
			if ss[i]+adjust <= 0 {
				diff := int64(1) - (ss[i] + adjust)
				ans += diff
				adjust += diff
			}
			continue
		}
		if ss[i]+adjust >= 0 {
			diff := int64(1) + (ss[i] + adjust)
			ans += diff
			adjust -= diff
		}
	}
	ans1 := ans
	ans = 0
	adjust = 0
	// i%2 == 1を正
	for i := 1; i < n+1; i++ {
		if i%2 == 1 {
			if ss[i]+adjust <= 0 {
				diff := int64(1) - (ss[i] + adjust)
				ans += diff
				adjust += diff
			}
			continue
		}
		if ss[i]+adjust >= 0 {
			diff := int64(1) + (ss[i] + adjust)
			ans += diff
			adjust -= diff
		}
	}

	if ans > ans1 {
		ans = ans1
	}

	fmt.Fprintln(writer, ans)

	writer.Flush()
}

