    } else if sum+a[i] > 0{
      cnt += 1+sum+a[i]
      sum = -1
    } else {
      cnt += 1
      if sum > 0 {
        sum = -1
      } else {
        sum = 1
      }
    }
  }
  fmt.Println(cnt)
}

