	sc.Split(bufio.ScanWords)
	sc.Buffer(make([]byte, initialBufSize), maxBufSize)
	defer wt.Flush()

	n := nextInt()
	a := nextInts(n)

	ans1 := 0
	for i, sum, pos := 0, 0, true; i < n; i, pos = i+1, !pos {
		var d int
		if pos && (sum+a[i]) <= 0 {
			d = abs(1 - (sum + a[i]))
			ans1 += d
		} else if !pos && (sum+a[i]) >= 0 {
			d = -abs(-1 - (sum + a[i]))
			ans1 -= d
		}
		sum += a[i] + d
	}

	ans2 := 0
	for i, sum, pos := 0, 0, false; i < n; i, pos = i+1, !pos {
		var d int
		if pos && (sum+a[i]) <= 0 {
			d = abs(1 - (sum + a[i]))
