	ans := 0
	sum := 0
	for i, a := range as {
		if i%2 == r {
			if sum+a <= 0 {
				ans += abs(sum+a) + 1
				sum = 1
			} else {
				sum += a
			}
		} else {
			if sum+a >= 0 {
				ans += abs(sum+a) + 1
				sum = -1
			} else {
				sum += a
			}
		}
	}
	return ans
