func solve(a []int64, ra int) int64 {
	s := int64(0) // S_i = \sum_i a[i]
	ans := int64(0)
	for i, e := range a {
		if i%2 == ra {
			if s+e >= 0 {
				ans += abs(-1 - s - e)
				s = -1
				continue
			}
		} else {
			if s+e <= 0 {
				ans += abs(1 - s - e)
				s = 1
				continue
			}
		}
		s += e
	}
	return ans
}

