		sc.Scan()
		x, _ := strconv.Atoi(sc.Text())
		a[i] = int64(x)
	}
	ans := int64(0)
	if a[0] == 0 {
		a[0] = -1
		ans = solve(a, 0)
		a[0] = 1
		ans = min(ans, solve(a, 1))
	} else if a[0] < 0 {
		ans = solve(a, 0)
	} else { // a[0] > 0
		ans = solve(a, 1)
	}
	fmt.Println(ans)
}

