func solveSub(headSign int, a []int) int {
	sign := headSign
	s := 0
	r := 0

	for _, ax := range a {
		var n int
		if sign == 1 {
			n = max(s+ax, sign)
		} else {
			n = min(s+ax, sign)
		}

		r += (n - (s + ax)) * sign
		s = n
		sign = -sign
	}

	return r
}

