func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func count(as []int, t int) int {
	cnt := 0
	sum := 0
	for i := 0; i < len(as); i++ {
		sum += as[i]
		if t == 1 && sum < 1 {
			cnt += 1 - sum
			sum = 1
		} else if t == -1 && sum > -1 {
			cnt += sum + 1
			sum = -1
		}
		t *= -1
	}

	return cnt
}

