uint func(int[] an, uint mod) {
  auto sum = 0;
  auto res = 0;
  foreach(i,a; an) {
    sum += a;
    if (i % 2 == mod && sum <= 0) {
      res += 1 - sum;
      sum = 1;
    }
    if (i % 2 != mod && sum >= 0) {
      res += 1 + sum;
      sum = -1;
    }
  }
  return res;
}

