auto solve( long[] as )
{
	auto ps = 0L;
	auto pd = 0L;
	auto ms = 0L;
	auto md = 0L;

	foreach( i, a; as )
	{
		ps += a;
		ms += a;
		if( i % 2 == 0 )
		{
			if( ps <= 0 ) pd -= ps - 1, ps -= ps - 1;
			if( 0 <= ms ) md += ms + 1, ms -= ms + 1;
		}
		else
		{
			if( 0 <= ps ) pd += ps + 1, ps -= ps + 1;
			if( ms <= 0 ) md -= ms - 1, ms -= ms - 1;
		}
	}

	return min( pd, md );
}

