long solve(int n, long[] a, int pm) {
    long as;
    long res;

    foreach (i; 0 .. n) {
        as += a[i];
        if (sign(as) != pm) {
            res += abs(as - pm);
            as = pm;

        }

        pm *= -1;
    }

    return res;
}

