def search(a, flip=False):
    if not flip:
        count = 0
    else:
        count = abs(a[0]) + 1
        a[0] = 1 if a[0] < 0 else -1
    a_sum = a[0]
    for ai in a[1:]:
        tmp_sum = a_sum + ai
        if tmp_sum < 0 and a_sum < 0:
            c = abs(tmp_sum) + 1
        elif tmp_sum > 0 and a_sum > 0:
            c = -abs(tmp_sum) - 1
        elif tmp_sum == 0 and a_sum < 0:
            c = 1
        elif tmp_sum == 0 and a_sum > 0:
            c = -1
        else:
            c = 0
        count += abs(c)
        a_sum = tmp_sum + c
    return count

print(min(search(a, False), search(a, True)))

