def op(pos, n, a):
    if pos:
        S = 1 if a[0] == 0 else a[0]
    else:
        S = -1 if a[0] == 0 else a[0]
    count = 1 if a[0] == 0 else 0

    for i in a[1:]:
        if S * (S + i) > 0:
            count += abs(S + i) + 1
            S = -1 if S > 0 else 1
        elif S + i == 0:
            count += 1
            S = -1 if S > 0 else 1
        else:
            S += i

    return count


