class AtCoder:
    def main(self):
        n = int(input())
        a = list(map(int, input().split()))

        even_plus_ans = 0
        before = a[0]
        if a[0] <= 0:
            even_plus_ans -= a[0] - 1
            before = 1

        for i in range(1, n):
            if i % 2 == 0:
                v = a[i] + before
                if v > 0:
                    before = v
                elif v <= 0:
                    before = 1
                    even_plus_ans -= v - 1
            else:
                v = a[i] + before
                if v < 0:
                    before = v
                elif v >= 0:
                    before = -1
                    even_plus_ans += v + 1

        odd_plus_ans = 0
        before = a[0]
        if a[0] >= 0:
            odd_plus_ans += a[0] + 1
            before = -1

        for i in range(1, n):
            if i % 2 != 0:
                v = a[i] + before
                if v > 0:
                    before = v
                elif v <= 0:
                    before = 1
                    odd_plus_ans -= v - 1
            else:
                v = a[i] + before
                if v < 0:
                    before = v
                elif v >= 0:
                    before = -1
                    odd_plus_ans += v + 1

        print(min(even_plus_ans, odd_plus_ans))


# Run main
if __name__ == '__main__':
    AtCoder().main()

