# nの把握
n = int(input())
# 数列の把握
AL = list(map(int, input().split()))

"""
条件１：すべてのi(1≦i≦n) に対し、第 1 項から第 i 項までの和は 0 でない
条件２：すべてのi(1≦i≦n−1) に対し、i 項までの和と i+1 項までの和の符号が異なる

条件２より、i項までの総和とi+1項までの総和は、正負又は負正という順番で進行する。
条件を満たさないとき、iについて、総和が1or-1となるまで手順を実施する。
"""

#正負を確かめる関数
def PN(AL):
	ISUM = 0
	P = 0
	for i in range(n):
		ISUM += AL[i]
		if i % 2 == 0:
			if ISUM > 0:
				pass
			else:
				P += abs(1 - ISUM)
				ISUM = 1
		else:
 			if ISUM < 0:
 				pass
 			else:
 				P += abs(-1 - ISUM)
 				ISUM = 1
	return P

#負正を確かめる関数
def NP(AL):
	ISUM = 0
	P = 0
	for i in range(n):
		ISUM += AL[i]
		if i % 2 == 0:
			if ISUM < 0:
				pass
			else:
				P += abs(-1 - ISUM)
				ISUM = -1
		else:
			if ISUM > 0:
 				pass
			else:
 				P += abs(1- ISUM)
 				ISUM = 1
	return P

ANSWER = min(PN(AL), NP(AL))
print(ANSWER)

