    if abs(target - x) < abs(x):
        return 0
    else:
        return target - x

def count_ops(a):
    total_ops = 0
    accum = a[0]
    for i in range(1, len(a)):
        new_accum = accum + a[i]
        if new_accum == 0:
            ops =  -1 * (accum / abs(accum))
        else:
            ops = ops_needed(new_accum, -1 * (accum / abs(accum)))
        total_ops += abs(ops)
        accum = new_accum + ops
    return int(total_ops)


