def calc(A, N):
    s = 0
    count = 0
    pre_sign = 0
    for i in range(N):
        s += A[i]
        if s == 0:
            if pre_sign == 1:
                s -= 1
            elif pre_sign == -1:
                s += 1
            count += 1
        if pre_sign == s/abs(s):
            if s < 0:
                ope = 1 - s
            else:
                ope = -1 - s
            s += ope
            count += abs(ope)
        pre_sign = s/abs(s)
    return count


