def check(A, mod2):
    cur = res = 0
    for i in range(N):
        cur += A[i]
        if i % 2 == mod2:
            # 0以下なら1にする
            if cur <= 0:
                # cur + x = 1 → x = 1 - cur
                A[i] += 1 - cur
                res += 1 - cur
                cur += 1 - cur
        else:
            # 0以上なら-1にする
            if cur >= 0:
                # cur - x = -1 → x = 1 + cur
                A[i] -= 1 + cur
                res += 1 + cur
                cur -= 1 + cur
    return res

