def solve(N, As):
    positive = True if As[0] < 0 else False
    for i, a in enumerate(As):
        if a != 0:
            if i % 2 == 0:
                positive = True if a < 0 else False
            else:
                positive = False if a < 0 else True
            break

    ans = 0
    i = As[0]
    if i == 0:
        ans = 1
        if positive:
            i = -1
        else:
            i = 1

    for a in As[1:]:
        if positive:
            if i + a <= 0:
                ans += abs(1 - (i + a))
                a += 1 - (i + a)
        else:
            if i + a >= 0:
                ans += abs(-1 - (i + a))
                a += -1 - (i + a)
        i += a
        positive = not positive

    return ans

