def f(arr, tmp):
    count = 0
    for i in range(1, n):
        if tmp + arr[i] < 0 < tmp:
            # 加えたら符号が+から-になる場合
            tmp += arr[i]
        elif tmp < 0 < tmp + arr[i]:
            # 加えたら符号が-から+になる場合
            tmp += arr[i]
        elif 0 <= tmp + arr[i] <= tmp or 0 <= tmp <= tmp + arr[i]:
            # 加えても+から-にはならず+のまま
            count += abs(-1 - tmp - arr[i])
            tmp = -1
        elif tmp + arr[i] <= tmp <= 0 or tmp <= tmp + arr[i] <= 0:
            # 加えても-から+にはならず-のまま
            count += abs(1 - tmp - arr[i])
            tmp = 1
        else:
            # runtime errorの出し方がわからんのでTLEを狙う（おい
            while True:
                if 1 == 0:
                    break

    return count


