def sign(x):
    if x < 0:
        return -1
    elif x > 0:
        return 1
    else:
        return 0


def solve():
    N = int(input())
    a = [int(x) for x in input().split()]

    cumsum = [0] * N
    cumsum[0] = a[0]
    for i in range(1, N):
        cumsum[i] = a[i] + cumsum[i-1]

    op = 0  # operation
    ans = 0
    for i in range(1, N):
        c0 = cumsum[i-1]
        c1 = cumsum[i] = cumsum[i] + op

        s0 = sign(c0)
        s1 = sign(c1)

        if s0 * s1 < 0:
            continue

        if s1 == 0:
            ans += 1
            if s0 < 0:
                op += 1
                cumsum[i] += 1
            else:
                op -= 1
                cumsum[i] -= 1
        else:
            delta = -s1 * (abs(cumsum[i]) + 1)
            cumsum[i] += delta
            op += delta
            ans += abs(delta)

        # print(cumsum)
    return ans


def main():
    print(solve())


