    if a[0] > 0:
        return min(rec(a[0], a[1:], 0), rec(-1, a[1:], a[0] + 1))
    else:
        return min(rec(a[0], a[1:], 0), rec(1, a[1:], 1 - a[0]))

def rec(s, a, r):
    if not a:
        return r
    elif s < 0:
        n = max(s + a[0], 1)
        return rec(n, a[1:], r + (n - (s + a[0])))
    else:
        n = min(s + a[0], -1)
        return rec(n, a[1:], r + s + a[0] - n)

