def sequence(N: int, A: list) -> int:
    def count_op(s: int) -> int:
        op = 0

        if s * A[0] > 0:
            s = A[0]
        else:
            s = s / abs(s)
            op = abs(1 - s)

        for a in A[1:]:
            if s < 0:
                if s + a > 0:
                    # OK
                    s = s + a
                    continue
                else:
                    op += 1 - (s + a)
                    s = 1
            else:  # s > 0
                if s + a < 0:
                    # OK
                    s = s + a
                    continue
                else:
                    op += (s + a) - (-1)
                    s = -1
        return op

    return min(count_op(1), count_op(-1))


