def solve():
    N = int(input())
    A = list(map(int, input().split()))

    ans = 0
    """
    (1) A = [0, 0, 0, 0, 0, 100, ...] みたいなときは
        A = [-1, 2, -2, 2, -2, 100, ...] にしたい
    (2) A = [0, 0, 0, 0, 100, ...] みたいなときは
        A = [1, -2, 2, -2, 100, ...] にしたい
    """
    if A[0] == 0:
        hugou = 1  # 最後の符号(1:+, -1:-)
        for i in range(1, N):
            if A[i] == 0:
                continue
            if A[i] > 0:
                hugou = 1
                break
            else:
                hugou = -1
                break

        for j in range(i-1, 0, -1):
            if hugou == -1:
                A[j] = 2
            else:
                A[j] = -2
            hugou *= -1
            ans += 2

        if hugou > 0:
            A[0] = -1
        else:
            A[0] = 1
        ans += 1

    # ruiseki[i] := i番目までの累積和
    ruiseki = [0] * N
    ruiseki[0] = A[0]
    for i in range(1, N):
        i_sum = A[i] + ruiseki[i-1]

        if ruiseki[i-1] > 0:
            # ruiseki[i]をマイナス値にする必要がある
            if i_sum < 0:
                ruiseki[i] = i_sum
            else:
                diff = abs(i_sum - (-1))
                ans += diff
                A[i] -= diff
                i_sum -= diff
                ruiseki[i] = i_sum
        elif ruiseki[i-1] < 0:
            # ruiseki[i]をプラス値にする必要がある
            if i_sum > 0:
                ruiseki[i] = i_sum
            else:
                diff = abs(i_sum - 1)
                ans += diff
                A[i] += diff
                i_sum += diff
                ruiseki[i] = i_sum

    print(ans)




