def calc(A, N):
    s = 0L
    count = 0
    pre_sign = 0
    for i in range(N):
        s += A[i]
        if s == 0:
            if pre_sign == 1:
                s -= 1L
            elif pre_sign == -1:
                s += 1L
            count += 1
        if pre_sign == s/abs(s):
            if s < 0L:
                ope = 1L - s
            else:
                ope = -1L - s
            s += ope
            count += abs(ope)
        pre_sign = s/abs(s)
    return count


