def op(sign, n, a):
    if sign * a[0] <= 0:
        count = abs(a[0]) + 1
        S = sign
    else:
        count = 0
        S = a[0]

    for i in a[1:]:
        if S * (S + i) > 0:
            count += abs(S + i) + 1
            S = -1 if S > 0 else 1
        elif S + i == 0:
            count += 1
            S = -1 if S > 0 else 1
        else:
            S += i

    return count


