            fast = 1
        else:
            fast = -1
        for w in range(n):
            if fast < 0 and kei + int(a[w]) >= 0:
                forans += abs(kei + int(a[w])) + 1
                kei = -1
                fast = 1
            elif fast > 0 and kei + int(a[w]) <= 0:
                forans += abs(kei + int(a[w])) + 1
                kei = 1
                fast = -1
            else:
                kei += int(a[w])
                fast *= -1
        ans = min(ans , forans)

