def count_loop(n, old_state, count, a_list, flag):
    for i in range(1, int(n)):
        num_state = old_state + int(a_list[i])
        if flag == 1:
            if num_state >= 0:
                count += num_state + 1
                old_state = -1
            elif num_state < 0:
