def solve():
    N = int(input())
    A = list(map(int, input().split()))

    # dp[i] := i番目までの最小の操作回数
    dp = [None] * N
    dp[0] = 0

    ans = 0
    # A = [0 0 0 0 0 100 ...] みたいなときは
    # A = [-1 2 -2 2 -2 100 ...] にしたい
    if A[0] == 0:
        hugou = 1
        for i in range(1, N):
            if A[i] == 0:
                continue
            if A[i] > 0:
                hugou = 1
                break
            else:
                hugou = -1
                break

        for j in range(i, 0, -1):
            if hugou == -1:
                A[j] = 2
            else:
                A[j] = -2
            hugou *= -1
            ans += 2

        if hugou > 0:
            A[0] = -1
        else:
            A[0] = 1
        ans += 1

    # ruiseki[i] := i番目までの累積和
    ruiseki = [0] * N
    ruiseki[0] = A[0]
    for i in range(1, N):
        total = A[i] + ruiseki[i-1]
        if ruiseki[i-1] > 0:
            # ruiseki[i]をマイナス値にする必要がある
            if total < 0:
                ruiseki[i] = total
            else:
                diff = abs(total - (-1))
                ans += diff
                A[i] -= diff
                total -= diff
                ruiseki[i] = total
        else:
            # ruiseki[i]をプラス値にする必要がある
            if total > 0:
                ruiseki[i] = total
            else:
                diff = abs(total - 1)
                ans += diff
                A[i] += diff
                total += diff
                ruiseki[i] = total

    print(ans)




