import itertools

def main():
    N = int(input())
    A = tuple(map(int, input().split()))

    a = list(itertools.accumulate(A))
    even, odd = [], []
    e_apnd, o_apnd = even.append, odd.append
    for i, v in enumerate(a):
        if i % 2:
            o_apnd(v)
        else:
            e_apnd(v)

    if sum(even) > sum(odd):
        func = (plus, minus)
    elif sum(even) < sum(odd):
        func = (minus, plus)
    elif max(even) > max(odd):
        func = (plus, minus)
    else:
        func = (minus, plus)

    cnt = 0
    add_ = 0
    for i, v in enumerate(a):
        ret = func[i%2](v + add_)
        add_ += ret
        cnt += abs(ret)
    print(cnt)

def plus(n):
    if n <= 0:
        x = 1 - n
        return x
    else:
        return 0

def minus(n):
    if n >= 0:
        x = -1 - n
        return x
    else:
        return 0

main()

