fn func(a: &Vec<i64>, tar: i64) -> i64 {
    let mut tmp = 0;
    let mut sum = 0;
    let mut sig = tar;
    for i in 0..a.len() {
        sum += a[i];
        if sum.signum() != sig {
            let d = sum.abs() + 1;
            tmp += d;
            sum += d * sig;
        }
        sig *= -1;
    }
    tmp
}


