    let mut cnt_even = 0;
    let mut cum_1 = vec![0; n];
    let mut cum_2 = vec![0; n];
    //cum_1[even] < 0,cum_2[odd] < 0
    if a[0] >= 0 {
        cnt_even += a[0].abs() + 1;
        cum_1[0] = a[0];
        cum_2[0] = -a[0];
    } else {
