fn f(mut plus: bool, list: &Vec<i64>) -> i64 {
    let mut sum = 0;
    let mut count = 0;
    for &x in list {
        sum += x;
        if !plus && sum >= 0 {
            let k = sum - -1;
            count += k;
            sum -= k;
        } else if plus && sum <= 0 {
            let k = 1 - sum;
            count += k;
            sum += k;
        }
        plus = !plus;
    }
    count
}

fn solve(input: String) -> String {
    input!(input=>(n:usize)(list:[i64]));
    std::cmp::min(f(true, &list), f(false, &list)).to_string()
}

pub fn sum_seq(v: Vec<i64>) -> Vec<i64> {
    v.into_iter()
        .scan(0, |state, x| {
            *state = *state + x;
            Some(*state)
        })
        .collect()
}

