fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);

    let n: usize = sc.read();
    let a: Vec<isize> = (0..n).map(|_| sc.read()).collect();

    let ans: usize = [0, 1]
        .iter()
        .map(|&stt| {
            let mut sum = 0;
            let mut scr = 0;
            for i in 0..n {
                sum += a[i];
                let d = if i & 1 == stt && sum <= 0 {
                    1 - sum
                } else if i & 1 != stt && sum >= 0 {
                    -1 - sum
                } else {
                    0
                };
                sum += d;
                scr += d.abs() as usize;
            }
            scr
        })
        .min()
        .unwrap();

    format!("{}\n", ans)
}

