fn solve(as_: Vec<i64>) -> i64 {
    let mut sum1 = 0;
    let mut sum2 = 0;
    let mut count1 = 0;
    let mut count2 = 0;

    if as_[0] <= 0 {
        count1 = 1 - as_[0];
        sum1 = 1;
    } else {
        sum1 = as_[0];
    }

    if as_[0] >= 0 {
        count2 = 1 + as_[0];
        sum2 = -1;
    } else {
        sum2 = as_[0];
    }

    for i in 1..as_.len() {
        let cur = as_[i];
        if sum1 > 0 {
            if cur + sum1 < 0 {
                sum1 += cur;
            } else {
                let exp = -1 - sum1;
                count1 += cur - exp;
                sum1 = -1;
            }
        } else if sum1 < 0 {
            if cur + sum1 > 0 {
                sum1 += cur;
            } else {
                let exp = 1 - sum1;
                count1 += exp - cur;
                sum1 = 1;
            }
        }
    }

    for i in 1..as_.len() {
        let cur = as_[i];
        if sum2 > 0 {
            if cur + sum2 < 0 {
                sum2 += cur;
            } else {
                let exp = -1 - sum2;
                count2 += cur - exp;
                sum2 = -1;
            }
        } else if sum2 < 0 {
            if cur + sum2 > 0 {
                sum2 += cur;
            } else {
                let exp = 1 - sum2;
                count2 += exp - cur;
                sum2 = 1;
            }
        }
    }
    std::cmp::min(count1, count2)
}

fn main() {
    input!{
        n: usize,
        as_: [i64; n],
    }
    println!("{}", solve(as_));
}

