                    sum = 1;
                    count += 1;
                    break;
                } else {
                    sum = -1;
                    count += 1;
                    break;
                }
            }
        }
    } else {
        sum = as_[0];
    }
    if sum == 0 {
        sum += 1;
        count += 1;
    }

    for i in 1..as_.len() {
        let cur = as_[i];
        if sum > 0 {
            if cur + sum < 0 {
                sum += cur;
            } else {
                let exp = -1 - sum;
                count += cur - exp;
                sum = -1;
            }
        } else if sum < 0 {
            if cur + sum > 0 {
                sum += cur;
            } else {
                let exp = 1 - sum;
                count += exp - cur;
                sum = 1;
            }
        }
    }
    count
}

fn main() {
    input!{
        n: usize,
        as_: [i64; n],
    }
    println!("{}", solve(as_));
}

