#[derive(PartialEq, Eq, PartialOrd, Ord, Clone, Copy, Debug)]
enum Hyper<X> { NegInf, Real(X), Inf }
use Hyper::{Real, NegInf, Inf};
impl<X> Hyper<X> {
    fn unwrap(self) -> X { if let Hyper::Real(x) = self { x } else { panic!() } }
}
impl<X: Ring> std::ops::Add for Hyper<X> {
    type Output = Self;
    fn add(self, rhs: Hyper<X>) -> Hyper<X> {
        match (self, rhs) {
            (Real(x), Real(y)) => Real(x + y),
            (Inf, _) => Inf,
            (_, Inf) => Inf,
            _ => NegInf,
        }
    }
}
impl<X: Ring> std::ops::Sub for Hyper<X> {
    type Output = Self;
    fn sub(self, rhs: Hyper<X>) -> Hyper<X> { self + (-rhs) }
}
impl<X: Ring> std::ops::Neg for Hyper<X> {
    type Output = Self;
    fn neg(self) -> Hyper<X> {
        match self {
            Inf => NegInf,
            NegInf => Inf,
            Real(x) => Real(-x),
        }
    }
}

fn solve(d: i64, sign: bool, xs: &Vec<i64>) -> i64 {
    let mut sign = sign;
    let mut sum = 0;
    let mut num = 0;
    for &x in xs.iter() {
        sum += x;
        if sign {
            if sum < 1 {
                num += 1 - sum;
                sum = 1;
            }
            else if sum > d {
                num += sum - d;
                sum = d;
            }
            sign = false;
        } else {
            if sum > -1 {
                num += sum + 1;
                sum = -1;
            }
            else if sum < -d {
                num += -d - sum;
                sum = -d;
            }
            sign = true;
        }
    }
    num
}

