fn main() {
    let n: usize = input();
    let a: Vec<i64> = (0..n).map(|_| input()).collect();

    let sum: Vec<i64> = a
        .iter()
        .scan(0, |acc, &a| {
            *acc += a;
            Some(*acc)
        })
        .collect();
    let mut x = 0;
    let mut ans = 0;
    for i in 1..n {
        if (sum[i - 1] + x > 0 && sum[i] + x < 0) || (sum[i - 1] + x < 0 && sum[i] + x > 0) {
            continue;
        }
        if sum[i - 1] + x > 0 {
            ans += sum[i] + x + 1;
            x -= sum[i] + x + 1;
        } else {
            ans += -sum[i] - x + 1;
            x -= sum[i] + x - 1;
        }
    }

    println!("{}", ans);
}

