fn main(){
    input!{
        N: usize,
        A: [i64; N],
    }
    let mut ans1 = 0_i64;
    let mut ans2 = 0_i64;
    let mut res = 0_i64;
    for i in 0..N{
        res += A[i];
        if i%2==0{
            if res <= 0{
                ans1 -= res-1;
                res = 1;
            }
        }else{
            if res >= 0{
                ans1 += res+1;
                res = -1;
            }
        }
    }

    res = 0;
    for i in 0..N{
        res += A[i];
        if i%2==1{
            if res <= 0{
                ans2 -= res-1;
                res = 1;
            }
        }else{
            if res >= 0{
                ans2 += res+1;
                res = -1;
            }
        }
    }
    println!("{}",min(ans1,ans2));
}

