fn main() {
    let n: usize = input();
    let a: Vec<i64> = (0..n).map(|_| input()).collect();

    let sum: Vec<i64> = a
        .iter()
        .scan(0, |acc, a| {
            *acc += a;
            Some(*acc)
        })
        .collect();
    let mut x = 0;
    let mut ans = 0;
    for i in 1..n {
        if (sum[i - 1] + x > 0 && sum[i] + x < 0) || (sum[i - 1] + x < 0 && sum[i] + x > 0) {
            continue;
        }
        if sum[i - 1] + x > 0 {
            ans += sum[i] + x + 1;
            x -= sum[i] + x + 1;
        } else {
            ans += -sum[i] - x + 1;
            x -= sum[i] + x - 1;
        }
    }

    println!("{}", ans);
}

use std::collections::HashMap;
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}
fn main() {
    input! {
        n:usize,
        an:[i64;n],
    }
    let ans = std::cmp::min(solve(true, &an), solve(false, &an));
    println!("{}", ans);
}
fn solve(mut flag: bool, an: &Vec<i64>) -> i64 {
    let mut sum = 0;
    let mut ans = 0;
    for &a in an {
        sum += a;
        if !flag && sum >= 0 {
            let diff = sum - -1;
            ans += diff;
            sum -= diff;
        } else if flag && sum <= 0 {
            let diff = 1 - sum;
            ans += diff;
            sum += diff;
        }
        flag = !flag;
    }
    ans
}

