fn solve(mut symbol: bool, v:&Vec<i64>) -> i64{
    let mut sum = 0;
    let mut ans = 0;
    for a in v{
        sum += a;
        if !symbol && sum >= 0 {
            let next = sum - -1;
            ans += next;
            sum -= next;
        } else if symbol && sum <= 0{
            let next = 1 -sum;
            sum += next;
            ans += next;
        }
        symbol = !symbol;
    }
    ans
}

