    let mut cnt_even = 0;
    let mut cum_1 = vec![0; n];
    let mut cum_2 = vec![0; n];
    //cum_1[even] < 0,cum_2[odd] < 0
    if a[0] >= 0 {
        cnt_even += a[0].abs() + 1;
        cum_1[0] = a[0];
        cum_2[0] = -1;
    } else {
        cnt_odd += a[0].abs() + 1;
        cum_1[0] = 1;
        cum_2[0] = a[0];
    }
    //+ - + -
    for i in 1..n {
        cum_1[i] = cum_1[i-1] + a[i];
        if i % 2 != 0 {
            if cum_1[i] >= 0 {
                cnt_odd += cum_1[i].abs() + 1;
                cum_1[i] = -1;
            }
        } else {
            if cum_1[i] <= 0 {
                cnt_odd += cum_1[i].abs() + 1;
                cum_1[i] = 1;
            }
        }
    }
    //- + - +
    for i in 1..n {
        cum_2[i] = cum_2[i-1] + a[i];
        if i % 2 == 0 {
            if cum_2[i] >= 0 {
                cnt_even += cum_2[i].abs() + 1;
                cum_2[i] = -1;
            }
        } else {
            if cum_2[i] <= 0 {
                cnt_even += cum_2[i].abs() + 1;
                cum_2[i] = 1;
            }
        }
    }
    puts!("{}\n",min(cnt_odd, cnt_even));
}

