fn main() {
  let n = read::<i64>();
  let mut vec_a = vec![];

  for i in 0..n {
    vec_a.push(read::<i64>());
  }

  let mut prev_sum = vec_a[0];
  let mut ans = 0;
  // 最初を正にする
  if prev_sum <= 0 {
    prev_sum = 1;
    ans = (1 - prev_sum).abs();
  }

  for i in 1..vec_a.len() {
    let b = vec_a[i as usize];
    if 0 < prev_sum {
      if 0 <= prev_sum + b {
        ans += (1 + prev_sum).abs() + b;
        prev_sum = -1;
      } else {
        prev_sum += b;
      }
    } else if prev_sum < 0 {
      if prev_sum + b <= 0 {
        ans += (1 - prev_sum).abs() - b;
        prev_sum = 1;
      } else {
        prev_sum += b;
      }
    }
  }
  let plus_min = ans;

  // 最初を負にする
  prev_sum = vec_a[0];
  ans = 0;
  if 0 <= prev_sum {
    prev_sum = -1;
    ans = (1 + prev_sum).abs();
  }
  for i in 1..vec_a.len() {
    let b = vec_a[i as usize];
    if 0 < prev_sum {
      if 0 <= prev_sum + b {
        ans += (1 + prev_sum).abs() + b;
        prev_sum = -1;
      } else {
        prev_sum += b;
      }
