      if prev_sum + b <= 0 {
        ans += (1 - prev_sum).abs() - b;
        prev_sum = 1;
      } else {
        prev_sum += b;
      }
    }
  }
  let minus_min = ans;
  ans = min(plus_min, minus_min);

  println!("{}", ans);

}

